-- Run inside one transaction (installer / Supabase migration runner / psql --single-transaction).
-- Gugu foundation: effective-schema candidate; no historical migration ancestors.
-- For a fresh, dedicated Supabase project only. Existing deployments retain their original ledger.
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS vector WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;
CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS supabase_vault WITH SCHEMA vault;
DO $role$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname='gugu_files') THEN
    CREATE ROLE gugu_files NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 16;
    ALTER ROLE gugu_files SET statement_timeout='10s';
    ALTER ROLE gugu_files SET idle_in_transaction_session_timeout='30s';
  END IF;
END $role$;
