--
-- Name: _keys_diff_owned_by(jsonb, jsonb, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat._keys_diff_owned_by(new_j jsonb, old_j jsonb, caller text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    k TEXT;
    old_val JSONB;
    new_val JSONB;
BEGIN
    -- Check every key present in new_j: if it's missing or different in
    -- old_j, the diff is attributable to caller — must equal caller.
    FOR k IN SELECT jsonb_object_keys(new_j) LOOP
        old_val := old_j -> k;
        new_val := new_j -> k;
        IF old_val IS DISTINCT FROM new_val AND k <> caller THEN
            RETURN false;
        END IF;
    END LOOP;
    -- Check for keys removed from old_j (deletion): must also be caller's
    FOR k IN SELECT jsonb_object_keys(old_j) LOOP
        IF (new_j -> k) IS NULL AND k <> caller THEN
            RETURN false;
        END IF;
    END LOOP;
    RETURN true;
END;
$$;


--
-- Name: add_group_agent(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.add_group_agent(p_chat_id text, p_agent_user_id text, p_message text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_me TEXT := (SELECT auth.uid()::text);
    v_denial TEXT;
    v_request TEXT;
BEGIN
    IF v_me IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    IF NOT EXISTS (
        SELECT 1 FROM identity.users u WHERE u.id = p_agent_user_id AND u.type = 'agent' AND u.owner_user_id = v_me
    ) THEN
        RAISE EXCEPTION 'agent_not_owned';
    END IF;
    -- 串行化同一群的并发加人(与 flood 阈值触发器同一把群行锁)。
    PERFORM 1 FROM chat.chats WHERE id = p_chat_id FOR UPDATE;
    v_denial := chat.group_add_denial(p_chat_id, p_agent_user_id, v_me);
    IF v_denial = 'agent_join_requires_manager' THEN
        v_request := chat.queue_agent_join_request(p_chat_id, p_agent_user_id, v_me, p_message);
        RETURN jsonb_build_object('status', 'pending_approval', 'request_id', v_request, 'chat_id', p_chat_id);
    END IF;
    IF v_denial IS NOT NULL THEN RAISE EXCEPTION '%', v_denial; END IF;
    INSERT INTO chat.chat_members (chat_id, user_id, role)
    VALUES (p_chat_id, p_agent_user_id, 'member')
    ON CONFLICT (chat_id, user_id) DO NOTHING;
    INSERT INTO chat.group_agent_states (chat_id, agent_user_id, functional_role, capability_roles, last_action, updated_at)
    VALUES (p_chat_id, p_agent_user_id, 'member', ARRAY['member']::TEXT[], '已加入群聊', now())
    ON CONFLICT (chat_id, agent_user_id) DO NOTHING;
    RETURN jsonb_build_object('status', 'joined', 'chat_id', p_chat_id);
END;
$$;


