--

CREATE TABLE chat.chats (
    id text NOT NULL,
    kind text NOT NULL,
    name text,
    status text DEFAULT 'active'::text NOT NULL,
    creator_user_id text,
    next_message_seq bigint DEFAULT 1 NOT NULL,
    last_message_at timestamp with time zone,
    last_message_preview text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pinned_message_id text,
    group_prompt text,
    default_agent_type text,
    public_id integer DEFAULT nextval('chat.public_chat_id_seq'::regclass) NOT NULL,
    join_token text DEFAULT encode(extensions.gen_random_bytes(16), 'hex'::text),
    description text,
    max_members integer DEFAULT 100 NOT NULL,
    allow_member_invite boolean DEFAULT false NOT NULL,
    agent_join_approval boolean DEFAULT false NOT NULL,
    join_mode text DEFAULT 'approval'::text NOT NULL,
    hide_history boolean DEFAULT false NOT NULL,
    invite_link_enabled boolean DEFAULT true NOT NULL,
    avatar_url text,
    is_discoverable boolean DEFAULT false NOT NULL,
    avatar_storage_bucket_id text,
    avatar_storage_object_name text,
    source_chat_id text,
    source_message_id text,
    agent_flood_tuned_at timestamp with time zone,
    agent_flood_threshold integer,
    CONSTRAINT chats_agent_flood_threshold_positive CHECK (((agent_flood_threshold IS NULL) OR (agent_flood_threshold >= 1))),
    CONSTRAINT chats_avatar_storage_reference_chk CHECK ((((avatar_storage_bucket_id IS NULL) AND (avatar_storage_object_name IS NULL)) OR ((avatar_storage_bucket_id IS NOT NULL) AND (avatar_storage_object_name IS NOT NULL) AND (avatar_url IS NOT NULL) AND (avatar_storage_bucket_id = ANY (ARRAY['avatars'::text, 'chat-media'::text])) AND (avatar_storage_object_name ~ '^[A-Za-z0-9._~-]+(?:/[A-Za-z0-9._~-]+)*$'::text)))),
    CONSTRAINT chats_join_mode_chk CHECK ((join_mode = ANY (ARRAY['open'::text, 'approval'::text, 'invite_only'::text]))),
    CONSTRAINT chats_kind_chk CHECK ((kind = ANY (ARRAY['dm'::text, 'group'::text, 'ai'::text, 'topic'::text]))),
    CONSTRAINT chats_status_check CHECK ((status = ANY (ARRAY['active'::text, 'stopped'::text, 'paused'::text, 'archived'::text]))),
    CONSTRAINT chats_topic_source_chk CHECK ((((kind = 'topic'::text) AND (source_chat_id IS NOT NULL) AND (source_message_id IS NOT NULL)) OR ((kind <> 'topic'::text) AND (source_chat_id IS NULL) AND (source_message_id IS NULL))))
);

