--

COMMENT ON FUNCTION chat.agent_flood_threshold_effective(chat.chats) IS 'chats 的计算列:界面读 agent_flood_threshold_effective 就拿到继承后的数,❌ 不在客户端重写 COALESCE。';


--
-- Name: agent_flood_threshold_for(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.agent_flood_threshold_for(p_chat_id text) RETURNS integer
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT COALESCE(
        c.agent_flood_threshold,
        (SELECT src.agent_flood_threshold FROM chat.chats src WHERE src.id = c.source_chat_id),
        5  -- 产品默认。spec 原话就是这个数:「agent 超过 5 个会转为全员 passive」。
    )
    FROM chat.chats c
    WHERE c.id = p_chat_id
      -- 与第九轮同一条纪律:DEFINER 的探针 ❌ 不许「传谁的 id 都行」。
      -- 服务端(触发器,auth.uid() 为空)放行;登录用户必须自己看得见这条线。
      AND ((SELECT auth.uid()) IS NULL OR chat.is_member(c.id) OR chat.can_see_topic(c.id));
$$;


--
-- Name: FUNCTION agent_flood_threshold_for(p_chat_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.agent_flood_threshold_for(p_chat_id text) IS '这条线实际生效的 agent 数量线。继承链只在这里实现一次:自己填的 → 来源那条线填的 → 5。';


--
-- Name: announce_group_member_joins(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.announce_group_member_joins() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_batch      RECORD;
    v_message_id TEXT;
BEGIN
    FOR v_batch IN
        WITH joined AS (
            SELECT j.chat_id, j.user_id, j.joined_at,
                   COALESCE(NULLIF(trim(u.display_name), ''), '新成员') AS name,
                   row_number() OVER (PARTITION BY j.chat_id ORDER BY j.joined_at, j.user_id) AS n
            FROM new_members j
            JOIN chat.chats c ON c.id = j.chat_id
            LEFT JOIN identity.users u ON u.id = j.user_id
            WHERE c.kind = 'group'
              -- 与建群同一个事务写进来的是初始成员(create_gugu_group 等都是一个事务建群带人)。
              AND c.created_at IS DISTINCT FROM now()
        )
        SELECT chat_id,
               array_agg(user_id ORDER BY n) AS user_ids,
               string_agg(name, '、' ORDER BY n) AS names
        FROM joined
        GROUP BY chat_id, (n - 1) / 20
        ORDER BY chat_id, min(n)
    LOOP
        v_message_id := gen_random_uuid()::text;
        INSERT INTO chat.messages (id, chat_id, sender_user_id, content, content_type, client_message_id)
        VALUES (
            v_message_id,
            v_batch.chat_id,
            NULL,
            v_batch.names || ' 加入了群聊',
            'system',
            'member-joined:' || v_message_id || ':' || array_to_string(v_batch.user_ids, ',')
        );
    END LOOP;
    RETURN NULL;
END;
$$;


