COMMENT ON FUNCTION chat.announce_group_member_joins() IS '#6386 有人入群(不含建群时的初始成员)→ 一行系统消息「X 加入了群聊」;入群者 id 编在 client_message_id(member-joined:<消息 id>:<uid>,…),客户端据此画可点的 @。';


--
-- Name: append_user_revision(text, text, jsonb, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.append_user_revision(p_user_id text, p_event text, p_resource_key jsonb, p_tombstone boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    next_revision BIGINT;
BEGIN
    IF p_user_id IS NULL OR btrim(p_user_id) = '' THEN
        RAISE EXCEPTION 'revision user id is required';
    END IF;
    IF p_event IS NULL OR btrim(p_event) = '' THEN
        RAISE EXCEPTION 'revision event is required';
    END IF;
    IF p_event NOT IN (
      'agent_changed',
      'chat_changed',
      'chat_members_changed',
      'chat_meta_changed',
      'delivery_changed',
      'device_changed',
      'friend_requests_changed',
      'friendship_changed',
      'group_collab_changed',
      'group_invitations_changed',
      'gugu_decision_event',
      'member_read_changed',
      'member_stream_read_changed',
      'message_created',
      'message_deleted',
      'presence_changed',
      'reaction_changed',
      'workspace_changed'
    ) THEN
        RAISE EXCEPTION 'unsupported account revision event %', p_event;
    END IF;
    IF p_resource_key IS NULL OR jsonb_typeof(p_resource_key) <> 'object' THEN
        RAISE EXCEPTION 'revision resource key must be an object';
    END IF;

    INSERT INTO chat.account_revision_heads (user_id, revision, updated_at)
    VALUES (p_user_id, 1, now())
    ON CONFLICT (user_id) DO UPDATE
       SET revision = chat.account_revision_heads.revision + 1,
           updated_at = now()
    RETURNING revision INTO next_revision;

    INSERT INTO chat.account_revisions (user_id, revision, event, resource_key, tombstone)
    VALUES (p_user_id, next_revision, p_event, p_resource_key, COALESCE(p_tombstone, false));
    RETURN next_revision;
END;
$$;


--
-- Name: apply_agent_flood_rule(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.apply_agent_flood_rule(p_chat_id text, p_joined_user_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_kind TEXT;
    v_tuned TIMESTAMPTZ;
    v_threshold INTEGER;
    v_agent_count INTEGER;
    v_changed JSONB;
    v_where TEXT;
    v_message_id TEXT := gen_random_uuid()::text;
BEGIN
    SELECT c.kind, c.agent_flood_tuned_at INTO v_kind, v_tuned
    FROM chat.chats c WHERE c.id = p_chat_id FOR NO KEY UPDATE;

    -- 群和话题都算。单聊没有「一群 agent 抢答」这回事(就俩人),所以不进来。
    IF v_kind IS NULL OR v_kind NOT IN ('group', 'topic') THEN
        RETURN;
    END IF;

    IF v_tuned IS NOT NULL THEN
        -- 这条线已经在规矩里了。规矩管的是这条线,不是过线那一秒在场的那几个 ⇒ 后来的人照办。
        -- ❌ 只管刚进来的这一个,不重扫全场:用户手动调回 active 的那几个是他的决定。
        IF p_joined_user_id IS NOT NULL THEN
            PERFORM chat.enforce_agent_flood_passive(p_chat_id, ARRAY[p_joined_user_id]);
        END IF;
        RETURN;
    END IF;

    v_threshold := chat.agent_flood_threshold_for(p_chat_id);
    IF v_threshold IS NULL THEN
        RETURN;
    END IF;

    SELECT count(*) INTO v_agent_count
    FROM chat.chat_members cm
    JOIN identity.users u ON u.id = cm.user_id AND u.type = 'agent'
    WHERE cm.chat_id = p_chat_id;

    IF v_agent_count <= v_threshold THEN
        RETURN;
    END IF;

    -- 台账只记真的会被改动的那几个(已经是 passive 的不算「改了」)。
    -- ❌ 这份名单**不进正文** —— 它的用途是「一键全撤」时照着还原。
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'user_id', cm.user_id,
        'previous_listen_mode', cm.listen_mode
    ) ORDER BY cm.user_id), '[]'::jsonb)
    INTO v_changed
    FROM chat.chat_members cm
    JOIN identity.users u ON u.id = cm.user_id AND u.type = 'agent'
    WHERE cm.chat_id = p_chat_id
      AND cm.listen_mode <> 'passive';

    -- 闸门无论如何都落:哪怕这次一个都不用改,这条线也不该再被自动**重扫**第二次。
    UPDATE chat.chats SET agent_flood_tuned_at = now() WHERE id = p_chat_id;

    IF jsonb_array_length(v_changed) = 0 THEN
        RETURN;
    END IF;

    v_where := CASE WHEN v_kind = 'topic' THEN '这条话题' ELSE '这个群' END;

    INSERT INTO chat.messages (id, chat_id, sender_user_id, content, content_type, client_message_id)
    VALUES (
        v_message_id,
        p_chat_id,
        NULL,
        v_where || '里 agent 较多,已把它们都转为被动模式,@ 它们才会回。',
        'system',
        'agent-flood:' || v_message_id
    );

    -- The message trigger snapshots the pre-transition mode. Both writes become visible
    -- together at commit; readers never have to race the subsequent mode update.
    UPDATE chat.chat_members cm
    SET listen_mode = 'passive', updated_at = now()
    WHERE cm.chat_id = p_chat_id
      AND cm.listen_mode <> 'passive'
      AND EXISTS (SELECT 1 FROM identity.users u WHERE u.id = cm.user_id AND u.type = 'agent');

    INSERT INTO chat.agent_flood_adjustments (chat_id, message_id, changed, agent_count)
    VALUES (p_chat_id, v_message_id, v_changed, v_agent_count);
END;
$$;


--
-- Name: FUNCTION apply_agent_flood_rule(p_chat_id text, p_joined_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.apply_agent_flood_rule(p_chat_id text, p_joined_user_id text) IS '第一次过线:整条线转 passive + 一条只说一句的系统消息 + 可一键全撤的台账。闸门落过之后再有人进来,交给 enforce_agent_flood_passive 只管新来的那一个。';


--
-- Name: apply_group_stop_decision_status(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.apply_group_stop_decision_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    target_status TEXT;
BEGIN
    IF NEW.event_type <> 'group_stop' OR NEW.status <> 'settled' THEN
        RETURN NEW;
    END IF;

    IF NEW.final_decision <> 'approved' THEN
        RETURN NEW;
    END IF;

    target_status := NEW.final_resource_states ->> 'group';
    IF target_status NOT IN ('stopped', 'active') THEN
        RETURN NEW;
    END IF;

    UPDATE chat.chats
    SET status = target_status,
        updated_at = now()
    WHERE id = NEW.chat_id
      AND status IS DISTINCT FROM target_status;

    RETURN NEW;
END;
$$;


--
-- Name: assign_message_seq(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.assign_message_seq() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
DECLARE
    v_seq BIGINT;
BEGIN
    UPDATE chat.chats
    SET next_message_seq = next_message_seq + 1
    WHERE id = NEW.chat_id
    RETURNING next_message_seq - 1 INTO v_seq;

    IF v_seq IS NULL THEN
        RAISE EXCEPTION 'chat not found: %', NEW.chat_id;
    END IF;

    NEW.seq := v_seq;
    RETURN NEW;
END;
$$;


