--

CREATE FUNCTION chat.attachment_caption_suffix(p_caption text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT CASE WHEN NULLIF(regexp_replace(COALESCE(p_caption, ''), '^\s+|\s+$', '', 'g'), '') IS NULL THEN ''
                ELSE E'\n[Caption]\n' || regexp_replace(p_caption, '^\s+|\s+$', '', 'g') END;
$_$;


--
-- Name: is_strict_legacy_chat_media_attachment(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_strict_legacy_chat_media_attachment(p_content text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
    SELECT CASE
        WHEN cardinality(parts) <> 4 THEN false
        WHEN left(parts[1], length('[附件] ')) <> '[附件] '
             OR length(parts[1]) = length('[附件] ') THEN false
        WHEN parts[2] !~
             '^[[]URL[]] https?://[A-Za-z0-9.-]+(:[0-9]{1,5})?/storage/v1/object/public/chat-media/[A-Za-z0-9._~-]+(/[A-Za-z0-9._~-]+)*$'
             THEN false
        WHEN left(parts[3], length('[Size] ')) <> '[Size] '
             OR substring(parts[3] FROM length('[Size] ') + 1) !~ '^(0|[1-9][0-9]*)$'
             THEN false
        ELSE parts[4] IN ('[Kind] image', '[Kind] file')
    END
    FROM (SELECT string_to_array(p_content, E'\n') AS parts) parsed;
$_$;


--
-- Name: message_reply_preview_for(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_reply_preview_for(p_message_id text, p_viewer_user_id text) RETURNS TABLE(reply_to_message_id text, reply_to_sender_user_id text, reply_to_sender_name text, reply_to_content text)
    LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    -- 判「你有没有资格以这个 viewer 提问」。答不上来就一行都不给(与 message_visible_to 同形,fail-closed)。
    IF chat.is_acting_as(p_viewer_user_id) IS NOT TRUE THEN
        RETURN;
    END IF;
    RETURN QUERY SELECT r.* FROM chat.message_reply_preview_row(p_message_id, p_viewer_user_id) r;
END;
$$;


--
-- Name: is_valid_avatar_url(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.is_valid_avatar_url(p_avatar text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
    SELECT p_avatar IS NOT NULL
       AND btrim(p_avatar) <> ''
       AND (
            btrim(p_avatar) ~ '^(\./|/)assets/app/(gugu-icon-512|gugu-mark-transparent)\.png$'
         OR btrim(p_avatar) ~ '^https?://'
       );
$_$;


