--
-- Name: messages; Type: TABLE; Schema: chat; Owner: -
--

CREATE TABLE chat.messages (
    id text NOT NULL,
    chat_id text NOT NULL,
    sender_user_id text,
    seq bigint DEFAULT 0 NOT NULL,
    content text,
    content_type text DEFAULT 'text'::text NOT NULL,
    client_message_id text,
    reply_to_message_id text,
    forwarded_from_message_id text,
    thread_root_id text,
    deleted_for_user_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    deleted_at timestamp with time zone,
    edited_at timestamp with time zone,
    retracted_at timestamp with time zone,
    search_vector tsvector,
    encrypted_content bytea,
    encryption_key_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    to_user_ids text[],
    is_whisper boolean DEFAULT false NOT NULL,
    is_thread_root boolean DEFAULT false NOT NULL,
    storage_bucket_id text,
    storage_object_name text,
    ingest_seq bigint NOT NULL,
    via_app text,
    file_item_id uuid,
    file_version integer,
    sent_by_agent boolean DEFAULT false NOT NULL,
    file_blob_id uuid,
    CONSTRAINT messages_content_type_chk CHECK ((content_type = ANY (ARRAY['text'::text, 'card'::text, 'system'::text, 'attachment'::text, 'widget'::text]))),
    CONSTRAINT messages_storage_reference_chk CHECK ((((storage_bucket_id IS NULL) AND (storage_object_name IS NULL) AND (NOT ((content_type = 'attachment'::text) AND chat.is_strict_legacy_chat_media_attachment(content)))) OR ((storage_bucket_id IS NOT NULL) AND (storage_object_name IS NOT NULL) AND (content_type = 'attachment'::text) AND (storage_bucket_id = 'chat-media'::text) AND (storage_object_name ~ '^[A-Za-z0-9._~-]+(?:/[A-Za-z0-9._~-]+)*$'::text)))),
    CONSTRAINT messages_whisper_directed_chk CHECK (((NOT is_whisper) OR ((to_user_ids IS NOT NULL) AND (array_length(to_user_ids, 1) > 0) AND (NOT ('*'::text = ANY (to_user_ids))))))
);

ALTER TABLE ONLY chat.messages REPLICA IDENTITY FULL;


