-- Name: COLUMN users.category; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.users.category IS '仅 type=agent 行有效；值域对应 Bloome MARKETPLACE_CATEGORIES 9 分类（#902）';


--
-- Name: messages_view; Type: VIEW; Schema: chat; Owner: -
--

CREATE VIEW chat.messages_view WITH (security_invoker='true') AS
 SELECT m.id,
    m.chat_id,
    m.sender_user_id,
    m.to_user_ids,
    COALESCE(su.display_name, '未知用户'::text) AS sender_name,
    su.avatar AS sender_avatar,
    m.seq,
    m.content,
    m.content_type,
    m.reply_to_message_id,
    rp.reply_to_sender_user_id,
    rp.reply_to_sender_name,
    rp.reply_to_content,
    m.deleted_at,
    m.deleted_for_user_ids,
    m.retracted_at,
    m.created_at,
    m.forwarded_from_message_id,
    m.thread_root_id,
    m.edited_at,
    m.is_whisper,
    m.is_thread_root,
    m.client_message_id,
    COALESCE((m.client_message_id ~ '^session-import-root:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'::text), false) AS is_imported_history_root,
    m.via_app,
    m.file_item_id,
    m.file_version,
    m.sent_by_agent,
        CASE
            WHEN (m.sender_user_id = ( SELECT (auth.uid())::text AS uid)) THEN ( SELECT jsonb_build_object('id', a.agent_user_id, 'name', a.agent_name) AS jsonb_build_object
               FROM chat.message_agent_sends a
              WHERE ((a.message_id = m.id) AND (a.owner_user_id = ( SELECT (auth.uid())::text AS uid))))
            ELSE NULL::jsonb
        END AS agent_sender,
    m.file_blob_id
   FROM ((chat.messages m
     LEFT JOIN identity.users su ON ((su.id = m.sender_user_id)))
     LEFT JOIN LATERAL chat.message_reply_preview_for(m.reply_to_message_id, ( SELECT (auth.uid())::text AS uid)) rp(reply_to_message_id, reply_to_sender_user_id, reply_to_sender_name, reply_to_content) ON (true));


--
-- Name: attachment_commit(text, text, text, text, text, text[], text, text, boolean, boolean, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_commit(p_staging_key text, p_message_id text, p_chat_id text, p_sender_user_id text, p_file_name text, p_to_user_ids text[] DEFAULT '{}'::text[], p_reply_to_message_id text DEFAULT NULL::text, p_thread_root_id text DEFAULT NULL::text, p_is_thread_root boolean DEFAULT false, p_is_whisper boolean DEFAULT false, p_via_app text DEFAULT NULL::text, p_caption text DEFAULT NULL::text) RETURNS SETOF chat.messages_view
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_placed RECORD;
BEGIN
    SELECT * INTO v_placed FROM chat.attachment_place(p_staging_key, p_chat_id, p_sender_user_id, p_file_name, p_message_id, COALESCE(p_is_whisper, false));
    RETURN QUERY
    SELECT * FROM chat.send_message_idempotent(
        p_message_id, p_chat_id, p_sender_user_id, COALESCE(p_to_user_ids, '{}'), v_placed.envelope || chat.attachment_caption_suffix(p_caption), 'attachment',
        p_reply_to_message_id, p_thread_root_id, COALESCE(p_is_thread_root, false), COALESCE(p_is_whisper, false), p_via_app,
        v_placed.item_id, v_placed.item_version, NULL, v_placed.file_blob_id);
END;
$$;


--
-- Name: attachment_envelope(text, bigint, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_envelope(p_name text, p_size bigint, p_content_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT '[附件] ' || p_name || CASE WHEN COALESCE(p_content_type, '') = '' THEN '' ELSE ' (' || p_content_type || ')' END
        || E'\n[Size] ' || COALESCE(p_size, 0)::TEXT
        || E'\n[Kind] ' || CASE WHEN p_content_type LIKE 'image/%' THEN 'image' ELSE 'file' END;
$$;


--
-- Name: attachment_envelope_name(text, bigint, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_envelope_name(p_content text, p_size bigint, p_content_type text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_head CONSTANT TEXT := '[附件] ';
    v_tail TEXT := substr(chat.attachment_envelope('', p_size, p_content_type), char_length(v_head) + 1);
    v_name TEXT;
BEGIN
    IF p_content IS NULL OR char_length(p_content) <= char_length(v_head) + char_length(v_tail)
       OR left(p_content, char_length(v_head)) <> v_head OR right(p_content, char_length(v_tail)) <> v_tail THEN
        RETURN NULL;
    END IF;
    v_name := substr(p_content, char_length(v_head) + 1, char_length(p_content) - char_length(v_head) - char_length(v_tail));
    IF v_name ~ '[\n\r]' THEN
        RETURN NULL;
    END IF;
    RETURN v_name;
END;
$$;


--
-- Name: attachment_forward(text, text, text, text, text[], text, boolean, boolean, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_forward(p_source_message_id text, p_message_id text, p_chat_id text, p_sender_user_id text, p_to_user_ids text[] DEFAULT '{}'::text[], p_thread_root_id text DEFAULT NULL::text, p_is_thread_root boolean DEFAULT false, p_is_whisper boolean DEFAULT false, p_staging_key text DEFAULT NULL::text) RETURNS SETOF chat.messages_view
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
    v_placed RECORD;
    v_source_text TEXT;
    v_legacy RECORD;
    v_caption TEXT;
BEGIN
    -- 先以调用者的身份读原消息(消息表的 RLS:看不到的历史、没发给你的悄悄话都读不到),与客户端 forwardCanonicalMessage
    -- 同一条判据(gugu apps/desktop/src/lib/chatCanonicalStorage.ts):读的是登录的那个人,以自己的 agent 转也一样。
    -- 撤回的由 definer 那一半拒(新式),老式的由 attachment_legacy_source 拒。
    SELECT m.content INTO v_source_text FROM chat.messages m WHERE m.id = p_source_message_id AND m.deleted_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING HINT = 'attachment_source_not_found',
            MESSAGE = format('message %s is not one you can read', p_source_message_id);
    END IF;
    SELECT * INTO v_legacy FROM chat.attachment_legacy_source(p_source_message_id);
    IF FOUND THEN
        -- 老式附件:字节由边缘函数从 chat-media 读出来、登记成这次的上传(p_staging_key);放进目标会话和提交同一步。
        IF p_staging_key IS NULL THEN
            RAISE EXCEPTION USING HINT = 'attachment_forward_needs_bytes',
                MESSAGE = format('message %s is an old attachment: forward it through attachments/forward, which brings its bytes', p_source_message_id);
        END IF;
        SELECT * INTO v_placed FROM chat.attachment_place(p_staging_key, p_chat_id, p_sender_user_id, v_legacy.file_name, p_message_id, COALESCE(p_is_whisper, false));
        v_caption := chat.attachment_caption_of(v_source_text);
        IF v_caption = '' AND split_part(v_source_text, E'\n', 2) LIKE '[语音] durationMs=%' THEN
            v_caption := chat.attachment_caption_suffix(substr(v_source_text, strpos(v_source_text, E'\n') + 1));
        END IF;
    ELSE
        IF p_staging_key IS NOT NULL THEN
            RAISE EXCEPTION USING HINT = 'file_place_invalid',
                MESSAGE = format('message %s is not an old attachment: it is forwarded without an upload', p_source_message_id);
        END IF;
        SELECT * INTO v_placed FROM chat.attachment_place_forward(p_source_message_id, p_chat_id, p_sender_user_id, p_message_id, COALESCE(p_is_whisper, false));
        v_caption := chat.attachment_caption_of(v_source_text);
    END IF;
    RETURN QUERY
    SELECT * FROM chat.send_message_idempotent(
        p_message_id, p_chat_id, p_sender_user_id, COALESCE(p_to_user_ids, '{}'), v_placed.envelope || v_caption, 'attachment',
        NULL, p_thread_root_id, COALESCE(p_is_thread_root, false), COALESCE(p_is_whisper, false), NULL,
        v_placed.item_id, v_placed.item_version, p_source_message_id, v_placed.file_blob_id);
END;
$$;


--
-- Name: workspace_items; Type: TABLE; Schema: chat; Owner: -
--

CREATE TABLE chat.workspace_items (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    chat_id text NOT NULL,
    kind text DEFAULT 'document'::text NOT NULL,
    filename text DEFAULT ''::text NOT NULL,
    content_type text DEFAULT 'text/markdown'::text NOT NULL,
    size_bytes bigint,
    inline_text text,
    source_message_ids text[] DEFAULT '{}'::text[] NOT NULL,
    created_by text,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ystate bytea,
    epoch integer DEFAULT 0 NOT NULL,
    app_publisher text,
    app_id text,
    last_writer text,
    parent_id uuid,
    system_role text,
    name_key text GENERATED ALWAYS AS (lower(filename)) STORED,
    blob_id uuid,
    CONSTRAINT workspace_items_app_chk CHECK ((((app_publisher IS NULL) = (app_id IS NULL)) AND ((app_publisher IS NULL) OR (app_publisher = 'gugu'::text) OR (app_publisher ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text)) AND ((app_id IS NULL) OR (app_id ~ '^[a-z0-9][a-z0-9-]{1,63}$'::text)))),
    CONSTRAINT workspace_items_folder_shape_chk CHECK (
CASE
    WHEN (kind = 'folder'::text) THEN ((blob_id IS NULL) AND (inline_text IS NULL))
    ELSE (system_role IS NULL)
END),
    CONSTRAINT workspace_items_kind_chk CHECK ((kind = ANY (ARRAY['document'::text, 'file'::text, 'folder'::text]))),
    CONSTRAINT workspace_items_last_writer_chk CHECK (((last_writer IS NULL) OR (last_writer ~ '^(gugu|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/[a-z0-9][a-z0-9-]{1,63}@[0-9]+\.[0-9]+\.[0-9]+$'::text))),
    CONSTRAINT workspace_items_system_role_chk CHECK (
CASE
    WHEN (system_role IS NULL) THEN true
    WHEN (system_role = 'attachments'::text) THEN ((kind = 'folder'::text) AND (parent_id IS NULL))
    ELSE false
END)
);

ALTER TABLE ONLY chat.workspace_items REPLICA IDENTITY FULL;


--
-- Name: TABLE workspace_items; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON TABLE chat.workspace_items IS 'Workspace artifact 仓库：群内文档/文件 artifact，agent 或用户均可创建。';


--
-- Name: COLUMN workspace_items.kind; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.kind IS '''document'' = 内联 markdown/MDX 文档；''file'' = 存储桶文件指针';


--
-- Name: COLUMN workspace_items.inline_text; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.inline_text IS '可读内容。建文件时客户端写初始正文(INSERT);之后只由文件服务(gugu_files)写,与 ystate、size_bytes 同一条 UPDATE。';


--
-- Name: COLUMN workspace_items.source_message_ids; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.source_message_ids IS '溯源：生成/引用该 artifact 的消息 UUID 列表';


--
-- Name: COLUMN workspace_items.version; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.version IS '乐观版本号；每次 UPDATE 由应用层递增（version = version + 1）';


--
-- Name: COLUMN workspace_items.ystate; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.ystate IS '文件服务的 Yjs 状态;与 inline_text、size_bytes 同一条 UPDATE 写入。NULL = 从没被打开过。只由 gugu_files 写。';


--
-- Name: COLUMN workspace_items.epoch; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.epoch IS '代号:文档名 <id>@<epoch>。冷压缩重建 ystate 时 +1,拿旧代号的连接被拒后重载。只由 gugu_files 写。';


--
-- Name: COLUMN workspace_items.app_publisher; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.app_publisher IS '第 3 件:这个文件用哪个 App 打开(与 app_id 一起;NULL = 没有,用默认的工作区 App)。只由确定的操作写:App 建自己的数据文件、「打开方式 → 始终用它」、「不再固定」。';


--
-- Name: COLUMN workspace_items.app_id; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.app_id IS '第 3 件:见 app_publisher。';


--
-- Name: COLUMN workspace_items.last_writer; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.last_writer IS '第 3 件:最近一次写这个文件的 App,<发布者>/<id>@<版本>;宿主在 App 写入时盖。App 读它与自己的版本比,怎么处理由 App 自己定。';


--
-- Name: COLUMN workspace_items.parent_id; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.parent_id IS '所在的文件夹(同一个对话里 kind = ''folder'' 的一行);NULL = 根。外键 NO ACTION:非空文件夹只能经 workspace_delete_as 整棵删。';


--
-- Name: COLUMN workspace_items.system_role; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.system_role IS '系统文件夹的身份:''attachments'' = 「附件」。只能在根上、一个对话一个;不能改名、移动、删除。显示名由界面按它本地化;根上「附件」这个名字留给它。';


--
-- Name: COLUMN workspace_items.name_key; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.name_key IS '不分大小写比名字用的 lower(filename);唯一索引 (chat_id, parent_id, name_key):同一个文件夹里不许重名。';


--
-- Name: COLUMN workspace_items.blob_id; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.workspace_items.blob_id IS '这个文件现在的内容是哪个 blob(chat.file_blobs);workspace 桶里的老对象,它的对象名由 chat.file_blob_pointer 推。客户端写不了。';


--
-- Name: attachment_item_for(text, uuid, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_item_for(p_chat_id text, p_blob_id uuid, p_file_name text, p_sender_user_id text, p_message_id text) RETURNS chat.workspace_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_blob chat.file_blobs%ROWTYPE;
    v_folder UUID;
    v_stored TEXT := chat.workspace_stored_name(p_file_name);
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    PERFORM chat.file_blob_take(p_blob_id);
    SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = p_blob_id;
    v_folder := chat.workspace_system_folder(p_chat_id, 'attachments');
    SELECT * INTO v_item FROM chat.workspace_items w
     WHERE w.chat_id = p_chat_id AND w.parent_id = v_folder AND w.kind = 'file' AND w.blob_id = p_blob_id
       AND chat.workspace_same_series(w.name_key, v_stored)
     ORDER BY w.created_at, w.id
     LIMIT 1
       FOR UPDATE;
    IF FOUND THEN
        UPDATE chat.workspace_items w
           SET source_message_ids = CASE WHEN p_message_id = ANY (w.source_message_ids) THEN w.source_message_ids
                                         ELSE array_append(w.source_message_ids, p_message_id) END
         WHERE w.id = v_item.id
        RETURNING * INTO v_item;
        RETURN v_item;
    END IF;
    INSERT INTO chat.workspace_items AS w (chat_id, parent_id, kind, filename, content_type, size_bytes, blob_id, source_message_ids, created_by, version)
    VALUES (p_chat_id, v_folder, 'file', v_stored, v_blob.content_type, v_blob.size_bytes, v_blob.id, ARRAY[p_message_id], p_sender_user_id, 1)
    RETURNING * INTO v_item;
    RETURN v_item;
END;
$$;


--
-- Name: attachment_legacy_source(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_legacy_source(p_source_message_id text) RETURNS TABLE(object_name text, file_name text, content_type text)
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
DECLARE
    v_object TEXT;
    v_header TEXT;
    v_match TEXT[];
BEGIN
    -- 消息表的 RLS 照调用者:看不到的历史、没发给自己的悄悄话都读不到 ⇒ 没有行(和 attachment_forward 读原消息同一条判据)。
    SELECT m.storage_object_name, split_part(m.content, E'\n', 1) INTO v_object, v_header
      FROM chat.messages m
     WHERE m.id = p_source_message_id AND m.deleted_at IS NULL AND m.retracted_at IS NULL
       AND m.content_type = 'attachment' AND m.storage_bucket_id = 'chat-media'
       AND m.file_item_id IS NULL AND m.file_blob_id IS NULL;
    IF NOT FOUND OR v_header NOT LIKE '[附件] %' THEN
        RETURN;
    END IF;
    -- 首行「[附件] 名字 (类型)」,类型可以没有(客户端 formatAttachmentMetadata 写的就是这个形状)。
    v_match := regexp_match(v_header, '^\[附件\] (.+) \(([^()]*)\)$');
    RETURN QUERY SELECT v_object,
        COALESCE(v_match[1], substr(v_header, 6)),
        NULLIF(v_match[2], '');
END;
$_$;


--
-- Name: attachment_place(text, text, text, text, text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_place(p_staging_key text, p_chat_id text, p_sender_user_id text, p_file_name text, p_message_id text, p_is_whisper boolean DEFAULT false) RETURNS TABLE(item_id uuid, item_version integer, envelope text, file_blob_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_upload chat.file_blob_uploads%ROWTYPE;
    v_item chat.workspace_items%ROWTYPE;
    v_blob chat.file_blobs%ROWTYPE;
    v_envelope TEXT;
BEGIN
    PERFORM chat.attachment_sender_check(p_chat_id, p_sender_user_id);
    IF NULLIF(p_message_id, '') IS NULL THEN
        RAISE EXCEPTION 'attachment_commit: a message id is required';
    END IF;
    SELECT * INTO v_upload FROM chat.file_blob_uploads u WHERE u.staging_key = p_staging_key FOR UPDATE;
    IF NOT FOUND OR v_upload.uploader IS DISTINCT FROM (SELECT auth.uid()::text) OR v_upload.expires_at <= now() THEN
        RAISE EXCEPTION USING HINT = 'attachment_upload_not_found',
            MESSAGE = format('no upload %s of yours is waiting to be sent', p_staging_key);
    END IF;
    IF v_upload.message_id IS NOT NULL THEN
        IF v_upload.message_id IS DISTINCT FROM p_message_id THEN
            RAISE EXCEPTION USING HINT = 'attachment_upload_used',
                MESSAGE = format('upload %s was already sent as message %s', p_staging_key, v_upload.message_id);
        END IF;
        -- 同一条消息重试:同一个条目、同一版、同一段正文(发消息那一步按它们重放)。
        RETURN QUERY SELECT v_upload.item_id, v_upload.item_version, v_upload.envelope,
                            CASE WHEN v_upload.item_id IS NULL THEN v_upload.blob_id END;
        RETURN;
    END IF;
    -- ◇ 悄悄话:不进群文件夹(那里全员看得见),消息直接指这份字节。名字照文件夹里的规矩规范化(不含换行)。
    IF COALESCE(p_is_whisper, false) THEN
        PERFORM chat.file_blob_take(v_upload.blob_id);
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = v_upload.blob_id;
        v_envelope := chat.attachment_envelope(chat.workspace_stored_name(p_file_name), v_blob.size_bytes, v_blob.content_type);
        UPDATE chat.file_blob_uploads u SET message_id = p_message_id, envelope = v_envelope WHERE u.staging_key = p_staging_key;
        RETURN QUERY SELECT NULL::UUID, NULL::INTEGER, v_envelope, v_upload.blob_id;
        RETURN;
    END IF;
    v_item := chat.attachment_item_for(p_chat_id, v_upload.blob_id, p_file_name, p_sender_user_id, p_message_id);
    v_envelope := chat.workspace_version_envelope(v_item.id, v_item.version);
    UPDATE chat.file_blob_uploads u
       SET message_id = p_message_id, item_id = v_item.id, item_version = v_item.version, envelope = v_envelope
     WHERE u.staging_key = p_staging_key;
    RETURN QUERY SELECT v_item.id, v_item.version, v_envelope, NULL::UUID;
END;
$$;


--
-- Name: attachment_place_forward(text, text, text, text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_place_forward(p_source_message_id text, p_chat_id text, p_sender_user_id text, p_message_id text, p_is_whisper boolean DEFAULT false) RETURNS TABLE(item_id uuid, item_version integer, envelope text, file_blob_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_source chat.messages%ROWTYPE;
    v_blob chat.file_blobs%ROWTYPE;
    v_blob_id UUID;
    v_name TEXT;
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    PERFORM chat.attachment_sender_check(p_chat_id, p_sender_user_id);
    SELECT * INTO v_source FROM chat.messages m WHERE m.id = p_source_message_id AND m.deleted_at IS NULL;
    IF NOT FOUND OR NOT chat.can_read_message(p_source_message_id, p_sender_user_id) THEN
        RAISE EXCEPTION USING HINT = 'attachment_source_not_found',
            MESSAGE = format('message %s is not one you can read', p_source_message_id);
    END IF;
    IF v_source.retracted_at IS NOT NULL THEN
        RAISE EXCEPTION USING HINT = 'attachment_source_retracted', MESSAGE = format('message %s was retracted', p_source_message_id);
    END IF;
    -- ◇ 字节:悄悄话附件直接指着的,或者条目钉住的那一版;名字:信封里的,或者条目现在的。
    IF v_source.file_blob_id IS NOT NULL THEN
        v_blob_id := v_source.file_blob_id;
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = v_blob_id;
        v_name := chat.attachment_envelope_name(v_source.content, v_blob.size_bytes, v_blob.content_type);
    ELSIF v_source.file_item_id IS NOT NULL THEN
        v_blob_id := chat.workspace_version_blob(v_source.file_item_id, v_source.file_version);
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = v_blob_id;
        SELECT w.filename INTO v_name FROM chat.workspace_items w WHERE w.id = v_source.file_item_id;
    ELSE
        RAISE EXCEPTION USING HINT = 'attachment_source_gone',
            MESSAGE = 'that message has no file to forward (it was deleted from its folder, or it is not an attachment)';
    END IF;
    IF v_blob_id IS NULL THEN
        RAISE EXCEPTION USING HINT = 'attachment_source_gone', MESSAGE = 'that version of the file has no bytes left';
    END IF;
    -- ◇ 转成悄悄话:指同一份字节,不进目标的文件夹。
    IF COALESCE(p_is_whisper, false) THEN
        PERFORM chat.file_blob_take(v_blob_id);
        RETURN QUERY SELECT NULL::UUID, NULL::INTEGER, chat.attachment_envelope(v_name, v_blob.size_bytes, v_blob.content_type), v_blob_id;
        RETURN;
    END IF;
    v_item := chat.attachment_item_for(p_chat_id, v_blob_id, v_name, p_sender_user_id, p_message_id);
    RETURN QUERY SELECT v_item.id, v_item.version, chat.workspace_version_envelope(v_item.id, v_item.version), NULL::UUID;
END;
$$;


--
-- Name: attachment_sender_check(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_sender_check(p_chat_id text, p_sender_user_id text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF (SELECT auth.uid()) IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF p_sender_user_id IS DISTINCT FROM (SELECT auth.uid()::text) AND NOT chat.can_act_as(p_sender_user_id, p_chat_id) THEN
        RAISE EXCEPTION 'Not allowed to act as %', COALESCE(p_sender_user_id, '<null>');
    END IF;
    PERFORM chat.workspace_require_room_member(p_chat_id, p_sender_user_id);
END;
$$;


--
-- Name: attachment_text_envelope(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.attachment_text_envelope(p_content text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT CASE
        WHEN strpos(p_content, E'\n[Caption]\n') = 0 THEN p_content
        WHEN substr(p_content, strpos(p_content, E'\n[Caption]\n') + 11) ~ '^\S' AND substr(p_content, strpos(p_content, E'\n[Caption]\n') + 11) ~ '\S$'
            THEN left(p_content, strpos(p_content, E'\n[Caption]\n') - 1)
    END;
$_$;


--
-- Name: auto_passive_on_agent_flood(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.auto_passive_on_agent_flood() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    PERFORM chat.apply_agent_flood_rule(NEW.chat_id, NEW.user_id);
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION auto_passive_on_agent_flood(); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.auto_passive_on_agent_flood() IS '入群/入话题时过一遍数量线 —— 第一次过线全员转,之后进来的人单独照办。规则本体不在这里。';


--
-- Name: broadcast_main_stream_read_changed(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_main_stream_read_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF OLD.last_read_seq IS NOT DISTINCT FROM NEW.last_read_seq
     AND OLD.is_marked_unread IS NOT DISTINCT FROM NEW.is_marked_unread
     AND OLD.version IS NOT DISTINCT FROM NEW.version THEN
    RETURN NEW;
  END IF;
  PERFORM realtime.send(
    jsonb_build_object('member', jsonb_build_object(
      'chat_id', NEW.chat_id,
      'user_id', NEW.user_id,
      'stream_id', 'main:' || NEW.chat_id,
      'stream_kind', 'main',
      'thread_root_id', NULL,
      'last_read_seq', NEW.last_read_seq,
      'is_marked_unread', NEW.is_marked_unread,
      'version', NEW.version
    )),
    'member_stream_read_changed',
    'gugu:user:' || NEW.user_id || ':events',
    true
  );
  RETURN NEW;
END;
$$;


--
-- Name: broadcast_member_read_changed(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_member_read_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF OLD.last_read_seq IS NOT DISTINCT FROM NEW.last_read_seq THEN
        RETURN NEW;
    END IF;

    PERFORM chat.broadcast_to_chat_member_user_events(
        NEW.chat_id,
        'member_read_changed',
        jsonb_build_object(
            'member', jsonb_build_object(
                'chat_id', NEW.chat_id,
                'user_id', NEW.user_id,
                'last_read_seq', NEW.last_read_seq
            )
        )
    );
    RETURN NEW;
END;
$$;


--
-- Name: broadcast_member_stream_read_changed(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_member_stream_read_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND OLD.last_read_seq IS NOT DISTINCT FROM NEW.last_read_seq
     AND OLD.is_marked_unread IS NOT DISTINCT FROM NEW.is_marked_unread
     AND OLD.version IS NOT DISTINCT FROM NEW.version THEN
    RETURN NEW;
  END IF;
  PERFORM realtime.send(
    jsonb_build_object('member', jsonb_build_object(
      'chat_id', NEW.chat_id,
      'user_id', NEW.user_id,
      'stream_id', NEW.stream_id,
      'stream_kind', NEW.stream_kind,
      'thread_root_id', NEW.thread_root_id,
      'last_read_seq', NEW.last_read_seq,
      'is_marked_unread', NEW.is_marked_unread,
      'version', NEW.version
    )),
    'member_stream_read_changed',
    'gugu:user:' || NEW.user_id || ':events',
    true
  );
  RETURN NEW;
END;
$$;


--
-- Name: broadcast_message_created(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_message_created() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    payload JSONB;
BEGIN
    SELECT jsonb_build_object(
        'message', jsonb_build_object(
            'id', NEW.id,
            'chat_id', NEW.chat_id,
            'sender_user_id', NEW.sender_user_id,
            'to_user_ids', NEW.to_user_ids,
            'is_whisper', NEW.is_whisper,
            'sender_name', COALESCE(u.display_name, '未知用户'),
            'sender_avatar', u.avatar,
            'seq', NEW.seq,
            'content', CASE WHEN NEW.is_whisper THEN NULL ELSE NEW.content END,
            'content_type', NEW.content_type,
            'reply_to_message_id', NEW.reply_to_message_id,
            'reply_to_sender_user_id', CASE WHEN NEW.is_whisper THEN NULL ELSE rp.reply_to_sender_user_id END,
            'reply_to_sender_name', CASE WHEN NEW.is_whisper THEN NULL ELSE rp.reply_to_sender_name END,
            'reply_to_content', CASE WHEN NEW.is_whisper THEN NULL ELSE rp.reply_to_content END,
            'retracted_at', NEW.retracted_at,
            'created_at', NEW.created_at,
            'forwarded_from_message_id', NEW.forwarded_from_message_id,
            'thread_root_id', NEW.thread_root_id,
            'edited_at', NEW.edited_at,
            'is_thread_root', NEW.is_thread_root,
            'client_message_id', NEW.client_message_id
        )
    )
    INTO payload
    FROM (SELECT 1) s
    LEFT JOIN identity.users u ON u.id = NEW.sender_user_id
    LEFT JOIN LATERAL chat.message_reply_preview(NEW.reply_to_message_id) rp ON true;

    PERFORM chat.broadcast_to_chat_member_user_events(NEW.chat_id, 'message_created', payload);
    RETURN NEW;
END;
$$;


--
-- Name: broadcast_message_deleted(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_message_deleted() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
BEGIN
    -- 只在「从未删除 → 已删除」的翻转沿广播（幂等：重复置 deleted_at 不再发）。
    IF OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL THEN
        PERFORM chat.broadcast_to_chat_member_user_events(
            NEW.chat_id,
            'message_deleted',
            jsonb_build_object(
                'message', jsonb_build_object(
                    'id', NEW.id,
                    'chat_id', NEW.chat_id,
                    'deleted_at', NEW.deleted_at
                )
            )
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: broadcast_message_delivery_changed(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_message_delivery_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    target_chat_id TEXT;
BEGIN
    SELECT m.chat_id
    INTO target_chat_id
    FROM chat.messages m
    WHERE m.id = NEW.message_id
      AND m.deleted_at IS NULL;

    IF target_chat_id IS NULL THEN
        RETURN NEW;
    END IF;

    PERFORM chat.broadcast_to_chat_member_user_events(
        target_chat_id,
        'delivery_changed',
        jsonb_build_object(
            'receipt', jsonb_build_object(
                'chat_id', target_chat_id,
                'message_id', NEW.message_id,
                'device_id', NEW.device_id,
                'status', NEW.status
            )
        )
    );
    RETURN NEW;
END;
$$;


--
-- Name: broadcast_message_reaction_changed(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_message_reaction_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    affected_message_id TEXT;
    reacting_user_id    TEXT;
    reaction_emoji      TEXT;
    op_label            TEXT;
    target_chat_id      TEXT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        affected_message_id := OLD.message_id;
        reacting_user_id    := OLD.user_id;
        reaction_emoji      := OLD.emoji;
        op_label            := 'removed';
    ELSE
        affected_message_id := NEW.message_id;
        reacting_user_id    := NEW.user_id;
        reaction_emoji      := NEW.emoji;
        op_label            := 'added';
    END IF;

    SELECT m.chat_id
    INTO target_chat_id
    FROM chat.messages m
    WHERE m.id = affected_message_id;

    -- 消息不存在（理论上被 ON DELETE CASCADE 一并删则无需广播）时静默跳过。
    IF target_chat_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    PERFORM chat.broadcast_to_chat_member_user_events(
        target_chat_id,
        'reaction_changed',
        jsonb_build_object(
            'reaction', jsonb_build_object(
                'chat_id',    target_chat_id,
                'message_id', affected_message_id,
                'user_id',    reacting_user_id,
                'emoji',      reaction_emoji,
                'op',         op_label
            )
        )
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: broadcast_to_chat_member_user_events(text, text, jsonb); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.broadcast_to_chat_member_user_events(p_chat_id text, p_event text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    target_user_id TEXT;
    v_about chat.messages%ROWTYPE;
    revision_key JSONB;
    revision_tombstone BOOLEAN;
BEGIN
    PERFORM chat.lock_chat_revision_recipients(p_chat_id);
    -- #6835 关于一条悄悄话的事件(它的新建、删除、投递/已读回执、回应,以及它在话题里引起的来源线动静)
    -- 只发给看得见它的人,判据就是 chat.message_visible_to。事件说的是哪条消息:message.id / receipt.message_id /
    -- reaction.message_id,话题动静带 about_message_id。只有悄悄话才逐人判,公开消息只多一次主键查询。
    -- 只取判定要用的列:m.* 会连 content 一起解 TOAST。
    SELECT m.id, m.chat_id, m.created_at, m.is_whisper, m.sender_user_id, m.to_user_ids
      INTO v_about.id, v_about.chat_id, v_about.created_at, v_about.is_whisper, v_about.sender_user_id, v_about.to_user_ids
      FROM chat.messages m
     WHERE m.id = COALESCE(p_payload #>> '{message,id}', p_payload #>> '{receipt,message_id}',
                           p_payload #>> '{reaction,message_id}', p_payload ->> 'about_message_id')
       AND m.is_whisper;
    revision_key := jsonb_strip_nulls(jsonb_build_object(
      'chat_id', p_chat_id,
      'entity_id', COALESCE(
        p_payload #>> '{message,id}',
        p_payload #>> '{receipt,message_id}',
        p_payload #>> '{member,user_id}',
        p_payload #>> '{event,id}',
        p_payload #>> '{reaction,message_id}',
        p_payload #>> '{workspace,id}'
      ),
      -- #5649 仅 member_read_changed 带值:读者(entity_id)读到的主线 seq。
      'last_read_seq', CASE
        WHEN p_event = 'member_read_changed' THEN (p_payload #>> '{member,last_read_seq}')::bigint
        ELSE NULL
      END,
      -- #5649 仅 delivery_changed 带值:哪台设备(gugu-agent:<uid> 即 agent)把这条(entity_id)标成了 delivered/read。
      'device_id', CASE WHEN p_event = 'delivery_changed' THEN p_payload #>> '{receipt,device_id}' ELSE NULL END,
      'status',    CASE WHEN p_event = 'delivery_changed' THEN p_payload #>> '{receipt,status}'    ELSE NULL END
    ));
    revision_tombstone := p_event LIKE '%deleted'
      OR p_event LIKE '%removed'
      OR p_payload ->> 'op' IN ('delete', 'deleted', 'removed');

    FOR target_user_id IN
        SELECT DISTINCT cm.user_id
          FROM chat.chat_members cm
         WHERE cm.chat_id = p_chat_id
           AND (v_about.id IS NULL
                OR chat.message_visible_to(v_about.chat_id, v_about.created_at, v_about.is_whisper,
                                           v_about.sender_user_id, v_about.to_user_ids, cm.user_id))
         ORDER BY cm.user_id
    LOOP
        PERFORM chat.publish_user_revision(target_user_id, p_event, revision_key, revision_tombstone);
        -- Topic source-line notifications are a deliberately narrow legacy edge: the
        -- topic projection needs the source-line marker to refresh its anchor card.
        -- Keep this low-volume payload only for that shape; ordinary chat/message
        -- mutations use the durable revision wake above.
        IF p_event = 'chat_changed' AND p_payload ? 'topic_of_source_chat' THEN
            PERFORM realtime.send(
                p_payload,
                p_event,
                'gugu:user:' || target_user_id || ':events',
                true
            );
        END IF;
    END LOOP;
END;
$$;


--
-- Name: caller_may_probe_chat(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.caller_may_probe_chat(p_chat_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT (SELECT auth.uid()) IS NULL
        OR EXISTS (
            SELECT 1
              FROM chat.chat_members cm
             WHERE cm.chat_id = p_chat_id
               AND chat.is_acting_as(cm.user_id)
        )
        OR EXISTS (
            SELECT 1
              FROM chat.chats t
              JOIN chat.chat_members cm2 ON cm2.chat_id = t.source_chat_id
             WHERE t.id = p_chat_id
               AND t.kind = 'topic'
               AND t.source_chat_id IS NOT NULL
               AND chat.is_acting_as(cm2.user_id)
        );
$$;


--
-- Name: FUNCTION caller_may_probe_chat(p_chat_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.caller_may_probe_chat(p_chat_id text) IS '@@@5856 提问的人自己(或他名下的 agent)在不在这条线里 —— 主体是第三方的探针改判这个,而不是判主体。';


--
-- Name: can_act_as(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_act_as(p_sender_user_id text, p_chat_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
    SELECT COALESCE(
        (SELECT auth.uid()) IS NOT NULL
        AND chat.is_chat_member(p_chat_id, p_sender_user_id)
        AND (
            p_sender_user_id = (SELECT auth.uid()::text)
            OR EXISTS (
                SELECT 1
                FROM identity.users u
                WHERE u.id = p_sender_user_id
                  AND u.type = 'agent'
                  AND u.owner_user_id = (SELECT auth.uid()::text)
            )
        ),
        false
    );
$$;


--
-- Name: can_add_group_member(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_add_group_member(p_chat_id text, p_user_id text, p_role text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := (SELECT auth.uid()::text);
BEGIN
    IF v_actor IS NULL OR chat.group_add_denial(p_chat_id, p_user_id, v_actor) IS NOT NULL THEN
        RETURN false;
    END IF;
    RETURN CASE COALESCE(p_role, 'member')
        WHEN 'member' THEN true
        WHEN 'admin' THEN chat.can_manage_group_members(p_chat_id)
        -- owner 只有一种合法来路:创建者给自己建首座(群的 owner = 创建者,见 chats_membership_invariants)。
        WHEN 'owner' THEN p_user_id = v_actor AND chat.is_group_creator(p_chat_id)
        ELSE false
    END;
END;
$$;


--
-- Name: can_manage_group_members(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_manage_group_members(p_chat_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT COALESCE(chat.current_user_group_role(p_chat_id) IN ('owner', 'admin'), false);
$$;


--
-- Name: can_read_message(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_read_message(p_message_id text, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT chat.is_acting_as(p_user_id) AND EXISTS (
        SELECT 1
        FROM chat.messages m
        WHERE m.id = p_message_id
          AND m.deleted_at IS NULL
          AND chat.message_visible_to(
                m.chat_id, m.created_at, m.is_whisper, m.sender_user_id, m.to_user_ids, p_user_id)
    );
$$;


--
-- Name: FUNCTION can_read_message(p_message_id text, p_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.can_read_message(p_message_id text, p_user_id text) IS '某个人读不读得到某条消息 —— 与 messages_select_member 同一份判据(删除态 / 成员或话题可见 / 入群前历史 / 悄悄话)。
SECURITY DEFINER 的 RPC 要在自己身上复现「调用者看得见吗」这件事时调它,❌ 不要把策略表达式再抄一遍。';


--
-- Name: can_see_delivery_of(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_see_delivery_of(p_message_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_me TEXT := (SELECT auth.uid()::text);
BEGIN
    RETURN EXISTS (
        SELECT 1
          FROM chat.messages m
          JOIN chat.chat_members cm ON cm.chat_id = m.chat_id AND cm.user_id = v_me
         WHERE m.id = p_message_id
           AND m.deleted_at IS NULL
           AND chat.message_visible_to(m.chat_id, m.created_at, m.is_whisper, m.sender_user_id, m.to_user_ids, v_me)
    );
END;
$$;


--
-- Name: can_see_topic(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_see_topic(p_chat_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM chat.chats t
        WHERE t.id = p_chat_id
          AND t.kind = 'topic'
          AND chat.is_member(t.source_chat_id)
    );
$$;


--
-- Name: FUNCTION can_see_topic(p_chat_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.can_see_topic(p_chat_id text) IS '能看见来源线的人就看得见这条话题(spec:可见继承来源)。它只管「看得见」,不管「收不收通知」——通知只到 chat_members 里的参与者,两者严格分开。';


--
-- Name: can_see_topic_message(text, timestamp with time zone, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_see_topic_message(p_chat_id text, p_created_at timestamp with time zone, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM chat.chats t
        JOIN chat.chat_members cm
          ON cm.chat_id = t.source_chat_id
         AND cm.user_id = p_user_id
        WHERE t.id = p_chat_id
          AND t.kind = 'topic'
          AND (cm.hide_history_before IS NULL OR p_created_at >= cm.hide_history_before)
    ) AND chat.caller_may_probe_chat(p_chat_id);
$$;


--
-- Name: can_speak_in_topic(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.can_speak_in_topic(p_chat_id text, p_sender_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT COALESCE(
        chat.can_see_topic(p_chat_id)
        AND (
            p_sender_user_id = (SELECT auth.uid()::text)
            OR EXISTS (
                SELECT 1 FROM identity.users u
                WHERE u.id = p_sender_user_id
                  AND u.type = 'agent'
                  AND u.owner_user_id = (SELECT auth.uid()::text)
            )
        ),
        false
    );
$$;


--
-- Name: chat_facts(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.chat_facts(p_chat_id text, p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(id text, kind text, source_chat_id text, group_prompt text, public_id integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_caller TEXT := (SELECT auth.uid()::text);
    v_actor TEXT;
    v_is_agent BOOLEAN;
    v_owner TEXT;
BEGIN
    v_actor := COALESCE(NULLIF(trim(p_as_user_id), ''), v_caller);
    SELECT u.type = 'agent', u.owner_user_id INTO v_is_agent, v_owner
      FROM identity.users u WHERE u.id = v_actor;
    IF v_actor IS DISTINCT FROM v_caller AND NOT (COALESCE(v_is_agent, false) AND v_owner = v_caller) THEN
        RAISE EXCEPTION 'Not allowed to act as %', v_actor;
    END IF;

    RETURN QUERY
    SELECT c.id, c.kind, c.source_chat_id, c.group_prompt, c.public_id
      FROM chat.chats c
     WHERE c.id = p_chat_id
       AND (
           chat.is_chat_member(c.id, v_actor)
           -- 主人看得见的,替他办事的 agent 也读得到(这就是它替换掉的那条裸读的可见域)。
           OR chat.is_chat_member(c.id, v_caller)
           -- 可见继承来源:看得见来源线就看得见这条话题存在(spec)。
           OR (c.kind = 'topic' AND c.source_chat_id IS NOT NULL
               AND (chat.is_chat_member(c.source_chat_id, v_actor)
                    OR chat.is_chat_member(c.source_chat_id, v_caller)))
       );
END;
$$;


--
-- Name: chat_members_broadcast(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.chat_members_broadcast() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    affected_chat_id TEXT := COALESCE(NEW.chat_id, OLD.chat_id);
    affected_user_id TEXT := COALESCE(NEW.user_id, OLD.user_id);
    chat_kind        TEXT;
    target_user_id   TEXT;
BEGIN
    SELECT kind INTO chat_kind FROM chat.chats WHERE id = affected_chat_id;
    IF chat_kind IS NULL OR chat_kind NOT IN ('group', 'channel') THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    FOR target_user_id IN
        SELECT DISTINCT user_id
        FROM (
            SELECT cm.user_id
            FROM chat.chat_members cm
            WHERE cm.chat_id = affected_chat_id
            UNION
            SELECT affected_user_id
        ) recipients
        WHERE user_id IS NOT NULL
    LOOP
        PERFORM realtime.send(
            jsonb_build_object(
                'op', CASE TG_OP
                    WHEN 'INSERT' THEN 'joined'
                    WHEN 'DELETE' THEN 'left'
                    ELSE 'role_changed'
                END,
                'event', row_to_json(COALESCE(NEW, OLD))
            ),
            'chat_members_changed',
            'gugu:user:' || target_user_id || ':events',
            true
        );
    END LOOP;

    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: chat_members_role_user_type_chk(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.chat_members_role_user_type_chk() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    utype TEXT;
BEGIN
    SELECT type INTO utype FROM identity.users WHERE id = NEW.user_id;
    IF utype IS NULL THEN
        RAISE EXCEPTION 'user % not found in identity.users', NEW.user_id;
    END IF;
    IF NEW.role NOT IN ('owner', 'admin', 'member') THEN
        RAISE EXCEPTION 'invalid group member role %', NEW.role;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: chats_membership_invariants(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.chats_membership_invariants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    affected_chat_id TEXT := COALESCE(NEW.chat_id, OLD.chat_id);
    chat_kind TEXT;
    chat_status TEXT;
    creator_user_id TEXT;
    owner_user_id TEXT;
    owner_count INTEGER;
    owner_is_human BOOLEAN;
    member_count_val INTEGER;
BEGIN
    SELECT kind, status, chats.creator_user_id
    INTO chat_kind, chat_status, creator_user_id
    FROM chat.chats WHERE id = affected_chat_id;
    IF chat_kind IS NULL OR chat_kind <> 'group' THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    SELECT count(*), min(cm.user_id), bool_and(u.type = 'human')
    INTO owner_count, owner_user_id, owner_is_human
    FROM chat.chat_members cm
    LEFT JOIN identity.users u ON u.id = cm.user_id
    WHERE cm.chat_id = affected_chat_id AND cm.role = 'owner';
    SELECT count(*) INTO member_count_val
    FROM chat.chat_members WHERE chat_id = affected_chat_id;

    IF chat_status <> 'archived' THEN
        IF owner_count <> 1 OR NOT COALESCE(owner_is_human, false) THEN
            RAISE EXCEPTION 'non-archived group chat % must have exactly 1 human owner', affected_chat_id;
        END IF;
        IF creator_user_id IS DISTINCT FROM owner_user_id THEN
            RAISE EXCEPTION 'active group chat % creator and owner must match', affected_chat_id;
        END IF;
        IF chat_status = 'active' AND member_count_val < 2 THEN
            RAISE EXCEPTION 'active group chat % must have >= 2 members (have %)', affected_chat_id, member_count_val;
        END IF;
    ELSE
        IF owner_count > 1 OR (owner_count = 1 AND NOT COALESCE(owner_is_human, false)) THEN
            RAISE EXCEPTION 'archived group chat % cannot have invalid owners', affected_chat_id;
        END IF;
        IF (owner_count = 0 AND creator_user_id IS NOT NULL)
           OR (owner_count = 1 AND creator_user_id IS DISTINCT FROM owner_user_id) THEN
            RAISE EXCEPTION 'archived group chat % creator and owner must both be absent or match', affected_chat_id;
        END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: chats_meta_broadcast(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.chats_meta_broadcast() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.kind <> 'group' THEN RETURN NEW; END IF;

    IF NEW.status              IS DISTINCT FROM OLD.status              OR
       NEW.group_prompt        IS DISTINCT FROM OLD.group_prompt        OR
       NEW.default_agent_type  IS DISTINCT FROM OLD.default_agent_type  OR
       NEW.name                IS DISTINCT FROM OLD.name THEN
        PERFORM chat.broadcast_to_chat_member_user_events(
            NEW.id,
            'chat_meta_changed',
            jsonb_build_object('op', 'updated', 'event', row_to_json(NEW))
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: chats_status_invariants(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.chats_status_invariants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    owner_user_id TEXT;
    owner_count INTEGER;
    owner_is_human BOOLEAN;
    member_count_val INTEGER;
BEGIN
    IF NEW.kind <> 'group' THEN RETURN NEW; END IF;
    SELECT count(*), min(cm.user_id), bool_and(u.type = 'human')
    INTO owner_count, owner_user_id, owner_is_human
    FROM chat.chat_members cm
    LEFT JOIN identity.users u ON u.id = cm.user_id
    WHERE cm.chat_id = NEW.id AND cm.role = 'owner';
    SELECT count(*) INTO member_count_val FROM chat.chat_members WHERE chat_id = NEW.id;

    IF NEW.status <> 'archived'
       AND (owner_count <> 1 OR NOT COALESCE(owner_is_human, false)
            OR NEW.creator_user_id IS DISTINCT FROM owner_user_id
            OR (NEW.status = 'active' AND member_count_val < 2)) THEN
        RAISE EXCEPTION 'cannot set invalid non-archived group chat %', NEW.id;
    END IF;
    IF NEW.status = 'archived'
       AND (owner_count > 1
            OR (owner_count = 1 AND NOT COALESCE(owner_is_human, false))
            OR (owner_count = 0 AND NEW.creator_user_id IS NOT NULL)
            OR (owner_count = 1 AND NEW.creator_user_id IS DISTINCT FROM owner_user_id)) THEN
        RAISE EXCEPTION 'cannot archive group chat % with inconsistent creator/owner', NEW.id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: claim_presence_wake(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.claim_presence_wake(p_viewer_user_id text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    claimed_user_id TEXT;
BEGIN
    IF p_viewer_user_id IS NULL OR btrim(p_viewer_user_id) = '' THEN
        RAISE EXCEPTION 'presence wake viewer is required';
    END IF;
    INSERT INTO chat.presence_wake_throttles(viewer_user_id, last_sent_at)
    VALUES (p_viewer_user_id, now())
    ON CONFLICT (viewer_user_id) DO UPDATE
       SET last_sent_at = EXCLUDED.last_sent_at
     WHERE chat.presence_wake_throttles.last_sent_at <= now() - interval '2 seconds'
    RETURNING viewer_user_id INTO claimed_user_id;
    RETURN claimed_user_id IS NOT NULL;
END;
$$;


--
-- Name: cleanup_removed_group_agent(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.cleanup_removed_group_agent(p_chat_id text, p_agent_user_id text) RETURNS TABLE(states_deleted integer, members_deleted integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_chat_id TEXT := NULLIF(trim(COALESCE(p_chat_id, '')), '');
    v_agent_user_id TEXT := NULLIF(trim(COALESCE(p_agent_user_id, '')), '');
    v_states_deleted INTEGER := 0;
    v_members_deleted INTEGER := 0;
BEGIN
    IF auth.uid() IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF v_chat_id IS NULL THEN
        RAISE EXCEPTION 'chat id is required';
    END IF;

    IF v_agent_user_id IS NULL THEN
        RAISE EXCEPTION 'agent user id is required';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM chat.chats c
        WHERE c.id = v_chat_id
          AND c.kind = 'group'
    ) THEN
        RAISE EXCEPTION 'group chat not found';
    END IF;

    IF NOT chat.can_manage_group_members(v_chat_id) THEN
        RAISE EXCEPTION 'only owner/admin can cleanup removed group agents';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM identity.users u
        WHERE u.id = v_agent_user_id
    ) THEN
        RAISE EXCEPTION 'agent % still exists', v_agent_user_id;
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM chat.group_agent_states gas
        WHERE gas.chat_id = v_chat_id
          AND gas.agent_user_id = v_agent_user_id
    ) THEN
        RAISE EXCEPTION 'removed group agent residue not found';
    END IF;

    DELETE FROM chat.group_agent_states gas
    WHERE gas.chat_id = v_chat_id
      AND gas.agent_user_id = v_agent_user_id;
    GET DIAGNOSTICS v_states_deleted = ROW_COUNT;

    DELETE FROM chat.chat_members cm
    WHERE cm.chat_id = v_chat_id
      AND cm.user_id = v_agent_user_id;
    GET DIAGNOSTICS v_members_deleted = ROW_COUNT;

    states_deleted := v_states_deleted;
    members_deleted := v_members_deleted;
    RETURN NEXT;
END;
$$;


--
-- Name: clear_messages_for_me(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.clear_messages_for_me(p_chat_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
DECLARE
    v_uid TEXT := (SELECT auth.uid()::text);
BEGIN
    IF NOT chat.is_member(p_chat_id) THEN
        RAISE EXCEPTION 'not a member of chat: %', p_chat_id;
    END IF;

    UPDATE chat.messages
    SET
        deleted_for_user_ids =
            CASE
                WHEN deleted_for_user_ids @> jsonb_build_array(v_uid) THEN deleted_for_user_ids
                ELSE deleted_for_user_ids || jsonb_build_array(v_uid)
            END,
        updated_at = now()
    WHERE chat_id = p_chat_id
      AND deleted_at IS NULL;
END;
$$;


--
-- Name: create_gugu_group(text, text, text, jsonb, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.create_gugu_group(p_chat_id text, p_name text, p_owner_user_id text, p_initial_members jsonb, p_default_agent_type text DEFAULT NULL::text, p_group_prompt text DEFAULT NULL::text) RETURNS chat.chats
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    caller_user_id TEXT;
    inserted       chat.chats;
    m              JSONB;
    member_user_id TEXT;
    member_role    TEXT;
    inserted_member_count INT := 0;
    inserted_member_rows  INT := 0;
    member_denial  TEXT;
BEGIN
    caller_user_id := (SELECT auth.uid()::text);
    IF caller_user_id IS NULL OR caller_user_id <> p_owner_user_id THEN
        RAISE EXCEPTION 'caller % cannot create group on behalf of %',
                        caller_user_id, p_owner_user_id;
    END IF;

    IF p_initial_members IS NULL OR jsonb_typeof(p_initial_members) <> 'array' THEN
        RAISE EXCEPTION 'p_initial_members must be a jsonb array';
    END IF;
    IF jsonb_array_length(p_initial_members) < 1 THEN
        RAISE EXCEPTION 'Group chat requires at least one member';
    END IF;

    SET CONSTRAINTS ALL DEFERRED;

    INSERT INTO chat.chats (
        id, kind, name, status, creator_user_id,
        group_prompt, default_agent_type
    ) VALUES (
        p_chat_id, 'group', p_name, 'active', p_owner_user_id,
        p_group_prompt, p_default_agent_type
    ) RETURNING * INTO inserted;

    INSERT INTO chat.chat_members (chat_id, user_id, role)
    VALUES (p_chat_id, p_owner_user_id, 'owner');

    FOR m IN SELECT * FROM jsonb_array_elements(p_initial_members) LOOP
        member_user_id := m ->> 'user_id';
        member_role    := COALESCE(m ->> 'role', 'member');
        IF member_user_id IS NULL OR member_user_id = p_owner_user_id THEN
            CONTINUE;
        END IF;
        -- #1761 云 agent 禁入群（fail-loud，不静默跳过）
        IF chat.is_cloud_agent_user(member_user_id) THEN
            RAISE EXCEPTION 'cloud agent % cannot join groups (#1761)', member_user_id;
        END IF;
        -- 群只有一个 owner(= 创建者);初始成员只能是 member/admin。
        IF member_role NOT IN ('member', 'admin') THEN
            RAISE EXCEPTION 'initial member % cannot have role %', member_user_id, member_role;
        END IF;
        -- 与其余入口同一道「能否加此人」(调用者就是 owner:拦的是上限、身份存在、别人名下的 agent ——
        -- 别人的 agent 要走 agent 群邀请,由它的主人接受)。
        member_denial := chat.group_add_denial(p_chat_id, member_user_id, p_owner_user_id);
        IF member_denial IS NOT NULL THEN
            RAISE EXCEPTION 'cannot add % to group %: %', member_user_id, p_chat_id, member_denial;
        END IF;
        INSERT INTO chat.chat_members (chat_id, user_id, role)
        VALUES (p_chat_id, member_user_id, member_role)
        ON CONFLICT (chat_id, user_id) DO NOTHING;
        GET DIAGNOSTICS inserted_member_rows = ROW_COUNT;
        inserted_member_count := inserted_member_count + inserted_member_rows;
    END LOOP;

    IF inserted_member_count < 1 THEN
        RAISE EXCEPTION 'Group chat requires at least one member';
    END IF;

    RETURN inserted;
END;
$$;


--
-- Name: create_topic(text, text, text, text[], text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.create_topic(p_source_chat_id text, p_source_message_id text, p_name text DEFAULT NULL::text, p_member_user_ids text[] DEFAULT NULL::text[], p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(chat_id text, public_id integer, name text, source_chat_id text, source_message_id text, creator_user_id text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE
    v_me TEXT := auth.uid()::text;
    v_actor TEXT;
    v_actor_is_agent BOOLEAN;
    v_actor_owner TEXT;
    v_owner_in_source BOOLEAN;
    v_actor_name TEXT;
    v_source_kind TEXT;
    v_source_hide_history BOOLEAN;
    v_source_content TEXT;
    v_source_is_whisper BOOLEAN;
    v_source_retracted TIMESTAMPTZ;
    v_source_content_type TEXT;
    v_name TEXT;
    v_chat_id TEXT := gen_random_uuid()::text;
    v_members TEXT[];
    v_denial TEXT;
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    v_actor := COALESCE(NULLIF(trim(COALESCE(p_as_user_id, '')), ''), v_me);
    SELECT u.type = 'agent', u.owner_user_id, u.display_name
      INTO v_actor_is_agent, v_actor_owner, v_actor_name
      FROM identity.users u WHERE u.id = v_actor;
    IF v_actor <> v_me AND NOT (COALESCE(v_actor_is_agent, false) AND v_actor_owner = v_me) THEN
        RAISE EXCEPTION 'Cannot open a topic as %', v_actor;
    END IF;

    SELECT c.kind, c.hide_history INTO v_source_kind, v_source_hide_history
      FROM chat.chats c WHERE c.id = p_source_chat_id;
    IF v_source_kind IS NULL THEN
        RAISE EXCEPTION 'Source chat % not found', p_source_chat_id;
    END IF;
    IF v_source_kind = 'topic' THEN
        RAISE EXCEPTION 'A topic cannot grow out of another topic';
    END IF;

    v_owner_in_source := COALESCE(v_actor_is_agent, false)
        AND v_actor_owner IS NOT NULL
        AND chat.is_chat_member(p_source_chat_id, v_actor_owner);

    IF NOT chat.is_chat_member(p_source_chat_id, v_actor) AND NOT v_owner_in_source THEN
        RAISE EXCEPTION 'Not a member of the source chat';
    END IF;

    -- 主人在群里、agent 不在:开话题等于把这个 agent 带进这条线。它得过同一道「能否加此人」,
    -- 否则「agent 加入需审批」的群里,普通成员可以借开话题把自己的 agent 塞进来。
    -- 话题不占来源群的座位(参与者都是来源线成员),所以这里不数人数。
    IF v_source_kind = 'group' AND v_owner_in_source AND NOT chat.is_chat_member(p_source_chat_id, v_actor) THEN
        v_denial := chat.group_add_denial(p_source_chat_id, v_actor, v_actor_owner, false);
        IF v_denial IS NOT NULL THEN
            RAISE EXCEPTION 'Agent % cannot open a topic in group %: %', v_actor, p_source_chat_id, v_denial;
        END IF;
    END IF;

    SELECT m.content, m.is_whisper, m.retracted_at, m.content_type
      INTO v_source_content, v_source_is_whisper, v_source_retracted, v_source_content_type
    FROM chat.messages m
    WHERE m.id = p_source_message_id
      AND m.chat_id = p_source_chat_id
      AND m.deleted_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Source message % is not a live message of chat %',
            p_source_message_id, p_source_chat_id;
    END IF;

    -- 悄悄话开不出话题:话题对来源线全员可见,而它的名字截自来源消息 ⇒ 开一条就是公开那句话。
    IF COALESCE(v_source_is_whisper, false) THEN
        RAISE EXCEPTION 'A whisper cannot be the source of a topic';
    END IF;

    -- 撤回的消息同理:那句话已经被收回,❌ 不许借话题名把它重新贴到所有人眼前。
    IF v_source_retracted IS NOT NULL THEN
        RAISE EXCEPTION 'A retracted message cannot be the source of a topic';
    END IF;

    IF NOT chat.can_read_message(p_source_message_id, v_actor)
       AND NOT (v_owner_in_source AND chat.can_read_message(p_source_message_id, v_actor_owner)) THEN
        RAISE EXCEPTION 'Source message % is not readable by %', p_source_message_id, v_actor;
    END IF;

    v_name := NULLIF(trim(COALESCE(p_name, '')), '');
    -- 只有正文类消息值得截名:系统消息会开出一条叫「某某 开了话题:…」的话题,附件会开出
    -- 「[附件] 季度报表.xlsx (2.1 MB)」—— 都不像人起的名字。其余类型退回「话题」,用户自己改。
    IF v_name IS NULL AND COALESCE(v_source_content_type, 'text') = 'text' THEN
        v_name := chat.topic_name_from_message(v_source_content);
    END IF;
    v_name := COALESCE(v_name, '话题');

    -- @@@5856 hide_history 跟着来源线走。不带它 ⇒ 话题默认 false ⇒ 入列触发器给成员置的时间界是 NULL,
    -- 于是「被时间界挡住的人在话题里说一句话(说话即参与)就解锁全部历史」。
    -- 可见继承来源,那道界也得继承。来源线里本来没有界的人不受影响 —— 他们走 can_see_topic_message。
    INSERT INTO chat.chats (id, kind, name, creator_user_id, source_chat_id, source_message_id, hide_history)
    VALUES (v_chat_id, 'topic', v_name, v_actor, p_source_chat_id, p_source_message_id,
            COALESCE(v_source_hide_history, false));

    -- ⚠️ 这道 is_chat_member 与下面 row3 的 `NOT v_owner_in_source OR …` 互补:主人不在来源线时
    -- row3 不过滤,但这里已经先把他踢掉了。动任一处都要看另一处。
    SELECT COALESCE(array_agg(DISTINCT candidate.user_id), ARRAY[]::TEXT[])
    INTO v_members
    FROM unnest(COALESCE(p_member_user_ids, ARRAY[]::TEXT[])) AS candidate(user_id)
    WHERE NULLIF(candidate.user_id, '') IS NOT NULL
      AND candidate.user_id <> v_actor
      AND chat.is_chat_member(p_source_chat_id, candidate.user_id);

    INSERT INTO chat.chat_members (chat_id, user_id, role)
    SELECT v_chat_id, v_actor, CASE WHEN v_owner_in_source THEN 'member' ELSE 'owner' END
    UNION ALL
    SELECT v_chat_id, v_actor_owner, 'owner'
     WHERE v_owner_in_source AND v_actor_owner <> v_actor
    UNION ALL
    SELECT v_chat_id, member_id, 'member' FROM unnest(v_members) AS member_id
     WHERE NOT v_owner_in_source OR member_id <> v_actor_owner
    ON CONFLICT (chat_id, user_id) DO NOTHING;

    INSERT INTO chat.group_agent_states (
        chat_id, agent_user_id, functional_role, capability_roles, last_action, updated_at
    )
    SELECT v_chat_id, u.id, 'member', ARRAY['member']::TEXT[], '已加入话题', now()
    FROM identity.users u
    WHERE u.type = 'agent'
      AND (u.id = v_actor OR u.id = ANY(v_members));

    IF COALESCE(v_actor_is_agent, false) THEN
        INSERT INTO chat.messages (id, chat_id, sender_user_id, content, content_type, client_message_id)
        VALUES (
            gen_random_uuid()::text,
            p_source_chat_id,
            v_actor,
            COALESCE(v_actor_name, 'Agent') || ' 开了话题:' || v_name,
            'system',
            'topic-opened:' || v_chat_id
        )
        ON CONFLICT (chat_id, client_message_id) WHERE client_message_id IS NOT NULL DO NOTHING;
    END IF;

    RETURN QUERY
    SELECT c.id, c.public_id, c.name, c.source_chat_id, c.source_message_id, c.creator_user_id
    FROM chat.chats c WHERE c.id = v_chat_id;
END;
$$;


--
-- Name: FUNCTION create_topic(p_source_chat_id text, p_source_message_id text, p_name text, p_member_user_ids text[], p_as_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.create_topic(p_source_chat_id text, p_source_message_id text, p_name text, p_member_user_ids text[], p_as_user_id text) IS '从一条已有消息开出一条话题。一步完成:建线 + 溯源 + 创建者入列 (+ agent 建时来源线留痕)。';


--
-- Name: current_user_group_role(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.current_user_group_role(p_chat_id text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT cm.role
    FROM chat.chat_members cm
    WHERE cm.chat_id = p_chat_id
      AND cm.user_id = (SELECT auth.uid()::text)
    LIMIT 1;
$$;


--
-- Name: decide_agent_group_invitation(text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.decide_agent_group_invitation(p_invitation_id text, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_inv chat.group_invitations%ROWTYPE;
    v_group chat.chats%ROWTYPE;
    v_target identity.users%ROWTYPE;
    v_members TEXT[];
    v_count INTEGER;
    v_queue BOOLEAN := false;
    v_request TEXT;
BEGIN
    IF v_me IS NULL OR p_accept IS NULL THEN RAISE EXCEPTION 'Authenticated decision is required'; END IF;
    SELECT * INTO v_inv FROM chat.group_invitations WHERE id = p_invitation_id AND decision_user_id = v_me;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invitation not found or not addressed to this account'; END IF;
    PERFORM 1 FROM chat.chats WHERE id = v_inv.chat_id FOR UPDATE;
    SELECT * INTO v_inv FROM chat.group_invitations WHERE id = p_invitation_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invitation no longer exists'; END IF;
    IF v_inv.status <> 'pending' THEN
        IF v_inv.status <> (CASE WHEN p_accept THEN 'accepted' ELSE 'rejected' END) THEN
            RAISE EXCEPTION 'Invitation already decided';
        END IF;
        RETURN jsonb_build_object('status', v_inv.status, 'invitation_id', v_inv.id, 'chat_id', v_inv.chat_id);
    END IF;
    IF NOT p_accept THEN
        UPDATE chat.group_invitations SET status = 'rejected', updated_at = now() WHERE id = v_inv.id;
        RETURN jsonb_build_object('status', 'rejected', 'invitation_id', v_inv.id, 'chat_id', v_inv.chat_id);
    END IF;
    v_group := chat.require_agent_group_inviter(v_inv.chat_id, v_inv.inviter_agent_user_id, v_inv.inviter_owner_user_id);
    SELECT * INTO v_target FROM identity.users WHERE id = v_inv.invitee_user_id FOR SHARE;
    IF NOT FOUND OR (v_target.type = 'agent' AND v_target.owner_user_id IS DISTINCT FROM v_me)
       OR (v_target.type = 'human' AND v_target.id <> v_me) THEN
        RAISE EXCEPTION 'Only the invited human or invited Agent owner may accept';
    END IF;
    IF chat.is_cloud_agent_user(v_target.id) THEN RAISE EXCEPTION 'Cloud Agents cannot join groups'; END IF;
    -- 需审批且邀请方主人不是管理员 ⇒ 受邀方(人)照常入群,agent 那一步进审批队列,由管理员决定。
    v_queue := v_target.type = 'agent' AND v_group.agent_join_approval AND NOT EXISTS (
        SELECT 1 FROM chat.chat_members WHERE chat_id = v_group.id AND user_id = v_inv.inviter_owner_user_id AND role IN ('owner', 'admin')
    );
    v_members := CASE
        WHEN v_target.type = 'agent' AND NOT v_queue THEN ARRAY[v_me, v_target.id]
        ELSE ARRAY[v_me]
    END;
    SELECT count(*) INTO v_count FROM chat.chat_members WHERE chat_id = v_group.id;
    IF v_count + (SELECT count(*) FROM unnest(v_members) AS member(id) WHERE NOT EXISTS (
        SELECT 1 FROM chat.chat_members WHERE chat_id = v_group.id AND user_id = member.id
    )) > v_group.max_members THEN RAISE EXCEPTION 'Group member limit reached'; END IF;
    SET CONSTRAINTS ALL DEFERRED;
    INSERT INTO chat.chat_members(chat_id, user_id, role)
    SELECT v_group.id, member.id, 'member' FROM unnest(v_members) AS member(id)
    ON CONFLICT (chat_id, user_id) DO NOTHING;
    IF v_target.type = 'agent' AND NOT v_queue THEN
        INSERT INTO chat.group_agent_states(chat_id, agent_user_id, functional_role, capability_roles, last_action, updated_at)
        VALUES (v_group.id, v_target.id, 'member', ARRAY['member']::TEXT[], '已加入群聊', now())
        ON CONFLICT (chat_id, agent_user_id) DO NOTHING;
    END IF;
    UPDATE chat.group_invitations SET status = 'accepted', updated_at = now() WHERE id = v_inv.id;
    -- 好友接受了 agent 的联系:邀请卡上的附言作为 agent 发给好友的第一条群消息落进群里。
    -- 入群灰字由 chat_members 的语句级触发器在上面那条 INSERT 里先写,这一条排在它后面;
    -- client_message_id 按邀请去重,重复接受也只有一条。
    IF v_inv.kind = 'friend_contact' AND NOT v_queue THEN
        INSERT INTO chat.messages (id, chat_id, sender_user_id, content, content_type, to_user_ids, client_message_id)
        VALUES (gen_random_uuid()::text, v_group.id, v_inv.inviter_agent_user_id, v_inv.message, 'text',
                ARRAY[v_target.id], 'invitation-note:' || v_inv.id)
        ON CONFLICT (chat_id, client_message_id) WHERE client_message_id IS NOT NULL DO NOTHING;
    END IF;
    IF v_queue THEN
        v_request := chat.queue_agent_join_request(v_group.id, v_target.id, v_inv.inviter_owner_user_id, v_inv.message);
        RETURN jsonb_build_object('status', 'pending_approval', 'invitation_id', v_inv.id, 'chat_id', v_group.id,
            'request_id', v_request);
    END IF;
    RETURN jsonb_build_object('status', 'accepted', 'invitation_id', v_inv.id, 'chat_id', v_group.id);
END;
$$;


--
-- Name: decide_group_join(text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.decide_group_join(p_request_id text, p_accept boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_req chat.group_join_requests%ROWTYPE;
    v_type TEXT;
    v_agent_owner TEXT;
    v_denial TEXT;
BEGIN
    IF v_me IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    SELECT * INTO v_req FROM chat.group_join_requests WHERE id = p_request_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Join request not found'; END IF;
    IF NOT chat.can_manage_group_members(v_req.chat_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;
    PERFORM 1 FROM chat.chats WHERE id = v_req.chat_id FOR UPDATE;
    SELECT * INTO v_req FROM chat.group_join_requests WHERE id = p_request_id FOR UPDATE;
    IF v_req.status <> 'pending' THEN RAISE EXCEPTION 'Join request already decided'; END IF;

    IF NOT p_accept THEN
        UPDATE chat.group_join_requests SET status = 'rejected', updated_at = now() WHERE id = p_request_id;
        RETURN 'rejected';
    END IF;

    SELECT u.type, u.owner_user_id INTO v_type, v_agent_owner FROM identity.users u WHERE u.id = v_req.requester_user_id;
    IF v_type = 'agent' THEN
        -- 等待期间事实可能变了:发起人退群 / agent 的主人不在群里了 ⇒ 这条请求不再成立。
        IF v_req.requested_by_user_id IS NOT NULL
           AND NOT chat.is_chat_member(v_req.chat_id, v_req.requested_by_user_id) THEN
            RAISE EXCEPTION 'join_request_requester_left';
        END IF;
        IF v_agent_owner IS NULL OR NOT chat.is_chat_member(v_req.chat_id, v_agent_owner) THEN
            RAISE EXCEPTION 'join_request_agent_owner_left';
        END IF;
    END IF;

    -- 按审批人身份判:审批人是管理员 ⇒ 邀请开关与 agent 审批放行,剩下上限 / 云 agent / 群状态。
    -- agent 归属:审批人不是 agent 的主人,但这条请求只可能由 queue_agent_join_request 落下
    -- (requested_by_user_id 非空),三个入队口子都已核过主人本人发起或主人已接受邀请 ⇒ 带上主人同意。
    -- requested_by 为空的 agent 请求没有这份同意 ⇒ 照常按归属拒。
    v_denial := chat.group_add_denial(v_req.chat_id, v_req.requester_user_id, v_me, true,
                                      v_type = 'agent' AND v_req.requested_by_user_id IS NOT NULL);
    IF v_denial IS NOT NULL THEN RAISE EXCEPTION '%', v_denial; END IF;

    INSERT INTO chat.chat_members (chat_id, user_id, role) VALUES (v_req.chat_id, v_req.requester_user_id, 'member')
    ON CONFLICT (chat_id, user_id) DO NOTHING;
    IF v_type = 'agent' THEN
        INSERT INTO chat.group_agent_states (chat_id, agent_user_id, functional_role, capability_roles, last_action, updated_at)
        VALUES (v_req.chat_id, v_req.requester_user_id, 'member', ARRAY['member']::TEXT[], '已加入群聊', now())
        ON CONFLICT (chat_id, agent_user_id) DO NOTHING;
    END IF;
    UPDATE chat.group_join_requests SET status = 'accepted', updated_at = now() WHERE id = p_request_id;
    RETURN 'accepted';
END;
$$;


--
-- Name: delete_message(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.delete_message(p_message_id text) RETURNS TABLE(chat_id text, globally_deleted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
DECLARE
    v_uid       TEXT := (SELECT auth.uid()::text);
    v_chat_id   TEXT;
    v_sender_id TEXT;
BEGIN
    SELECT m.chat_id, m.sender_user_id
    INTO v_chat_id, v_sender_id
    FROM chat.messages m
    WHERE m.id = p_message_id
      AND m.deleted_at IS NULL;

    IF v_chat_id IS NULL THEN
        RAISE EXCEPTION 'message not found: %', p_message_id;
    END IF;

    IF NOT chat.is_member(v_chat_id) THEN
        RAISE EXCEPTION 'not a member of chat: %', v_chat_id;
    END IF;

    IF v_sender_id = v_uid THEN
        UPDATE chat.messages
        SET
            deleted_at = now(),
            updated_at = now()
        WHERE id = p_message_id;
        PERFORM chat.recompute_chat_last_message(v_chat_id);
        RETURN QUERY SELECT v_chat_id, TRUE;
        RETURN;
    END IF;

    UPDATE chat.messages
    SET
        deleted_for_user_ids =
            CASE
                WHEN deleted_for_user_ids @> jsonb_build_array(v_uid) THEN deleted_for_user_ids
                ELSE deleted_for_user_ids || jsonb_build_array(v_uid)
            END,
        updated_at = now()
    WHERE id = p_message_id;

    RETURN QUERY SELECT v_chat_id, FALSE;
END;
$$;


--
-- Name: enforce_agent_flood_passive(text, text[]); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.enforce_agent_flood_passive(p_chat_id text, p_user_ids text[] DEFAULT NULL::text[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_kind TEXT;
    v_tuned TIMESTAMPTZ;
    v_threshold INTEGER;
    v_agent_count INTEGER;
    v_live_id TEXT;
    v_live_undone BOOLEAN;
    v_changed JSONB;
    v_where TEXT;
    v_message_id TEXT := gen_random_uuid()::text;
BEGIN
    SELECT c.kind, c.agent_flood_tuned_at INTO v_kind, v_tuned
    FROM chat.chats c WHERE c.id = p_chat_id FOR NO KEY UPDATE;

    -- 闸门没落过 = 这条线还没进过这个规矩,该走的是「第一次过线」那条路,不是这里。
    IF v_kind IS NULL OR v_kind NOT IN ('group', 'topic') OR v_tuned IS NULL THEN
        RETURN;
    END IF;

    SELECT a.id, a.undone_at IS NOT NULL
    INTO v_live_id, v_live_undone
    FROM chat.agent_flood_adjustments a
    WHERE a.chat_id = p_chat_id
    ORDER BY a.created_at DESC
    LIMIT 1;

    -- 撤回过 ⇒ 用户明确说了不要,这条线的规矩就不作数了(❌ 不许借「后来的人」把它偷偷装回去)。
    IF COALESCE(v_live_undone, FALSE) THEN
        RETURN;
    END IF;

    v_threshold := chat.agent_flood_threshold_for(p_chat_id);
    IF v_threshold IS NULL THEN
        RETURN;
    END IF;

    SELECT count(*) INTO v_agent_count
    FROM chat.chat_members cm
    JOIN identity.users u ON u.id = cm.user_id AND u.type = 'agent'
    WHERE cm.chat_id = p_chat_id;

    -- 人走光了、现在根本没过线,就没有理由再压谁的档位。
    IF v_agent_count <= v_threshold THEN
        RETURN;
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'user_id', cm.user_id,
        'previous_listen_mode', cm.listen_mode
    ) ORDER BY cm.user_id), '[]'::jsonb)
    INTO v_changed
    FROM chat.chat_members cm
    JOIN identity.users u ON u.id = cm.user_id AND u.type = 'agent'
    WHERE cm.chat_id = p_chat_id
      AND cm.listen_mode <> 'passive'
      AND (p_user_ids IS NULL OR cm.user_id = ANY (p_user_ids));

    IF jsonb_array_length(v_changed) = 0 THEN
        RETURN;
    END IF;

    -- Late joiners remain folded into the existing adjustment without a new notice.
    -- Only a genuinely new notice captures the event-time listening state.
    IF v_live_id IS NULL THEN
        v_where := CASE WHEN v_kind = 'topic' THEN '这条话题' ELSE '这个群' END;
        INSERT INTO chat.messages (id, chat_id, sender_user_id, content, content_type, client_message_id)
        VALUES (
            v_message_id,
            p_chat_id,
            NULL,
            v_where || '里 agent 较多,已把它们都转为被动模式,@ 它们才会回。',
            'system',
            'agent-flood:' || v_message_id
        );
    END IF;

    UPDATE chat.chat_members cm
    SET listen_mode = 'passive', updated_at = now()
    WHERE cm.chat_id = p_chat_id
      AND cm.listen_mode <> 'passive'
      AND (p_user_ids IS NULL OR cm.user_id = ANY (p_user_ids))
      AND EXISTS (SELECT 1 FROM identity.users u WHERE u.id = cm.user_id AND u.type = 'agent');

    IF v_live_id IS NOT NULL THEN
        -- 并进屏幕上那条调整,❌ 不发第二条系统消息:规矩已经在那儿说过一遍了,
        -- 每进一个 agent 再说一遍就是刷屏。并进去的代价是「全部撤回」必须连它一起还原 —— 这正是要的。
        UPDATE chat.agent_flood_adjustments
        SET changed = changed || v_changed
        WHERE id = v_live_id;
        RETURN;
    END IF;

    INSERT INTO chat.agent_flood_adjustments (chat_id, message_id, changed, agent_count)
    VALUES (p_chat_id, v_message_id, v_changed, v_agent_count);
END;
$$;


--
-- Name: FUNCTION enforce_agent_flood_passive(p_chat_id text, p_user_ids text[]); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.enforce_agent_flood_passive(p_chat_id text, p_user_ids text[]) IS '这条线的「点名才回」规矩还作数(闸门落过 + 没被撤回 + 仍然过线)时,让指定的 agent 照办;改动并进现有台账,「全部撤回」一并还原。p_user_ids 为 NULL = 整条线。';


--
-- Name: enforce_group_member_limit(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.enforce_group_member_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_kind TEXT;
    v_max INTEGER;
    v_count INTEGER;
BEGIN
    SELECT c.kind INTO v_kind FROM chat.chats c WHERE c.id = NEW.chat_id;
    IF v_kind IS DISTINCT FROM 'group' THEN
        RETURN NEW;
    END IF;
    SELECT COALESCE(c.max_members, 100) INTO v_max
      FROM chat.chats c WHERE c.id = NEW.chat_id
      FOR NO KEY UPDATE;
    IF EXISTS (SELECT 1 FROM chat.chat_members cm WHERE cm.chat_id = NEW.chat_id AND cm.user_id = NEW.user_id) THEN
        RETURN NEW;
    END IF;
    SELECT count(*) INTO v_count FROM chat.chat_members cm WHERE cm.chat_id = NEW.chat_id;
    IF v_count >= v_max THEN
        RAISE EXCEPTION 'member_limit_reached' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_whisper_rule(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.enforce_whisper_rule() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_count integer := COALESCE(cardinality(NEW.to_user_ids), 0);
BEGIN
    IF v_count <> 1 THEN
        RAISE EXCEPTION 'A whisper goes to exactly one person: to_user_ids holds % recipients', v_count
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.to_user_ids[1] = NEW.sender_user_id THEN
        RAISE EXCEPTION 'A whisper cannot be sent to yourself' USING ERRCODE = 'check_violation';
    END IF;
    IF NOT chat.is_chat_member(NEW.chat_id, NEW.to_user_ids[1]) THEN
        RAISE EXCEPTION 'A whisper goes to a member of this chat: % is not a member of %', NEW.to_user_ids[1], NEW.chat_id
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_agent_deliver_device_command(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.enqueue_agent_deliver_device_command() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 DECLARE
     v_reply_target    TEXT;
     v_sender_is_agent BOOLEAN;
 BEGIN
     IF NEW.deleted_at IS NOT NULL THEN
         RETURN NEW;
     END IF;

     IF NEW.content_type NOT IN ('text', 'attachment', 'system')
        OR NULLIF(trim(COALESCE(NEW.content, '')), '') IS NULL THEN
         RETURN NEW;
     END IF;

     v_reply_target := chat.message_reply_routing_target(NEW.reply_to_message_id);
     v_sender_is_agent := EXISTS (
         SELECT 1 FROM identity.users s WHERE s.id = NEW.sender_user_id AND s.type = 'agent'
     );

     INSERT INTO identity.gugu_device_commands (user_id, device_id, type, payload)
     SELECT u.owner_user_id::uuid, u.device_id, 'agent.deliver',
            jsonb_build_object(
                'agent_user_id', u.id, 'chat_id', NEW.chat_id, 'message_id', NEW.id,
                'sender_user_id', NEW.sender_user_id, 'content', NEW.content,
                'to_user_ids', to_jsonb(NEW.to_user_ids),
                -- #1761 F0:真实 whisper 标记,不是「任何点名都真」的派生值。
                'is_whisper', NEW.is_whisper,
                'listen_mode', cm.listen_mode,
                -- #1531:thread root(is_thread_root 真且 thread_root_id 空)→ 回复进本条自身 thread。
                'thread_root_id', COALESCE(NEW.thread_root_id, CASE WHEN NEW.is_thread_root THEN NEW.id END)
            ) || COALESCE(
                   -- 回复预览按**收件人**的可读性算(#5856),❌ 不共用一份。
                   (SELECT to_jsonb(rp)
                      FROM chat.message_reply_preview_row(NEW.reply_to_message_id, u.id) rp),
                   '{}'::jsonb
                 )
     FROM chat.chats c
     JOIN chat.chat_members cm ON cm.chat_id = c.id
     JOIN identity.users u
       ON u.id = cm.user_id
      AND u.type = 'agent'
      AND u.owner_user_id IS NOT NULL
      AND u.device_id IS NOT NULL
      AND u.desired_status = 'online'
     JOIN identity.gugu_devices d
       ON d.device_id = u.device_id
      AND d.user_id::text = u.owner_user_id
     WHERE c.id = NEW.chat_id
       AND c.status = 'active'
       AND chat.message_wakes_agent(
             u.id,
             cm.listen_mode,
             cm.notification_level,
             c.kind,
             NEW.sender_user_id,
             v_sender_is_agent,
             NEW.sender_user_id = c.creator_user_id,
             NEW.to_user_ids,
             NEW.is_whisper,
             v_reply_target
           );

     RETURN NEW;
 END;
 $$;


--
-- Name: file_blob_enqueue(uuid); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_enqueue(p_blob_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    INSERT INTO chat.file_blob_gc AS g (blob_id, next_attempt_at)
    VALUES (p_blob_id, now() + interval '24 hours')
    ON CONFLICT (blob_id) DO UPDATE
       SET next_attempt_at = GREATEST(g.next_attempt_at, EXCLUDED.next_attempt_at), updated_at = now()
     WHERE g.status <> 'running';
$$;


--
-- Name: file_blob_for_pointer(text, bigint, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_for_pointer(p_pointer text, p_size_bytes bigint, p_content_type text, p_made_by text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_id UUID;
BEGIN
    -- 登记的对象得真在 workspace 桶里;KEY SHARE 让它在这一笔提交前删不掉(原来 workspace_items 上那个校验触发器的那一句)。
    PERFORM 1 FROM storage.objects o WHERE o.bucket_id = 'workspace' AND o.name = p_pointer FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'workspace storage reference target does not exist';
    END IF;
    INSERT INTO chat.file_blobs AS b (bucket_id, object_name, size_bytes, content_type, created_by)
    VALUES ('workspace', p_pointer, p_size_bytes, COALESCE(NULLIF(btrim(COALESCE(p_content_type, '')), ''), 'application/octet-stream'), p_made_by)
    ON CONFLICT ON CONSTRAINT file_blobs_place_key DO NOTHING
    RETURNING b.id INTO v_id;
    IF v_id IS NULL THEN
        SELECT b.id INTO v_id FROM chat.file_blobs b WHERE b.bucket_id = 'workspace' AND b.object_name = p_pointer;
    END IF;
    PERFORM chat.file_blob_take(v_id);
    RETURN v_id;
END;
$$;


--
-- Name: file_blob_gc_claim(integer, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_gc_claim(p_limit integer DEFAULT 50, p_stale_seconds integer DEFAULT 600) RETURNS TABLE(blob_id uuid, claim_token uuid, bucket_id text, object_name text, content_type text, attempt_count integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    r RECORD;
    v_token UUID;
BEGIN
    IF p_limit < 1 OR p_limit > 500 OR p_stale_seconds < 30 THEN
        RAISE EXCEPTION 'file_blob_gc_claim: invalid bounds';
    END IF;
    UPDATE chat.file_blob_gc g
       SET status = 'failed', claim_token = NULL, claimed_at = NULL, next_attempt_at = now(),
           last_error = 'stale lease reclaimed', updated_at = now()
     WHERE g.status = 'running' AND g.claimed_at < now() - make_interval(secs => p_stale_seconds);

    FOR r IN
        SELECT g.blob_id
          FROM chat.file_blob_gc g
         WHERE g.status IN ('pending', 'failed') AND g.next_attempt_at <= now()
         ORDER BY g.next_attempt_at, g.blob_id
         LIMIT p_limit
           FOR UPDATE SKIP LOCKED
    LOOP
        -- 锁不到就跳过这一轮:正被人拿着(FOR SHARE)的 blob 本来就在用。❌ 等它 —— 拿着它的那一边可能接着要写这一行
        -- 队列(同一个事务里先用上 X、再让 X 失去一个引用,workspace_replace_file_as 换老文件就是这样),两边成环、死锁(复核 L11 实测)。
        PERFORM 1 FROM chat.file_blobs b WHERE b.id = r.blob_id FOR UPDATE SKIP LOCKED;
        IF NOT FOUND THEN
            CONTINUE;
        END IF;
        IF chat.file_blob_in_use(r.blob_id) THEN
            DELETE FROM chat.file_blob_gc g WHERE g.blob_id = r.blob_id;
            CONTINUE;
        END IF;
        UPDATE chat.file_blobs b SET state = 'deleting' WHERE b.id = r.blob_id;
        v_token := gen_random_uuid();
        UPDATE chat.file_blob_gc g
           SET status = 'running', attempt_count = g.attempt_count + 1, claim_token = v_token,
               claimed_at = now(), last_error = NULL, updated_at = now()
         WHERE g.blob_id = r.blob_id;
        RETURN QUERY
        SELECT b.id, v_token, b.bucket_id, b.object_name, b.content_type, g.attempt_count
          FROM chat.file_blobs b JOIN chat.file_blob_gc g ON g.blob_id = b.id
         WHERE b.id = r.blob_id;
    END LOOP;
END;
$$;


--
-- Name: file_blob_gc_fail(uuid, uuid, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_gc_fail(p_blob_id uuid, p_claim_token uuid, p_error text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    UPDATE chat.file_blob_gc g
       SET status = 'failed', claim_token = NULL, claimed_at = NULL,
           last_error = left(COALESCE(NULLIF(p_error, ''), 'delete failed'), 500),
           next_attempt_at = now() + make_interval(secs => LEAST(3600, 5 * (2 ^ LEAST(g.attempt_count, 10)))::INTEGER),
           updated_at = now()
     WHERE g.blob_id = p_blob_id AND g.claim_token = p_claim_token AND g.status = 'running';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'file_blob_gc_fail: the lease on % is stale', p_blob_id;
    END IF;
END;
$$;


--
-- Name: file_blob_gc_finish(uuid, uuid); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_gc_finish(p_blob_id uuid, p_claim_token uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM 1 FROM chat.file_blob_gc g
     WHERE g.blob_id = p_blob_id AND g.claim_token = p_claim_token AND g.status = 'running'
       FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'file_blob_gc_finish: the lease on % is stale', p_blob_id;
    END IF;
    DELETE FROM chat.file_blobs b WHERE b.id = p_blob_id AND b.state = 'deleting';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'file_blob_gc_finish: % is not being collected', p_blob_id;
    END IF;
END;
$$;


--
-- Name: file_blob_gc_kick(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_gc_kick() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_url TEXT;
    v_key TEXT;
BEGIN
    -- 到期的、或者租约过期该收回的(领取那一步会收回)。
    IF NOT EXISTS (SELECT 1 FROM chat.file_blob_gc g WHERE g.status IN ('pending', 'failed') AND g.next_attempt_at <= now())
       AND NOT EXISTS (SELECT 1 FROM chat.file_blob_gc g WHERE g.status = 'running' AND g.claimed_at < now() - interval '600 seconds') THEN
        RETURN NULL;
    END IF;
    SELECT s.decrypted_secret INTO v_url FROM vault.decrypted_secrets s WHERE s.name = 'attachments_gc_url';
    SELECT s.decrypted_secret INTO v_key FROM vault.decrypted_secrets s WHERE s.name = 'attachments_gc_key';
    IF NULLIF(btrim(COALESCE(v_url, '')), '') IS NULL OR NULLIF(btrim(COALESCE(v_key, '')), '') IS NULL THEN
        RAISE EXCEPTION 'file_blob_gc_kick: blobs are due for collection but Vault has no attachments_gc_url / attachments_gc_key — set them for this environment (see 20261016124500)';
    END IF;
    -- pg_net 在本事务提交以后才发;回应记在 net._http_response(不看:函数自己报完成 / 失败,队列就是账本)。
    RETURN net.http_post(
        url := v_url,
        body := '{}'::jsonb,
        headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_key),
        timeout_milliseconds := 120000
    );
END;
$$;


--
-- Name: file_blob_in_use(uuid); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_in_use(p_blob_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (SELECT 1 FROM chat.workspace_items w WHERE w.blob_id = p_blob_id)
        OR EXISTS (SELECT 1 FROM chat.workspace_item_versions v WHERE v.blob_id = p_blob_id)
        OR EXISTS (SELECT 1 FROM chat.file_blob_uploads u WHERE u.blob_id = p_blob_id AND u.expires_at > now())
        -- 悄悄话附件直接指着它(撤回、软删的行还在,也算)。
        OR EXISTS (SELECT 1 FROM chat.messages m WHERE m.file_blob_id = p_blob_id)
        -- 老式引用:存储列指着这个对象的消息、群头像、group_outputs(只有不在 OSS 的对象才可能有)。
        OR EXISTS (
            SELECT 1 FROM chat.file_blobs b
             WHERE b.id = p_blob_id AND b.bucket_id <> 'oss'
               AND (EXISTS (SELECT 1 FROM chat.messages m WHERE m.storage_bucket_id = b.bucket_id AND m.storage_object_name = b.object_name)
                    OR EXISTS (SELECT 1 FROM chat.chats c WHERE c.avatar_storage_bucket_id = b.bucket_id AND c.avatar_storage_object_name = b.object_name)
                    OR EXISTS (SELECT 1 FROM chat.group_outputs o WHERE o.storage_bucket_id = b.bucket_id AND o.storage_object_name = b.object_name)));
$$;


--
-- Name: file_blob_lost_reference(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_lost_reference() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    -- ◇ 消息表只有 DELETE 走到这里(file_blob_id 发出后不能改)。
    IF TG_TABLE_NAME = 'messages' THEN
        IF OLD.file_blob_id IS NOT NULL THEN
            PERFORM chat.file_blob_enqueue(OLD.file_blob_id);
        END IF;
    ELSIF TG_OP = 'DELETE' THEN
        IF OLD.blob_id IS NOT NULL THEN
            PERFORM chat.file_blob_enqueue(OLD.blob_id);
        END IF;
    ELSIF OLD.blob_id IS NOT NULL AND NEW.blob_id IS DISTINCT FROM OLD.blob_id THEN
        PERFORM chat.file_blob_enqueue(OLD.blob_id);
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: file_blob_pointer(uuid); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_pointer(p_blob_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
    SELECT b.object_name FROM chat.file_blobs b WHERE b.id = p_blob_id AND b.bucket_id = 'workspace';
$$;


--
-- Name: FUNCTION file_blob_pointer(p_blob_id uuid); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.file_blob_pointer(p_blob_id uuid) IS '一份字节在 workspace 桶里时的对象名(老客户端读的 pointer),在 OSS 里或没有字节时 NULL。只给 SECURITY DEFINER 的函数用。';


--
-- Name: file_blob_register(text, text, text, bigint, text, integer, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_register(p_uploader text, p_staging_key text, p_sha256 text, p_size_bytes bigint, p_content_type text, p_width integer DEFAULT NULL::integer, p_height integer DEFAULT NULL::integer) RETURNS TABLE(blob_id uuid, object_name text, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_sha TEXT := lower(btrim(COALESCE(p_sha256, '')));
    v_blob chat.file_blobs%ROWTYPE;
    v_created BOOLEAN := false;
    v_upload chat.file_blob_uploads%ROWTYPE;
BEGIN
    IF v_sha !~ '^[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'file_blob_register: sha256 must be 64 hex digits';
    END IF;
    IF p_size_bytes IS NULL OR p_size_bytes < 1 OR p_size_bytes > 26214400 THEN
        RAISE EXCEPTION USING HINT = 'file_too_large', MESSAGE = format('file_blob_register: size must be 1 byte to 25 MiB, got %s', p_size_bytes);
    END IF;
    SELECT * INTO v_upload FROM chat.file_blob_uploads u WHERE u.staging_key = p_staging_key;
    IF FOUND THEN
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = v_upload.blob_id;
        IF v_upload.uploader IS DISTINCT FROM p_uploader OR v_blob.sha256 IS DISTINCT FROM v_sha THEN
            RAISE EXCEPTION 'file_blob_register: % is already registered for other content', p_staging_key;
        END IF;
        RETURN QUERY SELECT v_blob.id, v_blob.object_name, false;
        RETURN;
    END IF;

    INSERT INTO chat.file_blobs AS b (bucket_id, object_name, sha256, size_bytes, content_type, width, height, created_by)
    VALUES ('oss', substr(v_sha, 1, 2) || '/' || v_sha, v_sha, p_size_bytes,
            COALESCE(NULLIF(btrim(COALESCE(p_content_type, '')), ''), 'application/octet-stream'), p_width, p_height, p_uploader)
    ON CONFLICT (sha256) DO NOTHING
    RETURNING b.* INTO v_blob;
    v_created := FOUND;
    IF NOT v_created THEN
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.sha256 = v_sha;
        IF v_blob.size_bytes IS DISTINCT FROM p_size_bytes THEN
            RAISE EXCEPTION 'file_blob_register: sha256 % is stored with % bytes, not %', v_sha, v_blob.size_bytes, p_size_bytes;
        END IF;
    END IF;
    PERFORM chat.file_blob_take(v_blob.id);

    INSERT INTO chat.file_blob_uploads (staging_key, uploader, blob_id) VALUES (p_staging_key, p_uploader, v_blob.id);
    RETURN QUERY SELECT v_blob.id, v_blob.object_name, v_created;
END;
$_$;


--
-- Name: file_blob_sweep(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_sweep() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    DELETE FROM chat.file_blob_uploads u WHERE u.expires_at <= now();
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: file_blob_take(uuid); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_blob_take(p_blob_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_state TEXT;
BEGIN
    SELECT b.state INTO v_state FROM chat.file_blobs b WHERE b.id = p_blob_id FOR SHARE;
    IF v_state IS NULL THEN
        RAISE EXCEPTION 'file blob % does not exist', p_blob_id;
    END IF;
    IF v_state = 'deleting' THEN
        RAISE EXCEPTION USING HINT = 'file_blob_deleting', ERRCODE = '55000',
            MESSAGE = format('file blob %s is being collected; try again shortly', p_blob_id);
    END IF;
END;
$$;


--
-- Name: file_place_as(text, text, text, text, text, text[]); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_place_as(p_staging_key text, p_chat_id text, p_as_user_id text, p_file_name text, p_folder text DEFAULT NULL::text, p_source_message_ids text[] DEFAULT NULL::text[]) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_filename TEXT := btrim(COALESCE(p_file_name, ''));
    v_upload chat.file_blob_uploads%ROWTYPE;
    v_blob chat.file_blobs%ROWTYPE;
    v_parent UUID;
    v_id UUID;
BEGIN
    PERFORM chat.workspace_require_room_member(p_chat_id, v_actor);
    IF v_filename = '' THEN RAISE EXCEPTION USING HINT = 'file_place_invalid', MESSAGE = 'file_place_as: file name is required'; END IF;
    v_upload := chat.file_upload_take(p_staging_key);
    IF v_upload.item_id IS NOT NULL THEN
        -- 重试:上次已经放成了这个条目(同一个会话里才算;放到别处的上传不能拿来再放)。
        IF NOT EXISTS (SELECT 1 FROM chat.workspace_items w WHERE w.id = v_upload.item_id AND w.chat_id = p_chat_id) THEN
            RAISE EXCEPTION USING HINT = 'attachment_upload_used',
                MESSAGE = format('upload %s was already placed elsewhere', p_staging_key);
        END IF;
        v_id := v_upload.item_id;
    ELSE
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = v_upload.blob_id;
        v_parent := chat.workspace_folder_for(p_chat_id, p_folder, v_actor, true);
        INSERT INTO chat.workspace_items AS w (chat_id, parent_id, kind, filename, content_type, size_bytes, blob_id, source_message_ids, created_by, version)
        VALUES (p_chat_id, v_parent, 'file', v_filename, v_blob.content_type, v_blob.size_bytes, v_blob.id, COALESCE(p_source_message_ids, '{}'), v_actor, 1)
        RETURNING w.id INTO v_id;
        UPDATE chat.file_blob_uploads u SET item_id = v_id, item_version = 1 WHERE u.staging_key = p_staging_key;
    END IF;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           w.parent_id, w.system_role, chat.workspace_path_of(w.id)
      FROM chat.workspace_items w
     WHERE w.id = v_id;
END;
$$;


--
-- Name: file_replace_as(text, text, text, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_replace_as(p_staging_key text, p_item_id text, p_as_user_id text, p_expected_version integer DEFAULT NULL::integer) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, pruned_pointers text[], parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_keep CONSTANT INTEGER := 50;
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_item chat.workspace_items%ROWTYPE;
    v_upload chat.file_blob_uploads%ROWTYPE;
    v_blob chat.file_blobs%ROWTYPE;
    v_next INTEGER;
    v_pruned TEXT[] := '{}';
BEGIN
    v_item := chat.workspace_item_for(p_item_id, v_actor, true);
    v_upload := chat.file_upload_take(p_staging_key);
    IF v_upload.item_id IS NOT NULL THEN
        -- 重试:上次已经把这个文件换成了这份字节(换到别的条目上的上传不能再用)。
        IF v_upload.item_id IS DISTINCT FROM v_item.id THEN
            RAISE EXCEPTION USING HINT = 'attachment_upload_used',
                MESSAGE = format('upload %s was already placed elsewhere', p_staging_key);
        END IF;
    ELSE
        IF v_item.kind <> 'file' THEN
            RAISE EXCEPTION USING HINT = 'file_place_invalid',
                MESSAGE = format('file_replace_as: %s is a live text file; change it through the file service', p_item_id);
        END IF;
        IF p_expected_version IS NOT NULL AND p_expected_version <> v_item.version THEN
            RAISE EXCEPTION USING HINT = 'workspace_version_conflict', DETAIL = v_item.version::TEXT,
                MESSAGE = format('workspace item %s version conflict: expected %s, got %s', p_item_id, p_expected_version, v_item.version);
        END IF;
        IF v_upload.blob_id = v_item.blob_id THEN
            RAISE EXCEPTION USING HINT = 'file_place_invalid', MESSAGE = 'file_replace_as: that is the content the file already has';
        END IF;
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = v_upload.blob_id;
        v_next := v_item.version + 1;
        -- 被替换的这一版:第一次换版本时它还不在历史里(建文件时不写历史),补上。
        INSERT INTO chat.workspace_item_versions (item_id, n, blob_id, content_type, size_bytes, made_by, made_at)
        VALUES (v_item.id, v_item.version, v_item.blob_id, v_item.content_type, v_item.size_bytes, v_item.created_by, v_item.updated_at)
        ON CONFLICT ON CONSTRAINT workspace_item_versions_pkey DO NOTHING;
        INSERT INTO chat.workspace_item_versions (item_id, n, blob_id, content_type, size_bytes, made_by)
        VALUES (v_item.id, v_next, v_blob.id, v_blob.content_type, v_blob.size_bytes, v_actor);
        UPDATE chat.workspace_items w
           SET blob_id = v_blob.id, size_bytes = v_blob.size_bytes, content_type = v_blob.content_type, version = v_next
         WHERE w.id = v_item.id;
        UPDATE chat.file_blob_uploads u SET item_id = v_item.id, item_version = v_next WHERE u.staging_key = p_staging_key;
        WITH gone AS (
            DELETE FROM chat.workspace_item_versions v
             WHERE v.item_id = v_item.id
               AND v.n NOT IN (SELECT k.n FROM chat.workspace_item_versions k WHERE k.item_id = v_item.id ORDER BY k.n DESC LIMIT v_keep)
               -- 聊天记录钉着的那一版不裁:它是「当时发的那一版」,得一直读得到。
               AND NOT EXISTS (SELECT 1 FROM chat.messages m WHERE m.file_item_id = v.item_id AND m.file_version = v.n)
            RETURNING v.blob_id
        )
        SELECT COALESCE(array_agg(chat.file_blob_pointer(g.blob_id)) FILTER (WHERE chat.file_blob_pointer(g.blob_id) IS NOT NULL), '{}') INTO v_pruned FROM gone g;
    END IF;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at, v_pruned,
           w.parent_id, w.system_role, chat.workspace_path_of(w.id)
      FROM chat.workspace_items w
     WHERE w.id = v_item.id;
END;
$$;


--
-- Name: file_blob_uploads; Type: TABLE; Schema: chat; Owner: -
--

CREATE TABLE chat.file_blob_uploads (
    staging_key text NOT NULL,
    uploader text NOT NULL,
    blob_id uuid NOT NULL,
    expires_at timestamp with time zone DEFAULT (now() + '01:00:00'::interval) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    message_id text,
    item_id uuid,
    item_version integer,
    envelope text,
    CONSTRAINT file_blob_uploads_own_key CHECK ((split_part(staging_key, '/'::text, 2) = uploader)),
    CONSTRAINT file_blob_uploads_staging_key_check CHECK ((staging_key ~ '^staging/[^/]+/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text))
);


--
-- Name: TABLE file_blob_uploads; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON TABLE chat.file_blob_uploads IS '服务端算完哈希的上传:这个人的暂存对象 staging/<uploader>/<uuid> = 这个 blob。一小时内由提交消费,过期由 chat.file_blob_sweep 清。只经 SECURITY DEFINER 的函数读写。';


--
-- Name: file_upload_take(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_upload_take(p_staging_key text) RETURNS chat.file_blob_uploads
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_upload chat.file_blob_uploads%ROWTYPE;
BEGIN
    SELECT * INTO v_upload FROM chat.file_blob_uploads u WHERE u.staging_key = p_staging_key FOR UPDATE;
    IF NOT FOUND OR v_upload.uploader IS DISTINCT FROM (SELECT auth.uid()::text) OR v_upload.expires_at <= now() THEN
        RAISE EXCEPTION USING HINT = 'attachment_upload_not_found',
            MESSAGE = format('no upload %s of yours is waiting to be placed', p_staging_key);
    END IF;
    IF v_upload.message_id IS NOT NULL THEN
        RAISE EXCEPTION USING HINT = 'attachment_upload_used',
            MESSAGE = format('upload %s was already sent as message %s', p_staging_key, v_upload.message_id);
    END IF;
    IF v_upload.item_id IS NULL THEN
        PERFORM chat.file_blob_take(v_upload.blob_id);
    END IF;
    RETURN v_upload;
END;
$$;


--
-- Name: file_urls_as(jsonb, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.file_urls_as(p_refs jsonb, p_as_user_id text) RETURNS TABLE(item_id uuid, version integer, message_id text, current_version integer, chat_id text, file_name text, bucket_id text, object_name text, sha256 text, size_bytes bigint, content_type text, width integer, height integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
BEGIN
    IF jsonb_typeof(p_refs) IS DISTINCT FROM 'array' OR jsonb_array_length(p_refs) > 200 THEN
        RAISE EXCEPTION 'file_urls_as: refs is an array of at most 200 {item_id, version} or {message_id}';
    END IF;
    RETURN QUERY
    WITH asked AS (
        SELECT CASE WHEN r.value ->> 'item_id' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    THEN (r.value ->> 'item_id')::uuid END AS ref_item,
               CASE WHEN r.value ->> 'version' ~ '^[0-9]{1,9}$' THEN (r.value ->> 'version')::INTEGER END AS ref_version,
               r.value ->> 'message_id' AS ref_message
          FROM jsonb_array_elements(p_refs) AS r(value)
    )
    SELECT DISTINCT w.id, COALESCE(a.ref_version, w.version), NULL::TEXT, w.version, w.chat_id, w.filename, b.bucket_id,
           b.object_name, b.sha256, b.size_bytes, b.content_type, b.width, b.height
      FROM asked a
      JOIN chat.workspace_items w ON w.id = a.ref_item
      JOIN chat.chats c ON c.id = w.chat_id AND c.kind IN ('group', 'topic', 'dm', 'ai')
      JOIN chat.file_blobs b ON b.id = chat.workspace_version_blob(w.id, COALESCE(a.ref_version, w.version))
     WHERE chat.is_chat_member(w.chat_id, v_actor)
    UNION
    SELECT NULL::UUID, NULL::INTEGER, m.id, NULL::INTEGER, m.chat_id,
           chat.attachment_envelope_name(m.content, b.size_bytes, b.content_type), b.bucket_id,
           b.object_name, b.sha256, b.size_bytes, b.content_type, b.width, b.height
      FROM asked a
      JOIN chat.messages m ON m.id = a.ref_message AND m.file_blob_id IS NOT NULL AND m.retracted_at IS NULL
      JOIN chat.file_blobs b ON b.id = m.file_blob_id
     WHERE chat.can_read_message(m.id, v_actor)
    -- ◇ 老式卡片:字节就是 storage 列指的那个 chat-media 对象(正文里的 [URL] 不参与);大小、类型取对象自己的元数据。
    UNION
    SELECT NULL::UUID, NULL::INTEGER, m.id, NULL::INTEGER, m.chat_id, chat.legacy_attachment_name(m.content),
           m.storage_bucket_id, m.storage_object_name, NULL::TEXT, NULLIF(o.metadata ->> 'size', '')::BIGINT,
           COALESCE(NULLIF(o.metadata ->> 'mimetype', ''), 'application/octet-stream'), NULL::INTEGER, NULL::INTEGER
      FROM asked a
      JOIN chat.messages m ON m.id = a.ref_message AND m.content_type = 'attachment' AND m.retracted_at IS NULL
                          AND m.file_item_id IS NULL AND m.file_blob_id IS NULL AND m.storage_bucket_id = 'chat-media'
      JOIN storage.objects o ON o.bucket_id = m.storage_bucket_id AND o.name = m.storage_object_name
     WHERE chat.can_read_message(m.id, v_actor);
END;
$_$;


--
-- Name: files_authorize(uuid, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.files_authorize(p_item_id uuid, p_user_id text, p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(chat_id text, epoch integer, content_type text, kind text, actor_id text, actor_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_user TEXT := NULLIF(btrim(COALESCE(p_user_id, '')), '');
    v_actor TEXT;
    v_prev_claims TEXT := current_setting('request.jwt.claims', true);
    v_prev_sub TEXT := current_setting('request.jwt.claim.sub', true);
    v_allowed BOOLEAN;
BEGIN
    IF v_user IS NULL OR p_item_id IS NULL THEN RETURN; END IF;
    v_actor := COALESCE(NULLIF(btrim(COALESCE(p_as_user_id, '')), ''), v_user);

    PERFORM set_config('request.jwt.claim.sub', v_user, true);
    PERFORM set_config('request.jwt.claims', jsonb_build_object('sub', v_user, 'role', 'authenticated')::text, true);
    v_allowed := chat.is_acting_as(v_actor);
    PERFORM set_config('request.jwt.claim.sub', COALESCE(v_prev_sub, ''), true);
    PERFORM set_config('request.jwt.claims', COALESCE(v_prev_claims, ''), true);
    IF NOT v_allowed THEN RETURN; END IF;

    RETURN QUERY
    SELECT w.chat_id, w.epoch, w.content_type, w.kind, v_actor, u.display_name
      FROM chat.workspace_items w
      JOIN chat.chats c ON c.id = w.chat_id AND c.kind IN ('group', 'topic', 'dm', 'ai')
      LEFT JOIN identity.users u ON u.id = v_actor
     WHERE w.id = p_item_id
       AND chat.is_chat_member(w.chat_id, v_actor);
END;
$$;


--
-- Name: FUNCTION files_authorize(p_item_id uuid, p_user_id text, p_as_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.files_authorize(p_item_id uuid, p_user_id text, p_as_user_id text) IS '文件服务验完 JWT 后的判权:p_user_id = JWT 的 sub,p_as_user_id = 以哪个 agent 的身份(空 = 本人)。资格走 chat.is_acting_as,可见域同 chat.workspace_item_for(群、话题、私聊、AI 单聊,actor 自己是成员)。不许 = 空结果。actor_name 给 presence 盖章。只授给 gugu_files。';


--
-- Name: files_record_version(uuid, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.files_record_version(p_item_id uuid, p_text text, p_made_by text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_keep CONSTANT INTEGER := 50;
    v_item chat.workspace_items%ROWTYPE;
    v_last chat.workspace_item_versions%ROWTYPE;
BEGIN
    IF p_text IS NULL THEN RAISE EXCEPTION 'files_record_version: text is required'; END IF;
    -- 锁住条目:同一个文件的两次记录(两台文件服务、或记录与删除)排队,编号不撞。
    SELECT * INTO v_item FROM chat.workspace_items w WHERE w.id = p_item_id FOR UPDATE;
    IF NOT FOUND THEN RETURN false; END IF;
    IF v_item.kind <> 'document' THEN
        RAISE EXCEPTION 'files_record_version: % is a stored file; its versions come with workspace_replace_file_as', p_item_id;
    END IF;
    SELECT * INTO v_last FROM chat.workspace_item_versions v WHERE v.item_id = p_item_id ORDER BY v.n DESC LIMIT 1;
    IF FOUND AND v_last.inline_text IS NOT DISTINCT FROM p_text THEN RETURN false; END IF;
    -- JSON 按值比(jsonb 的相等不看键的顺序,和文件服务加载时的 sameContent 同一个判法);解析不了就照上面文本比的结果。
    IF FOUND AND v_item.content_type ~* 'json' AND v_last.inline_text IS NOT NULL THEN
        BEGIN
            IF v_last.inline_text::jsonb = p_text::jsonb THEN RETURN false; END IF;
        EXCEPTION WHEN invalid_text_representation THEN NULL;
        END;
    END IF;

    INSERT INTO chat.workspace_item_versions (item_id, n, inline_text, content_type, size_bytes, made_by)
    VALUES (p_item_id, COALESCE(v_last.n, 0) + 1, p_text, v_item.content_type, octet_length(p_text),
            -- 作者不明(一次加载里第一笔改动之前的样子):文件从建好起正文没变过,那就是建它的人写的。
            COALESCE(NULLIF(btrim(COALESCE(p_made_by, '')), ''),
                     CASE WHEN v_last.n IS NULL AND v_item.updated_at = v_item.created_at THEN v_item.created_by END));

    DELETE FROM chat.workspace_item_versions v
     WHERE v.item_id = p_item_id
       AND v.n NOT IN (SELECT k.n FROM chat.workspace_item_versions k WHERE k.item_id = p_item_id ORDER BY k.n DESC LIMIT v_keep);
    RETURN true;
END;
$$;


--
-- Name: FUNCTION files_record_version(p_item_id uuid, p_text text, p_made_by text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.files_record_version(p_item_id uuid, p_text text, p_made_by text) IS '文件服务把文本文件的一轮改动记成一版(G2):与最近一版相同不记(false);n 接着最大的;留最近 50 版。p_made_by = 这一轮的人或 agent,不明为 NULL。只授给 gugu_files。';


--
-- Name: forwarded_source(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.forwarded_source(p_message_id text) RETURNS TABLE(source_chat_id text, source_chat_kind text, source_chat_name text)
    LANGUAGE sql STABLE
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT c.id, c.kind, c.name
    FROM chat.messages m
    JOIN chat.chats c ON c.id = m.chat_id
    WHERE m.id = NULLIF(p_message_id, '')
      AND m.deleted_at IS NULL
      AND NOT m.is_whisper;
$$;


--
-- Name: FUNCTION forwarded_source(p_message_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.forwarded_source(p_message_id text) IS '一条被转发消息的出处线(「引自:某某线」)。SECURITY INVOKER ⇒ 读者看不见那条线就读不到,界面退回只显「转发」——留痕不等于泄露。';


--
-- Name: get_or_create_agent_social_group(text, text[]); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.get_or_create_agent_social_group(p_agent_user_id text, p_other_user_ids text[]) RETURNS TABLE(chat_id text, name text, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner_user_id TEXT := auth.uid()::text;
    v_agent_user_id TEXT := NULLIF(p_agent_user_id, '');
    v_agent_name TEXT;
    v_other_user_ids TEXT[];
    v_other_user_names TEXT[];
    v_all_member_ids TEXT[];
    v_member_key TEXT;
    v_group_name TEXT;
    v_existing_chat_id TEXT;
    v_existing_name TEXT;
    v_chat_id TEXT;
BEGIN
    IF v_owner_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF v_agent_user_id IS NULL THEN
        RAISE EXCEPTION 'Agent is required';
    END IF;

    SELECT u.display_name
      INTO v_agent_name
      FROM identity.users u
     WHERE u.id = v_agent_user_id
       AND u.type = 'agent'
       AND u.owner_user_id = v_owner_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agent is not owned by current user';
    END IF;

    SELECT COALESCE(array_agg(id ORDER BY first_ord), ARRAY[]::TEXT[])
      INTO v_other_user_ids
      FROM (
          SELECT id, MIN(ord) AS first_ord
            FROM unnest(COALESCE(p_other_user_ids, ARRAY[]::TEXT[]))
                 WITH ORDINALITY AS input(id, ord)
           WHERE NULLIF(id, '') IS NOT NULL
             AND id <> v_owner_user_id
             AND id <> v_agent_user_id
           GROUP BY id
      ) normalized;

    IF cardinality(v_other_user_ids) = 0 THEN
        RAISE EXCEPTION 'Agent social group requires at least one other human member';
    END IF;

    IF (
        SELECT COUNT(*)
          FROM identity.users u
         WHERE u.id = ANY(v_other_user_ids)
           AND u.type = 'human'
    ) <> cardinality(v_other_user_ids) THEN
        RAISE EXCEPTION 'Selected member is not a human user';
    END IF;

    -- Owner friends may be contacted by the agent; a human who has an accepted
    -- request to this agent is also authorized to use the same group path.
    IF EXISTS (
        SELECT 1
          FROM unnest(v_other_user_ids) AS selected(id)
         WHERE NOT EXISTS (
             SELECT 1
               FROM identity.friendships f
              WHERE f.user_a_id = LEAST(v_owner_user_id, selected.id)
                AND f.user_b_id = GREATEST(v_owner_user_id, selected.id)
         )
           AND NOT EXISTS (
               SELECT 1
                 FROM identity.friend_requests fr
                WHERE fr.sender_id = selected.id
                  AND fr.receiver_id = v_agent_user_id
                  AND fr.status = 'accepted'
           )
    ) THEN
        RAISE EXCEPTION 'Selected human member is neither an owner friend nor an accepted agent requester';
    END IF;

    SELECT array_agg(u.display_name ORDER BY input.ord)
      INTO v_other_user_names
      FROM unnest(v_other_user_ids) WITH ORDINALITY AS input(id, ord)
      JOIN identity.users u ON u.id = input.id;

    IF cardinality(v_other_user_names) = 1 THEN
        v_group_name := v_agent_name || '、' || v_other_user_names[1];
    ELSIF cardinality(v_other_user_names) <= 3 THEN
        v_group_name := v_agent_name || '、' || array_to_string(v_other_user_names, '、');
    ELSE
        v_group_name := v_agent_name || '、' || v_other_user_names[1]
            || '等' || cardinality(v_other_user_names)::TEXT || '人';
    END IF;

    v_all_member_ids := ARRAY[v_owner_user_id, v_agent_user_id] || v_other_user_ids;

    SELECT array_to_string(array_agg(member_id ORDER BY member_id), ':')
      INTO v_member_key
      FROM unnest(v_all_member_ids) AS member_id;

    PERFORM pg_advisory_xact_lock(
        hashtextextended('chat:group-members:' || v_member_key, 0)
    );

    SELECT c.id, c.name
      INTO v_existing_chat_id, v_existing_name
      FROM chat.chats c
     WHERE c.kind = 'group'
       AND c.status = 'active'
       AND (
           SELECT COUNT(*)
             FROM chat.chat_members cm
            WHERE cm.chat_id = c.id
       ) = cardinality(v_all_member_ids)
       AND NOT EXISTS (
           SELECT 1
             FROM chat.chat_members cm
            WHERE cm.chat_id = c.id
              AND NOT (cm.user_id = ANY(v_all_member_ids))
       )
       AND EXISTS (
           SELECT 1
             FROM chat.chat_members cm
            WHERE cm.chat_id = c.id
              AND cm.user_id = v_owner_user_id
              AND cm.role = 'owner'
       )
     ORDER BY c.created_at ASC
     LIMIT 1;

    IF v_existing_chat_id IS NOT NULL THEN
        chat_id := v_existing_chat_id;
        name := COALESCE(v_existing_name, v_group_name);
        created := false;
        RETURN NEXT;
        RETURN;
    END IF;

    v_chat_id := gen_random_uuid()::text;

    SET CONSTRAINTS ALL DEFERRED;

    INSERT INTO chat.chats (id, kind, name, creator_user_id)
    VALUES (v_chat_id, 'group', v_group_name, v_owner_user_id);

    INSERT INTO chat.chat_members (chat_id, user_id, role)
    SELECT v_chat_id, member.user_id, member.role
      FROM (
          SELECT v_owner_user_id AS user_id, 'owner'::TEXT AS role
          UNION ALL
          SELECT v_agent_user_id AS user_id, 'member'::TEXT AS role
          UNION ALL
          SELECT other_user_id AS user_id, 'member'::TEXT AS role
            FROM unnest(v_other_user_ids) AS other_user_id
      ) member;

    INSERT INTO chat.group_agent_states (
        chat_id,
        agent_user_id,
        functional_role,
        capability_roles,
        last_action,
        updated_at
    )
    VALUES (
        v_chat_id,
        v_agent_user_id,
        'member',
        ARRAY['member']::TEXT[],
        '已加入群聊',
        now()
    );

    chat_id := v_chat_id;
    name := v_group_name;
    created := true;
    RETURN NEXT;
END;
$$;


--
-- Name: get_or_create_dm(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.get_or_create_dm(p_target_user_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
DECLARE
    v_current_user_id TEXT := auth.uid()::text;
    v_target_user_id TEXT := NULLIF(p_target_user_id, '');
    v_target_type TEXT;
    v_target_name TEXT;
    v_dm_name TEXT;
    v_user_low TEXT;
    v_user_high TEXT;
    v_chat_id TEXT;
BEGIN
    IF v_current_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF v_target_user_id IS NULL OR v_target_user_id = v_current_user_id THEN
        RAISE EXCEPTION 'Invalid DM target';
    END IF;

    SELECT u.type, u.display_name
    INTO v_target_type, v_target_name
    FROM identity.users u
    WHERE u.id = v_target_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Target user no longer exists';
    END IF;

    -- @@@dm-owned-agent-only (#509) - a DM whose target is an agent is only allowed
    -- when the caller owns that agent. A non-owner reaches the agent through the
    -- shared owner+agent+requester group instead, never a private 1:1 (privacy).
    -- IS DISTINCT FROM (not <>) so an agent with a NULL owner is also rejected — an
    -- ownerless agent must not be DM-able by anyone.
    IF EXISTS (
        SELECT 1 FROM identity.users u
        WHERE u.id = v_target_user_id
          AND u.type = 'agent'
          AND u.owner_user_id IS DISTINCT FROM v_current_user_id
    ) THEN
        RAISE EXCEPTION 'Cannot open a DM with an agent you do not own; use the shared group';
    END IF;

    -- @@@1623 - snapshot the agent's name into chats.name so the DM keeps a readable name after the agent is
    -- removed / its membership disappears. Only for agent DMs; human DMs keep NULL (peer name is computed live
    -- because a human can rename their profile). A blank agent name stays NULL → #1624 fail-loud (no fake).
    v_dm_name := CASE WHEN v_target_type = 'agent' THEN NULLIF(btrim(v_target_name), '') ELSE NULL END;

    v_user_low := LEAST(v_current_user_id, v_target_user_id);
    v_user_high := GREATEST(v_current_user_id, v_target_user_id);

    PERFORM pg_advisory_xact_lock(hashtextextended('chat:dm:' || v_user_low || ':' || v_user_high, 0));

    SELECT c.id
    INTO v_chat_id
    FROM chat.chats c
    WHERE c.kind = 'dm'
      AND c.status = 'active'
      AND EXISTS (
          SELECT 1 FROM chat.chat_members cm
          WHERE cm.chat_id = c.id
            AND cm.user_id = v_current_user_id
      )
      AND EXISTS (
          SELECT 1 FROM chat.chat_members cm
          WHERE cm.chat_id = c.id
            AND cm.user_id = v_target_user_id
      )
      AND (
          SELECT COUNT(*)
          FROM chat.chat_members cm
          WHERE cm.chat_id = c.id
      ) = 2
    ORDER BY c.created_at ASC
    LIMIT 1;

    IF v_chat_id IS NOT NULL THEN
        -- @@@1623 - heal an existing agent DM that predates this snapshot (name still NULL) while the agent is
        -- still resolvable. Only fill when currently NULL — never clobber an already-persisted name.
        IF v_dm_name IS NOT NULL THEN
            UPDATE chat.chats SET name = v_dm_name WHERE id = v_chat_id AND name IS NULL;
        END IF;
        RETURN v_chat_id;
    END IF;

    v_chat_id := gen_random_uuid()::text;
    INSERT INTO chat.chats (id, kind, name, creator_user_id)
    VALUES (v_chat_id, 'dm', v_dm_name, v_current_user_id);

    INSERT INTO chat.chat_members (chat_id, user_id, role)
    VALUES
        (v_chat_id, v_current_user_id, 'owner'),
        (v_chat_id, v_target_user_id, 'member');

    RETURN v_chat_id;
END;
$$;


--
-- Name: group_add_denial(text, text, text, boolean, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.group_add_denial(p_chat_id text, p_user_id text, p_actor_user_id text, p_take_seat boolean DEFAULT true, p_owner_consented boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_chat chat.chats%ROWTYPE;
    v_user_type TEXT;
    v_user_owner TEXT;
    v_actor_role TEXT;
    v_count INTEGER;
BEGIN
    IF p_actor_user_id IS NULL THEN
        RETURN 'not_authenticated';
    END IF;
    SELECT * INTO v_chat FROM chat.chats c WHERE c.id = p_chat_id;
    IF NOT FOUND OR v_chat.kind NOT IN ('group', 'topic') THEN
        RETURN 'not_a_group';
    END IF;
    IF v_chat.status = 'archived' THEN
        RETURN 'group_archived';
    END IF;
    SELECT u.type, u.owner_user_id INTO v_user_type, v_user_owner
      FROM identity.users u WHERE u.id = p_user_id;
    IF NOT FOUND THEN
        RETURN 'user_not_found';
    END IF;
    IF chat.is_cloud_agent_user(p_user_id) THEN
        RETURN 'cloud_agent';
    END IF;
    IF EXISTS (SELECT 1 FROM chat.chat_members cm WHERE cm.chat_id = p_chat_id AND cm.user_id = p_user_id) THEN
        RETURN NULL;
    END IF;

    SELECT cm.role INTO v_actor_role
      FROM chat.chat_members cm WHERE cm.chat_id = p_chat_id AND cm.user_id = p_actor_user_id;
    IF v_actor_role IS NULL THEN
        -- 唯一的例外:创建者给自己建第一张座位(群刚建出来、一个成员都还没有)。
        IF NOT (p_user_id = p_actor_user_id
                AND v_chat.creator_user_id = p_actor_user_id
                AND NOT EXISTS (SELECT 1 FROM chat.chat_members cm WHERE cm.chat_id = p_chat_id)) THEN
            RETURN 'actor_not_member';
        END IF;
    END IF;

    -- 话题:参与者只能是来源线里已有的人/agent(agent 能拉不能加,见 join_topic_participants),
    -- 来源线的门早已过过;话题不占座位,不数人数。
    IF v_chat.kind = 'topic' THEN
        IF NOT chat.is_chat_member(v_chat.source_chat_id, p_user_id) THEN
            RETURN 'not_in_source_line';
        END IF;
        RETURN NULL;
    END IF;

    -- agent 归属:被加的 agent 必须是操作者本人名下 —— ❌ 不因操作者是 owner/admin 豁免。
    -- agent 以主人身份活动,把它拉进群等于替它的主人入群,只能由主人发起。别人的 agent 只有两条合法来路:
    -- agent 群邀请(主人本人接受,decide_agent_group_invitation)与审批队列(入队的三个口子都已核过
    -- 发起方就是主人或主人已接受邀请,批准时 decide_group_join 传 p_owner_consented)。
    IF v_user_type = 'agent' AND v_user_owner IS DISTINCT FROM p_actor_user_id
       AND NOT COALESCE(p_owner_consented, false) THEN
        RETURN 'agent_not_owned';
    END IF;

    -- 管理员豁免的只有两道「群设置开关」(agent 审批、成员邀请),不含上面的归属。
    IF v_actor_role IS NOT NULL AND v_actor_role NOT IN ('owner', 'admin') THEN
        IF v_user_type = 'agent' THEN
            IF COALESCE(v_chat.agent_join_approval, false) THEN
                RETURN 'agent_join_requires_manager';
            END IF;
        ELSIF NOT COALESCE(v_chat.allow_member_invite, false) THEN
            RETURN 'member_invite_disabled';
        END IF;
    END IF;

    IF p_take_seat THEN
        SELECT count(*) INTO v_count FROM chat.chat_members cm WHERE cm.chat_id = p_chat_id;
        IF v_count >= COALESCE(v_chat.max_members, 100) THEN
            RETURN 'member_limit_reached';
        END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: group_collab_broadcast(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.group_collab_broadcast() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    affected_chat_id TEXT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        affected_chat_id := OLD.chat_id;
    ELSE
        affected_chat_id := NEW.chat_id;
    END IF;
    IF affected_chat_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    PERFORM chat.broadcast_to_chat_member_user_events(
        affected_chat_id,
        'group_collab_changed',
        jsonb_build_object(
            'chat_id', affected_chat_id,
            'table', TG_TABLE_NAME,
            'op', lower(TG_OP)
        )
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: guard_member_listen_mode_change(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.guard_member_listen_mode_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'chat', 'public'
    AS $$
BEGIN
  -- 只拦客户端直写:service_role、SECURITY DEFINER 函数(current_user 是定义者)不归这里管。
  IF current_user <> 'authenticated' THEN
    RETURN NEW;
  END IF;
  -- 改档位 = UPDATE 时值变了;INSERT 时带了非默认值(插入行的默认 'active' 见 20260919043000,集成测试钉着)。
  IF TG_OP = 'INSERT' THEN
    IF NEW.listen_mode IS NOT DISTINCT FROM 'active' THEN
      RETURN NEW;
    END IF;
  ELSIF NEW.listen_mode IS NOT DISTINCT FROM OLD.listen_mode THEN
    RETURN NEW;
  END IF;
  -- IS NOT TRUE:auth.uid() 为 NULL 时比较得 NULL,也算「不是本人或主人」⇒ 拒,默认关。
  IF (NEW.user_id = (SELECT auth.uid()::text) OR chat.is_owned_agent_user(NEW.user_id)) IS NOT TRUE THEN
    RAISE EXCEPTION '只有 agent 的主人能调整它在群里是主动还是被动'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: guard_member_role_change(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.guard_member_role_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    trusted_lifecycle_change BOOLEAN;
BEGIN
    IF NEW.role IS NOT DISTINCT FROM OLD.role THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM identity.account_lifecycle_context c
        JOIN chat.chats target_chat ON target_chat.id = NEW.chat_id
        WHERE c.transaction_id = pg_current_xact_id()
          AND c.operation = 'privacy_erasure'
          AND c.subject_user_id = c.delete_user_ids[1]
          AND (
              (OLD.role = 'owner' AND NEW.role <> 'owner'
               AND OLD.user_id = ANY(c.delete_user_ids))
              OR
              (OLD.role <> 'owner' AND NEW.role = 'owner'
               AND target_chat.creator_user_id = ANY(c.delete_user_ids))
          )
    ) INTO trusted_lifecycle_change;

    IF NOT COALESCE(trusted_lifecycle_change, false)
       AND session_user <> 'postgres'
       AND NOT chat.can_manage_group_members(NEW.chat_id) THEN
        RAISE EXCEPTION '只有群 owner/admin 能变更成员角色 (#1230 防自提升)'
            USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: gugu_can_send_as(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.gugu_can_send_as(p_owner_user_id text, p_chat_id text, p_sender_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM chat.chat_members cm
        WHERE cm.chat_id = p_chat_id
          AND cm.user_id = p_sender_user_id
    )
    AND (
        p_sender_user_id = p_owner_user_id
        OR EXISTS (
            SELECT 1
            FROM identity.users u
            WHERE u.id = p_sender_user_id
              AND u.type = 'agent'
              AND u.owner_user_id = p_owner_user_id
        )
    );
$$;


--
-- Name: gugu_decision_events_auto_settle(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.gugu_decision_events_auto_settle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.status <> 'pending' THEN
        RETURN NULL;
    END IF;

    UPDATE chat.gugu_decision_events
    SET status = 'settled',
        settled_at = now(),
        final_decision = 'approved',
        final_resource_states = CASE NEW.event_type
            WHEN 'group_stop' THEN jsonb_build_object('group', 'stopped')
            ELSE jsonb_build_object(
                'tasks',
                (
                    SELECT jsonb_object_agg(
                        task_id,
                        CASE NEW.event_type
                            WHEN 'task_proposed_decision' THEN 'in_progress'
                            WHEN 'task_submitted_decision' THEN 'completed'
                        END
                    )
                    FROM unnest(NEW.task_ids) AS task_id
                )
            )
        END,
        updated_at = now()
    WHERE id = NEW.id;

    RETURN NULL;
END;
$$;


--
-- Name: gugu_decision_events_broadcast(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.gugu_decision_events_broadcast() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    op_label TEXT;
    affected_chat_id TEXT;
BEGIN
    affected_chat_id := COALESCE(NEW.chat_id, OLD.chat_id);
    op_label := CASE
        WHEN TG_OP = 'INSERT' THEN 'created'
        WHEN TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status = 'settled' THEN 'settled'
        WHEN TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status = 'cancelled' THEN 'cancelled'
        WHEN TG_OP = 'DELETE' THEN 'deleted'
        ELSE 'updated'
    END;

    PERFORM chat.broadcast_to_chat_member_user_events(
        affected_chat_id,
        'gugu_decision_event',
        jsonb_build_object(
            'op', op_label,
            'event', row_to_json(COALESCE(NEW, OLD))
        )
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: gugu_decision_events_vote_scope_chk(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.gugu_decision_events_vote_scope_chk() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    caller_user_id TEXT;
    is_admin_or_owner BOOLEAN;
BEGIN
    IF identity.is_trusted_decision_erasure_update(OLD, NEW) THEN
        NEW.updated_at := now();
        RETURN NEW;
    END IF;

    caller_user_id := (SELECT auth.uid()::text);
    IF caller_user_id IS NULL THEN
        RAISE EXCEPTION 'no auth.uid() — cannot identify caller';
    END IF;

    is_admin_or_owner := EXISTS (
        SELECT 1 FROM chat.chat_members cm
        WHERE cm.chat_id = NEW.chat_id
          AND cm.user_id = caller_user_id
          AND cm.role IN ('owner', 'admin')
    );

    IF OLD.status = 'pending' AND NEW.status = 'cancelled' THEN
        IF NOT is_admin_or_owner THEN
            RAISE EXCEPTION 'only owner/admin can cancel decision';
        END IF;
        NEW.updated_at := now();
        RETURN NEW;
    END IF;

    IF OLD.status <> 'pending' THEN
        RAISE EXCEPTION 'cannot modify decision in status=%', OLD.status;
    END IF;

    IF NOT chat._keys_diff_owned_by(NEW.user_task_decisions, OLD.user_task_decisions, caller_user_id)
       OR NOT chat._keys_diff_owned_by(NEW.user_resource_states, OLD.user_resource_states, caller_user_id)
       OR NOT chat._keys_diff_owned_by(NEW.user_rationales, OLD.user_rationales, caller_user_id) THEN
        RAISE EXCEPTION 'supervisors can only modify their own vote keys';
    END IF;

    IF NEW.chat_id IS DISTINCT FROM OLD.chat_id
       OR NEW.event_type IS DISTINCT FROM OLD.event_type
       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id THEN
        RAISE EXCEPTION 'chat_id/event_type/created_by_user_id are immutable';
    END IF;

    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


--
-- Name: gugu_mark_message_delivered(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.gugu_mark_message_delivered(p_chat_id text, p_message_id text, p_agent_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM chat.messages m
        WHERE m.id = p_message_id
          AND m.chat_id = p_chat_id
          AND m.deleted_at IS NULL
    ) THEN
        RAISE EXCEPTION 'message % not found in chat %', p_message_id, p_chat_id;
    END IF;

    IF NOT chat.can_act_as(p_agent_user_id, p_chat_id) THEN
        RAISE EXCEPTION 'Token owner cannot mark delivery for agent % in chat %',
            p_agent_user_id,
            p_chat_id;
    END IF;

    INSERT INTO chat.message_deliveries (
        message_id,
        device_id,
        status,
        delivered_at
    )
    VALUES (
        p_message_id,
        'gugu-agent:' || p_agent_user_id,
        'delivered',
        now()
    )
    ON CONFLICT (message_id, device_id) DO UPDATE SET
        status = CASE
            WHEN chat.message_deliveries.status = 'read' THEN 'read'
            ELSE 'delivered'
        END,
        delivered_at = COALESCE(chat.message_deliveries.delivered_at, EXCLUDED.delivered_at),
        updated_at = now();
END;
$$;


--
-- Name: gugu_token_context(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.gugu_token_context(p_token text, p_required_scope text) RETURNS TABLE(user_id text, key_id text, scopes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT v.user_id, v.key_id, v.scopes
    FROM identity.verify_api_key(p_token) AS v
    WHERE identity.api_key_has_scope(v.scopes, p_required_scope)
    LIMIT 1;
END;
$$;


--
-- Name: history_floor(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.history_floor(p_chat_id text, p_actor text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT LEAST(
        (SELECT COALESCE(cm.hide_history_before, '-infinity'::timestamptz)
           FROM chat.chat_members cm
          WHERE cm.chat_id = p_chat_id AND cm.user_id = p_actor),
        (SELECT COALESCE(cm.hide_history_before, '-infinity'::timestamptz)
           FROM chat.chats t
           JOIN chat.chat_members cm ON cm.chat_id = t.source_chat_id AND cm.user_id = p_actor
          WHERE t.id = p_chat_id AND t.kind = 'topic'))
$$;


--
-- Name: import_agent_session_history(text, text, text, jsonb); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.import_agent_session_history(p_agent_user_id text, p_chat_id text, p_title text, p_turns jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner_id  TEXT := auth.uid()::text;
    v_root_id   TEXT := gen_random_uuid()::text;
    v_turn      JSONB;
    v_role      TEXT;
    v_content   TEXT;
    v_created   TIMESTAMPTZ;
    v_first_at  TIMESTAMPTZ;
    v_last_seq  BIGINT;
BEGIN
    IF v_owner_id IS NULL THEN
        RAISE EXCEPTION 'import_agent_session_history requires authenticated session';
    END IF;
    IF NULLIF(btrim(COALESCE(p_title, '')), '') IS NULL THEN
        RAISE EXCEPTION 'import_agent_session_history requires title';
    END IF;
    IF jsonb_typeof(p_turns) IS DISTINCT FROM 'array' OR jsonb_array_length(p_turns) = 0 THEN
        RAISE EXCEPTION 'import_agent_session_history requires non-empty turns array';
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM identity.users u
         WHERE u.id = p_agent_user_id
           AND u.type = 'agent'
           AND u.owner_user_id = v_owner_id
    ) THEN
        RAISE EXCEPTION 'import_agent_session_history agent % is not owned by caller', p_agent_user_id;
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM chat.chats c
         WHERE c.id = p_chat_id
           AND c.kind = 'dm'
           AND c.status = 'active'
           AND (SELECT count(*) FROM chat.chat_members cm WHERE cm.chat_id = c.id) = 2
           AND chat.is_chat_member(c.id, v_owner_id)
           AND chat.is_chat_member(c.id, p_agent_user_id)
    ) THEN
        RAISE EXCEPTION 'import_agent_session_history chat % is not the owner-agent DM', p_chat_id;
    END IF;

    SELECT NULLIF(t->>'createdAt', '')::timestamptz
      INTO v_first_at
      FROM jsonb_array_elements(p_turns) t
     WHERE NULLIF(t->>'createdAt', '') IS NOT NULL
     LIMIT 1;

    -- Provenance header = the thread root (owner-authored source note; NOT a conversation turn, and its
    -- text does not repeat the first turn → no duplicate). It anchors the thread and supplies its label.
    INSERT INTO chat.messages (
        id, chat_id, sender_user_id, content, content_type,
        client_message_id, is_thread_root, created_at
    ) VALUES (
        v_root_id, p_chat_id, v_owner_id, btrim(p_title), 'text',
        'session-import-root:' || gen_random_uuid()::text, true, COALESCE(v_first_at, now())
    );

    FOR v_turn IN SELECT value FROM jsonb_array_elements(p_turns)
    LOOP
        v_role := v_turn->>'role';
        v_content := v_turn->>'content';
        IF v_role NOT IN ('user', 'assistant') THEN
            RAISE EXCEPTION 'import_agent_session_history invalid turn role %', v_role;
        END IF;
        IF NULLIF(btrim(COALESCE(v_content, '')), '') IS NULL THEN
            RAISE EXCEPTION 'import_agent_session_history empty turn content';
        END IF;
        v_created := NULLIF(v_turn->>'createdAt', '')::timestamptz;
        INSERT INTO chat.messages (
            id, chat_id, sender_user_id, content, content_type,
            client_message_id, thread_root_id, created_at
        ) VALUES (
            gen_random_uuid()::text,
            p_chat_id,
            CASE WHEN v_role = 'user' THEN v_owner_id ELSE p_agent_user_id END,
            v_content,
            'text',
            'session-import-turn:' || gen_random_uuid()::text,
            v_root_id,
            COALESCE(v_created, v_first_at, now())
        );
    END LOOP;

    SELECT max(m.seq) INTO v_last_seq FROM chat.messages m WHERE m.chat_id = p_chat_id;
    UPDATE chat.chat_members
       SET last_read_seq = GREATEST(last_read_seq, COALESCE(v_last_seq, 0)),
           updated_at = now()
     WHERE chat_id = p_chat_id
       AND user_id IN (v_owner_id, p_agent_user_id);

    RETURN v_root_id;
END;
$$;


--
-- Name: is_acting_as(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_acting_as(p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT (SELECT auth.uid()) IS NULL   -- 服务端自己(service_role / 内部会话):anon 没有 EXECUTE,到不了这里
        OR p_user_id = (SELECT auth.uid()::text)
        OR EXISTS (
            SELECT 1 FROM identity.users u
             WHERE u.id = p_user_id
               AND u.type = 'agent'
               AND u.owner_user_id = (SELECT auth.uid()::text)
        );
$$;


--
-- Name: FUNCTION is_acting_as(p_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.is_acting_as(p_user_id text) IS '@@@5856 调用者有没有资格以 p_user_id 的身份提问:本人,或自己名下的 agent。auth.uid() 为空=服务端自己。';


--
-- Name: is_addressable_in(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_addressable_in(p_chat_id text, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT chat.caller_may_probe_chat(p_chat_id)
       AND (
            chat.is_chat_member(p_chat_id, p_user_id)
            OR EXISTS (
                SELECT 1 FROM chat.chats t
                WHERE t.id = p_chat_id
                  AND t.kind = 'topic'
                  AND chat.is_chat_member(t.source_chat_id, p_user_id)
            )
       );
$$;


--
-- Name: is_agent_user(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_agent_user(p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM identity.users u
        WHERE u.id = p_user_id
          AND u.type = 'agent'
    );
$$;


--
-- Name: is_chat_member(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_chat_member(p_chat_id text, p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM chat.chat_members cm
        WHERE cm.chat_id = p_chat_id
          AND cm.user_id = p_user_id
    );
$$;


--
-- Name: is_cloud_agent_user(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_cloud_agent_user(p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM identity.users u
        LEFT JOIN identity.agent_profiles ap ON ap.id::text = u.id
        WHERE u.id = p_user_id
          AND u.type = 'agent'
          AND (ap.agent_type = 'gugu-cloud' OR u.device_id LIKE 'cloud:%')
    );
$$;


--
-- Name: is_group_creator(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_group_creator(p_chat_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM chat.chats c
        WHERE c.id = p_chat_id
          AND c.creator_user_id = (SELECT auth.uid()::text)
    );
$$;


--
-- Name: is_member(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_member(p_chat_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM chat.chat_members
        WHERE chat_id = p_chat_id
          AND user_id = (SELECT auth.uid()::text)
    );
$$;


--
-- Name: is_owned_agent_user(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.is_owned_agent_user(p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM identity.users u
        WHERE u.id = p_user_id
          AND u.type = 'agent'
          AND u.owner_user_id = (SELECT auth.uid()::text)
    );
$$;


--
-- Name: join_public_group(integer, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.join_public_group(p_public_id integer, p_join_token text) RETURNS TABLE(chat_id text, public_id integer, kind text, name text, member_count integer, is_member boolean, is_muted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
declare
    v_current_user_id text := auth.uid()::text;
    v_chat_id text;
    v_token text;
    v_max_members integer;
    v_count integer;
    v_already boolean;
    v_invite_link_enabled boolean;
    v_join_mode text;
begin
    if v_current_user_id is null then
        raise exception 'Not authenticated';
    end if;
    if p_public_id is null or p_public_id <= 0 then
        raise exception 'Public group id is required';
    end if;
    if p_join_token is null or length(trim(p_join_token)) = 0 then
        raise exception 'Join token is required';
    end if;

    -- 锁群行再判(与 add_group_agent / decide_group_join 同一把锁):两个人同时拿链接加入快满的群,
    -- 后到的等前一笔提交后再数人数。
    select c.id, c.join_token, coalesce(c.max_members, 100), coalesce(c.invite_link_enabled, true),
           coalesce(c.join_mode, 'open')
      into v_chat_id, v_token, v_max_members, v_invite_link_enabled, v_join_mode
      from chat.chats c
     where c.public_id = p_public_id
       and c.kind = 'group'
       and c.status <> 'archived'
     limit 1
       for update;

    if v_chat_id is null then
        raise exception 'Public group not found';
    end if;

    if v_token is null or p_join_token <> v_token then
        raise exception 'Invalid join token';
    end if;

    -- #1240 fix：限定 chat_members.chat_id，避免与 RETURNS TABLE 的 OUT-col chat_id 歧义(42702)。
    select exists(select 1 from chat.chat_members where chat_members.chat_id = v_chat_id and user_id = v_current_user_id)
      into v_already;

    -- 抛稳定的 ASCII 标识(与 request_group_join_by_id 同一套),客户端按它分流成产品文案。
    if not v_already and v_invite_link_enabled is not true then
        raise exception 'group_self_serve_closed';
    end if;

    -- 安全:邀请链接 token 只证明「你拿到过链接」,不绕过群主设的入群方式。
    -- approval 群要走申请(request_group_join),invite_only 群只能被邀请。
    if not v_already and v_join_mode = 'invite_only' then
        raise exception 'group_invite_only';
    end if;
    if not v_already and v_join_mode = 'approval' then
        raise exception 'group_join_requires_approval';
    end if;

    if not v_already then
        -- #1240 fix：同上限定 chat_members.chat_id。
        select count(*) into v_count from chat.chat_members where chat_members.chat_id = v_chat_id;
        if v_count >= v_max_members then
            raise exception 'Group member limit reached';
        end if;
    end if;

    insert into chat.chat_members (chat_id, user_id, role)
    values (v_chat_id, v_current_user_id, 'member')
    on conflict on constraint chat_members_pkey do nothing;

    return query
    select lookup.chat_id, lookup.public_id, lookup.kind, lookup.name,
           lookup.member_count, lookup.is_member, lookup.is_muted
    from chat.lookup_public_group(p_public_id) lookup;
end;
$$;


--
-- Name: join_topic_participants(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.join_topic_participants() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_source_chat_id TEXT;
BEGIN
    SELECT c.source_chat_id INTO v_source_chat_id
    FROM chat.chats c
    WHERE c.id = NEW.chat_id AND c.kind = 'topic';

    IF v_source_chat_id IS NULL THEN
        RETURN NEW;
    END IF;

    -- 说话就是参与
    IF NEW.sender_user_id IS NOT NULL THEN
        INSERT INTO chat.chat_members (chat_id, user_id, role, joined_ingest_seq)
        VALUES (NEW.chat_id, NEW.sender_user_id, 'member', NEW.ingest_seq - 1)
        ON CONFLICT (chat_id, user_id) DO NOTHING;
    END IF;

    -- 被 @ 就是被拉进来(只限来源线里已有的人/agent:agent 能拉不能加,见 agent-social)。
    -- 在这条消息入群(界 = NEW.ingest_seq - 1,门 `>`):拉你进来的这一条,你收得到(#6405)。
    IF NEW.to_user_ids IS NOT NULL THEN
        INSERT INTO chat.chat_members (chat_id, user_id, role, joined_ingest_seq)
        SELECT NEW.chat_id, target.user_id, 'member', NEW.ingest_seq - 1
        FROM unnest(NEW.to_user_ids) AS target(user_id)
        WHERE target.user_id <> '*'
          AND chat.is_chat_member(v_source_chat_id, target.user_id)
        ON CONFLICT (chat_id, user_id) DO NOTHING;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION join_topic_participants(); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.join_topic_participants() IS 'spec「参与:靠在里面说话,或被 @ 进来」。BEFORE INSERT ⇒ 跑在投递触发器之前;新成员在这条消息入群(joined_ingest_seq = 这条的 ingest_seq - 1,门 >),刚被 @ 进来的 agent 这一条就收得到(push 与 pull 都算它)。';


--
-- Name: leave_topics_of_source_line(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.leave_topics_of_source_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    DELETE FROM chat.chat_members cm
     USING chat.chats t
     WHERE t.id = cm.chat_id
       AND t.kind = 'topic'
       AND t.source_chat_id = OLD.chat_id
       AND cm.user_id = OLD.user_id;
    RETURN OLD;
END;
$$;


--
-- Name: legacy_attachment_name(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.legacy_attachment_name(p_content text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    v_head CONSTANT TEXT := '[附件] ';
    v_line TEXT := split_part(COALESCE(p_content, ''), E'\n', 1);
    v_name TEXT;
BEGIN
    IF left(v_line, char_length(v_head)) <> v_head THEN
        RETURN NULL;
    END IF;
    v_name := substr(v_line, char_length(v_head) + 1);
    IF v_name ~ ' \([^()]*\)$' THEN
        v_name := regexp_replace(v_name, ' \([^()]*\)$', '');
    END IF;
    RETURN NULLIF(v_name, '');
END;
$_$;


--
-- Name: list_agent_group_invitations(text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_agent_group_invitations(p_agent_user_id text DEFAULT NULL::text, p_include_decided boolean DEFAULT false) RETURNS TABLE(id text, chat_id text, group_name text, inviter_agent_user_id text, inviter_name text, inviter_owner_name text, invitee_user_id text, invitee_name text, invitee_type text, decision_user_id text, owner_will_join boolean, message text, status text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    IF p_agent_user_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM identity.users actor WHERE actor.id = p_agent_user_id AND actor.type = 'agent' AND actor.owner_user_id = auth.uid()::text
    ) THEN RAISE EXCEPTION 'Agent is not owned by this account'; END IF;
    RETURN QUERY SELECT i.id, i.chat_id, c.name, i.inviter_agent_user_id, sender.display_name, sender_owner.display_name,
        i.invitee_user_id, target.display_name, target.type, i.decision_user_id,
        target.type = 'agent' AND NOT EXISTS (SELECT 1 FROM chat.chat_members m WHERE m.chat_id = i.chat_id AND m.user_id = i.decision_user_id),
        i.message, i.status, i.created_at
    FROM chat.group_invitations i
    JOIN chat.chats c ON c.id = i.chat_id
    JOIN identity.users sender ON sender.id = i.inviter_agent_user_id
    JOIN identity.users sender_owner ON sender_owner.id = i.inviter_owner_user_id
    JOIN identity.users target ON target.id = i.invitee_user_id
    WHERE (p_agent_user_id IS NULL AND i.decision_user_id = auth.uid()::text AND (p_include_decided OR i.status = 'pending'))
       OR (p_agent_user_id IS NOT NULL AND i.inviter_agent_user_id = p_agent_user_id AND i.inviter_owner_user_id = auth.uid()::text)
    ORDER BY (i.status = 'pending') DESC, i.created_at DESC;
END;
$$;


--
-- Name: list_group_join_requests(text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_group_join_requests(p_chat_id text, p_include_decided boolean DEFAULT false) RETURNS TABLE(id text, chat_id text, requester_user_id text, requester_name text, requester_avatar text, message text, status text, created_at timestamp with time zone, requester_type text, requested_by_user_id text, requested_by_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    IF NOT chat.can_manage_group_members(p_chat_id) THEN RAISE EXCEPTION 'Not authorized'; END IF;
    RETURN QUERY
    SELECT r.id, r.chat_id, r.requester_user_id, u.display_name, u.avatar, r.message, r.status, r.created_at,
           u.type, r.requested_by_user_id, b.display_name
      FROM chat.group_join_requests r
      JOIN identity.users u ON u.id = r.requester_user_id
      LEFT JOIN identity.users b ON b.id = r.requested_by_user_id
     WHERE r.chat_id = p_chat_id AND (p_include_decided OR r.status = 'pending')
     ORDER BY (r.status = 'pending') DESC, r.created_at DESC;
END;
$$;


--
-- Name: list_member_ids(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_member_ids(p_chat_id text, p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(user_id text, role text, listen_mode text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_caller TEXT := (SELECT auth.uid()::text);
    v_actor TEXT;
    v_is_agent BOOLEAN;
    v_owner TEXT;
BEGIN
    v_actor := COALESCE(NULLIF(trim(p_as_user_id), ''), v_caller);
    SELECT u.type = 'agent', u.owner_user_id INTO v_is_agent, v_owner
      FROM identity.users u WHERE u.id = v_actor;
    IF v_actor IS DISTINCT FROM v_caller AND NOT (COALESCE(v_is_agent, false) AND v_owner = v_caller) THEN
        RAISE EXCEPTION 'Not allowed to act as %', v_actor;
    END IF;
    -- 与 chat.chat_facts 同一个可见域:actor 在,或调用者(主人)在,或这是一条话题而两人之一在来源线。
    IF NOT EXISTS (
        SELECT 1 FROM chat.chats c
         WHERE c.id = p_chat_id
           AND (
               chat.is_chat_member(c.id, v_actor)
               OR chat.is_chat_member(c.id, v_caller)
               OR (c.kind = 'topic' AND c.source_chat_id IS NOT NULL
                   AND (chat.is_chat_member(c.source_chat_id, v_actor)
                        OR chat.is_chat_member(c.source_chat_id, v_caller)))
           )
    ) THEN
        RETURN;
    END IF;
    RETURN QUERY SELECT cm.user_id, cm.role, cm.listen_mode
                   FROM chat.chat_members cm WHERE cm.chat_id = p_chat_id;
END;
$$;


--
-- Name: list_my_agent_join_requests(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_my_agent_join_requests(p_chat_id text) RETURNS TABLE(id text, agent_user_id text, agent_name text, status text, updated_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT r.id, r.requester_user_id, u.display_name, r.status, r.updated_at
      FROM chat.group_join_requests r
      JOIN identity.users u ON u.id = r.requester_user_id
     WHERE r.chat_id = p_chat_id
       AND r.requested_by_user_id = (SELECT auth.uid()::text)
     ORDER BY r.updated_at DESC;
$$;


--
-- Name: list_my_chats_as(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_my_chats_as(p_as_user_id text) RETURNS TABLE(chat_id text, public_id integer, kind text, status text, name text, role text, listen_mode text, last_message_at timestamp with time zone, last_message_preview text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_caller TEXT := (SELECT auth.uid()::text);
    v_actor TEXT := NULLIF(btrim(COALESCE(p_as_user_id, '')), '');
BEGIN
    IF v_caller IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    IF v_actor IS NULL OR NOT chat.is_acting_as(v_actor) THEN
        RAISE EXCEPTION 'Not allowed to act as %', COALESCE(v_actor, '<null>');
    END IF;

    RETURN QUERY
    SELECT c.id,
           c.public_id,
           c.kind,
           c.status,
           c.name,
           mine.role,
           mine.listen_mode,
           c.last_message_at,
           c.last_message_preview
      FROM chat.chat_members mine
      JOIN chat.chats c ON c.id = mine.chat_id
     WHERE mine.user_id = v_actor
       AND c.status IN ('active', 'stopped', 'paused')
     ORDER BY c.last_message_at DESC NULLS LAST, c.created_at DESC;
END;
$$;


--
-- Name: FUNCTION list_my_chats_as(p_as_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.list_my_chats_as(p_as_user_id text) IS 'p_as_user_id 自己是成员的会话(active / stopped / paused),带它在每个会话里的 role 与 listen_mode;按它自己的成员行判,❌ 不按调用者。';


--
-- Name: list_owner_groups_as(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_owner_groups_as(p_as_user_id text) RETURNS TABLE(chat_id text, public_id integer, name text, member_count integer, joined boolean, agent_join_needs_approval boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_owner TEXT := (SELECT auth.uid()::text);
    v_actor TEXT := NULLIF(btrim(COALESCE(p_as_user_id, '')), '');
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    -- 提问资格走统一的 chat.is_acting_as:本人,或自己名下的 agent。替本人问时 joined 恒为 true。
    IF v_actor IS NULL OR NOT chat.is_acting_as(v_actor) THEN
        RAISE EXCEPTION 'Not allowed to act as %', COALESCE(v_actor, '<null>');
    END IF;

    RETURN QUERY
    SELECT c.id,
           c.public_id,
           c.name,
           (SELECT count(*)::INTEGER FROM chat.chat_members cm WHERE cm.chat_id = c.id),
           EXISTS (SELECT 1 FROM chat.chat_members cm WHERE cm.chat_id = c.id AND cm.user_id = v_actor),
           COALESCE(c.agent_join_approval, false) AND mine.role NOT IN ('owner', 'admin')
      FROM chat.chat_members mine
      JOIN chat.chats c ON c.id = mine.chat_id
     WHERE mine.user_id = v_owner
       AND c.kind = 'group'
       AND c.status = 'active'
     ORDER BY c.last_message_at DESC NULLS LAST, c.created_at DESC;
END;
$$;


--
-- Name: FUNCTION list_owner_groups_as(p_as_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.list_owner_groups_as(p_as_user_id text) IS '#6492 主人所在的活跃群(不含话题,不含 stopped / paused / archived),替本人或名下 agent p_as_user_id 列:只给入群要用的元数据,❌ 不给预览或正文。第 3 件起本人也能问(App 的 groups.list)。';


--
-- Name: list_topics_of_chat(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_topics_of_chat(p_source_chat_id text, p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(chat_id text, name text, source_message_id text, creator_user_id text, last_message_at timestamp with time zone, message_count bigint, participant_count bigint, is_participant boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_caller TEXT := (SELECT auth.uid()::text);
    v_actor TEXT;
    v_actor_owner TEXT;
    v_actor_is_agent BOOLEAN;
BEGIN
    v_actor := COALESCE(p_as_user_id, v_caller);
    SELECT u.type = 'agent', u.owner_user_id INTO v_actor_is_agent, v_actor_owner
      FROM identity.users u WHERE u.id = v_actor;
    IF v_actor IS DISTINCT FROM v_caller
       AND NOT (COALESCE(v_actor_is_agent, false) AND v_actor_owner = v_caller) THEN
        RAISE EXCEPTION 'Not allowed to act as %', v_actor;
    END IF;

    -- 与 create_topic 同形:actor 在来源线,**或** actor 是 agent 且主人在来源线。
    -- 两边不同形的后果是 agent 开得出话题却列不出来,而这个函数的用途正是
    -- 「开第二条之前先看看有没有」—— 它永远回「没有」,于是同一个问题被开成一串重复的线。
    IF NOT chat.is_chat_member(p_source_chat_id, v_actor)
       AND NOT (COALESCE(v_actor_is_agent, false)
                AND v_actor_owner IS NOT NULL
                AND chat.is_chat_member(p_source_chat_id, v_actor_owner)) THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        t.id,
        t.name,
        t.source_message_id,
        t.creator_user_id,
        t.last_message_at,
        -- 数的是 actor 读得到的条数:与 message_history_as 同一组条件(未删 + 可见下界 + 悄悄话规则);
        -- 下界每个话题只算一次,逐行只剩内联后的悄悄话规则。
        (SELECT count(*) FROM chat.messages m
          WHERE m.chat_id = t.id AND m.deleted_at IS NULL
            AND m.created_at >= (SELECT chat.history_floor(t.id, v_actor))
            AND chat.whisper_visible_to(m.is_whisper, m.sender_user_id, m.to_user_ids, v_actor)),
        (SELECT count(*) FROM chat.chat_members cm WHERE cm.chat_id = t.id),
        chat.is_chat_member(t.id, v_actor)
    FROM chat.chats t
    WHERE t.kind = 'topic'
      AND t.source_chat_id = p_source_chat_id
    ORDER BY t.last_message_at DESC NULLS LAST, t.created_at DESC;
END;
$$;


--
-- Name: FUNCTION list_topics_of_chat(p_source_chat_id text, p_as_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.list_topics_of_chat(p_source_chat_id text, p_as_user_id text) IS '一条线上长出来的全部话题(锚点卡与话题面板都读它)。可见继承来源:只要 actor 在来源线里就列得出,是不是参与者另外一列说清。actor 默认是调用者,agent 走 MCP 时必须显式传它自己 —— 用的是主人的 JWT,不传就会把「主人在不在」当成「我在不在」答出去。';


--
-- Name: list_unread_locators(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.list_unread_locators(p_chat_id text DEFAULT NULL::text) RETURNS TABLE(chat_id text, stream_id text, stream_kind text, thread_root_id text, message_id text, message_seq bigint, unread_count bigint, cursor_seq bigint, version integer, is_marked_unread boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_user TEXT := (SELECT auth.uid()::text);
BEGIN
  IF v_user IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  IF p_chat_id IS NOT NULL AND NOT chat.can_act_as(v_user, p_chat_id) THEN
    RAISE EXCEPTION 'not authorized to read unread locator for chat %', p_chat_id;
  END IF;

  RETURN QUERY
  WITH streams AS (
    SELECT source.chat_id, source.stream_id, source.stream_kind, source.thread_root_id,
           source.last_read_seq, source.is_marked_unread, source.version,
           COUNT(message.id)::BIGINT AS unread_count,
           MIN(message.seq) AS first_seq,
           (ARRAY_AGG(message.id ORDER BY message.seq, message.id)
             FILTER (WHERE message.id IS NOT NULL))[1] AS first_id
    FROM (
      SELECT member.chat_id, 'main:' || member.chat_id AS stream_id, 'main'::TEXT AS stream_kind,
             NULL::TEXT AS thread_root_id, member.last_read_seq, member.is_marked_unread,
             member.version, member.hide_history_before
      FROM chat.chat_members member
      JOIN chat.chats conversation ON conversation.id = member.chat_id
      WHERE member.user_id = v_user
        AND member.inbox_published_at IS NOT NULL
        AND conversation.status IN ('active', 'stopped', 'paused')
        AND (p_chat_id IS NULL OR member.chat_id = p_chat_id)
      UNION ALL
      SELECT stream.chat_id, stream.stream_id, stream.stream_kind, stream.thread_root_id,
             stream.last_read_seq, stream.is_marked_unread, stream.version, member.hide_history_before
      FROM chat.chat_member_stream_read_state stream
      JOIN chat.chat_members member
        ON member.chat_id = stream.chat_id AND member.user_id = stream.user_id
      JOIN chat.chats conversation ON conversation.id = stream.chat_id
      WHERE stream.user_id = v_user
        AND stream.stream_kind = 'thread'
        AND member.inbox_published_at IS NOT NULL
        AND conversation.status IN ('active', 'stopped', 'paused')
        AND (p_chat_id IS NULL OR stream.chat_id = p_chat_id)
      UNION ALL
      SELECT root.chat_id, 'thread:' || root.chat_id || ':' || root.id, 'thread'::TEXT, root.id,
             0, false, 0, member.hide_history_before
      FROM chat.messages root
      JOIN chat.chat_members member ON member.chat_id = root.chat_id AND member.user_id = v_user
      JOIN chat.chats conversation ON conversation.id = root.chat_id
      WHERE root.thread_root_id IS NULL
        AND root.is_thread_root = true
        AND NOT COALESCE(
          root.client_message_id ~ '^session-import-root:[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',
          false
        )
        AND root.deleted_at IS NULL
        AND member.inbox_published_at IS NOT NULL
        AND conversation.kind = 'group'
        AND conversation.status IN ('active', 'stopped', 'paused')
        AND (p_chat_id IS NULL OR root.chat_id = p_chat_id)
        AND EXISTS (
          SELECT 1 FROM chat.messages reply
          WHERE reply.chat_id = root.chat_id
            AND reply.thread_root_id = root.id
            AND reply.deleted_at IS NULL
            AND NOT (reply.deleted_for_user_ids @> jsonb_build_array(v_user))
            AND (member.hide_history_before IS NULL OR reply.created_at >= member.hide_history_before)
            AND reply.seq > 0
            AND reply.sender_user_id <> v_user
            AND chat.whisper_visible_to(reply.is_whisper, reply.sender_user_id, reply.to_user_ids, v_user)
        )
        AND NOT EXISTS (
          SELECT 1 FROM chat.chat_member_stream_read_state existing
          WHERE existing.chat_id = root.chat_id
            AND existing.user_id = v_user
            AND existing.stream_id = 'thread:' || root.chat_id || ':' || root.id
        )
    ) source
    LEFT JOIN chat.messages message
      ON message.chat_id = source.chat_id
     AND message.deleted_at IS NULL
     AND NOT (message.deleted_for_user_ids @> jsonb_build_array(v_user))
     AND (source.hide_history_before IS NULL OR message.created_at >= source.hide_history_before)
     AND message.seq > source.last_read_seq
     AND message.sender_user_id <> v_user
     AND chat.whisper_visible_to(message.is_whisper, message.sender_user_id, message.to_user_ids, v_user)
     AND ((source.stream_kind = 'main' AND message.thread_root_id IS NULL)
       OR (source.stream_kind = 'thread' AND message.thread_root_id = source.thread_root_id))
    GROUP BY source.chat_id, source.stream_id, source.stream_kind, source.thread_root_id,
             source.last_read_seq, source.is_marked_unread, source.version, source.hide_history_before
  )
  SELECT streams.chat_id, streams.stream_id, streams.stream_kind, streams.thread_root_id,
         COALESCE(streams.first_id, manual.message_id),
         COALESCE(streams.first_seq, manual.message_seq),
         GREATEST(streams.unread_count, CASE WHEN streams.is_marked_unread THEN 1 ELSE 0 END),
         streams.last_read_seq, streams.version, streams.is_marked_unread
  FROM streams
  LEFT JOIN LATERAL (
    SELECT message.id AS message_id, message.seq AS message_seq
    FROM chat.messages message
    JOIN chat.chat_members member
      ON member.chat_id = streams.chat_id AND member.user_id = v_user
    WHERE streams.is_marked_unread
      AND streams.first_id IS NULL
      AND message.chat_id = streams.chat_id
      AND message.deleted_at IS NULL
      AND NOT (message.deleted_for_user_ids @> jsonb_build_array(v_user))
      AND (member.hide_history_before IS NULL OR message.created_at >= member.hide_history_before)
      AND chat.whisper_visible_to(message.is_whisper, message.sender_user_id, message.to_user_ids, v_user)
      AND ((streams.stream_kind = 'main' AND message.thread_root_id IS NULL)
        OR (streams.stream_kind = 'thread' AND message.thread_root_id = streams.thread_root_id))
    ORDER BY message.seq DESC, message.id DESC
    LIMIT 1
  ) manual ON true
  WHERE streams.unread_count > 0 OR manual.message_id IS NOT NULL
  ORDER BY COALESCE(streams.first_seq, manual.message_seq), streams.stream_id;
END;
$_$;


--
-- Name: lock_chat_revision_recipients(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.lock_chat_revision_recipients(p_chat_id text, p_affected_user_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'pg_catalog'
    AS $$
DECLARE
    target_user_id TEXT;
BEGIN
    FOR target_user_id IN
        SELECT DISTINCT recipient.user_id
        FROM (
            SELECT cm.user_id
            FROM chat.chat_members cm
            WHERE cm.chat_id = p_chat_id
               OR cm.chat_id = (
                   SELECT c.source_chat_id FROM chat.chats c
                   WHERE c.id = p_chat_id AND c.kind = 'topic'
               )
            UNION ALL
            SELECT p_affected_user_id
        ) recipient
        WHERE recipient.user_id IS NOT NULL
        ORDER BY recipient.user_id
    LOOP
        -- Initializing a missing head neither advances its revision nor emits an
        -- event. Keep creation and locking in the same global order. NO KEY
        -- UPDATE matches publish_user_revision and permits revision-row FKs.
        INSERT INTO chat.account_revision_heads (user_id)
        VALUES (target_user_id)
        ON CONFLICT (user_id) DO NOTHING;
        PERFORM 1 FROM chat.account_revision_heads h
        WHERE h.user_id = target_user_id
        FOR NO KEY UPDATE;
    END LOOP;
END;
$$;


--
-- Name: lookup_public_group(integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.lookup_public_group(p_public_id integer) RETURNS TABLE(chat_id text, public_id integer, kind text, name text, member_count integer, is_member boolean, is_muted boolean, join_mode text, join_request_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
declare
    v_current_user_id text := auth.uid()::text;
begin
    if v_current_user_id is null then raise exception 'Not authenticated'; end if;
    if p_public_id is null or p_public_id <= 0 then raise exception 'Public group id is required'; end if;
    return query
    select c.id, c.public_id, c.kind, c.name,
        (select count(*)::integer from chat.chat_members cm_count where cm_count.chat_id = c.id),
        (cm_self.user_id is not null),
        (cm_self.notification_level = 'none'),
        coalesce(c.join_mode, 'open'),
        (select r.status from chat.group_join_requests r where r.chat_id = c.id and r.requester_user_id = v_current_user_id)
    from chat.chats c
    left join chat.chat_members cm_self on cm_self.chat_id = c.id and cm_self.user_id = v_current_user_id
    where c.public_id = p_public_id and c.kind = 'group' and c.status <> 'archived'
    limit 1;
end;
$$;


--
-- Name: mark_message_read(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.mark_message_read(p_chat_id text, p_message_id text, p_agent_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
BEGIN
    -- 消息尚不可见 / 不属本 chat：优雅 no-op（读后写竞态由水位自愈，#1659）。不再 RAISE，
    -- 否则渲染端 IntersectionObserver 抢在行可见前调用会恒抛 400。与 mark_read_on_deliver 同款。
    IF NOT EXISTS (
        SELECT 1
        FROM chat.messages m
        WHERE m.id = p_message_id
          AND m.chat_id = p_chat_id
          AND m.deleted_at IS NULL
    ) THEN
        RETURN;
    END IF;

    -- 授权守卫是真错误，保留 RAISE。
    IF NOT chat.can_act_as(p_agent_user_id, p_chat_id) THEN
        RAISE EXCEPTION 'Cannot mark read for agent % in chat %',
            p_agent_user_id,
            p_chat_id;
    END IF;

    INSERT INTO chat.message_deliveries (
        message_id,
        device_id,
        status,
        delivered_at,
        read_at
    )
    VALUES (
        p_message_id,
        'gugu-agent:' || p_agent_user_id,
        'read',
        now(),
        now()
    )
    ON CONFLICT (message_id, device_id) DO UPDATE SET
        status = 'read',
        delivered_at = COALESCE(chat.message_deliveries.delivered_at, EXCLUDED.delivered_at),
        read_at = COALESCE(chat.message_deliveries.read_at, EXCLUDED.read_at),
        updated_at = now();
END;
$$;


--
-- Name: mark_read(text, bigint, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.mark_read(p_chat_id text, p_seq bigint, p_user_id text DEFAULT NULL::text) RETURNS TABLE(last_read_seq bigint, is_marked_unread boolean, version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
DECLARE
    v_actor TEXT := COALESCE(NULLIF(p_user_id, ''), (SELECT auth.uid()::text));
BEGIN
    IF NOT chat.can_act_as(v_actor, p_chat_id) THEN
        RAISE EXCEPTION 'not authorized to mark read for % in chat %', v_actor, p_chat_id;
    END IF;

    RETURN QUERY
    UPDATE chat.chat_members AS member
    SET
        last_read_seq    = GREATEST(member.last_read_seq, p_seq),
        is_marked_unread = false,
        version          = member.version + 1,
        updated_at       = now()
    WHERE member.chat_id = p_chat_id
      AND member.user_id = v_actor
    RETURNING member.last_read_seq, member.is_marked_unread, member.version;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'chat member % not found in chat %', v_actor, p_chat_id;
    END IF;
END;
$$;


--
-- Name: mark_stream_read(text, text, bigint, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.mark_stream_read(p_chat_id text, p_stream_id text, p_seq bigint, p_thread_root_id text DEFAULT NULL::text, p_user_id text DEFAULT NULL::text) RETURNS TABLE(stream_id text, last_read_seq bigint, is_marked_unread boolean, version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_user TEXT := COALESCE(NULLIF(p_user_id, ''), (SELECT auth.uid()::text));
  v_kind TEXT := CASE WHEN p_thread_root_id IS NULL THEN 'main' ELSE 'thread' END;
BEGIN
  IF v_user IS NULL OR NOT chat.can_act_as(v_user, p_chat_id) THEN
    RAISE EXCEPTION 'not authorized to mark stream read for chat %', p_chat_id;
  END IF;
  IF p_stream_id IS NULL OR (v_kind = 'main' AND p_stream_id <> 'main:' || p_chat_id)
     OR (v_kind = 'thread' AND p_stream_id <> 'thread:' || p_chat_id || ':' || p_thread_root_id) THEN
    RAISE EXCEPTION 'invalid stream locator %', p_stream_id;
  END IF;
  IF v_kind = 'main' THEN
    RETURN QUERY UPDATE chat.chat_members cm
      SET last_read_seq = GREATEST(cm.last_read_seq, p_seq), is_marked_unread = false,
          version = cm.version + 1, updated_at = now()
      WHERE cm.chat_id = p_chat_id AND cm.user_id = v_user
      RETURNING p_stream_id, cm.last_read_seq, cm.is_marked_unread, cm.version;
  ELSE
    INSERT INTO chat.chat_member_stream_read_state(chat_id, user_id, stream_id, stream_kind, thread_root_id)
      VALUES (p_chat_id, v_user, p_stream_id, v_kind, p_thread_root_id)
      ON CONFLICT ON CONSTRAINT chat_member_stream_read_state_pkey DO NOTHING;
    RETURN QUERY UPDATE chat.chat_member_stream_read_state sr
      SET last_read_seq = GREATEST(sr.last_read_seq, p_seq), is_marked_unread = false,
          version = sr.version + 1, updated_at = now()
      WHERE sr.chat_id = p_chat_id AND sr.user_id = v_user AND sr.stream_id = p_stream_id
      RETURNING sr.stream_id, sr.last_read_seq, sr.is_marked_unread, sr.version;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION 'chat stream member % not found', p_stream_id; END IF;
END;
$$;


--
-- Name: mark_thread_root(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.mark_thread_root(p_chat_id text, p_root_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NOT chat.is_chat_member(p_chat_id, (SELECT auth.uid()::text)) THEN
        RAISE EXCEPTION 'mark_thread_root: 调用者不是 chat % 的成员', p_chat_id;
    END IF;
    -- 只能把主线消息(thread_root_id IS NULL)标为话题根，防把回复误标。幂等。
    UPDATE chat.messages
       SET is_thread_root = true
     WHERE id = p_root_id
       AND chat_id = p_chat_id
       AND deleted_at IS NULL
       AND thread_root_id IS NULL;
END;
$$;


--
-- Name: mark_unread(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.mark_unread(p_chat_id text, p_user_id text DEFAULT NULL::text) RETURNS TABLE(last_read_seq bigint, is_marked_unread boolean, version integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_actor TEXT := COALESCE(NULLIF(p_user_id, ''), (SELECT auth.uid()::text));
BEGIN
  IF NOT chat.can_act_as(v_actor, p_chat_id) THEN
    RAISE EXCEPTION 'not authorized to mark unread for % in chat %', v_actor, p_chat_id;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM chat.messages m
    WHERE m.chat_id = p_chat_id
      AND m.thread_root_id IS NULL
      AND m.deleted_at IS NULL
      AND NOT (m.deleted_for_user_ids @> jsonb_build_array(v_actor))
      AND chat.whisper_visible_to(m.is_whisper, m.sender_user_id, m.to_user_ids, v_actor)
  ) THEN
    RAISE EXCEPTION 'cannot mark an empty main stream unread for chat %', p_chat_id;
  END IF;

  RETURN QUERY
  UPDATE chat.chat_members AS member
  SET is_marked_unread = true,
      version = member.version + 1,
      updated_at = now()
  WHERE member.chat_id = p_chat_id AND member.user_id = v_actor
  RETURNING member.last_read_seq, member.is_marked_unread, member.version;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'chat member % not found in chat %', v_actor, p_chat_id;
  END IF;
END;
$$;


--
-- Name: market_install_ranking(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.market_install_ranking() RETURNS TABLE(app_id text, score double precision)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT i.app_id,
         sum(power(0.5, extract(epoch FROM now() - i.first_at) / 86400 / 7))::double precision
    FROM chat.app_installs i
   WHERE i.app_publisher = 'gugu'
     AND i.first_at > now() - interval '14 days'
   GROUP BY i.app_id
  HAVING count(*) >= 3;
$$;


--
-- Name: member_accepts_delivery(text, boolean, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.member_accepts_delivery(p_level text, p_is_owner_message boolean, p_explicitly_addressed boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT p_level <> 'none'
       AND (p_level = 'all' OR COALESCE(p_is_owner_message, false) OR COALESCE(p_explicitly_addressed, false));
$$;


--
-- Name: message_history_as(text, text, text, bigint, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_history_as(p_chat_id text, p_as_user_id text DEFAULT NULL::text, p_thread_root_id text DEFAULT NULL::text, p_before_seq bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 20) RETURNS TABLE(id text, seq bigint, sender_user_id text, sender_name text, to_user_ids text[], content text, content_type text, reply_to_message_id text, thread_root_id text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := COALESCE(NULLIF(trim(COALESCE(p_as_user_id, '')), ''), (SELECT auth.uid()::text));
BEGIN
    IF v_actor IS NULL OR NOT chat.is_acting_as(v_actor) THEN
        RAISE EXCEPTION 'Not allowed to act as %', v_actor;
    END IF;
    RETURN QUERY
    SELECT m.id, m.seq::BIGINT, m.sender_user_id, COALESCE(u.display_name, '未知用户'), m.to_user_ids, m.content,
           m.content_type, m.reply_to_message_id, m.thread_root_id, m.created_at
      FROM chat.messages m
      LEFT JOIN identity.users u ON u.id = m.sender_user_id
     WHERE m.chat_id = p_chat_id
       AND m.deleted_at IS NULL
       AND m.thread_root_id IS NOT DISTINCT FROM NULLIF(p_thread_root_id, '')
       AND (p_before_seq IS NULL OR m.seq < p_before_seq)
       -- = chat.message_visible_to 拆成两半:下界整条查询只算一次,悄悄话规则被内联。
       AND m.created_at >= (SELECT chat.history_floor(p_chat_id, v_actor))
       AND chat.whisper_visible_to(m.is_whisper, m.sender_user_id, m.to_user_ids, v_actor)
     ORDER BY m.seq DESC
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
END;
$$;


--
-- Name: message_preview(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_preview(p_content text, p_content_type text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT CASE
        WHEN p_content_type = 'attachment' AND split_part(p_content, E'\n', 1) LIKE '[附件] %'
            -- 头行 `[附件] 名字 (mime)`;mime 可缺。与客户端 attachmentModels 的 parseHeader 同一种切法。
            THEN COALESCE(
                NULLIF(btrim(regexp_replace(substr(split_part(p_content, E'\n', 1), 6), ' \([^()]+\)$', '')), ''),
                left(p_content, 100))
        ELSE left(coalesce(p_content, ''), 100)
    END;
$_$;


--
-- Name: FUNCTION message_preview(p_content text, p_content_type text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.message_preview(p_content text, p_content_type text) IS '会话列表那一行的预览:附件给文件名,其它截 100 字。chats.last_message_preview 与 messages_view 的计算列 preview 共用。';


--
-- Name: message_preview_keepalive(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_preview_keepalive(p_chat_id text, p_agent_id text, p_subscription_id text) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'chat', 'pg_catalog'
    AS $$ SELECT chat.message_preview_relay(p_chat_id, p_agent_id, p_subscription_id, 'keepalive') $$;


--
-- Name: message_preview_relay(text, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_preview_relay(p_chat_id text, p_agent_id text, p_subscription_id text, p_op text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_viewer TEXT := auth.uid()::text;
    v_device TEXT;
    v_public_id INTEGER;
    v_topic TEXT;
BEGIN
    IF v_viewer IS NULL THEN
        RAISE EXCEPTION 'not authenticated' USING ERRCODE = '42501';
    END IF;
    IF p_op NOT IN ('subscribe', 'keepalive', 'unsubscribe') THEN
        RAISE EXCEPTION 'unknown message preview op: %', p_op USING ERRCODE = '22023';
    END IF;
    IF coalesce(btrim(p_subscription_id), '') = '' OR length(p_subscription_id) > 128 THEN
        RAISE EXCEPTION 'subscription id is required (<=128 chars)' USING ERRCODE = '22023';
    END IF;
    IF NOT chat.is_member(p_chat_id) THEN
        RAISE EXCEPTION 'not a member of chat %', p_chat_id USING ERRCODE = '42501';
    END IF;
    IF NOT chat.is_chat_member(p_chat_id, p_agent_id) THEN
        RAISE EXCEPTION 'agent % is not a member of chat %', p_agent_id, p_chat_id USING ERRCODE = '42501';
    END IF;

    SELECT u.device_id INTO v_device
    FROM identity.users u
    WHERE u.id = p_agent_id AND u.type = 'agent';
    IF v_device IS NULL THEN
        RAISE EXCEPTION 'agent % has no host device', p_agent_id USING ERRCODE = 'P0002';
    END IF;

    SELECT c.public_id INTO v_public_id FROM chat.chats c WHERE c.id = p_chat_id;
    v_topic := 'gugu:preview:' || p_chat_id || ':' || p_agent_id;

    PERFORM realtime.send(
        jsonb_build_object(
            'type', 'taskpage.preview.' || p_op,
            'request_id', gen_random_uuid()::text,
            'user_id', v_viewer,
            'payload', jsonb_build_object(
                'chatId', p_chat_id,
                'chatPublicId', v_public_id,
                'agentId', p_agent_id,
                'subscriptionId', p_subscription_id,
                'topic', v_topic
            )
        ),
        'broadcast',
        'gugu:' || v_device || ':rpc',
        true
    );

    RETURN jsonb_build_object('topic', v_topic);
END;
$$;


