--
-- Name: message_reply_preview(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_reply_preview(p_message_id text) RETURNS TABLE(reply_to_message_id text, reply_to_sender_user_id text, reply_to_sender_name text, reply_to_content text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT * FROM chat.message_reply_preview_for(p_message_id, (SELECT auth.uid()::text));
$$;


--
-- Name: message_reply_preview_row(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_reply_preview_row(p_message_id text, p_viewer_user_id text) RETURNS TABLE(reply_to_message_id text, reply_to_sender_user_id text, reply_to_sender_name text, reply_to_content text)
    LANGUAGE plpgsql STABLE STRICT SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        q.id,
        q.sender_user_id,
        CASE
            WHEN q.sender_user_id IS NULL THEN '已注销用户'
            ELSE COALESCE(u.display_name, '未知用户')
        END,
        left(COALESCE(q.content, ''), 280)
    FROM chat.messages q
    LEFT JOIN identity.users u ON u.id = q.sender_user_id
    WHERE q.id = NULLIF(p_message_id, '')
      AND q.deleted_at IS NULL
      AND NOT q.is_whisper
      -- ❌ 这里不许再出现「viewer 为空就放行」:没有可判的身份 = 判不过,不是免判(STRICT 已让 NULL 进不来)。
      AND chat.message_visible_to(
            q.chat_id, q.created_at, q.is_whisper, q.sender_user_id, q.to_user_ids, p_viewer_user_id);
END;
$$;


--
-- Name: FUNCTION message_reply_preview_row(p_message_id text, p_viewer_user_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.message_reply_preview_row(p_message_id text, p_viewer_user_id text) IS '@@@5856 内核:不判 actor,只判 viewer 读不读得到。❌ 不给 authenticated —— 投递触发器(DEFINER)专用。';


--
-- Name: message_reply_routing_target(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_reply_routing_target(p_reply_to_message_id text) RETURNS text
    LANGUAGE sql STABLE STRICT
    AS $$
    -- 解析不出(已删 / whisper / 系统消息无发送者)= 这条回复没有路由目标。
    SELECT m.sender_user_id
    FROM chat.messages m
    WHERE m.id = p_reply_to_message_id
      AND m.deleted_at IS NULL
      AND NOT m.is_whisper;
$$;


--
-- Name: message_search_as(text, text, text, bigint, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_search_as(p_chat_id text, p_query text, p_as_user_id text DEFAULT NULL::text, p_before_seq bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 20) RETURNS TABLE(id text, seq bigint, sender_user_id text, sender_name text, content text, content_type text, thread_root_id text, created_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := COALESCE(NULLIF(trim(COALESCE(p_as_user_id, '')), ''), (SELECT auth.uid()::text));
    v_pattern TEXT := '%' || replace(replace(replace(COALESCE(p_query, ''), '\', '\\'), '%', '\%'), '_', '\_') || '%';
BEGIN
    IF v_actor IS NULL OR NOT chat.is_acting_as(v_actor) THEN
        RAISE EXCEPTION 'Not allowed to act as %', v_actor;
    END IF;
    RETURN QUERY
    SELECT m.id, m.seq::BIGINT, m.sender_user_id, COALESCE(u.display_name, '未知用户'), m.content,
           m.content_type, m.thread_root_id, m.created_at
      FROM chat.messages m
      LEFT JOIN identity.users u ON u.id = m.sender_user_id
     WHERE m.chat_id = p_chat_id
       AND m.deleted_at IS NULL
       AND m.content ILIKE v_pattern
       AND (p_before_seq IS NULL OR m.seq < p_before_seq)
       -- = chat.message_visible_to 拆成两半:下界整条查询只算一次,悄悄话规则被内联。
       AND m.created_at >= (SELECT chat.history_floor(p_chat_id, v_actor))
       AND chat.whisper_visible_to(m.is_whisper, m.sender_user_id, m.to_user_ids, v_actor)
     ORDER BY m.seq DESC
     LIMIT LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
END;
$$;


--
-- Name: message_visible_to(text, timestamp with time zone, boolean, text, text[], text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_visible_to(p_chat_id text, p_created_at timestamp with time zone, p_is_whisper boolean, p_sender_user_id text, p_to_user_ids text[], p_actor text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    RETURN COALESCE(p_created_at >= chat.history_floor(p_chat_id, p_actor), false)
       AND chat.whisper_visible_to(p_is_whisper, p_sender_user_id, p_to_user_ids, p_actor);
END;
$$;


--
-- Name: message_wakes_agent(text, text, text, text, text, boolean, boolean, text[], boolean, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.message_wakes_agent(p_agent_user_id text, p_listen_mode text, p_notification_level text, p_chat_kind text, p_sender_user_id text, p_sender_is_agent boolean, p_sender_is_creator boolean, p_to_user_ids text[], p_is_whisper boolean, p_reply_target text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT COALESCE(
        p_agent_user_id IS DISTINCT FROM p_sender_user_id
        AND CASE
            WHEN f.directed THEN
                (f.named OR f.everyone)
                AND chat.member_accepts_delivery(p_notification_level, p_sender_is_creator, f.named)
            ELSE
                -- whisper 必定向(表上有 CHECK);这里不靠它 —— 没有收件人的 whisper 谁也不唤醒。
                NOT COALESCE(p_is_whisper, false)
                AND p_chat_kind IN ('group', 'topic')
                -- #6860 没有发信人 = 服务端写的旁白(入群、agent 较多);没点名就不是请求,谁也不唤醒。
                AND p_sender_user_id IS NOT NULL
                AND NOT COALESCE(p_sender_is_agent, false)
                AND p_listen_mode = 'active'
                AND chat.member_accepts_delivery(p_notification_level, p_sender_is_creator, false)
        END,
        false)
    FROM (
        SELECT
            COALESCE(cardinality(p_to_user_ids), 0) > 0 OR p_reply_target IS NOT NULL AS directed,
            COALESCE(p_agent_user_id = ANY (p_to_user_ids), false)
                OR (NOT COALESCE(p_is_whisper, false)
                    AND COALESCE(p_agent_user_id = p_reply_target, false))              AS named,
            NOT COALESCE(p_is_whisper, false)
                AND COALESCE('*' = ANY (p_to_user_ids), false)                           AS everyone
    ) f;
$$;


--
-- Name: messages_file_ref(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.messages_file_ref() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_item chat.workspace_items%ROWTYPE;
    v_blob chat.file_blobs%ROWTYPE;
    v_source chat.messages%ROWTYPE;
    v_envelope TEXT;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        -- 发出去以后不能改指向;删文件时外键把 file_item_id 清空(墓碑)是唯一的变化。
        IF NEW.file_version IS DISTINCT FROM OLD.file_version
           OR (NEW.file_item_id IS DISTINCT FROM OLD.file_item_id AND NEW.file_item_id IS NOT NULL)
           -- ◇ 悄悄话附件指着的那份字节也不能改。
           OR NEW.file_blob_id IS DISTINCT FROM OLD.file_blob_id THEN
            RAISE EXCEPTION USING HINT = 'message_file_fixed', MESSAGE = 'an attachment keeps the file version it was sent with';
        END IF;
        -- 正文和类型也不能改(墓碑也一样):authenticated 本来就能改自己消息的正文(编辑),而老客户端照正文画名字、大小和 [URL],
        -- 新客户端照条目读字节 —— 改了正文,同一条消息两边看到两样东西。撤回只写 retracted_at,不经过这里。
        IF (OLD.file_item_id IS NOT NULL OR OLD.file_version IS NOT NULL OR OLD.file_blob_id IS NOT NULL)
           AND (NEW.content IS DISTINCT FROM OLD.content OR NEW.content_type IS DISTINCT FROM OLD.content_type) THEN
            RAISE EXCEPTION USING HINT = 'message_file_fixed', MESSAGE = 'an attachment''s text is fixed once it is sent';
        END IF;
        RETURN NEW;
    END IF;
    -- ◇ 悄悄话附件:消息直接指字节。形状(悄悄话、没有条目)由 CHECK messages_file_blob_shape 管。
    IF NEW.file_blob_id IS NOT NULL THEN
        -- 先锁住、核它没在回收(同条目那一路的 file_blob_take)。
        PERFORM chat.file_blob_take(NEW.file_blob_id);
        -- 字节从哪来:这条消息自己消费的那次上传,或者发送者读得到、指着同一份字节的源消息。
        IF NOT EXISTS (SELECT 1 FROM chat.file_blob_uploads u WHERE u.message_id = NEW.id AND u.blob_id = NEW.file_blob_id) THEN
            IF NEW.forwarded_from_message_id IS NOT NULL
               AND chat.can_read_message(NEW.forwarded_from_message_id, NEW.sender_user_id) THEN
                SELECT * INTO v_source FROM chat.messages s WHERE s.id = NEW.forwarded_from_message_id AND s.retracted_at IS NULL;
            END IF;
            IF v_source.id IS NULL
               OR COALESCE(v_source.file_blob_id, chat.workspace_version_blob(v_source.file_item_id, v_source.file_version))
                  IS DISTINCT FROM NEW.file_blob_id THEN
                RAISE EXCEPTION USING HINT = 'message_file_not_here',
                    MESSAGE = 'a whisper attachment carries bytes uploaded for it, or forwards the bytes of an unretracted message its sender can read';
            END IF;
        END IF;
        SELECT * INTO v_blob FROM chat.file_blobs b WHERE b.id = NEW.file_blob_id;
        IF NEW.content_type IS DISTINCT FROM 'attachment'
           OR chat.attachment_envelope_name(chat.attachment_text_envelope(NEW.content), v_blob.size_bytes, v_blob.content_type) IS NULL THEN
            RAISE EXCEPTION USING HINT = 'message_file_envelope',
                MESSAGE = format('an attachment''s text is its file''s envelope: %s',
                                 chat.attachment_envelope('<name>', v_blob.size_bytes, v_blob.content_type));
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.file_item_id IS NULL THEN
        IF NEW.file_version IS NOT NULL THEN
            RAISE EXCEPTION USING HINT = 'message_file_not_here', MESSAGE = 'an attachment''s version needs its file';
        END IF;
        RETURN NEW;
    END IF;
    -- FOR SHARE:换版本那边(workspace_replace_file_as)先对条目拿 FOR UPDATE、修剪历史;这里排在它后面,拿到锁时它已提交,
    -- 下一句用新快照,看得到修剪以后的历史 —— 钉的那一版已经裁掉就拒。只靠外键的 KEY SHARE 不排队:两边都成功,
    -- 消息钉着一版历史里已经没有的字节,回收随后把它删掉(复核 L11 两个连接实测)。反过来这边先到,修剪等这边提交、看得见钉住。
    SELECT * INTO v_item FROM chat.workspace_items w WHERE w.id = NEW.file_item_id FOR SHARE;
    IF NOT FOUND OR v_item.chat_id IS DISTINCT FROM NEW.chat_id OR v_item.kind <> 'file' THEN
        RAISE EXCEPTION USING HINT = 'message_file_not_here',
            MESSAGE = 'an attachment points at a file in its own chat''s folder';
    END IF;
    NEW.file_version := COALESCE(NEW.file_version, v_item.version);
    v_envelope := chat.workspace_version_envelope(v_item.id, NEW.file_version);
    IF v_envelope IS NULL THEN
        RAISE EXCEPTION USING HINT = 'message_file_not_here',
            MESSAGE = format('version %s of that file has no bytes to send', NEW.file_version);
    END IF;
    IF NEW.content_type IS DISTINCT FROM 'attachment' OR chat.attachment_text_envelope(NEW.content) IS DISTINCT FROM v_envelope THEN
        RAISE EXCEPTION USING HINT = 'message_file_envelope',
            MESSAGE = format('an attachment''s text is its file''s envelope: %s', v_envelope);
    END IF;
    -- ◇ 钉住条目现在那一版:写进历史(还没有的话)。改名、移动只升版本、不写历史,不记的话那一版的字节就只挂在条目上,
    -- 下一次改名以后 chat.workspace_version_blob 找不到它。写法同 workspace_replace_file_as 补旧版本那一句。
    IF NEW.file_version = v_item.version THEN
        INSERT INTO chat.workspace_item_versions (item_id, n, blob_id, content_type, size_bytes, made_by, made_at)
        VALUES (v_item.id, v_item.version, v_item.blob_id, v_item.content_type, v_item.size_bytes, v_item.created_by, v_item.updated_at)
        ON CONFLICT ON CONSTRAINT workspace_item_versions_pkey DO NOTHING;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: notify_agent_of_reaction(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.notify_agent_of_reaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 DECLARE
     v_chat_id      TEXT;
     v_agent_id     TEXT;
     v_content      TEXT;
     v_content_type TEXT;
     v_reactor      TEXT;
     v_preview      TEXT;
 BEGIN
     -- 只认表情字符(符号/箭头/杂项技术/丁巴特区、补充平面的 emoji、ZWJ、变体选择符、键帽),1–16 个。
     IF NEW.emoji !~ '^[\u2190-\u2BFF\u200D\uFE0F\u20E3\U0001F000-\U0001FAFF]{1,16}$' THEN
         RETURN NULL;
     END IF;

     SELECT m.chat_id, m.sender_user_id, m.content, m.content_type
       INTO v_chat_id, v_agent_id, v_content, v_content_type
     FROM chat.messages m
     JOIN identity.users a ON a.id = m.sender_user_id AND a.type = 'agent'
     JOIN chat.chats c ON c.id = m.chat_id AND c.status = 'active'
     JOIN chat.chat_members cm ON cm.chat_id = m.chat_id AND cm.user_id = m.sender_user_id
     WHERE m.id = NEW.message_id
       AND m.content_type <> 'system'
       AND m.deleted_at IS NULL
       AND m.retracted_at IS NULL;
     IF v_agent_id IS NULL OR v_agent_id = NEW.user_id THEN
         RETURN NULL;
     END IF;

     -- 名字是用户自己填的:压成一行、截到 40 个字符,后面跟可寻址的 typed id。
     SELECT left(regexp_replace(COALESCE(NULLIF(trim(u.display_name), ''), '有人'), '\s+', ' ', 'g'), 40)
            || '(' || CASE WHEN u.gugu_number IS NOT NULL THEN 'gugu:' || u.gugu_number ELSE 'user:' || u.id END || ')'
       INTO v_reactor
     FROM identity.users u
     WHERE u.id = NEW.user_id AND u.type <> 'agent';
     IF v_reactor IS NULL THEN
         RETURN NULL;
     END IF;

     v_preview := CASE v_content_type
         WHEN 'text' THEN regexp_replace(trim(COALESCE(v_content, '')), '\s+', ' ', 'g')
         WHEN 'attachment' THEN '[附件]'
         ELSE '[' || v_content_type || ']'
     END;
     IF char_length(v_preview) > 60 THEN
         v_preview := left(v_preview, 60) || '…';
     END IF;

     INSERT INTO chat.messages (id, chat_id, sender_user_id, content, content_type, to_user_ids, is_whisper, client_message_id)
     VALUES (
         gen_random_uuid()::text,
         v_chat_id,
         NULL,
         v_reactor || ' 对你的消息点了 ' || NEW.emoji || E'\n' || 'msg:' || NEW.message_id || ' 「' || v_preview || '」',
         'system',
         ARRAY[v_agent_id],
         true,
         'reaction:' || NEW.message_id || ':' || md5(NEW.user_id || '|' || NEW.emoji)
     )
     ON CONFLICT (chat_id, client_message_id) WHERE client_message_id IS NOT NULL DO NOTHING;

     RETURN NULL;
 END;
 $_$;


--
-- Name: FUNCTION notify_agent_of_reaction(); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.notify_agent_of_reaction() IS '#6562 人给 agent 的消息点 reaction ⇒ 给这个 agent 写一条只有它看得见的系统通知(whisper)。之后的推送/唤醒/拉取全走现成系统消息链。';


