--
-- Name: open_dm(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.open_dm(p_target_user_id text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_chat_id text;
BEGIN
    v_chat_id := chat.get_or_create_dm(p_target_user_id);

    UPDATE chat.chat_members
    SET inbox_published_at = COALESCE(inbox_published_at, now()),
        updated_at = CASE WHEN inbox_published_at IS NULL THEN now() ELSE updated_at END
    WHERE chat_id = v_chat_id;

    RETURN v_chat_id;
END;
$$;


--
-- Name: own_agent_app_sends(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.own_agent_app_sends(p_chat_id text, p_sender_user_id text, p_via_app text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT CASE
        WHEN p_sender_user_id IS DISTINCT FROM (SELECT auth.uid()::text) AND chat.can_act_as(p_sender_user_id, p_chat_id)
        THEN (SELECT count(*)::integer
                FROM chat.messages AS m
               WHERE m.sender_user_id = p_sender_user_id
                 AND m.via_app = p_via_app
                 AND m.deleted_at IS NULL
                 AND m.created_at > pg_catalog.now() - INTERVAL '1 minute')
    END;
$$;


--
-- Name: own_agent_sent(text, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.own_agent_sent(p_message_id text, p_chat_id text, p_sender_user_id text, p_via_app text) RETURNS SETOF chat.messages
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT m.*
      FROM chat.messages AS m
     WHERE m.chat_id = p_chat_id
       AND (m.id = p_message_id OR m.client_message_id = p_message_id)
       AND m.sender_user_id = p_sender_user_id
       AND m.via_app = p_via_app
       AND m.deleted_at IS NULL
       AND p_sender_user_id IS DISTINCT FROM (SELECT auth.uid()::text)
       AND chat.can_act_as(p_sender_user_id, p_chat_id);
$$;


--
-- Name: own_agent_sent_view(text, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.own_agent_sent_view(p_message_id text, p_chat_id text, p_sender_user_id text, p_via_app text) RETURNS SETOF chat.messages_view
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT mv.*
      FROM chat.messages_view AS mv
     WHERE mv.id = p_message_id
       AND mv.chat_id = p_chat_id
       AND mv.sender_user_id = p_sender_user_id
       AND mv.via_app = p_via_app
       AND mv.deleted_at IS NULL
       AND p_sender_user_id IS DISTINCT FROM (SELECT auth.uid()::text)
       AND chat.can_act_as(p_sender_user_id, p_chat_id);
$$;


