-- Name: preview(chat.messages_view); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.preview(chat.messages_view) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT chat.message_preview($1.content, $1.content_type);
$_$;


