-- Name: FUNCTION preview(chat.messages_view); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.preview(chat.messages_view) IS 'messages_view 的计算列:会话列表的预览(chat.message_preview),客户端 ❌ 自己截、自己解析附件信封。';


--
-- Name: publish_chat_row_revision(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_chat_row_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    target_chat_id TEXT := COALESCE(NEW.id, OLD.id);
BEGIN
    PERFORM chat.broadcast_to_chat_member_user_events(
      target_chat_id,
      'chat_changed',
      jsonb_build_object('op', lower(TG_OP), 'chat', to_jsonb(COALESCE(NEW, OLD)))
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_group_invitation_revision(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_group_invitation_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE v_row chat.group_invitations%ROWTYPE := COALESCE(NEW, OLD); v_user TEXT;
BEGIN
    FOR v_user IN SELECT DISTINCT id FROM unnest(ARRAY[v_row.decision_user_id, v_row.inviter_owner_user_id]) AS recipient(id) ORDER BY id LOOP
        PERFORM chat.publish_user_revision(v_user, 'group_invitations_changed', jsonb_build_object('invitation_id', v_row.id), TG_OP = 'DELETE');
    END LOOP;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_group_join_request_revision(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_group_join_request_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE v_row chat.group_join_requests%ROWTYPE := COALESCE(NEW, OLD); v_user TEXT;
BEGIN
    FOR v_user IN
        SELECT DISTINCT recipient.id FROM (
            SELECT member.user_id AS id FROM chat.chat_members member
             WHERE member.chat_id = v_row.chat_id AND member.role IN ('owner', 'admin')
            UNION ALL
            SELECT COALESCE(v_row.requested_by_user_id, v_row.requester_user_id)
        ) recipient
         WHERE recipient.id IS NOT NULL
         ORDER BY recipient.id
    LOOP
        PERFORM chat.publish_user_revision(v_user, 'friend_requests_changed', jsonb_build_object('join_request_id', v_row.id), TG_OP = 'DELETE');
    END LOOP;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_membership_revision(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_membership_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    target_chat_id TEXT := COALESCE(NEW.chat_id, OLD.chat_id);
    affected_user_id TEXT := COALESCE(NEW.user_id, OLD.user_id);
    target_user_id TEXT;
BEGIN
    PERFORM chat.lock_chat_revision_recipients(target_chat_id, affected_user_id);
    FOR target_user_id IN
      SELECT DISTINCT recipient.user_id
        FROM (
          SELECT cm.user_id FROM chat.chat_members cm WHERE cm.chat_id = target_chat_id
          UNION ALL
          SELECT affected_user_id
        ) recipient
       WHERE recipient.user_id IS NOT NULL
       ORDER BY recipient.user_id
    LOOP
      PERFORM chat.publish_user_revision(
        target_user_id,
        'chat_members_changed',
        jsonb_build_object('chat_id', target_chat_id, 'user_id', affected_user_id),
        TG_OP = 'DELETE'
      );
    END LOOP;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_topic_activity_to_source_line(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_topic_activity_to_source_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_source TEXT;
BEGIN
    SELECT c.source_chat_id INTO v_source
      FROM chat.chats c WHERE c.id = NEW.chat_id AND c.kind = 'topic';
    IF v_source IS NULL THEN
        RETURN NEW;
    END IF;
    PERFORM chat.broadcast_to_chat_member_user_events(
      v_source,
      'chat_changed',
      jsonb_build_object('op', 'update', 'topic_of_source_chat', v_source, 'chat_id', NEW.chat_id, 'about_message_id', NEW.id)
    );
    RETURN NEW;
END;
$$;


--
-- Name: publish_topic_created_to_source_line(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_topic_created_to_source_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.kind <> 'topic' OR NEW.source_chat_id IS NULL THEN
        RETURN NEW;
    END IF;
    -- 改名时 op 写 'update',客户端按同一条路径重拉即可(它只认 topic_of_source_chat 这个键)。
    PERFORM chat.broadcast_to_chat_member_user_events(
      NEW.source_chat_id,
      'chat_changed',
      jsonb_build_object(
        'op', CASE WHEN TG_OP = 'INSERT' THEN 'insert' ELSE 'update' END,
        'topic_of_source_chat', NEW.source_chat_id,
        'chat', to_jsonb(NEW))
    );
    RETURN NEW;
END;
$$;


--
-- Name: publish_topic_membership_to_source_line(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_topic_membership_to_source_line() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_topic TEXT := COALESCE(NEW.chat_id, OLD.chat_id);
    v_source TEXT;
BEGIN
    SELECT c.source_chat_id INTO v_source
      FROM chat.chats c WHERE c.id = v_topic AND c.kind = 'topic';
    IF v_source IS NOT NULL THEN
        PERFORM chat.broadcast_to_chat_member_user_events(
          v_source,
          'chat_changed',
          jsonb_build_object('op', 'update', 'topic_of_source_chat', v_source, 'chat_id', v_topic)
        );
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_user_revision(text, text, jsonb, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.publish_user_revision(p_user_id text, p_event text, p_resource_key jsonb, p_tombstone boolean DEFAULT false) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    next_revision BIGINT;
BEGIN
    IF p_user_id IS NULL OR btrim(p_user_id) = '' THEN
        RAISE EXCEPTION 'revision user id is required';
    END IF;
    IF p_event IS NULL OR btrim(p_event) = '' THEN
        RAISE EXCEPTION 'revision event is required';
    END IF;
    IF p_event NOT IN (
      'agent_changed',
      'chat_changed',
      'chat_members_changed',
      'chat_meta_changed',
      'delivery_changed',
      'device_changed',
      'friend_requests_changed',
      'friendship_changed',
      'group_collab_changed',
      'group_invitations_changed',
      'gugu_decision_event',
      'member_read_changed',
      'member_stream_read_changed',
      'message_created',
      'message_deleted',
      'presence_changed',
      'reaction_changed',
      'workspace_changed'
    ) THEN
        RAISE EXCEPTION 'unsupported account revision event %', p_event;
    END IF;
    IF p_resource_key IS NULL OR jsonb_typeof(p_resource_key) <> 'object' THEN
        RAISE EXCEPTION 'revision resource key must be an object';
    END IF;

    INSERT INTO chat.account_revision_heads (user_id, revision, updated_at)
    VALUES (p_user_id, 1, now())
    ON CONFLICT (user_id) DO UPDATE
       SET revision = chat.account_revision_heads.revision + 1,
           updated_at = now()
    RETURNING revision INTO next_revision;

    INSERT INTO chat.account_revisions (user_id, revision, event, resource_key, tombstone)
    VALUES (p_user_id, next_revision, p_event, p_resource_key, COALESCE(p_tombstone, false));

    PERFORM realtime.send(
        jsonb_build_object('revision', next_revision),
        'im_revision_advanced',
        'gugu:user:' || p_user_id || ':events',
        true
    );
    RETURN next_revision;
END;
$$;


