--
-- Name: queue_agent_join_request(text, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.queue_agent_join_request(p_chat_id text, p_agent_user_id text, p_requested_by text, p_message text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_id TEXT;
BEGIN
    INSERT INTO chat.group_join_requests (chat_id, requester_user_id, requested_by_user_id, message, status)
    VALUES (p_chat_id, p_agent_user_id, p_requested_by, NULLIF(btrim(COALESCE(p_message, '')), ''), 'pending')
    ON CONFLICT ON CONSTRAINT group_join_requests_unique DO UPDATE
        SET status = 'pending',
            requested_by_user_id = EXCLUDED.requested_by_user_id,
            message = EXCLUDED.message,
            updated_at = now()
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$$;


--
-- Name: reapply_agent_flood_on_threshold_change(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.reapply_agent_flood_on_threshold_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    -- 用户自己下的新命令 ⇒ 重新武装闸门。这不是「跟用户打架」,恰恰相反:
    -- 不清闸门的话,他把线从 5 调到 3 之后产品什么都不做,那个数就白填了。
    UPDATE chat.chats SET agent_flood_tuned_at = NULL WHERE id = NEW.id;
    PERFORM chat.apply_agent_flood_rule(NEW.id);
    RETURN NULL;
END;
$$;


--
-- Name: FUNCTION reapply_agent_flood_on_threshold_change(); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.reapply_agent_flood_on_threshold_change() IS '改了这条线的数量线就当场按新线过一遍,否则这个设置在下一个 agent 进来之前是死的。';


--
-- Name: recompute_chat_last_message(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.recompute_chat_last_message(p_chat_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
BEGIN
    UPDATE chat.chats c
    SET
        last_message_at      = latest.created_at,
        last_message_preview = latest.preview,
        updated_at           = now()
    FROM (
        SELECT
            m.created_at,
            chat.message_preview(m.content, m.content_type) AS preview
        FROM chat.messages m
        WHERE m.chat_id = p_chat_id
          AND m.deleted_at IS NULL
          AND NOT m.is_whisper
        ORDER BY m.seq DESC, m.created_at DESC
        LIMIT 1
    ) latest
    WHERE c.id = p_chat_id;

    IF NOT FOUND THEN
        UPDATE chat.chats
        SET
            last_message_at      = NULL,
            last_message_preview = NULL,
            updated_at           = now()
        WHERE id = p_chat_id;
    END IF;
END;
$$;


--
-- Name: recompute_chat_last_message_on_update(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.recompute_chat_last_message_on_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
BEGIN
    IF OLD.deleted_at IS DISTINCT FROM NEW.deleted_at
       OR OLD.content IS DISTINCT FROM NEW.content
       OR OLD.created_at IS DISTINCT FROM NEW.created_at THEN
        PERFORM chat.recompute_chat_last_message(NEW.chat_id);
    END IF;
    RETURN NEW;
END;
$$;


