--
-- Name: request_agent_friend_contact(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.request_agent_friend_contact(p_agent_user_id text, p_friend_user_id text, p_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_agent_name TEXT;
    v_friend_name TEXT;
    v_chat_id TEXT;
    v_name TEXT;
    v_result JSONB;
    v_status TEXT;
    v_invitation_id TEXT;
    v_created BOOLEAN := false;
BEGIN
    IF v_me IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    SELECT display_name INTO v_agent_name FROM identity.users WHERE id = p_agent_user_id AND type = 'agent' AND owner_user_id = v_me;
    IF NOT FOUND THEN RAISE EXCEPTION 'Agent is not owned by this account'; END IF;
    SELECT display_name INTO v_friend_name FROM identity.users WHERE id = p_friend_user_id AND type = 'human';
    IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM identity.friendships
        WHERE user_a_id = LEAST(v_me, p_friend_user_id) AND user_b_id = GREATEST(v_me, p_friend_user_id)) THEN
        RAISE EXCEPTION 'Selected person is not an owner friend';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('agent-friend-invitation:' || p_agent_user_id || ':' || p_friend_user_id, 0));
    SELECT c.id, c.name INTO v_chat_id, v_name FROM chat.chats c
    WHERE c.kind = 'group' AND c.status = 'active'
      AND (SELECT count(*) FROM chat.chat_members m WHERE m.chat_id = c.id) = 3
      AND NOT EXISTS (SELECT 1 FROM chat.chat_members m WHERE m.chat_id = c.id AND m.user_id <> ALL(ARRAY[v_me, p_agent_user_id, p_friend_user_id]))
      AND EXISTS (SELECT 1 FROM chat.chat_members m WHERE m.chat_id = c.id AND m.user_id = v_me AND m.role = 'owner')
    ORDER BY c.created_at LIMIT 1;
    IF v_chat_id IS NOT NULL THEN
        RETURN jsonb_build_object('status', 'already_member', 'chat_id', v_chat_id, 'name', v_name, 'created', false);
    END IF;
    SELECT i.chat_id, c.name, i.status, i.id INTO v_chat_id, v_name, v_status, v_invitation_id FROM chat.group_invitations i JOIN chat.chats c ON c.id = i.chat_id
    WHERE i.inviter_agent_user_id = p_agent_user_id AND i.invitee_user_id = p_friend_user_id
      AND c.status = 'active'
      AND (SELECT count(*) FROM chat.chat_members m WHERE m.chat_id = c.id) = 2
      AND NOT EXISTS (SELECT 1 FROM chat.chat_members m WHERE m.chat_id = c.id AND m.user_id <> ALL(ARRAY[v_me, p_agent_user_id]))
      AND EXISTS (SELECT 1 FROM chat.chat_members m WHERE m.chat_id = c.id AND m.user_id = v_me AND m.role = 'owner')
    ORDER BY i.created_at DESC LIMIT 1;
    IF v_status = 'rejected' THEN
        RETURN jsonb_build_object('status', 'rejected', 'chat_id', v_chat_id, 'name', v_name, 'invitation_id', v_invitation_id, 'created', false, 'message_id', NULL);
    END IF;
    IF v_chat_id IS NULL THEN
        v_created := true;
        v_chat_id := gen_random_uuid()::text;
        v_name := v_agent_name || '、' || v_friend_name;
        SET CONSTRAINTS ALL DEFERRED;
        INSERT INTO chat.chats(id, kind, name, creator_user_id) VALUES (v_chat_id, 'group', v_name, v_me);
        INSERT INTO chat.chat_members(chat_id, user_id, role) VALUES (v_chat_id, v_me, 'owner'), (v_chat_id, p_agent_user_id, 'member');
        INSERT INTO chat.group_agent_states(chat_id, agent_user_id, functional_role, capability_roles, last_action, updated_at)
        VALUES (v_chat_id, p_agent_user_id, 'member', ARRAY['member']::TEXT[], '已加入群聊', now());
    END IF;
    v_result := chat.request_agent_group_invitation(v_chat_id, p_agent_user_id, p_friend_user_id, p_message);
    -- 这张邀请的附言在好友接受时要落成 agent 的第一条群消息(见 decide_agent_group_invitation)。
    IF v_result ->> 'status' = 'pending' THEN
        UPDATE chat.group_invitations SET kind = 'friend_contact' WHERE id = v_result ->> 'invitation_id';
    END IF;
    RETURN v_result || jsonb_build_object('name', v_name, 'created', v_created, 'message_id', NULL);
END;
$$;


--
-- Name: request_agent_group_invitation(text, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.request_agent_group_invitation(p_chat_id text, p_agent_user_id text, p_invitee_user_id text, p_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_group chat.chats%ROWTYPE;
    v_target identity.users%ROWTYPE;
    v_decider TEXT;
    v_invitation_id TEXT;
BEGIN
    IF v_me IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    IF p_message IS NULL OR btrim(p_message) = '' THEN RAISE EXCEPTION 'Invitation message is required'; END IF;
    v_group := chat.require_agent_group_inviter(p_chat_id, p_agent_user_id, v_me);
    SELECT * INTO v_target FROM identity.users WHERE id = p_invitee_user_id FOR SHARE;
    IF NOT FOUND OR (v_target.type = 'agent' AND v_target.owner_user_id <> v_me AND NOT COALESCE(v_target.agent_public, false)) THEN
        RAISE EXCEPTION 'Invited person or public Agent not found';
    END IF;
    IF chat.is_cloud_agent_user(v_target.id) THEN RAISE EXCEPTION 'Cloud Agents cannot join groups'; END IF;
    v_decider := CASE WHEN v_target.type = 'agent' THEN v_target.owner_user_id ELSE v_target.id END;
    IF v_decider IS NULL THEN RAISE EXCEPTION 'Invited Agent has no owner'; END IF;
    IF EXISTS (SELECT 1 FROM chat.chat_members WHERE chat_id = v_group.id AND user_id = v_target.id) THEN
        RETURN jsonb_build_object('status', 'already_member', 'chat_id', v_group.id, 'invitee_user_id', v_target.id);
    END IF;
    -- 「Agent 加入需审批」不再在这里拒:受邀方同意之后,agent 那一步进审批队列(见 decide_agent_group_invitation)。
    SELECT id INTO v_invitation_id FROM chat.group_invitations
    WHERE chat_id = v_group.id AND invitee_user_id = v_target.id AND status = 'pending';
    IF v_invitation_id IS NULL THEN
        INSERT INTO chat.group_invitations(chat_id, inviter_agent_user_id, inviter_owner_user_id, invitee_user_id, decision_user_id, message)
        VALUES (v_group.id, p_agent_user_id, v_me, v_target.id, v_decider, p_message)
        RETURNING id INTO v_invitation_id;
    END IF;
    IF v_decider = v_me THEN RETURN chat.decide_agent_group_invitation(v_invitation_id, true); END IF;
    RETURN jsonb_build_object('status', 'pending', 'invitation_id', v_invitation_id, 'chat_id', v_group.id,
        'invitee_user_id', v_target.id, 'decision_user_id', v_decider);
END;
$$;


--
-- Name: request_group_join(integer, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.request_group_join(p_public_id integer, p_join_token text, p_message text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
declare
    v_uid text := auth.uid()::text;
    v_chat_id text;
    v_token text;
    v_mode text;
    v_max integer;
    v_count integer;
    v_invite_link_enabled boolean;
begin
    if v_uid is null then raise exception 'Not authenticated'; end if;
    if p_public_id is null or p_public_id <= 0 then raise exception 'Public group id is required'; end if;
    if p_join_token is null or length(trim(p_join_token)) = 0 then raise exception 'Join token is required'; end if;

    select c.id, c.join_token, coalesce(c.join_mode, 'open'), coalesce(c.max_members, 100), coalesce(c.invite_link_enabled, true)
      into v_chat_id, v_token, v_mode, v_max, v_invite_link_enabled
      from chat.chats c
     where c.public_id = p_public_id
       and c.kind = 'group'
       and c.status <> 'archived'
     limit 1;

    if v_chat_id is null then raise exception 'Public group not found'; end if;
    if v_token is null or p_join_token <> v_token then raise exception 'Invalid join token'; end if;

    if exists (select 1 from chat.chat_members where chat_id = v_chat_id and user_id = v_uid) then
        return 'joined';
    end if;

    if v_invite_link_enabled is not true then
        raise exception '邀请链接已关闭';
    end if;

    if v_mode = 'invite_only' then
        raise exception '该群仅限邀请加入';
    elsif v_mode = 'approval' then
        insert into chat.group_join_requests (chat_id, requester_user_id, message, status)
        values (v_chat_id, v_uid, nullif(trim(coalesce(p_message, '')), ''), 'pending')
        on conflict on constraint group_join_requests_unique
          do update set status = 'pending', message = excluded.message, updated_at = now();
        return 'pending';
    else
        select count(*) into v_count from chat.chat_members where chat_id = v_chat_id;
        if v_count >= v_max then raise exception 'Group member limit reached'; end if;
        insert into chat.chat_members (chat_id, user_id, role)
        values (v_chat_id, v_uid, 'member')
        on conflict on constraint chat_members_pkey do nothing;
        return 'joined';
    end if;
end;
$$;


--
-- Name: request_group_join_by_id(integer, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.request_group_join_by_id(p_public_id integer, p_message text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
declare
    v_uid text := auth.uid()::text;
    v_chat_id text;
    v_mode text;
    v_invite_link_enabled boolean;
begin
    if v_uid is null then raise exception 'Not authenticated'; end if;
    if p_public_id is null or p_public_id <= 0 then raise exception 'Public group id is required'; end if;

    select c.id, coalesce(c.join_mode, 'open'), coalesce(c.invite_link_enabled, true)
      into v_chat_id, v_mode, v_invite_link_enabled
      from chat.chats c
     where c.public_id = p_public_id
       and c.kind = 'group'
       and c.status <> 'archived'
     limit 1;

    -- ⚠️ 抛稳定的 ASCII 标识,❌ 别抛中文人话:客户端要按它分流成产品文案。
    -- 直接把服务端消息显示给用户 = 措辞一改用户就看到裸报错,而且没法翻译。
    if v_chat_id is null then raise exception 'group_not_found'; end if;

    -- 已是成员：幂等,不落申请
    if exists (select 1 from chat.chat_members cm where cm.chat_id = v_chat_id and cm.user_id = v_uid) then
        return 'joined';
    end if;

    if v_invite_link_enabled is not true then
        raise exception 'group_self_serve_closed';
    end if;

    if v_mode = 'invite_only' then
        raise exception 'group_invite_only';
    end if;

    -- open 与 approval 在这条路上一视同仁:都只能申请。见抬头的枚举说明。
    insert into chat.group_join_requests (chat_id, requester_user_id, message, status)
    values (v_chat_id, v_uid, nullif(trim(coalesce(p_message, '')), ''), 'pending')
    on conflict on constraint group_join_requests_unique
      do update set status = 'pending', message = excluded.message, updated_at = now();
    return 'pending';
end;
$$;


--
-- Name: require_agent_group_inviter(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.require_agent_group_inviter(p_chat_id text, p_agent_id text, p_owner_id text) RETURNS chat.chats
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE v_group chat.chats%ROWTYPE;
BEGIN
    SELECT * INTO v_group FROM chat.chats WHERE id = p_chat_id FOR UPDATE;
    IF NOT FOUND OR v_group.kind <> 'group' OR v_group.status <> 'active' THEN
        RAISE EXCEPTION 'Active group not found';
    END IF;
    IF chat.is_cloud_agent_user(p_agent_id) THEN RAISE EXCEPTION 'Cloud Agents cannot join groups'; END IF;
    IF NOT EXISTS (SELECT 1 FROM identity.users WHERE id = p_agent_id AND type = 'agent' AND owner_user_id = p_owner_id)
       OR NOT EXISTS (SELECT 1 FROM chat.chat_members WHERE chat_id = p_chat_id AND user_id = p_agent_id)
       OR NOT EXISTS (SELECT 1 FROM chat.chat_members WHERE chat_id = p_chat_id AND user_id = p_owner_id) THEN
        RAISE EXCEPTION 'Inviting Agent and its owner must both be group members';
    END IF;
    IF NOT v_group.allow_member_invite AND NOT EXISTS (
        SELECT 1 FROM chat.chat_members WHERE chat_id = p_chat_id AND user_id = p_owner_id AND role IN ('owner', 'admin')
    ) THEN RAISE EXCEPTION 'Group does not allow this member to invite'; END IF;
    RETURN v_group;
END;
$$;


--
-- Name: search_discoverable_groups(text, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.search_discoverable_groups(p_query text, p_limit integer DEFAULT 30) RETURNS TABLE(chat_id text, public_id integer, name text, description text, avatar_url text, member_count integer, is_member boolean, join_mode text, join_request_status text, join_token text, invite_link_enabled boolean, creator_name text, member_avatars jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
declare
  v_uid text := auth.uid()::text;
  v_q text := trim(coalesce(p_query, ''));
  v_needle text := '%' || v_q || '%';
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  return query
  select
    c.id as chat_id,
    c.public_id,
    c.name,
    c.description,
    c.avatar_url,
    (select count(*)::integer from chat.chat_members m where m.chat_id = c.id) as member_count,
    (cm_self.user_id is not null) as is_member,
    c.join_mode,
    gjr.status as join_request_status,
    c.join_token,
    coalesce(c.invite_link_enabled, true) as invite_link_enabled,
    u.display_name as creator_name,
    coalesce(tiles.member_avatars, '[]'::jsonb) as member_avatars
  from chat.chats c
  left join chat.chat_members cm_self
    on cm_self.chat_id = c.id and cm_self.user_id = v_uid
  left join identity.users u
    on u.id = c.creator_user_id
  left join lateral (
    select r.status
    from chat.group_join_requests r
    where r.chat_id = c.id and r.requester_user_id = v_uid
    order by r.updated_at desc
    limit 1
  ) gjr on true
  left join lateral (
    select jsonb_agg(
             jsonb_build_object('id', head.user_id, 'name', head.display_name, 'avatar', head.avatar)
             order by head.joined_at, head.user_id
           ) as member_avatars
    from (
      -- join 在 limit 之前 = 「先丢后截」，与客户端同序：身份行缺失的成员先出局，再取前 9。
      select m.user_id, m.joined_at, mu.display_name, mu.avatar
      from chat.chat_members m
      join identity.users mu on mu.id = m.user_id
      where m.chat_id = c.id
      order by m.joined_at asc, m.user_id asc
      limit 9
    ) head
  ) tiles on true
  where c.kind = 'group'
    and c.is_discoverable = true
    and c.status <> 'archived'
    and (
      v_q = ''
      or c.name ilike v_needle
      or c.description ilike v_needle
      or u.display_name ilike v_needle
    )
  order by member_count desc, c.created_at desc
  limit greatest(1, least(coalesce(p_limit, 30), 100));
end;
$$;


--
-- Name: send_friend_file_as_owner(text, text, text, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.send_friend_file_as_owner(p_agent_user_id text, p_friend_user_id text, p_staging_key text, p_file_name text, p_request_id text, p_caption text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_owner TEXT := (SELECT auth.uid()::text);
    v_name TEXT;
    v_chat TEXT;
    v_id TEXT;
    v_source chat.message_agent_sends%ROWTYPE;
    v_existing chat.messages%ROWTYPE;
    v_placed RECORD;
BEGIN
    IF v_owner IS NULL OR NOT EXISTS (SELECT 1 FROM identity.users WHERE id = v_owner AND type = 'human') THEN
        RAISE EXCEPTION 'Authenticated human owner is required' USING ERRCODE = '42501';
    END IF;
    IF NULLIF(btrim(p_request_id), '') IS NULL OR length(p_request_id) > 128 THEN
        RAISE EXCEPTION 'A request_id of at most 128 characters is required' USING ERRCODE = '22023';
    END IF;
    SELECT u.display_name INTO v_name FROM identity.users u
        WHERE u.id = p_agent_user_id AND u.type = 'agent' AND u.owner_user_id = v_owner FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agent is not owned by this account' USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM identity.users WHERE id = p_friend_user_id AND type = 'human' AND id <> v_owner FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Selected person is not an owner friend' USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM identity.friendships WHERE user_a_id = LEAST(v_owner, p_friend_user_id)
        AND user_b_id = GREATEST(v_owner, p_friend_user_id) FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Selected person is not an owner friend' USING ERRCODE = '42501';
    END IF;
    -- 同 send_friend_message_as_owner:先按请求串行,再开私聊(开私聊可能先锁主人的修订行)。
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-owner-send:' || p_agent_user_id || ':' || p_request_id, 0));
    v_chat := chat.open_dm(p_friend_user_id);
    SELECT * INTO v_source FROM chat.message_agent_sends WHERE agent_user_id = p_agent_user_id AND request_id = p_request_id;
    IF FOUND THEN
        v_id := v_source.message_id;
        SELECT * INTO STRICT v_existing FROM chat.messages WHERE id = v_id;
        IF v_existing.chat_id IS DISTINCT FROM v_chat OR v_existing.sender_user_id IS DISTINCT FROM v_owner
           OR v_existing.content_type IS DISTINCT FROM 'attachment' OR v_source.owner_user_id IS DISTINCT FROM v_owner
           OR NOT EXISTS (SELECT 1 FROM chat.file_blob_uploads u WHERE u.staging_key = p_staging_key AND u.message_id = v_id)
           OR chat.attachment_caption_of(v_existing.content) IS DISTINCT FROM chat.attachment_caption_suffix(p_caption) THEN
            RAISE EXCEPTION 'Idempotency conflict: request_id was already used for a different send' USING ERRCODE = '23505';
        END IF;
    ELSE
        v_id := pg_catalog.gen_random_uuid()::text;
        SELECT * INTO v_placed FROM chat.attachment_place(p_staging_key, v_chat, v_owner, p_file_name, v_id, false);
        SET CONSTRAINTS chat.message_agent_sends_message_id_fkey DEFERRED;
        INSERT INTO chat.message_agent_sends(message_id, owner_user_id, agent_user_id, request_id, agent_name)
            VALUES (v_id, v_owner, p_agent_user_id, p_request_id, v_name);
        INSERT INTO chat.messages(id, chat_id, sender_user_id, to_user_ids, content, content_type, client_message_id, file_item_id, file_version)
            VALUES (v_id, v_chat, v_owner, ARRAY[p_friend_user_id], v_placed.envelope || chat.attachment_caption_suffix(p_caption), 'attachment', v_id,
                    v_placed.item_id, v_placed.item_version);
    END IF;
    RETURN jsonb_build_object('chat_id', v_chat, 'message_id', v_id, 'sender_user_id', v_owner, 'sent_by_agent', true);
END;
$$;


--
-- Name: send_friend_message_as_owner(text, text, text, text, text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.send_friend_message_as_owner(p_agent_user_id text, p_friend_user_id text, p_content text, p_request_id text, p_content_type text DEFAULT 'text'::text, p_storage_bucket_id text DEFAULT NULL::text, p_storage_object_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_owner TEXT := (SELECT auth.uid()::text);
    v_name TEXT;
    v_chat TEXT;
    v_id TEXT;
    v_existing chat.messages%ROWTYPE;
    v_source chat.message_agent_sends%ROWTYPE;
BEGIN
    IF v_owner IS NULL OR NOT EXISTS (SELECT 1 FROM identity.users WHERE id = v_owner AND type = 'human') THEN
        RAISE EXCEPTION 'Authenticated human owner is required' USING ERRCODE = '42501';
    END IF;
    IF NULLIF(btrim(p_content), '') IS NULL OR NULLIF(btrim(p_request_id), '') IS NULL OR length(p_request_id) > 128 THEN
        RAISE EXCEPTION 'Message text and a request_id of at most 128 characters are required' USING ERRCODE = '22023';
    END IF;
    SELECT u.display_name INTO v_name FROM identity.users u
        WHERE u.id = p_agent_user_id AND u.type = 'agent' AND u.owner_user_id = v_owner FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agent is not owned by this account' USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM identity.users WHERE id = p_friend_user_id AND type = 'human' AND id <> v_owner FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Selected person is not an owner friend' USING ERRCODE = '42501';
    END IF;
    PERFORM 1 FROM identity.friendships WHERE user_a_id = LEAST(v_owner, p_friend_user_id)
        AND user_b_id = GREATEST(v_owner, p_friend_user_id) FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Selected person is not an owner friend' USING ERRCODE = '42501';
    END IF;

    IF p_content_type IS NULL OR p_content_type NOT IN ('text', 'attachment') THEN
        RAISE EXCEPTION 'Only text and attachment messages can be sent on behalf of the owner' USING ERRCODE = '22023';
    END IF;
    IF p_content_type = 'attachment' THEN
        IF p_storage_bucket_id IS DISTINCT FROM 'chat-media'
           OR p_storage_object_name IS NULL
           OR split_part(p_storage_object_name, '/', 1) <> v_owner
           OR NOT chat.is_strict_legacy_chat_media_attachment(p_content)
           OR right(split_part(p_content, E'\n', 2), length(p_storage_object_name) + 1) <> '/' || p_storage_object_name THEN
            RAISE EXCEPTION 'Attachment requires the owner''s canonical chat-media object' USING ERRCODE = '22023';
        END IF;
    ELSIF p_storage_bucket_id IS NOT NULL OR p_storage_object_name IS NOT NULL THEN
        RAISE EXCEPTION 'Text messages cannot carry attachment storage references' USING ERRCODE = '22023';
    END IF;

    -- Serialize the request before opening a DM: opening a new DM can already
    -- lock the owner's revision row, so taking this lock afterward could invert
    -- the order against a replay targeting a different DM.
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('agent-owner-send:' || p_agent_user_id || ':' || p_request_id, 0));
    v_chat := chat.open_dm(p_friend_user_id);
    SELECT * INTO v_source FROM chat.message_agent_sends
        WHERE agent_user_id = p_agent_user_id AND request_id = p_request_id;
    IF FOUND THEN
        v_id := v_source.message_id;
        SELECT * INTO STRICT v_existing FROM chat.messages WHERE id = v_id;
        IF v_existing.chat_id IS DISTINCT FROM v_chat OR v_existing.sender_user_id IS DISTINCT FROM v_owner
           OR v_existing.content IS DISTINCT FROM p_content OR v_existing.content_type IS DISTINCT FROM p_content_type
           OR v_existing.storage_bucket_id IS DISTINCT FROM p_storage_bucket_id
           OR v_existing.storage_object_name IS DISTINCT FROM p_storage_object_name
           OR v_source.agent_user_id IS DISTINCT FROM p_agent_user_id OR v_source.owner_user_id IS DISTINCT FROM v_owner THEN
            RAISE EXCEPTION 'Idempotency conflict: request_id was already used for a different send' USING ERRCODE = '23505';
        END IF;
    ELSE
        v_id := pg_catalog.gen_random_uuid()::text;
        SET CONSTRAINTS chat.message_agent_sends_message_id_fkey DEFERRED;
        INSERT INTO chat.message_agent_sends(message_id, owner_user_id, agent_user_id, request_id, agent_name)
            VALUES (v_id, v_owner, p_agent_user_id, p_request_id, v_name);
        INSERT INTO chat.messages(id, chat_id, sender_user_id, to_user_ids, content, content_type, client_message_id, storage_bucket_id, storage_object_name)
            VALUES (v_id, v_chat, v_owner, ARRAY[p_friend_user_id], p_content, p_content_type, v_id, p_storage_bucket_id, p_storage_object_name);
    END IF;
    RETURN jsonb_build_object('chat_id', v_chat, 'message_id', v_id, 'sender_user_id', v_owner, 'sent_by_agent', true);
END;
$$;


--
-- Name: send_message_idempotent(text, text, text, text[], text, text, text, text, boolean, boolean, text, uuid, integer, text, uuid); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.send_message_idempotent(p_message_id text, p_chat_id text, p_sender_user_id text, p_to_user_ids text[], p_content text, p_content_type text, p_reply_to_message_id text, p_thread_root_id text, p_is_thread_root boolean, p_is_whisper boolean, p_via_app text DEFAULT NULL::text, p_file_item_id uuid DEFAULT NULL::uuid, p_file_version integer DEFAULT NULL::integer, p_forwarded_from_message_id text DEFAULT NULL::text, p_file_blob_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id text, chat_id text, sender_user_id text, to_user_ids text[], sender_name text, sender_avatar text, seq bigint, content text, content_type text, reply_to_message_id text, reply_to_sender_user_id text, reply_to_sender_name text, reply_to_content text, deleted_at timestamp with time zone, deleted_for_user_ids jsonb, retracted_at timestamp with time zone, created_at timestamp with time zone, forwarded_from_message_id text, thread_root_id text, edited_at timestamp with time zone, is_whisper boolean, is_thread_root boolean, client_message_id text, is_imported_history_root boolean, via_app text, file_item_id uuid, file_version integer, sent_by_agent boolean, agent_sender jsonb, file_blob_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_existing chat.messages%ROWTYPE;
    v_existing_count INTEGER;
    v_id_lock BIGINT;
    v_client_lock BIGINT;
    v_recent INTEGER;
BEGIN
    IF NULLIF(p_message_id, '') IS NULL OR NULLIF(p_chat_id, '') IS NULL THEN
        RAISE EXCEPTION 'message id and chat id are required';
    END IF;

    v_id_lock := pg_catalog.hashtextextended('chat.messages.id:' || p_message_id, 0);
    v_client_lock := pg_catalog.hashtextextended(
        'chat.messages.client:' || p_chat_id || ':' || p_message_id,
        0
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(LEAST(v_id_lock, v_client_lock));
    IF v_id_lock <> v_client_lock THEN
        PERFORM pg_catalog.pg_advisory_xact_lock(GREATEST(v_id_lock, v_client_lock));
    END IF;

    SELECT count(*)
      INTO v_existing_count
      FROM (
        SELECT m.id
          FROM chat.messages AS m
         WHERE m.id = p_message_id
            OR (m.chat_id = p_chat_id AND m.client_message_id = p_message_id)
        UNION
        SELECT o.id FROM chat.own_agent_sent(p_message_id, p_chat_id, p_sender_user_id, NULLIF(p_via_app, '')) AS o
      ) AS k;

    IF v_existing_count > 1 THEN
        RAISE EXCEPTION 'idempotency keys resolve to different messages for %', p_message_id
            USING ERRCODE = '23505';
    END IF;

    SELECT m.*
      INTO v_existing
      FROM chat.messages AS m
     WHERE m.id = p_message_id
        OR (m.chat_id = p_chat_id AND m.client_message_id = p_message_id)
     LIMIT 1;
    IF NOT FOUND THEN
        SELECT o.* INTO v_existing FROM chat.own_agent_sent(p_message_id, p_chat_id, p_sender_user_id, NULLIF(p_via_app, '')) AS o LIMIT 1;
    END IF;

    IF FOUND THEN
        IF v_existing.id IS DISTINCT FROM p_message_id
           OR v_existing.chat_id IS DISTINCT FROM p_chat_id
           OR v_existing.sender_user_id IS DISTINCT FROM p_sender_user_id
           OR v_existing.to_user_ids IS DISTINCT FROM p_to_user_ids
           OR v_existing.content IS DISTINCT FROM p_content
           OR v_existing.content_type IS DISTINCT FROM p_content_type
           OR v_existing.client_message_id IS DISTINCT FROM p_message_id
           OR v_existing.reply_to_message_id IS DISTINCT FROM p_reply_to_message_id
           OR v_existing.thread_root_id IS DISTINCT FROM p_thread_root_id
           OR v_existing.is_thread_root IS DISTINCT FROM p_is_thread_root
           OR v_existing.is_whisper IS DISTINCT FROM p_is_whisper
           OR v_existing.via_app IS DISTINCT FROM NULLIF(p_via_app, '')
           -- ◇ 附件指向哪一版、转自哪一条:给了就要对得上(版本不给 = 发的时候那一版,不比)。
           OR v_existing.file_item_id IS DISTINCT FROM p_file_item_id
           OR (p_file_version IS NOT NULL AND v_existing.file_version IS DISTINCT FROM p_file_version)
           OR v_existing.forwarded_from_message_id IS DISTINCT FROM p_forwarded_from_message_id
           -- ◇ 悄悄话附件直接指着的那份字节。
           OR v_existing.file_blob_id IS DISTINCT FROM p_file_blob_id THEN
            RAISE EXCEPTION 'idempotency conflict for message %', p_message_id
                USING ERRCODE = '23505';
        END IF;
    ELSE
        -- F16 An App's message sent in a person's name: at most 30 a minute per (person, App). What holds it is that an
        -- App's code reaches this function only through gugu's main process, which always passes p_via_app; a caller
        -- that passes none is not an App and is not counted. A replay above never counts.
        IF NULLIF(p_via_app, '') IS NOT NULL THEN
            -- One count at a time per (person, App): two sends at once would both see 29 and both write. Taken after
            -- the message-id locks above, always in this order, so it cannot close a cycle with them.
            PERFORM pg_catalog.pg_advisory_xact_lock(
                pg_catalog.hashtextextended('chat.messages.via_app:' || p_sender_user_id || ':' || NULLIF(p_via_app, ''), 0)
            );
            v_recent := chat.own_agent_app_sends(p_chat_id, p_sender_user_id, NULLIF(p_via_app, ''));
            IF v_recent IS NULL THEN
                SELECT count(*)
                  INTO v_recent
                  FROM chat.messages AS m
                 WHERE m.sender_user_id = p_sender_user_id
                   AND m.via_app = NULLIF(p_via_app, '')
                   AND m.created_at > pg_catalog.now() - INTERVAL '1 minute';
            END IF;
            IF v_recent >= 30 THEN
                RAISE EXCEPTION 'rate-limited: at most 30 messages a minute from one App in one person''s name'
                    USING ERRCODE = 'PT429';
            END IF;
        END IF;
        INSERT INTO chat.messages (
            id,
            chat_id,
            sender_user_id,
            to_user_ids,
            content,
            content_type,
            client_message_id,
            reply_to_message_id,
            thread_root_id,
            is_thread_root,
            is_whisper,
            via_app,
            file_item_id,
            file_version,
            forwarded_from_message_id,
            file_blob_id
        ) VALUES (
            p_message_id,
            p_chat_id,
            p_sender_user_id,
            p_to_user_ids,
            p_content,
            p_content_type,
            p_message_id,
            p_reply_to_message_id,
            p_thread_root_id,
            p_is_thread_root,
            p_is_whisper,
            NULLIF(p_via_app, ''),
            p_file_item_id,
            p_file_version,
            p_forwarded_from_message_id,
            p_file_blob_id
        );
    END IF;

    RETURN QUERY
    SELECT mv.*
      FROM chat.messages_view AS mv
     WHERE mv.id = p_message_id
       AND mv.deleted_at IS NULL;
    IF NOT FOUND THEN
        RETURN QUERY
        SELECT o.* FROM chat.own_agent_sent_view(p_message_id, p_chat_id, p_sender_user_id, NULLIF(p_via_app, '')) AS o;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'authoritative message row missing for %', p_message_id;
    END IF;
END;
$$;


--
-- Name: set_agent_sent_marker(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.set_agent_sent_marker() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        NEW.sent_by_agent := OLD.sent_by_agent;
    ELSE
        NEW.sent_by_agent := EXISTS (SELECT 1 FROM chat.message_agent_sends a
            WHERE a.message_id = NEW.id AND a.owner_user_id = NEW.sender_user_id);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: set_hide_history_before_on_join(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.set_hide_history_before_on_join() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
DECLARE
    v_hide_history boolean;
BEGIN
    SELECT CASE
             -- 话题没有自己的「隐藏聊天记录」这件事:它的可见范围整个继承来源线(spec)。
             -- 所以这里顺 source_chat_id 读**来源线此刻**的值,话题自己那一列不承重。
             WHEN c.kind = 'topic' AND c.source_chat_id IS NOT NULL
               THEN (SELECT s.hide_history FROM chat.chats s WHERE s.id = c.source_chat_id)
             ELSE c.hide_history
           END
      INTO v_hide_history
      FROM chat.chats c
     WHERE c.id = NEW.chat_id;

    IF v_hide_history IS TRUE THEN
        NEW.hide_history_before := now();
    ELSE
        NEW.hide_history_before := NULL;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: set_inbox_publication_on_membership_insert(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.set_inbox_publication_on_membership_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_kind text;
BEGIN
    SELECT c.kind INTO v_kind
    FROM chat.chats c
    WHERE c.id = NEW.chat_id;

    IF v_kind IS NULL THEN
        RAISE EXCEPTION 'cannot add membership for absent chat %', NEW.chat_id;
    END IF;

    NEW.inbox_published_at := CASE WHEN v_kind IN ('group', 'topic') THEN now() ELSE NULL END;
    RETURN NEW;
END;
$$;


--
-- Name: set_join_instant_on_membership_insert(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.set_join_instant_on_membership_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
BEGIN
    NEW.joined_at := now();
    -- 触发器里带着显式位置进来的(join_topic_participants:在带它进来的那条消息入群)照收;
    -- 其余一律取序列此刻的位置 ——「此后入库的每一条都严格大于它」。
    IF NOT (pg_trigger_depth() > 1 AND NEW.joined_ingest_seq IS NOT NULL) THEN
        NEW.joined_ingest_seq := nextval(pg_get_serial_sequence('chat.messages', 'ingest_seq'));
    END IF;
    NEW.join_context_shown_at := NULL;
    RETURN NEW;
END;
$$;


--
-- Name: set_workspace_item_updated_at(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.set_workspace_item_updated_at() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
BEGIN
    IF NEW.inline_text IS DISTINCT FROM OLD.inline_text OR NEW.blob_id IS DISTINCT FROM OLD.blob_id THEN
        NEW.updated_at := now();
    ELSE
        NEW.updated_at := OLD.updated_at;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: FUNCTION set_workspace_item_updated_at(); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.set_workspace_item_updated_at() IS 'F88: updated_at moves only when the content does (inline_text for documents, pointer for files); every other UPDATE keeps it.';


--
-- Name: sync_since(bigint, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.sync_since(p_after_revision bigint DEFAULT 0, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    current_user_id TEXT := auth.uid()::text;
    head_revision BIGINT := 0;
    first_available BIGINT;
    page JSONB;
    page_last_revision BIGINT;
BEGIN
    IF current_user_id IS NULL OR current_user_id = '' THEN
        RAISE EXCEPTION 'authenticated account is required';
    END IF;
    IF p_after_revision IS NULL OR p_after_revision < 0 THEN
        RAISE EXCEPTION 'revision cursor must be non-negative';
    END IF;
    IF p_limit IS NULL OR p_limit < 1 OR p_limit > 500 THEN
        RAISE EXCEPTION 'revision page limit must be between 1 and 500';
    END IF;

    SELECT h.revision
      INTO head_revision
      FROM chat.account_revision_heads h
     WHERE h.user_id = current_user_id;
    head_revision := COALESCE(head_revision, 0);

    IF p_after_revision > head_revision THEN
        RAISE EXCEPTION 'revision cursor % is ahead of head %', p_after_revision, head_revision;
    END IF;

    SELECT min(r.revision)
      INTO first_available
      FROM chat.account_revisions r
     WHERE r.user_id = current_user_id
       AND r.revision > p_after_revision;

    IF p_after_revision < head_revision
       AND first_available IS DISTINCT FROM p_after_revision + 1 THEN
        RAISE EXCEPTION 'revision gap after %, first available %', p_after_revision, first_available;
    END IF;

    SELECT COALESCE(
             jsonb_agg(
               jsonb_build_object(
                 'revision', selected.revision::text,
                 'event', selected.event,
                 'payload', selected.resource_key
                   || jsonb_build_object('tombstone', selected.tombstone)
                   -- #5649 message_created 带上消息行本身(messages_view 同形);行已不在(硬删)则不带,客户端按旧路补洞。
                   || CASE
                        WHEN selected.event = 'message_created' THEN COALESCE(
                          (SELECT jsonb_build_object('message', to_jsonb(v))
                             FROM chat.messages_view v
                            WHERE v.id::text = selected.resource_key ->> 'entity_id'),
                          '{}'::jsonb)
                        ELSE '{}'::jsonb
                      END
               ) ORDER BY selected.revision
             ),
             '[]'::jsonb
           ),
           max(selected.revision)
      INTO page, page_last_revision
      FROM (
        SELECT r.revision, r.event, r.resource_key, r.tombstone
          FROM chat.account_revisions r
         WHERE r.user_id = current_user_id
           AND r.revision > p_after_revision
         ORDER BY r.revision
         LIMIT p_limit
      ) selected;

    RETURN jsonb_build_object(
      'operations', page,
      'has_more', COALESCE(page_last_revision, p_after_revision) < head_revision
    );
END;
$$;


