    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION 'chat.thread_handoff_deliver is retired; use emdash conversation delivery';
