--
-- Name: thread_summaries(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.thread_summaries(p_chat_id text) RETURNS TABLE(thread_root_id text, reply_count bigint, participant_count bigint, last_reply_at timestamp with time zone, last_reply_seq bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'chat', 'public', 'pg_catalog'
    AS $$
  WITH thread_msgs AS (
    -- 回复行
    SELECT m.thread_root_id AS root_id, m.sender_user_id, m.created_at, m.seq, true AS is_reply
    FROM chat.messages m
    WHERE m.chat_id = p_chat_id
      AND m.thread_root_id IS NOT NULL
      AND m.deleted_at IS NULL
      AND NOT (m.deleted_for_user_ids @> to_jsonb(ARRAY[(auth.uid())::text]))
    UNION ALL
    -- root 行:is_thread_root 的话题根(含零回复，#1243),或历史上有可见回复的根(兼容旧未标记 root，不回退)
    SELECT r.id AS root_id, r.sender_user_id, r.created_at, r.seq, false AS is_reply
    FROM chat.messages r
    WHERE r.chat_id = p_chat_id
      AND r.thread_root_id IS NULL
      AND r.deleted_at IS NULL
      AND NOT (r.deleted_for_user_ids @> to_jsonb(ARRAY[(auth.uid())::text]))
      AND (
        r.is_thread_root = true
        OR EXISTS (
          SELECT 1 FROM chat.messages rep
          WHERE rep.thread_root_id = r.id
            AND rep.deleted_at IS NULL
            AND NOT (rep.deleted_for_user_ids @> to_jsonb(ARRAY[(auth.uid())::text]))
        )
      )
  )
  SELECT t.root_id AS thread_root_id,
         count(*) FILTER (WHERE t.is_reply) AS reply_count,
         count(DISTINCT t.sender_user_id) AS participant_count,
         COALESCE(
           max(t.created_at) FILTER (WHERE t.is_reply),
           max(t.created_at) FILTER (WHERE NOT t.is_reply)
         ) AS last_reply_at,
         COALESCE(
           max(t.seq) FILTER (WHERE t.is_reply),
           max(t.seq) FILTER (WHERE NOT t.is_reply)
         ) AS last_reply_seq
  FROM thread_msgs t
  GROUP BY t.root_id
$$;


--
-- Name: topic_name_from_message(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.topic_name_from_message(p_content text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT CASE
        WHEN char_length(trimmed) = 0 THEN NULL
        WHEN char_length(trimmed) <= 40 THEN trimmed
        ELSE left(trimmed, 40) || '…'
    END
    FROM (
        SELECT trim(split_part(COALESCE(p_content, ''), E'\n', 1)) AS trimmed
    ) first_line;
$$;


--
-- Name: FUNCTION topic_name_from_message(p_content text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.topic_name_from_message(p_content text) IS '话题默认名 = 来源消息首行前 40 字。spec:建立是一步,名字可事后改。';


--
-- Name: topic_source_state(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.topic_source_state(p_topic_chat_id text, p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(state text, preview text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_caller TEXT := (SELECT auth.uid()::text);
    v_actor TEXT;
    v_is_agent BOOLEAN;
    v_owner TEXT;
    v_source_chat TEXT;
    v_source_message TEXT;
    v_row RECORD;
BEGIN
    v_actor := COALESCE(NULLIF(trim(p_as_user_id), ''), v_caller);
    SELECT u.type = 'agent', u.owner_user_id INTO v_is_agent, v_owner
      FROM identity.users u WHERE u.id = v_actor;
    IF v_actor IS DISTINCT FROM v_caller AND NOT (COALESCE(v_is_agent, false) AND v_owner = v_caller) THEN
        RAISE EXCEPTION 'Not allowed to act as %', v_actor;
    END IF;

    SELECT c.source_chat_id, c.source_message_id INTO v_source_chat, v_source_message
      FROM chat.chats c
     WHERE c.id = p_topic_chat_id AND c.kind = 'topic';

    -- 看不见这条话题就什么都不回(与 chat_facts 同形:话题成员,或来源线成员)。
    IF v_source_chat IS NULL THEN
        RETURN;
    END IF;
    IF NOT (chat.is_chat_member(p_topic_chat_id, v_actor)
            OR chat.is_chat_member(p_topic_chat_id, v_caller)
            OR chat.is_chat_member(v_source_chat, v_actor)
            OR chat.is_chat_member(v_source_chat, v_caller)) THEN
        RETURN;
    END IF;

    SELECT m.chat_id, m.created_at, m.is_whisper, m.sender_user_id, m.to_user_ids, m.content, m.deleted_at
      INTO v_row
      FROM chat.messages m
     WHERE m.id = v_source_message;

    -- 真没了(行不在,或已删):溯源断了是一个可呈现的状态,如实说。
    IF v_source_message IS NULL OR v_row.chat_id IS NULL OR v_row.deleted_at IS NOT NULL THEN
        RETURN QUERY SELECT 'gone'::TEXT, NULL::TEXT;
        RETURN;
    END IF;

    IF chat.message_visible_to(
         v_row.chat_id, v_row.created_at, v_row.is_whisper, v_row.sender_user_id, v_row.to_user_ids, v_actor) THEN
        RETURN QUERY SELECT 'readable'::TEXT, left(COALESCE(v_row.content, ''), 280);
    ELSE
        -- 行还在,只是这个人读不到。❌ 不许说成「已被删除」—— 那与事实相反。
        RETURN QUERY SELECT 'unreadable'::TEXT, NULL::TEXT;
    END IF;
END;
$$;


--
-- Name: undo_agent_flood_adjustment(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.undo_agent_flood_adjustment(p_adjustment_id text) RETURNS TABLE(adjustment_id text, restored integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_chat_id TEXT;
    v_changed JSONB;
    v_restored INTEGER := 0;
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT a.chat_id, a.changed INTO v_chat_id, v_changed
    FROM chat.agent_flood_adjustments a
    WHERE a.id = p_adjustment_id AND a.undone_at IS NULL;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Adjustment % not found or already undone', p_adjustment_id;
    END IF;

    IF NOT chat.is_chat_member(v_chat_id, v_me) THEN
        RAISE EXCEPTION 'Not a member of chat %', v_chat_id;
    END IF;

    -- 只还原那些「现在仍然是我们改成的 passive」的成员:用户在这中间手动调过的,他的选择说了算。
    WITH restored AS (
        UPDATE chat.chat_members cm
        SET listen_mode = entry.previous_listen_mode, updated_at = now()
        FROM jsonb_to_recordset(v_changed) AS entry(user_id TEXT, previous_listen_mode TEXT)
        WHERE cm.chat_id = v_chat_id
          AND cm.user_id = entry.user_id
          AND cm.listen_mode = 'passive'
        RETURNING 1
    )
    SELECT count(*) INTO v_restored FROM restored;

    UPDATE chat.agent_flood_adjustments
    SET undone_at = now(), undone_by = v_me
    WHERE id = p_adjustment_id;

    -- 闸门故意不清:撤回之后同一个群不再自动改第二次(spec:否则就是跟用户打架)。

    RETURN QUERY SELECT p_adjustment_id, v_restored;
END;
$$;


--
-- Name: FUNCTION undo_agent_flood_adjustment(p_adjustment_id text); Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON FUNCTION chat.undo_agent_flood_adjustment(p_adjustment_id text) IS '把自动转成的 passive 全部还原。撤回不清 agent_flood_tuned_at ⇒ 同一个群不会被自动改第二次。';


--
-- Name: update_chat_last_message(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.update_chat_last_message() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
BEGIN
    IF NEW.is_whisper THEN
        RETURN NEW;  -- whisper 不进共享预览；sender/收件人在打开的会话里看得到
    END IF;
    UPDATE chat.chats
    SET
        last_message_at      = NEW.created_at,
        last_message_preview = chat.message_preview(NEW.content, NEW.content_type),
        updated_at           = now()
    WHERE id = NEW.chat_id;
    RETURN NEW;
END;
$$;


--
-- Name: validate_storage_reference_pair(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.validate_storage_reference_pair() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'storage', 'public', 'pg_catalog'
    AS $_$
DECLARE
    bucket_value TEXT;
    name_value TEXT;
    presentation_value TEXT;
    presentation_lines TEXT[];
    presentation_url TEXT;
    request_host TEXT := lower(COALESCE(
        NULLIF(current_setting('request.headers', true), '')::jsonb ->> 'host', ''
    ));
    legacy_match TEXT[];
BEGIN
    IF TG_TABLE_NAME = 'messages' THEN
        bucket_value := NEW.storage_bucket_id;
        name_value := NEW.storage_object_name;
        presentation_value := NEW.content;
        IF bucket_value IS NULL AND NEW.content_type = 'attachment' THEN
            IF chat.is_strict_legacy_chat_media_attachment(presentation_value) THEN
                presentation_lines := string_to_array(presentation_value, E'\n');
                presentation_url := substring(
                    presentation_lines[2] FROM length('[URL] ') + 1
                );
                legacy_match := regexp_match(
                    presentation_url,
                    '^https?://([A-Za-z0-9.-]+(:[0-9]{1,5})?)/storage/v1/object/public/chat-media/([A-Za-z0-9._~-]+(/[A-Za-z0-9._~-]+)*)$'
                );
                IF request_host = '' OR lower(legacy_match[1]) <> request_host THEN
                    RAISE EXCEPTION 'canonical attachment requires an explicit storage reference';
                END IF;
                NEW.storage_bucket_id := 'chat-media';
                NEW.storage_object_name := legacy_match[3];
                bucket_value := NEW.storage_bucket_id;
                name_value := NEW.storage_object_name;
            ELSIF presentation_value LIKE E'%\n[URL] %/storage/v1/object/public/chat-media/%' THEN
                RAISE EXCEPTION 'unparseable Storage attachment cannot omit its canonical reference';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'chats' THEN
        bucket_value := NEW.avatar_storage_bucket_id;
        name_value := NEW.avatar_storage_object_name;
        presentation_value := NEW.avatar_url;
        IF bucket_value IS NULL AND presentation_value IS NOT NULL THEN
            legacy_match := regexp_match(
                presentation_value,
                '^https?://([A-Za-z0-9.-]+(?::[0-9]{1,5})?)/storage/v1/object/public/(avatars|chat-media)/([A-Za-z0-9._~-]+(?:/[A-Za-z0-9._~-]+)*)$'
            );
            IF legacy_match IS NOT NULL THEN
                IF request_host = '' OR lower(legacy_match[1]) <> request_host THEN
                    RAISE EXCEPTION 'chat avatar requires an explicit canonical storage reference';
                END IF;
                NEW.avatar_storage_bucket_id := legacy_match[2];
                NEW.avatar_storage_object_name := legacy_match[3];
                bucket_value := NEW.avatar_storage_bucket_id;
                name_value := NEW.avatar_storage_object_name;
            ELSIF presentation_value LIKE '%/storage/v1/object/public/%' THEN
                RAISE EXCEPTION 'unparseable chat avatar cannot omit its canonical storage reference';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'group_outputs' THEN
        bucket_value := NEW.storage_bucket_id;
        name_value := NEW.storage_object_name;
        presentation_value := NEW.url;
        IF bucket_value IS NULL AND presentation_value IS NOT NULL THEN
            legacy_match := regexp_match(
                presentation_value,
                '^https?://([A-Za-z0-9.-]+(?::[0-9]{1,5})?)/storage/v1/object/public/(avatars|chat-media)/([A-Za-z0-9._~-]+(?:/[A-Za-z0-9._~-]+)*)$'
            );
            IF legacy_match IS NOT NULL THEN
                IF request_host = '' OR lower(legacy_match[1]) <> request_host THEN
                    RAISE EXCEPTION 'group output requires an explicit canonical storage reference';
                END IF;
                NEW.storage_bucket_id := legacy_match[2];
                NEW.storage_object_name := legacy_match[3];
                bucket_value := NEW.storage_bucket_id;
                name_value := NEW.storage_object_name;
            ELSIF presentation_value LIKE '%/storage/v1/object/public/%' THEN
                RAISE EXCEPTION 'unparseable group output cannot omit its canonical storage reference';
            END IF;
        END IF;
    ELSE
        RAISE EXCEPTION 'unsupported storage reference table %', TG_TABLE_NAME;
    END IF;

    IF (bucket_value IS NULL) <> (name_value IS NULL) THEN
        RAISE EXCEPTION 'storage reference pair must be both null or both set';
    END IF;
    IF bucket_value IS NOT NULL THEN
        PERFORM 1 FROM storage.objects o
        WHERE o.bucket_id = bucket_value AND o.name = name_value
        FOR KEY SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'storage reference target does not exist';
        END IF;
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: whisper_visible_to(boolean, text, text[], text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.whisper_visible_to(p_is_whisper boolean, p_sender_user_id text, p_to_user_ids text[], p_actor text) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT NOT COALESCE(p_is_whisper, false)
        OR COALESCE(p_actor OPERATOR(pg_catalog.=) ANY (
               ARRAY[p_sender_user_id] OPERATOR(pg_catalog.||) COALESCE(p_to_user_ids, ARRAY[]::pg_catalog.text[])), false)
$$;


--
-- Name: workspace_actor_for(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_actor_for(p_as_user_id text) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := NULLIF(btrim(COALESCE(p_as_user_id, '')), '');
BEGIN
    IF (SELECT auth.uid()) IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    IF v_actor IS NULL OR NOT chat.is_acting_as(v_actor) THEN
        RAISE EXCEPTION 'Not allowed to act as %', COALESCE(v_actor, '<null>');
    END IF;
    RETURN v_actor;
END;
$$;


--
-- Name: workspace_bytes_pinned(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_bytes_pinned() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.blob_id IS NOT DISTINCT FROM OLD.blob_id THEN
        RETURN NEW;
    END IF;
    IF TG_TABLE_NAME = 'workspace_item_versions' THEN
        RAISE EXCEPTION USING HINT = 'workspace_version_bytes_fixed',
            MESSAGE = format('version %s of file %s keeps its bytes', OLD.n, OLD.item_id);
    END IF;
    IF NEW.version <= OLD.version THEN
        RAISE EXCEPTION USING HINT = 'workspace_version_bytes_fixed',
            MESSAGE = format('file %s changes its bytes only as a new version (it is at version %s)', OLD.id, OLD.version);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: workspace_clash_as(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_clash_as(p_item_id text, p_as_user_id text, p_picked text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_key TEXT := lower(chat.workspace_stored_name(p_picked));
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    IF COALESCE(p_item_id, '') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        SELECT * INTO v_item FROM chat.workspace_items w WHERE w.id = p_item_id::uuid;
    END IF;
    IF v_item.id IS NULL OR NOT chat.is_chat_member(v_item.chat_id, v_actor) THEN
        RAISE EXCEPTION 'workspace_clash: % is not found in a chat you are a member of', COALESCE(p_item_id, '<null>');
    END IF;
    IF v_item.name_key = v_key THEN
        RETURN NULL;
    END IF;
    RETURN (SELECT o.id
              FROM chat.workspace_items o
             WHERE o.chat_id = v_item.chat_id
               AND (o.parent_id = v_item.parent_id OR (v_item.parent_id IS NULL AND o.parent_id IS NULL))
               AND o.name_key = v_key
               AND o.id <> v_item.id
             ORDER BY o.created_at, o.id
             LIMIT 1);
END;
$_$;


--
-- Name: workspace_clean_name(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_clean_name(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
    SELECT CASE WHEN s.v IN ('', '.', '..') THEN '未命名' ELSE s.v END
      FROM (SELECT regexp_replace(
                       regexp_replace(
                           normalize(regexp_replace(COALESCE(p_name, ''),
                               '[\u00AD\u034F\u0600-\u0605\u061C\u06DD\u070F\u0890\u0891\u08E2\u115F-\u1160\u17B4-\u17B5\u180B-\u180F\u200B-\u200C\u200E-\u200F\u202A-\u202E\u2060-\u206F\u3164\uFE00-\uFE0E\uFEFF\uFFA0\uFFF0-\uFFFB\U000110BD\U000110CD\U00013430-\U0001343F\U0001BCA0-\U0001BCA3\U0001D173-\U0001D17A\U000E0000-\U000E0FFF]|(?<![\u00A9\u00AE\u203C\u2049\u2122\u2139\u2194-\u21AA\u231A-\u23FF\u24C2\u25AA-\u25FE\u2600-\u27BF\u2934-\u2935\u2B00-\u2BFF\u3030\u303D\u3297\u3299\U0001F000-\U0001FAFF])(?<![\u00A9\u00AE\u203C\u2049\u2122\u2139\u2194-\u21AA\u231A-\u23FF\u24C2\u25AA-\u25FE\u2600-\u27BF\u2934-\u2935\u2B00-\u2BFF\u3030\u303D\u3297\u3299\U0001F000-\U0001FAFF]\uFE0F)\u200D|\u200D(?![\u00A9\u00AE\u203C\u2049\u2122\u2139\u2194-\u21AA\u231A-\u23FF\u24C2\u25AA-\u25FE\u2600-\u27BF\u2934-\u2935\u2B00-\u2BFF\u3030\u303D\u3297\u3299\U0001F000-\U0001FAFF])|(?<![\u00A9\u00AE\u203C\u2049\u2122\u2139\u2194-\u21AA\u231A-\u23FF\u24C2\u25AA-\u25FE\u2600-\u27BF\u2934-\u2935\u2B00-\u2BFF\u3030\u303D\u3297\u3299\U0001F000-\U0001FAFF0-9#*])\uFE0F|(?<=[0-9#*])\uFE0F(?!\u20E3)', '', 'g'), NFC),
                           '^[\u0009-\u000D\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+|[\u0009-\u000D\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]+$', '', 'g'),
                       '[/\\\u0001-\u001F\u007F-\u009F]', '_', 'g') AS v) s;
$_$;


--
-- Name: workspace_create_document_as(text, text, text, text, text, text[], text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_create_document_as(p_chat_id text, p_as_user_id text, p_title text, p_content text DEFAULT ''::text, p_content_type text DEFAULT NULL::text, p_source_message_ids text[] DEFAULT NULL::text[], p_folder text DEFAULT NULL::text) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_title TEXT := btrim(COALESCE(p_title, ''));
    v_content TEXT := COALESCE(p_content, '');
    v_parent UUID;
    v_id UUID;
BEGIN
    PERFORM chat.workspace_require_room_member(p_chat_id, v_actor);
    IF v_title = '' THEN RAISE EXCEPTION 'workspace_create_document: title is required'; END IF;
    v_parent := chat.workspace_folder_for(p_chat_id, p_folder, v_actor, true);
    INSERT INTO chat.workspace_items AS w (chat_id, parent_id, kind, filename, content_type, inline_text, size_bytes, source_message_ids, created_by, version)
    VALUES (p_chat_id, v_parent, 'document', v_title, COALESCE(NULLIF(btrim(COALESCE(p_content_type, '')), ''), 'text/markdown'),
            v_content, octet_length(v_content), COALESCE(p_source_message_ids, '{}'), v_actor, 1)
    RETURNING w.id INTO v_id;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           w.parent_id, w.system_role, chat.workspace_path_of(w.id)
      FROM chat.workspace_items w
     WHERE w.id = v_id;
END;
$$;


--
-- Name: workspace_create_file_as(text, text, text, text, bigint, text, text[], text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_create_file_as(p_chat_id text, p_as_user_id text, p_filename text, p_content_type text, p_size_bytes bigint, p_pointer text, p_source_message_ids text[] DEFAULT NULL::text[], p_folder text DEFAULT NULL::text) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_filename TEXT := btrim(COALESCE(p_filename, ''));
    v_parent UUID;
    v_id UUID;
BEGIN
    PERFORM chat.workspace_require_room_member(p_chat_id, v_actor);
    IF v_filename = '' THEN RAISE EXCEPTION 'workspace_upload_file: file name is required'; END IF;
    -- 桶对象的首段就是它所属的房间(桶 RLS 按它判成员):登记一个别的房间的对象 = 把那边的字节搬进这边的清单。
    IF p_pointer IS NULL OR split_part(p_pointer, '/', 1) <> p_chat_id THEN
        RAISE EXCEPTION 'workspace_upload_file: pointer must live under %/', p_chat_id;
    END IF;
    v_parent := chat.workspace_folder_for(p_chat_id, p_folder, v_actor, true);
    INSERT INTO chat.workspace_items AS w (chat_id, parent_id, kind, filename, content_type, size_bytes, blob_id, source_message_ids, created_by, version)
    VALUES (p_chat_id, v_parent, 'file', v_filename, COALESCE(NULLIF(btrim(COALESCE(p_content_type, '')), ''), 'application/octet-stream'),
            p_size_bytes, chat.file_blob_for_pointer(p_pointer, p_size_bytes, p_content_type, v_actor), COALESCE(p_source_message_ids, '{}'), v_actor, 1)
    RETURNING w.id INTO v_id;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           w.parent_id, w.system_role, chat.workspace_path_of(w.id)
      FROM chat.workspace_items w
     WHERE w.id = v_id;
END;
$$;


--
-- Name: workspace_deletable_as(uuid[], text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_deletable_as(p_item_ids uuid[], p_as_user_id text) RETURNS SETOF uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_owner TEXT;
BEGIN
    SELECT u.owner_user_id INTO v_owner FROM identity.users u WHERE u.id = v_actor;
    RETURN QUERY
    SELECT w.id
      FROM chat.workspace_items w
     WHERE w.id = ANY(p_item_ids)
       AND w.system_role IS NULL
       AND chat.is_chat_member(w.chat_id, v_actor)
       AND (chat.workspace_is_chat_admin(w.chat_id, v_actor)
            OR NOT EXISTS (
                WITH RECURSIVE sub AS (
                    SELECT w.id AS id, w.created_by AS created_by, 1 AS depth
                    UNION ALL
                    SELECT c.id, c.created_by, sub.depth + 1 FROM chat.workspace_items c JOIN sub ON c.parent_id = sub.id WHERE sub.depth < 64
                )
                SELECT 1 FROM sub s WHERE NOT chat.workspace_may_delete(s.created_by, v_actor, v_owner)
            ));
END;
$$;


--
-- Name: workspace_delete_as(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_delete_as(p_item_id text, p_as_user_id text) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_item chat.workspace_items%ROWTYPE;
    v_owner TEXT;
    v_admin BOOLEAN;
    v_blocked BIGINT;
    v_depth INTEGER;
BEGIN
    v_item := chat.workspace_item_for(p_item_id, v_actor, true);
    PERFORM chat.workspace_lock_chat(v_item.chat_id);
    IF v_item.system_role IS NOT NULL THEN
        RAISE EXCEPTION USING HINT = 'workspace_system_folder',
            MESSAGE = '「附件」是系统文件夹,不能改名、移动或删除;里面的文件照常管';
    END IF;
    SELECT u.owner_user_id INTO v_owner FROM identity.users u WHERE u.id = v_actor;
    v_admin := chat.workspace_is_chat_admin(v_item.chat_id, v_actor);
    WITH RECURSIVE sub AS (
        SELECT w.id, w.created_by, 1 AS depth FROM chat.workspace_items w WHERE w.id = v_item.id
        UNION ALL
        SELECT c.id, c.created_by, sub.depth + 1 FROM chat.workspace_items c JOIN sub ON c.parent_id = sub.id WHERE sub.depth < 64
    )
    SELECT count(*) FILTER (WHERE NOT v_admin AND NOT chat.workspace_may_delete(s.created_by, v_actor, v_owner)), max(s.depth)
      INTO v_blocked, v_depth
      FROM sub s;
    IF v_blocked > 0 THEN
        IF v_item.kind = 'folder' AND chat.workspace_may_delete(v_item.created_by, v_actor, v_owner) THEN
            RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', HINT = 'workspace_folder_not_yours',
                MESSAGE = format('文件夹「%s」里有 %s 项不是你(或你的 agent)建的,删不了:什么都没删', v_item.filename, v_blocked);
        END IF;
        -- 说人话、码进 HINT(复核 L11 追记 3);已发出的客户端照旧把 message 放进横幅。
        RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', HINT = 'workspace_item_not_yours',
            MESSAGE = format('「%s」不是你(或你的 agent)建的,删不了', v_item.filename);
    END IF;
    FOR d IN REVERSE v_depth..1 LOOP
        RETURN QUERY
        WITH RECURSIVE sub AS (
            SELECT w.id, 1 AS depth FROM chat.workspace_items w WHERE w.id = v_item.id
            UNION ALL
            SELECT c.id, sub.depth + 1 FROM chat.workspace_items c JOIN sub ON c.parent_id = sub.id WHERE sub.depth < 64
        )
        DELETE FROM chat.workspace_items w
         USING sub s
         WHERE w.id = s.id AND s.depth = d
        RETURNING w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
                  w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at;
    END LOOP;
END;
$$;


--
-- Name: workspace_fit_name(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_fit_name(p_stem text, p_tail text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
    SELECT left(p_stem, greatest(1, 255 - char_length(p_tail))) || p_tail;
$$;


--
-- Name: workspace_folder_for(text, text, text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_folder_for(p_chat_id text, p_folder text, p_actor text, p_create boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_text TEXT := btrim(COALESCE(p_folder, ''));
    v_parent UUID := NULL;
    v_seg TEXT;
    v_row chat.workspace_items%ROWTYPE;
    v_kept UUID;
BEGIN
    IF v_text IN ('', '/') THEN
        RETURN NULL;
    END IF;
    IF v_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        SELECT * INTO v_row FROM chat.workspace_items w WHERE w.id = v_text::uuid;
        IF NOT FOUND OR v_row.chat_id <> p_chat_id OR v_row.kind <> 'folder' THEN
            RAISE EXCEPTION USING HINT = 'workspace_folder_not_found', MESSAGE = format('找不到文件夹「%s」', p_folder);
        END IF;
        RETURN v_row.id;
    END IF;
    IF p_create THEN
        PERFORM chat.workspace_lock_chat(p_chat_id);
    END IF;
    FOREACH v_seg IN ARRAY string_to_array(v_text, '/') LOOP
        CONTINUE WHEN btrim(v_seg) = '';
        v_seg := chat.workspace_stored_name(v_seg);
        IF v_parent IS NULL AND lower(v_seg) = '附件' THEN
            SELECT * INTO v_row FROM chat.workspace_items w WHERE w.chat_id = p_chat_id AND w.system_role = 'attachments';
            IF NOT FOUND AND p_create THEN
                v_kept := chat.workspace_system_folder(p_chat_id, 'attachments');
                SELECT * INTO v_row FROM chat.workspace_items w WHERE w.id = v_kept;
            ELSIF NOT FOUND THEN
                RAISE EXCEPTION USING HINT = 'workspace_folder_not_found', MESSAGE = format('找不到文件夹「%s」', p_folder);
            END IF;
            v_parent := v_row.id;
            CONTINUE;
        END IF;
        SELECT * INTO v_row FROM chat.workspace_items w
         WHERE w.chat_id = p_chat_id
           AND (w.parent_id = v_parent OR (v_parent IS NULL AND w.parent_id IS NULL))
           AND w.name_key = lower(v_seg);
        IF NOT FOUND AND p_create THEN
            INSERT INTO chat.workspace_items AS w (chat_id, parent_id, kind, filename, content_type, source_message_ids, created_by, version)
            VALUES (p_chat_id, v_parent, 'folder', v_seg, 'inode/directory', '{}', p_actor, 1)
            RETURNING * INTO v_row;
        ELSIF NOT FOUND THEN
            RAISE EXCEPTION USING HINT = 'workspace_folder_not_found', MESSAGE = format('找不到文件夹「%s」', p_folder);
        END IF;
        IF v_row.kind <> 'folder' THEN
            RAISE EXCEPTION USING HINT = 'workspace_not_a_folder', MESSAGE = format('「%s」是文件,不是文件夹', v_seg);
        END IF;
        v_parent := v_row.id;
    END LOOP;
    RETURN v_parent;
END;
$_$;


--
-- Name: workspace_get_as(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_get_as(p_item_id text, p_as_user_id text) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, inline_text text, epoch integer, parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    v_item := chat.workspace_item_for(p_item_id, v_actor);
    RETURN QUERY
    SELECT v_item.id, v_item.chat_id, v_item.kind, v_item.filename, v_item.content_type, v_item.size_bytes, chat.file_blob_pointer(v_item.blob_id),
           v_item.source_message_ids, v_item.created_by, v_item.version, v_item.created_at, v_item.updated_at,
           v_item.inline_text, v_item.epoch, v_item.parent_id, v_item.system_role, chat.workspace_path_of(v_item.id);
END;
$$;


--
-- Name: workspace_is_chat_admin(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_is_chat_admin(p_chat_id text, p_actor text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM chat.chats c
          JOIN chat.chats g ON g.id = CASE WHEN c.kind = 'topic' THEN c.source_chat_id ELSE c.id END AND g.kind = 'group'
          JOIN chat.chat_members m ON m.chat_id = g.id AND m.user_id = p_actor AND m.role IN ('owner', 'admin')
         WHERE c.id = p_chat_id
    );
$$;


--
-- Name: workspace_item_for(text, text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_item_for(p_item_id text, p_actor text, p_lock boolean DEFAULT false) RETURNS chat.workspace_items
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_id UUID;
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    BEGIN
        v_id := btrim(COALESCE(p_item_id, ''))::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'workspace item not found: %', p_item_id USING HINT = 'workspace_item_not_found';
    END;
    IF p_lock THEN
        SELECT * INTO v_item FROM chat.workspace_items w WHERE w.id = v_id FOR UPDATE;
    ELSE
        SELECT * INTO v_item FROM chat.workspace_items w WHERE w.id = v_id;
    END IF;
    IF NOT FOUND
       OR NOT EXISTS (SELECT 1 FROM chat.chats c WHERE c.id = v_item.chat_id AND c.kind IN ('group', 'topic', 'dm', 'ai'))
       OR NOT chat.is_chat_member(v_item.chat_id, p_actor) THEN
        RAISE EXCEPTION 'workspace item not found: %', p_item_id USING HINT = 'workspace_item_not_found';
    END IF;
    RETURN v_item;
END;
$$;


--
-- Name: workspace_items_guard_delete(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_items_guard_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM chat.chats c WHERE c.id = OLD.chat_id) THEN
        IF OLD.system_role IS NOT NULL THEN
            RAISE EXCEPTION USING HINT = 'workspace_system_folder',
                MESSAGE = '「附件」是系统文件夹,不能改名、移动或删除;里面的文件照常管';
        END IF;
        IF OLD.kind = 'folder' AND EXISTS (SELECT 1 FROM chat.workspace_items c WHERE c.parent_id = OLD.id) THEN
            RAISE EXCEPTION USING ERRCODE = 'foreign_key_violation', HINT = 'workspace_folder_not_empty',
                MESSAGE = format('文件夹「%s」里还有东西,这里不能直接删;请在最新版咕咕里删,会连同里面的一起删', OLD.filename);
        END IF;
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: workspace_items_place(); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_items_place() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_parent chat.workspace_items%ROWTYPE;
    v_name TEXT;
    v_above INTEGER := 0;
    v_cycle BOOLEAN := false;
    v_below INTEGER := 0;
    v_system BOOLEAN;
BEGIN
    v_system := NEW.system_role IS NOT NULL;
    IF TG_OP = 'UPDATE'
       AND NEW.filename IS NOT DISTINCT FROM OLD.filename
       AND NEW.parent_id IS NOT DISTINCT FROM OLD.parent_id
       AND NEW.chat_id IS NOT DISTINCT FROM OLD.chat_id
       AND NEW.kind IS NOT DISTINCT FROM OLD.kind
       AND NEW.system_role IS NOT DISTINCT FROM OLD.system_role THEN
        RETURN NEW;
    END IF;

    -- 读树之前:这个对话的锁。
    PERFORM chat.workspace_lock_chat(NEW.chat_id);

    IF TG_OP = 'UPDATE' THEN
        IF OLD.system_role IS NOT NULL AND (
               NEW.filename IS DISTINCT FROM OLD.filename
            OR NEW.parent_id IS DISTINCT FROM OLD.parent_id
            OR NEW.system_role IS DISTINCT FROM OLD.system_role
            OR NEW.kind IS DISTINCT FROM OLD.kind
            OR NEW.chat_id IS DISTINCT FROM OLD.chat_id) THEN
            RAISE EXCEPTION USING HINT = 'workspace_system_folder',
                MESSAGE = '「附件」是系统文件夹,不能改名、移动或删除;里面的文件照常管';
        END IF;
        IF (OLD.kind = 'folder') <> (NEW.kind = 'folder') THEN
            RAISE EXCEPTION USING HINT = 'workspace_bad_kind', MESSAGE = '文件夹不能变成文件,文件也不能变成文件夹';
        END IF;
        IF NEW.chat_id IS DISTINCT FROM OLD.chat_id
           AND (NEW.parent_id IS NOT NULL OR EXISTS (SELECT 1 FROM chat.workspace_items c WHERE c.parent_id = OLD.id)) THEN
            RAISE EXCEPTION USING HINT = 'workspace_bad_parent', MESSAGE = '文件夹里的东西、或装着东西的文件夹,不能挪到别的对话';
        END IF;
        IF NEW.filename IS NOT DISTINCT FROM OLD.filename
           AND NEW.parent_id IS NOT DISTINCT FROM OLD.parent_id
           AND NEW.chat_id IS NOT DISTINCT FROM OLD.chat_id THEN
            RETURN NEW;
        END IF;
    END IF;

    v_name := chat.workspace_stored_name(NEW.filename);

    IF NEW.parent_id IS NOT NULL THEN
        SELECT * INTO v_parent FROM chat.workspace_items w WHERE w.id = NEW.parent_id;
        IF NOT FOUND OR v_parent.chat_id <> NEW.chat_id OR v_parent.kind <> 'folder' THEN
            RAISE EXCEPTION USING HINT = 'workspace_bad_parent', MESSAGE = '要放进去的地方不是这个对话里的文件夹';
        END IF;
        -- 新位置上面有几层文件夹;往上走的路上碰到自己 = 把文件夹放进它自己里面。
        WITH RECURSIVE up AS (
            SELECT w.id, w.parent_id, 1 AS depth FROM chat.workspace_items w WHERE w.id = NEW.parent_id
            UNION ALL
            SELECT p.id, p.parent_id, up.depth + 1 FROM chat.workspace_items p JOIN up ON p.id = up.parent_id WHERE up.depth < 64
        )
        SELECT max(up.depth), COALESCE(bool_or(up.id = NEW.id), false) INTO v_above, v_cycle FROM up;
        IF v_cycle THEN
            RAISE EXCEPTION USING HINT = 'workspace_bad_parent', MESSAGE = '不能把文件夹放进它自己里面';
        END IF;
    END IF;
    -- 跟着一起动的:一个文件夹自己下面有几层。
    IF TG_OP = 'UPDATE' AND NEW.kind = 'folder' THEN
        WITH RECURSIVE down AS (
            SELECT c.id, 1 AS depth FROM chat.workspace_items c WHERE c.parent_id = NEW.id
            UNION ALL
            SELECT c.id, down.depth + 1 FROM chat.workspace_items c JOIN down ON c.parent_id = down.id WHERE down.depth < 64
        )
        SELECT COALESCE(max(down.depth), 0) INTO v_below FROM down;
    END IF;
    IF v_above + 1 + v_below > 16 THEN
        RAISE EXCEPTION USING HINT = 'workspace_too_deep', MESSAGE = '文件夹最多套 16 层';
    END IF;

    IF TG_OP = 'INSERT' THEN
        NEW.filename := chat.workspace_place_item(NEW.chat_id, NEW.parent_id, v_name, NULL, v_system);
    ELSE
        IF chat.workspace_name_taken(NEW.chat_id, NEW.parent_id, v_name, NEW.id, v_system) THEN
            RAISE EXCEPTION USING ERRCODE = 'unique_violation', HINT = 'workspace_name_taken',
                MESSAGE = format('这个文件夹里已经有「%s」了', v_name);
        END IF;
        NEW.filename := v_name;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: workspace_list_as(text, text, integer, integer, text, text, text, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_list_as(p_chat_id text, p_as_user_id text, p_offset integer DEFAULT 0, p_limit integer DEFAULT NULL::integer, p_name text DEFAULT NULL::text, p_kind text DEFAULT NULL::text, p_folder text DEFAULT NULL::text, p_exact boolean DEFAULT false) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, total bigint, parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_name TEXT := NULLIF(btrim(COALESCE(p_name, '')), '');
    v_exact BOOLEAN := COALESCE(p_exact, false);
    v_key TEXT := lower(chat.workspace_stored_name(p_name));
    v_offset INTEGER := COALESCE(p_offset, 0);
    v_all BOOLEAN := p_folder IS NULL;
    v_parent UUID;
BEGIN
    IF v_offset < 0 OR p_limit < 0 THEN
        RAISE EXCEPTION 'workspace_list: offset and limit must not be negative';
    END IF;
    IF p_kind IS NOT NULL AND p_kind NOT IN ('document', 'file', 'folder') THEN
        RAISE EXCEPTION 'workspace_list: kind must be document, file or folder, got %', p_kind;
    END IF;
    PERFORM chat.workspace_require_room_member(p_chat_id, v_actor);
    IF NOT v_all THEN
        v_parent := chat.workspace_folder_for(p_chat_id, p_folder, v_actor, false);
    END IF;
    RETURN QUERY
    WITH RECURSIVE tree AS (
        SELECT r.id AS item_id, r.filename::TEXT AS item_path, 1 AS depth
          FROM chat.workspace_items r
         WHERE r.chat_id = p_chat_id AND r.parent_id IS NULL
        UNION ALL
        SELECT c.id, t.item_path || '/' || c.filename, t.depth + 1
          FROM chat.workspace_items c
          JOIN tree t ON c.parent_id = t.item_id
         WHERE t.depth < 64
    )
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           count(*) OVER (), w.parent_id, w.system_role, t.item_path
      FROM chat.workspace_items w
      JOIN tree t ON t.item_id = w.id
     WHERE w.chat_id = p_chat_id
       AND (v_all OR w.parent_id = v_parent OR (v_parent IS NULL AND w.parent_id IS NULL))
       AND (p_kind IS NULL OR w.kind = p_kind)
       AND (v_name IS NULL
            OR (v_exact AND w.name_key = v_key)
            OR (NOT v_exact AND w.filename ILIKE '%' || replace(replace(replace(v_name, '\', '\\'), '%', '\%'), '_', '\_') || '%'))
     ORDER BY w.created_at DESC, w.id DESC
    OFFSET v_offset
     LIMIT p_limit;
END;
$$;


--
-- Name: workspace_lock_chat(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_lock_chat(p_chat_id text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('workspace-tree:' || p_chat_id, 0));
END;
$$;


--
-- Name: workspace_may_delete(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_may_delete(p_created_by text, p_actor text, p_actor_owner text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT COALESCE(p_created_by IS NOT NULL AND (
           p_created_by = p_actor
        OR p_created_by IS NOT DISTINCT FROM p_actor_owner
        OR EXISTS (SELECT 1 FROM identity.users u WHERE u.id = p_created_by AND u.owner_user_id = p_actor)
    ), false);
$$;


--
-- Name: workspace_mkdir_as(text, text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_mkdir_as(p_chat_id text, p_as_user_id text, p_path text) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_id UUID;
BEGIN
    PERFORM chat.workspace_require_room_member(p_chat_id, v_actor);
    v_id := chat.workspace_folder_for(p_chat_id, p_path, v_actor, true);
    IF v_id IS NULL THEN
        RAISE EXCEPTION USING HINT = 'workspace_mkdir', MESSAGE = '要建的文件夹没有名字';
    END IF;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           w.parent_id, w.system_role, chat.workspace_path_of(w.id)
      FROM chat.workspace_items w
     WHERE w.id = v_id;
END;
$$;


--
-- Name: workspace_move_as(text, text, text, text, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_move_as(p_item_id text, p_as_user_id text, p_folder text, p_name text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_item chat.workspace_items%ROWTYPE;
    v_parent UUID;
BEGIN
    v_item := chat.workspace_item_for(p_item_id, v_actor, true);
    IF p_expected_version IS NOT NULL AND p_expected_version <> v_item.version THEN
        RAISE EXCEPTION 'workspace item % version conflict: expected %, got %', p_item_id, p_expected_version, v_item.version
            USING HINT = 'workspace_version_conflict', DETAIL = v_item.version::TEXT;
    END IF;
    IF p_name IS NOT NULL AND btrim(p_name) = '' THEN
        RAISE EXCEPTION USING HINT = 'workspace_move', MESSAGE = '名字不能是空的';
    END IF;
    IF p_folder IS NULL THEN
        v_parent := v_item.parent_id;
    ELSE
        v_parent := chat.workspace_folder_for(v_item.chat_id, p_folder, v_actor, true);
    END IF;
    UPDATE chat.workspace_items w
       SET parent_id = v_parent,
           filename = COALESCE(NULLIF(btrim(COALESCE(p_name, '')), ''), w.filename),
           version = w.version + 1
     WHERE w.id = v_item.id;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           w.parent_id, w.system_role, chat.workspace_path_of(w.id)
      FROM chat.workspace_items w
     WHERE w.id = v_item.id;
END;
$$;


--
-- Name: workspace_name_taken(text, uuid, text, uuid, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_name_taken(p_chat_id text, p_parent_id uuid, p_name text, p_self uuid DEFAULT NULL::uuid, p_system boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT (p_parent_id IS NULL AND NOT p_system AND lower(p_name) = '附件')
        OR EXISTS (
            SELECT 1 FROM chat.workspace_items w
             WHERE w.chat_id = p_chat_id
               AND (w.parent_id = p_parent_id OR (p_parent_id IS NULL AND w.parent_id IS NULL))
               AND w.name_key = lower(p_name)
               AND w.id IS DISTINCT FROM p_self
        );
$$;


--
-- Name: workspace_note_open(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_note_open(p_item_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_me TEXT := (SELECT auth.uid()::text);
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    IF v_me IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
    v_item := chat.workspace_item_for(p_item_id, v_me);
    IF v_item.kind = 'folder' THEN
        RAISE EXCEPTION 'workspace_note_open: % is a folder, not a file', p_item_id;
    END IF;
    INSERT INTO chat.workspace_item_opens (user_id, item_id, opened_at)
    VALUES (v_me, v_item.id, clock_timestamp())
    ON CONFLICT (user_id, item_id) DO UPDATE SET opened_at = EXCLUDED.opened_at;
END;
$$;


--
-- Name: workspace_path_of(uuid); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_path_of(p_item_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    WITH RECURSIVE up AS (
        SELECT w.id, w.parent_id, w.filename, 0 AS depth FROM chat.workspace_items w WHERE w.id = p_item_id
        UNION ALL
        SELECT p.id, p.parent_id, p.filename, up.depth + 1 FROM chat.workspace_items p JOIN up ON p.id = up.parent_id WHERE up.depth < 64
    )
    SELECT string_agg(up.filename, '/' ORDER BY up.depth DESC) FROM up;
$$;


--
-- Name: workspace_place_item(text, uuid, text, uuid, boolean); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_place_item(p_chat_id text, p_parent_id uuid, p_name text, p_self uuid DEFAULT NULL::uuid, p_system boolean DEFAULT false) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_split RECORD;
    v_stem TEXT;
    v_ext TEXT;
    v_series TEXT[];
    v_base TEXT;
    v_prefix TEXT;
    v_suffix TEXT;
    v_n BIGINT;
    v_try TEXT;
    v_tries INTEGER := 0;
BEGIN
    IF NOT chat.workspace_name_taken(p_chat_id, p_parent_id, p_name, p_self, p_system) THEN
        RETURN p_name;
    END IF;
    SELECT * INTO v_split FROM chat.workspace_split_name(p_name);
    v_stem := v_split.stem;
    v_ext := v_split.ext;
    v_series := regexp_match(v_stem, '^(.+) \(([0-9]{1,9})\)$');
    IF v_series IS NOT NULL THEN
        v_stem := v_series[1];
    END IF;
    v_base := lower(v_stem || v_ext);
    v_prefix := lower(v_stem) || ' (';
    v_suffix := ')' || lower(v_ext);

    SELECT COALESCE(max(CASE WHEN w.name_key = v_base THEN 1
                             ELSE substr(w.name_key, char_length(v_prefix) + 1,
                                         char_length(w.name_key) - char_length(v_prefix) - char_length(v_suffix))::BIGINT
                        END), 1)
      INTO v_n
      FROM chat.workspace_items w
     WHERE w.chat_id = p_chat_id
       AND (w.parent_id = p_parent_id OR (p_parent_id IS NULL AND w.parent_id IS NULL))
       AND w.id IS DISTINCT FROM p_self
       AND (w.name_key = v_base
            OR (char_length(w.name_key) > char_length(v_prefix) + char_length(v_suffix)
                AND left(w.name_key, char_length(v_prefix)) = v_prefix
                AND right(w.name_key, char_length(v_suffix)) = v_suffix
                AND substr(w.name_key, char_length(v_prefix) + 1,
                           char_length(w.name_key) - char_length(v_prefix) - char_length(v_suffix)) ~ '^[0-9]{1,9}$'));

    LOOP
        v_n := v_n + 1;
        v_tries := v_tries + 1;
        v_try := chat.workspace_fit_name(v_stem, ' (' || v_n || ')' || v_ext);
        EXIT WHEN NOT chat.workspace_name_taken(p_chat_id, p_parent_id, v_try, p_self, p_system);
        IF v_tries >= 1000 THEN
            RAISE EXCEPTION USING ERRCODE = 'unique_violation', HINT = 'workspace_name_taken',
                MESSAGE = format('这个文件夹里给「%s」找不到空着的名字了', p_name);
        END IF;
    END LOOP;
    RETURN v_try;
END;
$_$;


--
-- Name: workspace_placed_for(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_placed_for(p_actor text) RETURNS TABLE(item_id uuid, item_path text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    WITH RECURSIVE tree AS (
        SELECT r.id AS item_id, r.chat_id, r.filename::TEXT AS item_path, 1 AS depth
          FROM chat.chat_members cm
          JOIN chat.workspace_items r ON r.chat_id = cm.chat_id AND r.parent_id IS NULL
         WHERE cm.user_id = p_actor
        UNION ALL
        -- 往下只走同一个对话里的子项：哪怕有一行的 parent_id 指到了别的对话，也带不出那个对话的东西。
        SELECT c.id, c.chat_id, t.item_path || '/' || c.filename, t.depth + 1
          FROM chat.workspace_items c
          JOIN tree t ON c.parent_id = t.item_id AND c.chat_id = t.chat_id
         WHERE t.depth < 64
    )
    SELECT tree.item_id, tree.item_path FROM tree;
$$;


--
-- Name: workspace_pointer_in_use(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_pointer_in_use(p_pointer text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT EXISTS (SELECT 1 FROM chat.file_blobs b WHERE b.bucket_id = 'workspace' AND b.object_name = p_pointer AND chat.file_blob_in_use(b.id));
$$;


--
-- Name: workspace_recent(integer, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_recent(p_limit integer DEFAULT 50, p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, parent_id uuid, system_role text, path text, epoch integer, chat_name text, chat_kind text, opened_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(COALESCE(p_as_user_id, (SELECT auth.uid()::text)));
BEGIN
    IF p_limit IS NOT NULL AND (p_limit < 1 OR p_limit > 200) THEN
        RAISE EXCEPTION 'workspace_recent: limit must be 1 to 200, got %', p_limit;
    END IF;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           w.parent_id, w.system_role, p.item_path, w.epoch, c.name, c.kind, o.opened_at
      FROM chat.workspace_item_opens o
      JOIN chat.workspace_items w ON w.id = o.item_id
      JOIN chat.workspace_placed_for(v_actor) p ON p.item_id = w.id
      JOIN chat.chats c ON c.id = w.chat_id
     WHERE o.user_id = (SELECT auth.uid()::text)
     ORDER BY o.opened_at DESC, w.id DESC
     LIMIT COALESCE(p_limit, 50);
END;
$$;


--
-- Name: workspace_replace_file_as(text, text, text, bigint, text, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_replace_file_as(p_item_id text, p_as_user_id text, p_pointer text, p_size_bytes bigint, p_content_type text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, pruned_pointers text[], parent_id uuid, system_role text, path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_keep CONSTANT INTEGER := 50;
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_item chat.workspace_items%ROWTYPE;
    v_type TEXT;
    v_next INTEGER;
    v_pruned TEXT[];
    v_blob UUID;
BEGIN
    v_item := chat.workspace_item_for(p_item_id, v_actor, true);
    IF v_item.kind <> 'file' THEN
        RAISE EXCEPTION 'workspace_replace_file: % is a live text file; change it through the file service', p_item_id;
    END IF;
    IF p_pointer IS NULL OR split_part(p_pointer, '/', 1) <> v_item.chat_id THEN
        RAISE EXCEPTION 'workspace_replace_file: pointer must live under %/', v_item.chat_id;
    END IF;
    IF p_pointer = chat.file_blob_pointer(v_item.blob_id) THEN
        RAISE EXCEPTION 'workspace_replace_file: that is the content the file already has';
    END IF;
    IF p_size_bytes IS NULL OR p_size_bytes < 0 THEN
        RAISE EXCEPTION 'workspace_replace_file: size_bytes is required';
    END IF;
    IF p_expected_version IS NOT NULL AND p_expected_version <> v_item.version THEN
        RAISE EXCEPTION 'workspace item % version conflict: expected %, got %', p_item_id, p_expected_version, v_item.version
            USING HINT = 'workspace_version_conflict', DETAIL = v_item.version::TEXT;
    END IF;
    v_type := COALESCE(NULLIF(btrim(COALESCE(p_content_type, '')), ''), v_item.content_type);
    v_next := v_item.version + 1;

    INSERT INTO chat.workspace_item_versions (item_id, n, blob_id, content_type, size_bytes, made_by, made_at)
    VALUES (v_item.id, v_item.version, v_item.blob_id, v_item.content_type, v_item.size_bytes, v_item.created_by, v_item.updated_at)
    ON CONFLICT ON CONSTRAINT workspace_item_versions_pkey DO NOTHING;
    v_blob := chat.file_blob_for_pointer(p_pointer, p_size_bytes, v_type, v_actor);
    INSERT INTO chat.workspace_item_versions (item_id, n, blob_id, content_type, size_bytes, made_by)
    VALUES (v_item.id, v_next, v_blob, v_type, p_size_bytes, v_actor);

    UPDATE chat.workspace_items w
       SET blob_id = v_blob, size_bytes = p_size_bytes, content_type = v_type, version = v_next
     WHERE w.id = v_item.id;

    WITH gone AS (
        DELETE FROM chat.workspace_item_versions v
         WHERE v.item_id = v_item.id
           AND v.n NOT IN (SELECT k.n FROM chat.workspace_item_versions k WHERE k.item_id = v_item.id ORDER BY k.n DESC LIMIT v_keep)
           AND NOT EXISTS (SELECT 1 FROM chat.messages m WHERE m.file_item_id = v.item_id AND m.file_version = v.n)
        RETURNING v.blob_id
    )
    SELECT COALESCE(array_agg(chat.file_blob_pointer(g.blob_id)) FILTER (WHERE chat.file_blob_pointer(g.blob_id) IS NOT NULL), '{}') INTO v_pruned FROM gone g;

    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at, v_pruned,
           w.parent_id, w.system_role, chat.workspace_path_of(w.id)
      FROM chat.workspace_items w
     WHERE w.id = v_item.id;
END;
$$;


--
-- Name: workspace_require_room_member(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_require_room_member(p_chat_id text, p_actor text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM chat.chats c WHERE c.id = p_chat_id AND c.kind IN ('group', 'topic', 'dm', 'ai'))
       OR NOT chat.is_chat_member(p_chat_id, p_actor) THEN
        -- 不区分「这个对话不存在」与「你不在里面」:不在的对话,它的存在本身也不该被探出来。
        RAISE EXCEPTION 'workspace: % is not a chat you are a member of', p_chat_id USING HINT = 'workspace_not_member';
    END IF;
END;
$$;


--
-- Name: workspace_same_series(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_same_series(p_name_key text, p_name text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
DECLARE
    v_split RECORD;
    v_stem TEXT;
    v_series TEXT[];
    v_base TEXT;
    v_prefix TEXT;
    v_suffix TEXT;
BEGIN
    SELECT * INTO v_split FROM chat.workspace_split_name(p_name);
    v_stem := v_split.stem;
    v_series := regexp_match(v_stem, '^(.+) \(([0-9]{1,9})\)$');
    IF v_series IS NOT NULL THEN
        v_stem := v_series[1];
    END IF;
    v_base := lower(v_stem || v_split.ext);
    v_prefix := lower(v_stem) || ' (';
    v_suffix := ')' || lower(v_split.ext);
    RETURN p_name_key = v_base
        OR (char_length(p_name_key) > char_length(v_prefix) + char_length(v_suffix)
            AND left(p_name_key, char_length(v_prefix)) = v_prefix
            AND right(p_name_key, char_length(v_suffix)) = v_suffix
            AND substr(p_name_key, char_length(v_prefix) + 1,
                       char_length(p_name_key) - char_length(v_prefix) - char_length(v_suffix)) ~ '^[0-9]{1,9}$');
END;
$_$;


--
-- Name: workspace_search(text, text[], integer, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_search(p_query text DEFAULT NULL::text, p_suffixes text[] DEFAULT NULL::text[], p_limit integer DEFAULT 50, p_as_user_id text DEFAULT NULL::text) RETURNS TABLE(id uuid, chat_id text, kind text, filename text, content_type text, size_bytes bigint, pointer text, source_message_ids text[], created_by text, version integer, created_at timestamp with time zone, updated_at timestamp with time zone, parent_id uuid, system_role text, path text, epoch integer, chat_name text, chat_kind text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(COALESCE(p_as_user_id, (SELECT auth.uid()::text)));
    v_query TEXT := NULLIF(btrim(COALESCE(p_query, '')), '');
    v_suffixes TEXT[] := (SELECT array_agg(lower(s)) FROM unnest(p_suffixes) s);
BEGIN
    IF p_limit IS NOT NULL AND (p_limit < 1 OR p_limit > 200) THEN
        RAISE EXCEPTION 'workspace_search: limit must be 1 to 200, got %', p_limit;
    END IF;
    RETURN QUERY
    SELECT w.id, w.chat_id, w.kind, w.filename, w.content_type, w.size_bytes, chat.file_blob_pointer(w.blob_id),
           w.source_message_ids, w.created_by, w.version, w.created_at, w.updated_at,
           w.parent_id, w.system_role, p.item_path, w.epoch, c.name, c.kind
      FROM chat.workspace_placed_for(v_actor) p
      JOIN chat.workspace_items w ON w.id = p.item_id
      JOIN chat.chats c ON c.id = w.chat_id
     WHERE w.kind <> 'folder'
       AND (v_query IS NULL
            OR p.item_path ILIKE '%' || replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%')
       AND (v_suffixes IS NULL OR lower(substring(w.filename FROM '\.[^.]+$')) = ANY (v_suffixes))
     ORDER BY w.updated_at DESC, w.id DESC
     LIMIT COALESCE(p_limit, 50);
END;
$_$;


--
-- Name: workspace_split_name(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_split_name(p_name text, OUT stem text, OUT ext text) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_from_end INTEGER := strpos(reverse(p_name), '.');
    v_dot INTEGER;
    v_after TEXT;
BEGIN
    stem := p_name;
    ext := '';
    IF v_from_end = 0 THEN RETURN; END IF;
    v_dot := char_length(p_name) - v_from_end + 1;
    v_after := substr(p_name, v_dot + 1);
    -- 空白:与 workspace_clean_name 同一张表。
    IF v_dot > 1 AND char_length(v_after) BETWEEN 1 AND 16 AND v_after !~ '[\u0009-\u000D\u0020\u0085\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]' THEN
        stem := left(p_name, v_dot - 1);
        ext := '.' || v_after;
    END IF;
END;
$$;


--
-- Name: workspace_status_as(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_status_as(p_chat_id text, p_as_user_id text) RETURNS TABLE(total integer, documents integer, files integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
BEGIN
    PERFORM chat.workspace_require_room_member(p_chat_id, v_actor);
    RETURN QUERY
    SELECT count(*)::INTEGER,
           (count(*) FILTER (WHERE w.kind = 'document'))::INTEGER,
           (count(*) FILTER (WHERE w.kind = 'file'))::INTEGER
      FROM chat.workspace_items w
     WHERE w.chat_id = p_chat_id;
END;
$$;


--
-- Name: workspace_stored_name(text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_stored_name(p_name text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
DECLARE
    v_name TEXT := chat.workspace_clean_name(p_name);
    v_split RECORD;
BEGIN
    IF char_length(v_name) <= 255 THEN RETURN v_name; END IF;
    SELECT * INTO v_split FROM chat.workspace_split_name(v_name);
    RETURN chat.workspace_fit_name(v_split.stem, v_split.ext);
END;
$$;


--
-- Name: workspace_system_folder(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_system_folder(p_chat_id text, p_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_id UUID;
BEGIN
    IF p_role IS DISTINCT FROM 'attachments' THEN
        RAISE EXCEPTION 'workspace_system_folder: unknown role %', p_role;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM chat.chats c WHERE c.id = p_chat_id) THEN
        RAISE EXCEPTION 'workspace_system_folder: no chat %', p_chat_id;
    END IF;
    PERFORM chat.workspace_lock_chat(p_chat_id);
    SELECT w.id INTO v_id FROM chat.workspace_items w WHERE w.chat_id = p_chat_id AND w.system_role = p_role;
    IF FOUND THEN
        RETURN v_id;
    END IF;
    INSERT INTO chat.workspace_items AS w (chat_id, parent_id, kind, filename, content_type, source_message_ids, created_by, version, system_role)
    VALUES (p_chat_id, NULL, 'folder', '附件', 'inode/directory', '{}', NULL, 1, p_role)
    RETURNING w.id INTO v_id;
    RETURN v_id;
END;
$$;


--
-- Name: workspace_version_as(text, text, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_version_as(p_item_id text, p_as_user_id text, p_n integer) RETURNS TABLE(n integer, pointer text, inline_text text, content_type text, size_bytes bigint, made_by text, made_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    v_item := chat.workspace_item_for(p_item_id, v_actor, false);
    RETURN QUERY
    SELECT v.n, chat.file_blob_pointer(v.blob_id), v.inline_text, v.content_type, v.size_bytes, v.made_by, v.made_at
      FROM chat.workspace_item_versions v
     WHERE v.item_id = v_item.id AND v.n = p_n;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'workspace item % has no version %', p_item_id, p_n USING HINT = 'workspace_no_version';
    END IF;
END;
$$;


--
-- Name: workspace_version_blob(uuid, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_version_blob(p_item_id uuid, p_n integer) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT COALESCE(
        (SELECT v.blob_id FROM chat.workspace_item_versions v WHERE v.item_id = p_item_id AND v.n = p_n),
        (SELECT w.blob_id FROM chat.workspace_items w WHERE w.id = p_item_id AND w.version = p_n));
$$;


--
-- Name: workspace_version_envelope(uuid, integer); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_version_envelope(p_item_id uuid, p_n integer) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
    SELECT chat.attachment_envelope(w.filename, COALESCE(b.size_bytes, w.size_bytes), b.content_type)
      FROM chat.workspace_items w
      JOIN chat.file_blobs b ON b.id = chat.workspace_version_blob(p_item_id, p_n)
     WHERE w.id = p_item_id;
$$;


--
-- Name: workspace_versions_as(text, text); Type: FUNCTION; Schema: chat; Owner: -
--

CREATE FUNCTION chat.workspace_versions_as(p_item_id text, p_as_user_id text) RETURNS TABLE(n integer, pointer text, content_type text, size_bytes bigint, made_by text, made_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_actor TEXT := chat.workspace_actor_for(p_as_user_id);
    v_item chat.workspace_items%ROWTYPE;
BEGIN
    v_item := chat.workspace_item_for(p_item_id, v_actor, false);
    RETURN QUERY
    SELECT v.n, chat.file_blob_pointer(v.blob_id), v.content_type, v.size_bytes, v.made_by, v.made_at
      FROM chat.workspace_item_versions v
     WHERE v.item_id = v_item.id
     ORDER BY v.n DESC;
END;
$$;


--
-- Name: accept_friend_request_by_id(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.accept_friend_request_by_id(p_request_id text) RETURNS TABLE(chat_id text, name text, kind text, created boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_sender_id TEXT;
    v_receiver_id TEXT;
    v_receiver_type TEXT;
    v_receiver_owner_user_id TEXT;
    v_sender_type TEXT;
    v_request_status TEXT;
    v_request_message TEXT;
    v_a_id TEXT;
    v_b_id TEXT;
    v_group_chat_id TEXT;
    v_group_name TEXT;
    v_group_created BOOLEAN;
    v_target_chat_id TEXT;
    v_target_name TEXT;
    v_target_kind TEXT;
    v_target_created BOOLEAN := false;
    v_message_row RECORD;
BEGIN
    SELECT fr.sender_id,
           fr.receiver_id,
           fr.status,
           fr.message,
           receiver.type,
           receiver.owner_user_id,
           sender.type
      INTO v_sender_id,
           v_receiver_id,
           v_request_status,
           v_request_message,
           v_receiver_type,
           v_receiver_owner_user_id,
           v_sender_type
      FROM identity.friend_requests fr
      JOIN identity.users receiver ON receiver.id = fr.receiver_id
      JOIN identity.users sender ON sender.id = fr.sender_id
     WHERE fr.id = p_request_id
       AND (
           fr.receiver_id = v_me
           OR (
               receiver.type = 'agent'
               AND receiver.owner_user_id = v_me
           )
       )
     FOR UPDATE OF fr;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Friend request not found';
    END IF;

    IF v_request_status = 'rejected' THEN
        RAISE EXCEPTION 'Friend request not found';
    END IF;

    IF v_request_status = 'pending' THEN
        UPDATE identity.friend_requests
           SET status = 'accepted', updated_at = now()
         WHERE id = p_request_id;
    END IF;

    -- Agent requests never create an agent-human friendship. The owner accepts the
    -- request into the idempotent owner+agent+requester social group.
    IF v_receiver_type = 'agent' THEN
        IF v_receiver_owner_user_id <> v_me THEN
            RAISE EXCEPTION 'Agent is not owned by current user';
        END IF;
        IF v_sender_type <> 'human' THEN
            RAISE EXCEPTION 'Agent requests must be sent by a human user';
        END IF;

        SELECT social_group.chat_id,
               social_group.name,
               social_group.created
          INTO v_group_chat_id,
               v_group_name,
               v_group_created
          FROM chat.get_or_create_agent_social_group(
              v_receiver_id,
              ARRAY[v_sender_id]::TEXT[]
          ) AS social_group;
        IF NOT FOUND OR v_group_chat_id IS NULL THEN
            RAISE EXCEPTION 'agent social group was not created';
        END IF;

        v_target_chat_id := v_group_chat_id;
        v_target_name := v_group_name;
        v_target_kind := 'group';
        v_target_created := v_group_created;
    ELSE
        IF v_receiver_type <> 'human' OR v_sender_type <> 'human' THEN
            RAISE EXCEPTION 'Friendships are only between human users';
        END IF;

        IF v_sender_id < v_receiver_id THEN
            v_a_id := v_sender_id;
            v_b_id := v_receiver_id;
        ELSE
            v_a_id := v_receiver_id;
            v_b_id := v_sender_id;
        END IF;

        INSERT INTO identity.friendships (user_a_id, user_b_id)
        VALUES (v_a_id, v_b_id)
        ON CONFLICT DO NOTHING;

        v_target_chat_id := chat.open_dm(v_sender_id);
    END IF;

    -- The request id makes publication safe across acceptance retries. The sender
    -- remains the human who wrote the request, including in an agent social group.
    IF NULLIF(btrim(v_request_message), '') IS NOT NULL THEN
        SELECT *
          INTO v_message_row
          FROM chat.send_message_idempotent(
              'friend-request:' || p_request_id,
              v_target_chat_id,
              v_sender_id,
              NULL,
              btrim(v_request_message),
              'text',
              NULL,
              NULL,
              false,
              false
          );
        IF NOT FOUND THEN
            RAISE EXCEPTION 'friend request greeting message was not persisted';
        END IF;
    END IF;

    chat_id := v_target_chat_id;
    name := v_target_name;
    kind := v_target_kind;
    created := v_target_created;
    RETURN NEXT;
END;
$$;


--
-- Name: agent_ratings_guard_update(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.agent_ratings_guard_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
DECLARE
  is_rater boolean := OLD.rater_user_id = (SELECT auth.uid()::text);
  is_owner boolean := EXISTS (
    SELECT 1 FROM identity.users u
    WHERE u.id = OLD.agent_user_id AND u.owner_user_id = (SELECT auth.uid()::text)
  );
BEGIN
  IF NEW.review IS DISTINCT FROM OLD.review AND NOT is_rater THEN
    RAISE EXCEPTION 'only the rater may modify review';
  END IF;
  IF NEW.owner_reply IS DISTINCT FROM OLD.owner_reply AND NOT is_owner THEN
    RAISE EXCEPTION 'only the agent owner may modify owner_reply';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: api_key_has_scope(text[], text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.api_key_has_scope(p_scopes text[], p_required text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT p_required = ANY(p_scopes);
$$;


--
-- Name: assert_device_command_post_context(uuid, uuid, text, text, text, text[]); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.assert_device_command_post_context(p_command_id uuid, p_claim_token uuid, p_agent_user_id text, p_chat_id text, p_reply_to_message_id text DEFAULT NULL::text, p_to_user_ids text[] DEFAULT NULL::text[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    command_chat_kind TEXT;
    command_owner_id UUID;
    command_agent_id TEXT;
    command_chat_id TEXT;
    command_sender_id TEXT;
    command_message_id TEXT;
    reply_sender_id TEXT;
    required_identity_ids TEXT[];
    required_count INTEGER;
    locked_count INTEGER;
    required_member_ids TEXT[];
    locked_member_count INTEGER;
BEGIN
    -- Match lifecycle's chat -> command -> identity lock order.
    SELECT c.kind INTO command_chat_kind
    FROM chat.chats c
    WHERE c.id = p_chat_id
    FOR KEY SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'device command chat is not live'; END IF;

    SELECT c.user_id, c.payload->>'agent_user_id', c.payload->>'chat_id',
           c.payload->>'sender_user_id', c.payload->>'message_id'
    INTO command_owner_id, command_agent_id, command_chat_id, command_sender_id, command_message_id
    FROM identity.gugu_device_commands c
    WHERE c.id = p_command_id
      AND c.claim_token = p_claim_token
      AND c.status = 'running'
      AND c.type = 'agent.deliver'
    FOR KEY SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION 'device command lease is not live'; END IF;
    IF command_agent_id IS DISTINCT FROM p_agent_user_id
       OR command_chat_id IS DISTINCT FROM p_chat_id THEN
        RAISE EXCEPTION 'device command context does not match message';
    END IF;
    -- 没有发送者只有一种合法来路:这条命令叫醒的是一条服务端写的系统行(#6860 起只剩点名的那种,
    -- 如 #6562 的表情通知)。发送者被注销抹空的消息(#2051)是人话,content_type 不是 system,照旧拒。
    IF command_sender_id IS NULL AND NOT EXISTS (
        SELECT 1
        FROM chat.message_agent_wakes w
        JOIN chat.messages m ON m.id = w.message_id
        WHERE w.message_id = command_message_id
          AND w.agent_user_id = command_agent_id
          AND m.chat_id = p_chat_id
          AND m.content_type = 'system'
          AND m.sender_user_id IS NULL
    ) THEN
        RAISE EXCEPTION 'device command context does not match message';
    END IF;
    IF (SELECT auth.role()) = 'authenticated'
       AND command_owner_id IS DISTINCT FROM (SELECT auth.uid()) THEN
        RAISE EXCEPTION 'device command owner does not match caller';
    ELSIF (SELECT auth.role()) NOT IN ('authenticated', 'service_role') THEN
        RAISE EXCEPTION 'device command post requires an authenticated runtime';
    END IF;
    IF p_reply_to_message_id IS NOT NULL THEN
        SELECT m.sender_user_id INTO reply_sender_id
        FROM chat.messages m
        WHERE m.id = p_reply_to_message_id AND m.chat_id = p_chat_id;
        IF NOT FOUND OR reply_sender_id IS NULL THEN
            RAISE EXCEPTION 'reply target sender is not live';
        END IF;
    END IF;

    SELECT array_agg(DISTINCT identity_id ORDER BY identity_id)
    INTO required_identity_ids
    FROM (
        SELECT command_agent_id AS identity_id
        UNION ALL SELECT command_owner_id::TEXT
        UNION ALL SELECT command_sender_id
        UNION ALL SELECT reply_sender_id WHERE reply_sender_id IS NOT NULL
        UNION ALL
        SELECT recipient_id
        FROM unnest(COALESCE(p_to_user_ids, ARRAY[]::TEXT[])) AS recipient_id
        WHERE recipient_id <> '*'
    ) identities
    WHERE identity_id IS NOT NULL;
    required_count := COALESCE(cardinality(required_identity_ids), 0);
    SELECT count(*) INTO locked_count
    FROM (
        SELECT u.id
        FROM identity.users u
        WHERE u.id = ANY(COALESCE(required_identity_ids, ARRAY[]::TEXT[]))
        ORDER BY u.id
        FOR KEY SHARE
    ) locked;
    IF locked_count <> required_count THEN
        RAISE EXCEPTION 'device command sender or recipient is not live';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM identity.users agent
        WHERE agent.id = command_agent_id
          AND agent.type = 'agent'
          AND agent.owner_user_id = command_owner_id::text
    ) THEN
        RAISE EXCEPTION 'device command target agent is not live';
    END IF;

    IF '*' = ANY(COALESCE(p_to_user_ids, ARRAY[]::TEXT[]))
       AND command_chat_kind <> 'group' THEN
        RAISE EXCEPTION 'broadcast recipient is only valid in a group chat';
    END IF;
    SELECT array_agg(DISTINCT member_id ORDER BY member_id)
    INTO required_member_ids
    FROM (
        SELECT command_agent_id AS member_id
        UNION ALL SELECT command_sender_id
        UNION ALL SELECT reply_sender_id WHERE reply_sender_id IS NOT NULL
        UNION ALL
        SELECT recipient_id
        FROM unnest(COALESCE(p_to_user_ids, ARRAY[]::TEXT[])) AS recipient_id
        WHERE recipient_id <> '*'
    ) members
    WHERE member_id IS NOT NULL;
    required_count := COALESCE(cardinality(required_member_ids), 0);
    SELECT count(*) INTO locked_member_count
    FROM (
        SELECT cm.user_id
        FROM chat.chat_members cm
        WHERE cm.chat_id = p_chat_id
          AND cm.user_id = ANY(COALESCE(required_member_ids, ARRAY[]::TEXT[]))
        ORDER BY cm.user_id
        FOR KEY SHARE
    ) locked_members;
    IF locked_member_count <> required_count THEN
        RAISE EXCEPTION 'device command sender, target agent, reply sender or recipient is not a chat member';
    END IF;
    IF (SELECT auth.role()) = 'authenticated'
       AND NOT chat.can_act_as(command_agent_id, p_chat_id) THEN
        RAISE EXCEPTION 'device command owner cannot act as target agent in chat';
    END IF;
    RETURN command_owner_id;
END;
$$;


--
-- Name: assert_provision_owner_live(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.assert_provision_owner_live(p_owner_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NULLIF(p_owner_user_id, '') IS NULL THEN
        RAISE EXCEPTION 'provision owner id is required';
    END IF;
    -- Lock the owner's auth.users row FOR KEY SHARE FIRST — before the advisory. account-lifecycle
    -- owner-erasure (#2051) acquires the SAME row first (its entrypoint is the auth.users DELETE, which holds
    -- that row for the whole erase txn) and only THEN takes this advisory; taking them in the same order here
    -- makes a provision txn and a concurrent erase serialize on the auth.users row instead of acquiring
    -- {row, advisory} in opposite orders. auth. is fully qualified (this helper's search_path omits it).
    PERFORM 1 FROM auth.users WHERE id = p_owner_user_id::uuid FOR KEY SHARE;
    IF NOT FOUND THEN
        -- auth owner absent (already erased) — reject BEFORE the advisory or any resource action.
        RAISE EXCEPTION 'provision owner % is not a live human account (erased or erasing)', p_owner_user_id
            USING ERRCODE = 'no_data_found';
    END IF;
    -- Same key as account-lifecycle owner-erasure (#2051): 'identity:erase-human:' || <owner>.
    PERFORM pg_advisory_xact_lock(hashtextextended('identity:erase-human:' || p_owner_user_id, 0));
    IF NOT EXISTS (SELECT 1 FROM identity.users WHERE id = p_owner_user_id AND type = 'human') THEN
        RAISE EXCEPTION 'provision owner % is not a live human account (erased or erasing)', p_owner_user_id
            USING ERRCODE = 'no_data_found';
    END IF;
    -- The KEY SHARE above is held through COMMIT, so the deferred command->auth.users FK check still executes
    -- for real at commit but finds a compatible lock already held by this txn (no new wait), while a
    -- concurrent erase DELETE on the row stays blocked. The FK constraint is NOT skipped.
END;
$$;


--
-- Name: broadcast_agent_deliver_outcome_7503(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.broadcast_agent_deliver_outcome_7503() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
    IF NEW.type = 'agent.deliver' AND OLD.status IS DISTINCT FROM NEW.status THEN
        PERFORM realtime.send(
            pg_catalog.jsonb_build_object(
                'id', NEW.id,
                'status', NEW.status,
                'agent_user_id', NEW.payload ->> 'agent_user_id',
                'chat_id', NEW.payload ->> 'chat_id',
                'thread_root_id', NEW.payload ->> 'thread_root_id'
            ),
            'agent_deliver_changed',
            'gugu:user:' || NEW.user_id || ':events',
            true
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: broadcast_agent_presence_from_device(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.broadcast_agent_presence_from_device() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_agent RECORD;
    v_payload JSONB;
BEGIN
    FOR v_agent IN
        SELECT id
        FROM identity.users
        WHERE device_id = NEW.device_id
          AND type = 'agent'
    LOOP
        v_payload := identity.build_agent_presence_payload(v_agent.id);
        IF v_payload IS NULL THEN
            CONTINUE;
        END IF;
        PERFORM identity.fan_agent_presence_to_viewers(v_agent.id, v_payload);
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: broadcast_agent_presence_from_runtime(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.broadcast_agent_presence_from_runtime() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_payload JSONB;
BEGIN
    -- Suppress last_seen_at-only heartbeats only when every visible field is
    -- unchanged. active_chat_id and the #6448 reading are part of the visible projection.
    IF TG_OP = 'UPDATE'
       AND NEW.runtime_status      IS NOT DISTINCT FROM OLD.runtime_status
       AND NEW.activity_status     IS NOT DISTINCT FROM OLD.activity_status
       AND NEW.agent_status        IS NOT DISTINCT FROM OLD.agent_status
       AND NEW.agent_status_detail IS NOT DISTINCT FROM OLD.agent_status_detail
       AND NEW.runtime_kind        IS NOT DISTINCT FROM OLD.runtime_kind
       AND NEW.runtime_label       IS NOT DISTINCT FROM OLD.runtime_label
       AND NEW.window_title        IS NOT DISTINCT FROM OLD.window_title
       AND NEW.pid                 IS NOT DISTINCT FROM OLD.pid
       AND NEW.recent_tool_type    IS NOT DISTINCT FROM OLD.recent_tool_type
       AND NEW.recent_actions      IS NOT DISTINCT FROM OLD.recent_actions
       AND NEW.last_action_at      IS NOT DISTINCT FROM OLD.last_action_at
       AND NEW.active_chat_id      IS NOT DISTINCT FROM OLD.active_chat_id
    THEN
        RETURN NEW;
    END IF;

    v_payload := identity.build_agent_presence_payload(NEW.agent_user_id);
    IF v_payload IS NULL THEN
        RETURN NEW;
    END IF;

    PERFORM identity.fan_agent_presence_to_viewers(NEW.agent_user_id, v_payload);

    RETURN NEW;
END;
$$;


--
-- Name: broadcast_friend_request_changed(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.broadcast_friend_request_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    request_row identity.friend_requests%ROWTYPE;
    target_user_id TEXT;
    payload JSONB;
BEGIN
    request_row := COALESCE(NEW, OLD);
    -- @@@friend-request-sender - Insert policy keeps sender_id as the acting human; owned-agent fanout is only needed for agent receivers.
    payload := jsonb_build_object(
        'request_id', request_row.id,
        'sender_id', request_row.sender_id,
        'receiver_id', request_row.receiver_id,
        'status', request_row.status,
        'op', lower(TG_OP)
    );

    FOR target_user_id IN
        SELECT DISTINCT candidate.user_id
          FROM (
              SELECT request_row.sender_id AS user_id
              UNION ALL
              SELECT request_row.receiver_id AS user_id
              UNION ALL
              SELECT receiver.owner_user_id AS user_id
                FROM identity.users receiver
               WHERE receiver.id = request_row.receiver_id
                 AND receiver.type = 'agent'
                 AND receiver.owner_user_id IS NOT NULL
          ) candidate
         WHERE candidate.user_id IS NOT NULL
    LOOP
        PERFORM realtime.send(
            payload,
            'friend_requests_changed',
            'gugu:user:' || target_user_id || ':events',
            true
        );
    END LOOP;

    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: broadcast_user_agent_changed(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.broadcast_user_agent_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    target_row identity.users%ROWTYPE;
    op TEXT;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_row := OLD;
        op := 'deleted';
    ELSE
        target_row := NEW;
        op := lower(TG_OP);
    END IF;

    IF target_row.type IS DISTINCT FROM 'agent'
       OR target_row.owner_user_id IS NULL THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    PERFORM realtime.send(
        jsonb_build_object(
            'op', op,
            'agent', jsonb_build_object(
                'id',            target_row.id,
                'owner_user_id', target_row.owner_user_id,
                'device_id',     target_row.device_id,
                'local_path',    target_row.local_path,
                'prompt_path',   target_row.prompt_path,
                'display_name',  target_row.display_name,
                'agent_public',  target_row.agent_public,
                'updated_at',    target_row.updated_at
            )
        ),
        'agent_changed',
        'gugu:user:' || target_row.owner_user_id || ':agents',
        true
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: broadcast_user_setting_changed(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.broadcast_user_setting_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    target_user_id TEXT;
    op             TEXT;
    target_row     identity.user_settings%ROWTYPE;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_row := OLD;
        op := 'deleted';
    ELSE
        target_row := NEW;
        op := lower(TG_OP);
    END IF;
    target_user_id := target_row.user_id;

    PERFORM realtime.send(
        jsonb_build_object(
            'op', op,
            'setting', jsonb_build_object(
                'user_id',    target_row.user_id,
                'scope',      target_row.scope,
                'config',     target_row.config,
                'updated_at', target_row.updated_at
            )
        ),
        'setting_changed',
        'gugu:user:' || target_user_id || ':events',
        true
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: build_agent_presence_payload(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.build_agent_presence_payload(p_agent_user_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_payload JSONB;
BEGIN
    SELECT jsonb_build_object(
        'presence', jsonb_build_object(
            'agent_user_id',        u.id,
            'account_status',       'active',
            'runtime_status',       COALESCE(r.runtime_status, 'offline'),
            'derived_status',       CASE
                                        WHEN COALESCE(u.desired_status, 'online') = 'offline' THEN 'offline'
                                        WHEN r.last_seen_at IS NULL THEN 'offline'
                                        WHEN EXTRACT(EPOCH FROM (now() - r.last_seen_at)) * 1000 <= 180000 THEN 'online'
                                        ELSE 'offline'
                                    END,
            'desired_status',       COALESCE(u.desired_status, 'online'),
            'activity_status',      COALESCE(r.activity_status, 'idle'),
            -- #6448 宿主写下的读数;NULL = 这一行没有读数(读方退回 activity_status)。
            'agent_status',         r.agent_status,
            'agent_status_detail',  r.agent_status_detail,
            'active_chat_id',       r.active_chat_id,
            'runtime_kind',         r.runtime_kind,
            'runtime_label',        r.runtime_label,
            'agent_type',           ap.agent_type,
            'recent_tool_type',     r.recent_tool_type,
            'recent_actions',       COALESCE(r.recent_actions, ARRAY[]::TEXT[]),
            'last_action_at',       r.last_action_at,
            'window_title',         r.window_title,
            'pid',                  r.pid,
            'runtime_last_seen_at', r.last_seen_at,
            'device_id',            u.device_id,
            'device_status',        d.status,
            'device_last_seen_at',  d.last_seen_at,
            'host_runtime_capability', (d.capabilities->>'host_runtime_capability')::int,
            'consecutive_deliver_failures', COALESCE(r.consecutive_deliver_failures, 0),
            'updated_at',           GREATEST(
                                        COALESCE(r.updated_at, to_timestamp(0)),
                                        COALESCE(d.updated_at, to_timestamp(0))
                                    )
        )
    )
      INTO v_payload
      FROM identity.users u
      LEFT JOIN identity.agent_runtime_states r ON r.agent_user_id = u.id
      LEFT JOIN identity.gugu_devices d ON d.device_id = u.device_id
      LEFT JOIN identity.agent_profiles ap ON ap.id::text = u.id
     WHERE u.id = p_agent_user_id
       AND u.type = 'agent';

    IF v_payload IS NOT NULL THEN
        RETURN v_payload;
    END IF;

    SELECT jsonb_build_object(
        'presence', jsonb_build_object(
            'agent_user_id',        t.agent_user_id,
            'account_status',       'removed',
            'runtime_status',       'offline',
            'derived_status',       'offline',
            'desired_status',       'offline',
            'activity_status',      'idle',
            'agent_status',         NULL,
            'agent_status_detail',  NULL,
            'active_chat_id',       NULL,
            'runtime_kind',         NULL,
            'runtime_label',        NULL,
            'agent_type',           NULL,
            'recent_tool_type',     NULL,
            'recent_actions',       ARRAY[]::TEXT[],
            'last_action_at',       NULL,
            'window_title',         NULL,
            'pid',                  NULL,
            'runtime_last_seen_at', NULL,
            'device_id',            NULL,
            'device_status',        NULL,
            'device_last_seen_at',  NULL,
            'host_runtime_capability', NULL,
            'consecutive_deliver_failures', 0,
            'updated_at',           t.removed_at
        )
    )
      INTO v_payload
      FROM identity.agent_lifecycle_tombstones t
     WHERE t.agent_user_id = p_agent_user_id;

    RETURN v_payload;
END;
$$;


--
-- Name: can_view_agent_runtime_state(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.can_view_agent_runtime_state(p_agent_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM identity.users u
        WHERE u.id = p_agent_user_id
          AND u.type = 'agent'
          AND (
              u.owner_user_id = (SELECT auth.uid()::text)
              OR EXISTS (
                  SELECT 1
                  FROM identity.friendships f
                  WHERE (f.user_a_id = (SELECT auth.uid()::text) AND f.user_b_id = p_agent_user_id)
                     OR (f.user_b_id = (SELECT auth.uid()::text) AND f.user_a_id = p_agent_user_id)
              )
              OR EXISTS (
                  SELECT 1
                  FROM chat.chat_members cm_self
                  JOIN chat.chat_members cm_agent ON cm_agent.chat_id = cm_self.chat_id
                  WHERE cm_self.user_id = (SELECT auth.uid()::text)
                    AND cm_agent.user_id = p_agent_user_id
              )
          )
    ) OR EXISTS (
        SELECT 1
        FROM identity.agent_lifecycle_tombstones t
        WHERE t.agent_user_id = p_agent_user_id
          AND t.presence_viewer_user_ids @> ARRAY[(SELECT auth.uid()::text)]
    );
$$;


--
-- Name: can_write_agent_runtime_state(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.can_write_agent_runtime_state(p_agent_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM identity.users u
        WHERE u.id = p_agent_user_id
          AND u.type = 'agent'
          AND u.owner_user_id = (SELECT auth.uid()::text)
    );
$$;


--
-- Name: cancel_agent_provision_operation(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.cancel_agent_provision_operation(p_operation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_owner      TEXT := (SELECT auth.uid()::text);
  v_op         identity.agent_provision_operations;
  v_p          identity.agent_provisions;
  v_cmd_status TEXT;
BEGIN
  SELECT * INTO v_p FROM identity.agent_provisions
   WHERE operation_id = p_operation_id AND existing_agent_user_id IS NOT NULL
   ORDER BY created_at LIMIT 1;
  IF NOT FOUND OR v_owner IS NULL OR v_p.owner_user_id <> v_owner THEN
    PERFORM identity.cancel_agent_provision_operation_pre_adopt_7199(p_operation_id);
    RETURN;
  END IF;
  PERFORM identity.assert_provision_owner_live(v_owner);

  SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id;
  IF NOT FOUND OR v_op.owner_user_id <> v_owner THEN RAISE EXCEPTION 'operation % not found for caller', p_operation_id; END IF;
  IF v_op.phase IN ('completed', 'cancelled') THEN RETURN; END IF;

  -- identity 优先 → 命令 → 成员行最后(与 legacy 同序)。
  PERFORM 1 FROM identity.users WHERE id IN (v_owner, v_p.existing_agent_user_id) ORDER BY id FOR KEY SHARE;
  IF v_p.create_command_id IS NOT NULL THEN
    SELECT status INTO v_cmd_status FROM identity.gugu_device_commands WHERE id = v_p.create_command_id FOR UPDATE;
  END IF;
  SELECT * INTO v_p FROM identity.agent_provisions WHERE id = v_p.id FOR UPDATE;
  IF v_p.phase IN ('ready', 'completed') THEN
    RAISE EXCEPTION 'adopt: a move that is already ready cannot be cancelled (provision %)', v_p.id;
  END IF;
  IF v_cmd_status = 'running' THEN
    RAISE EXCEPTION 'adopt: the target device is still creating the new home (provision %); cancel after it finishes', v_p.id;
  END IF;
  IF v_cmd_status = 'pending' THEN
    DELETE FROM identity.gugu_device_commands WHERE id = v_p.create_command_id AND status = 'pending';
  ELSIF v_cmd_status IN ('done', 'error') THEN
    -- 新家那台已经做过 agent.create:发一条 agent.retire 把半成品拆掉(身份与旧家都不动)。
    INSERT INTO identity.gugu_device_commands (user_id, device_id, type, payload)
    VALUES (
      v_owner::uuid, v_p.device_id, 'agent.retire',
      jsonb_build_object('agent_user_id', v_p.existing_agent_user_id, 'reason', 'move_cancelled')
    );
  END IF;
  UPDATE identity.agent_provisions SET phase = 'cancelled', memory_content = NULL, updated_at = now() WHERE id = v_p.id;
  UPDATE identity.agent_provision_operations SET phase = 'cancelled', error = NULL, updated_at = now() WHERE id = p_operation_id;
END;
$$;


--
-- Name: cancel_agent_provision_operation_pre_adopt_7199(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.cancel_agent_provision_operation_pre_adopt_7199(p_operation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner TEXT := (SELECT auth.uid()::text);
    v_op    identity.agent_provision_operations;
    r       RECORD;
    v_deleted INT;
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    PERFORM identity.assert_provision_owner_live(v_owner);

    -- Unlocked locate (owner advisory already serializes this owner's provision txns, so the read is stable).
    SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id;
    IF NOT FOUND OR v_op.owner_user_id <> v_owner THEN RAISE EXCEPTION 'operation % not found for caller', p_operation_id; END IF;
    IF v_op.phase IN ('completed','cancelled') THEN RETURN; END IF;

    -- command domain (before op/member): compare-and-delete each still-pending create command. A 0-row
    -- delete means the device already claimed it (device isn't advisory-fenced) or it is terminal/absent —
    -- that running command is left for the renderer to stop after runtime terminal, then remove_owned_agent.
    FOR r IN SELECT id, create_command_id FROM identity.agent_provisions
             WHERE operation_id = p_operation_id AND phase <> 'cancelled' AND create_command_id IS NOT NULL LOOP
        DELETE FROM identity.gugu_device_commands WHERE id = r.create_command_id AND status = 'pending';
        GET DIAGNOSTICS v_deleted = ROW_COUNT;
    END LOOP;

    -- operation/member LAST: lock + re-validate under the lock, then advance phases.
    SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id FOR UPDATE;
    IF v_op.phase IN ('completed','cancelled') THEN RETURN; END IF;
    UPDATE identity.agent_provision_operations SET phase = 'cleaning_up', updated_at = now() WHERE id = p_operation_id;
    -- Compensate EVERY not-yet-cancelled member — INCLUDING completed ones (only a FINALIZED operation, early-
    -- returned above as phase='completed', is non-cancellable; leaving completed members would make terminal
    -- cancellation impossible). The provisioned-agent evidence was already bound at prepare (F6, set-once, never
    -- cleared); cancel only defensively COALESCE-rechecks it (never the sole snapshot moment) and scrubs raw memory
    -- (row + any surviving create-command payload). The member reaches 'cancelled' only later, in settle_provision_cancellation.
    FOR r IN SELECT * FROM identity.agent_provisions WHERE operation_id = p_operation_id AND phase <> 'cancelled' FOR UPDATE LOOP
        IF r.create_command_id IS NOT NULL THEN
            UPDATE identity.gugu_device_commands SET payload = payload - 'memory_content' WHERE id = r.create_command_id;
        END IF;
        UPDATE identity.agent_provisions
        SET provisioned_agent_user_id = COALESCE(provisioned_agent_user_id, agent_user_id::uuid),
            phase = 'cancelling', memory_content = NULL, updated_at = now()
        WHERE id = r.id;
    END LOOP;
    RETURN;
END;
$$;


--
-- Name: agent_provisions; Type: TABLE; Schema: identity; Owner: -
--

CREATE TABLE identity.agent_provisions (
    id uuid NOT NULL,
    owner_user_id text NOT NULL,
    operation_id uuid NOT NULL,
    member_key text NOT NULL,
    device_id text NOT NULL,
    display_name text NOT NULL,
    agent_type text NOT NULL,
    project_path text,
    avatar text,
    special_focus text,
    inherit_memory boolean NOT NULL,
    memory_sources text[],
    history_import_required boolean NOT NULL,
    memory_content jsonb,
    memory_content_hash text,
    history_payload_hash text,
    history_thread_root_id text,
    provisioned_agent_user_id uuid,
    payload_hash text NOT NULL,
    agent_user_id text,
    dm_chat_id text,
    create_command_id uuid,
    phase text DEFAULT 'queued'::text NOT NULL,
    template_client_message_id text,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    initial_message_text text,
    initial_message_id text,
    model text,
    effort text,
    permission_mode text,
    child_harness text,
    first_task text,
    existing_agent_user_id text,
    CONSTRAINT agent_provisions_binding_immutable CHECK (((agent_user_id IS NULL) OR ((provisioned_agent_user_id IS NOT NULL) AND (agent_user_id = (provisioned_agent_user_id)::text)))),
    CONSTRAINT agent_provisions_phase_check CHECK ((phase = ANY (ARRAY['queued'::text, 'preparing'::text, 'awaiting_terminal'::text, 'ready'::text, 'completed'::text, 'failed'::text, 'cancelling'::text, 'cancelled'::text])))
);


--
-- Name: claim_provision_slots(uuid, integer, uuid[]); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.claim_provision_slots(p_operation_id uuid, p_limit integer DEFAULT NULL::integer, p_retry_provision_ids uuid[] DEFAULT NULL::uuid[]) RETURNS SETOF identity.agent_provisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner     TEXT := (SELECT auth.uid()::text);
    v_op        identity.agent_provision_operations;
    v_inflight  INT;
    v_budget    INT;
    v_has_retry BOOLEAN := (p_retry_provision_ids IS NOT NULL AND cardinality(p_retry_provision_ids) > 0);
    -- round-5 retry-selection buckets: validated NEW failed candidates, the subset actually GRANTED, and the
    -- already-'preparing' idempotent-replay ids (returned but consuming no capacity and mutating nothing).
    v_retry_cand   UUID[] := '{}';
    v_retry_new    UUID[] := '{}';
    v_retry_replay UUID[] := '{}';
    v_queued_ok UUID[] := '{}';
    v_claimed   UUID[];
    v_rid       UUID;
    v_rp        identity.agent_provisions;
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    PERFORM identity.assert_provision_owner_live(v_owner);
    -- operation/member locked LAST, after the fence.
    SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id FOR UPDATE;
    IF NOT FOUND OR v_op.owner_user_id <> v_owner THEN RAISE EXCEPTION 'operation % not found for caller', p_operation_id; END IF;
    -- ── round-6 (P1-3): when retry ids are supplied, the WHOLE-ARRAY validation must run BEFORE any
    -- operation-phase early return. Otherwise a terminal operation (completed / cleaning_up / cancelled) would
    -- silently answer an invalid, foreign-operation or wrong-phase retry request with an empty set — turning
    -- "retry these ids" into "nothing to say, success", which breaks all-or-fail. An EMPTY selection keeps the
    -- original early-return behaviour (nothing to validate, nothing to grant).
    -- ── round-5/6: validate the ENTIRE retry selection BEFORE ANY mutation — all-or-fail on ELIGIBILITY ──
    -- Silently filtering an ineligible id would turn "retry A" into "quietly promoted queued B", so any violation
    -- rejects the WHOLE call with zero queued/retry/operation mutation. Exactly TWO phases are legal retry-selection
    -- states: 'failed' (a NEW candidate) and 'preparing' (an already-granted IDEMPOTENT REPLAY, so a lost claim
    -- response can still recover the same member). Everything else — queued / awaiting_terminal / ready / completed
    -- / cancelling / cancelled — is rejected here, as is the governed-removed cancel-only state (which must never
    -- be promoted nor consume a slot; prepare stays the final race fence, not this stable state's first detector).
    IF v_has_retry THEN
        IF EXISTS (SELECT 1 FROM unnest(p_retry_provision_ids) x WHERE x IS NULL) THEN
            RAISE EXCEPTION 'claim: retry selection contains a NULL provision id';
        END IF;
        IF (SELECT count(DISTINCT x) FROM unnest(p_retry_provision_ids) x) <> cardinality(p_retry_provision_ids) THEN
            RAISE EXCEPTION 'claim: retry selection contains duplicate provision ids';
        END IF;
        FOREACH v_rid IN ARRAY p_retry_provision_ids LOOP
            SELECT * INTO v_rp FROM identity.agent_provisions WHERE id = v_rid;
            IF NOT FOUND OR v_rp.owner_user_id <> v_owner OR v_rp.operation_id <> p_operation_id THEN
                RAISE EXCEPTION 'claim: retry id % is not a member of operation % owned by the caller', v_rid, p_operation_id;
            END IF;
            IF v_rp.provisioned_agent_user_id IS NOT NULL AND v_rp.agent_user_id IS NULL THEN
                RAISE EXCEPTION 'claim: retry id % is governed-removed (cancel/settle only) — refusing to grant a slot', v_rid;
            END IF;
            IF NOT (v_rp.agent_user_id IS NOT NULL AND v_rp.provisioned_agent_user_id IS NOT NULL
                    AND v_rp.agent_user_id = v_rp.provisioned_agent_user_id::text) THEN
                RAISE EXCEPTION 'claim: retry id % has no retryable immutable binding', v_rid;
            END IF;
            IF v_rp.phase NOT IN ('failed','preparing') THEN
                RAISE EXCEPTION 'claim: retry id % phase % is not a retry-selection state (want failed, or preparing for an idempotent replay)', v_rid, v_rp.phase;
            END IF;
            IF v_rp.phase = 'failed' THEN v_retry_cand := v_retry_cand || v_rid;
            ELSE v_retry_replay := v_retry_replay || v_rid; END IF;   -- already granted → replay, no new capacity
        END LOOP;
    END IF;

    -- Operation-phase gate AFTER validation (P1-3): claim grants only while provisioning_members, and a retry
    -- selection may additionally re-open a 'failed' operation. Reaching here means either there was no retry
    -- selection at all, or every requested id already passed the strict eligibility checks above.
    IF v_op.phase NOT IN ('provisioning_members','failed') THEN RETURN; END IF;
    IF v_op.phase = 'failed' AND NOT v_has_retry THEN RETURN; END IF;

    -- Capacity AFTER validation. Already-'preparing' replay rows are inherently counted in inflight, so they
    -- neither consume new budget nor get re-promoted.
    SELECT count(*) INTO v_inflight FROM identity.agent_provisions
    WHERE operation_id = p_operation_id AND phase IN ('preparing','awaiting_terminal');
    v_budget := LEAST(COALESCE(p_limit, v_op.concurrency_limit), v_op.concurrency_limit) - v_inflight;

    -- (1) deterministic RETRY-FIRST progress: grant validated NEW failed candidates within budget (a retry must
    -- never starve behind queued rows, and a failed operation must not reopen without advancing its failed member).
    IF v_budget > 0 AND cardinality(v_retry_cand) > 0 THEN
        v_retry_new := ARRAY(
            SELECT id FROM identity.agent_provisions
            WHERE id = ANY(v_retry_cand)
            ORDER BY created_at, id LIMIT v_budget);
    END IF;
    -- (2) fill only the REMAINING budget with 'queued' first-creates.
    IF v_budget - cardinality(v_retry_new) > 0 THEN
        v_queued_ok := ARRAY(
            SELECT id FROM identity.agent_provisions
            WHERE operation_id = p_operation_id AND phase = 'queued'
            ORDER BY created_at, id LIMIT (v_budget - cardinality(v_retry_new)));
    END IF;
    v_claimed := v_retry_new || v_queued_ok;

    IF cardinality(v_claimed) > 0 THEN
        -- Promote ONLY the new grants under this op-row lock. Validated-but-ungranted failed rows stay 'failed'
        -- (capacity, not an error); replay rows are untouched.
        UPDATE identity.agent_provisions SET phase = 'preparing', error = NULL, updated_at = now()
        WHERE id = ANY(v_claimed);
        -- round-6 (P1-4): reopen on ANY real new grant — new failed-retry grants PLUS new queued grants. A
        -- 'preparing' replay alone grants nothing and must never reopen; but a replay accompanied by a newly
        -- granted queued member IS real new work and must reopen (the old v_retry_new-only guard missed that).
        IF cardinality(v_retry_new) + cardinality(v_queued_ok) > 0 THEN
            UPDATE identity.agent_provision_operations SET phase = 'provisioning_members', error = NULL, updated_at = now()
            WHERE id = p_operation_id AND phase = 'failed';
        END IF;
    END IF;

    -- Return new grants PLUS already-preparing replay rows, so a caller whose earlier claim response was lost can
    -- still drive the SAME member. A pure replay mutates nothing but must still be returned.
    IF cardinality(v_claimed) = 0 AND cardinality(v_retry_replay) = 0 THEN RETURN; END IF;
    RETURN QUERY SELECT * FROM identity.agent_provisions
     WHERE id = ANY(v_claimed || v_retry_replay) ORDER BY created_at, id;
END;
$$;


--
-- Name: cleanup_legacy_gugu_devices(text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.cleanup_legacy_gugu_devices(p_keep_device_id text, p_hostname text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
DECLARE
    v_user_id UUID := auth.uid();
    v_deleted INTEGER := 0;
    v_stale   INTEGER := 0;
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'cleanup_legacy_gugu_devices requires an authenticated user';
    END IF;

    DELETE FROM identity.gugu_devices d
    WHERE d.user_id = v_user_id
      AND d.device_id <> p_keep_device_id
      AND d.machine_id IS NULL
      AND d.hostname = p_hostname
      AND d.last_seen_at < now() - interval '2 minutes'
      AND NOT EXISTS (
          SELECT 1
          FROM identity.users u
          WHERE u.device_id = d.device_id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM identity.gugu_device_commands c
          WHERE c.device_id = d.device_id
      );

    GET DIAGNOSTICS v_deleted = ROW_COUNT;

    -- #663 stale reclaim：30 天无心跳 + 无 agent 绑定 + 未改名 + 无近期在途命令 → 删（跨 hostname）。
    DELETE FROM identity.gugu_devices d
    WHERE d.user_id = v_user_id
      AND d.device_id <> p_keep_device_id
      AND d.last_seen_at < now() - interval '30 days'
      AND d.label_customized_at IS NULL
      AND NOT EXISTS (
          SELECT 1
          FROM identity.users u
          WHERE u.device_id = d.device_id
      )
      AND NOT EXISTS (
          SELECT 1
          FROM identity.gugu_device_commands c
          WHERE c.user_id = v_user_id
            AND c.device_id = d.device_id
            AND c.status IN ('pending', 'running')
            AND c.created_at > now() - interval '30 days'
      );

    GET DIAGNOSTICS v_stale = ROW_COUNT;
    RETURN v_deleted + v_stale;
END;
$$;


--
-- Name: complete_agent_provision(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.complete_agent_provision(p_provision_id uuid) RETURNS TABLE(message_id text, client_message_id text, already boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_owner      TEXT := (SELECT auth.uid()::text);
  v_p          identity.agent_provisions;
  v_cmd_status TEXT;
  v_already    BOOLEAN;
BEGIN
  SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id;
  IF NOT FOUND OR v_p.existing_agent_user_id IS NULL OR v_owner IS NULL OR v_p.owner_user_id <> v_owner THEN
    RETURN QUERY SELECT * FROM identity.complete_agent_provision_pre_adopt_7199(p_provision_id);
    RETURN;
  END IF;
  PERFORM identity.assert_provision_owner_live(v_owner);
  IF v_p.agent_user_id IS NULL OR v_p.dm_chat_id IS NULL OR v_p.create_command_id IS NULL THEN
    RAISE EXCEPTION 'provision % is not prepared', p_provision_id;
  END IF;

  PERFORM 1 FROM identity.users WHERE id IN (v_owner, v_p.agent_user_id) ORDER BY id FOR KEY SHARE;
  SELECT status INTO v_cmd_status FROM identity.gugu_device_commands WHERE id = v_p.create_command_id FOR UPDATE;
  IF v_cmd_status IS DISTINCT FROM 'done' THEN
    RAISE EXCEPTION 'agent.create command for provision % is not done (status=%)', p_provision_id, COALESCE(v_cmd_status, '<missing>');
  END IF;
  SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id FOR UPDATE;
  IF v_p.phase NOT IN ('ready', 'completed') THEN
    RAISE EXCEPTION 'provision % must be settled ready before complete (phase=%)', p_provision_id, v_p.phase;
  END IF;
  v_already := v_p.phase = 'completed';
  IF NOT v_already THEN
    UPDATE identity.agent_provisions SET phase = 'completed', memory_content = NULL, updated_at = now() WHERE id = p_provision_id;
  END IF;
  UPDATE identity.agent_provision_operations SET phase = 'completed', updated_at = now()
   WHERE id = v_p.operation_id AND kind = 'single' AND phase <> 'completed';
  RETURN QUERY SELECT NULL::TEXT, NULL::TEXT, v_already;
END;
$$;


--
-- Name: complete_agent_provision_internal(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.complete_agent_provision_internal(p_provision_id uuid) RETURNS TABLE(message_id text, client_message_id text, already boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner     TEXT := (SELECT auth.uid()::text);
    v_p         identity.agent_provisions;
    v_cmd_status TEXT;
    v_key       TEXT;
    v_msg_id    TEXT;
    v_content   TEXT;
    v_inserted  INT;
    v_already   BOOLEAN;
    v_e_sender  TEXT;
    v_e_content TEXT;
    v_e_ctype   TEXT;
    v_e_to      TEXT[];
    v_e_reply   TEXT;
    v_e_thread  TEXT;
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    PERFORM identity.assert_provision_owner_live(v_owner);

    -- Unlocked locate (which chat/command to lock) then lock in global order and re-read + validate.
    SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id;
    IF NOT FOUND OR v_p.owner_user_id <> v_owner THEN RAISE EXCEPTION 'provision % not found for caller', p_provision_id; END IF;
    IF v_p.agent_user_id IS NULL OR v_p.dm_chat_id IS NULL OR v_p.create_command_id IS NULL THEN
        RAISE EXCEPTION 'provision % is not prepared', p_provision_id;
    END IF;

    -- F5 global lock order (identity -> chat -> command -> operation/member last): identity FIRST so complete and
    -- a concurrent remove_owned_agent (identity->chat) never form a cycle (the erase advisory does NOT cover
    -- ordinary removal — correctness is the shared identity->chat->command order, not the fence).
    -- identity lock (order 1): owner + agent, id-ordered, FOR KEY SHARE — compatible with the message insert's
    -- FK-share on the agent, consistently ahead of chat/command/op-member and behind erase's FOR UPDATE.
    PERFORM 1 FROM identity.users WHERE id IN (v_owner, v_p.agent_user_id) ORDER BY id FOR KEY SHARE;
    -- chat lock (order 2)
    PERFORM 1 FROM chat.chats WHERE id = v_p.dm_chat_id FOR UPDATE;
    -- command lock (order 3) + terminal check: reject completion before the create command is done.
    SELECT status INTO v_cmd_status FROM identity.gugu_device_commands WHERE id = v_p.create_command_id FOR UPDATE;
    IF v_cmd_status IS DISTINCT FROM 'done' THEN
        RAISE EXCEPTION 'agent.create command for provision % is not done (status=%)', p_provision_id, COALESCE(v_cmd_status,'<missing>');
    END IF;
    -- operation/member lock (LAST) + re-read and re-validate owner/phase under the lock. complete ONLY
    -- accepts a member already settled to 'ready' (its terminal folded by settle_agent_provision_terminal),
    -- and re-verifies the command is done above; 'completed' is the idempotent-replay case.
    SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id FOR UPDATE;
    IF v_p.owner_user_id <> v_owner THEN RAISE EXCEPTION 'provision % not owned by caller', p_provision_id; END IF;
    IF v_p.phase NOT IN ('ready','completed') THEN
        RAISE EXCEPTION 'provision % must be settled ready before complete (phase=%)', p_provision_id, v_p.phase;
    END IF;
    -- Required history import MUST already have landed (root non-null) before the template — imported standard
    -- history therefore always precedes the deterministic template (see import_agent_provision_history /
    -- [[conversation-data]]). No agent.deliver / model turn is ever involved.
    IF v_p.history_import_required AND v_p.history_thread_root_id IS NULL THEN
        RAISE EXCEPTION 'provision % requires history import to complete before the template (no history thread root)', p_provision_id;
    END IF;

    v_key := 'agent-bootstrap:' || p_provision_id::text || ':' || v_p.member_key;
    v_content := identity.provision_template_message(v_p.display_name, v_p.agent_type, v_p.special_focus);
    v_msg_id := gen_random_uuid()::text;

    -- Agent-authored standard message, sender = the agent (only a definer path writes this under RLS).
    -- Targetless DO NOTHING avoids the partial-index WHERE predicate that shadows the OUT parameter
    -- client_message_id (42702). On a 0-row insert, re-read the stable dedup key and field-validate the FULL
    -- server-derived template projection (created_at excluded); a conflict that is NOT our dedup key (no row)
    -- or any divergent projection fails loud — never a false "already".
    INSERT INTO chat.messages (id, chat_id, sender_user_id, content, content_type, client_message_id)
    VALUES (v_msg_id, v_p.dm_chat_id, v_p.agent_user_id, v_content, 'text', v_key)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_inserted = ROW_COUNT;
    IF v_inserted = 1 THEN
        v_already := false;
    ELSE
        SELECT m.id, m.sender_user_id, m.content, m.content_type, m.to_user_ids, m.reply_to_message_id, m.thread_root_id
        INTO v_msg_id, v_e_sender, v_e_content, v_e_ctype, v_e_to, v_e_reply, v_e_thread
        FROM chat.messages m WHERE m.chat_id = v_p.dm_chat_id AND m.client_message_id = v_key;
        IF v_msg_id IS NULL THEN
            RAISE EXCEPTION 'complete_agent_provision: unexpected unique conflict for provision % (no row at dedup key %)', p_provision_id, v_key;
        END IF;
        IF v_e_sender IS DISTINCT FROM v_p.agent_user_id
           OR v_e_content IS DISTINCT FROM v_content
           OR v_e_ctype IS DISTINCT FROM 'text'
           OR COALESCE(cardinality(v_e_to), 0) <> 0
           OR v_e_reply IS NOT NULL
           OR v_e_thread IS NOT NULL THEN
            RAISE EXCEPTION 'complete_agent_provision: dedup key % exists with a divergent server-derived projection', v_key;
        END IF;
        v_already := true;   -- exactly-once idempotent replay
    END IF;

    -- Defensive raw-memory scrub for idempotent convergence (settle=done already cleared these): a completed
    -- member and its create command never retain raw memory_content.
    UPDATE identity.gugu_device_commands SET payload = payload - 'memory_content' WHERE id = v_p.create_command_id;
    IF v_p.phase <> 'completed' THEN
        UPDATE identity.agent_provisions SET phase = 'completed', template_client_message_id = v_key, memory_content = NULL, updated_at = now()
        WHERE id = p_provision_id;
    END IF;
    -- A single operation has no group / no finalize: it completes atomically once its sole member completes.
    UPDATE identity.agent_provision_operations SET phase = 'completed', updated_at = now()
    WHERE id = v_p.operation_id AND kind = 'single' AND phase <> 'completed';
    RETURN QUERY SELECT v_msg_id, v_key, v_already;
END;
$$;


--
-- Name: complete_agent_provision_pre_adopt_7199(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.complete_agent_provision_pre_adopt_7199(p_provision_id uuid) RETURNS TABLE(message_id text, client_message_id text, already boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_result record;
    v_owner text := (SELECT auth.uid()::text);
    v_kind text;
    v_dm_chat_id text;
BEGIN
    SELECT * INTO v_result
    FROM identity.complete_agent_provision_internal(p_provision_id);

    SELECT op.kind, p.dm_chat_id
    INTO v_kind, v_dm_chat_id
    FROM identity.agent_provisions p
    JOIN identity.agent_provision_operations op ON op.id = p.operation_id
    WHERE p.id = p_provision_id
      AND p.owner_user_id = v_owner;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'completed provision % disappeared or changed owner', p_provision_id;
    END IF;

    IF v_kind = 'single' THEN
        UPDATE chat.chat_members
        SET inbox_published_at = COALESCE(inbox_published_at, now()),
            updated_at = CASE WHEN inbox_published_at IS NULL THEN now() ELSE updated_at END
        WHERE chat_id = v_dm_chat_id
          AND user_id = v_owner;
    END IF;

    RETURN QUERY SELECT v_result.message_id, v_result.client_message_id, v_result.already;
END;
$$;


--
-- Name: create_owned_agent(text, text, text, text, text, text, boolean, text, uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.create_owned_agent(p_display_name text, p_avatar text, p_agent_type text, p_device_id text, p_local_path text DEFAULT NULL::text, p_prompt_path text DEFAULT NULL::text, p_inherit_memory boolean DEFAULT true, p_special_focus text DEFAULT NULL::text, p_agent_id uuid DEFAULT NULL::uuid) RETURNS TABLE(id uuid, display_name text, avatar text, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner TEXT := (SELECT auth.uid()::text);
    v_new_id UUID; v_avatar TEXT;
BEGIN
    IF v_owner IS NULL THEN
        RAISE EXCEPTION 'create_owned_agent requires authenticated session';
    END IF;
    IF p_device_id IS NULL OR p_device_id = '' THEN
        RAISE EXCEPTION 'p_device_id is required (death-bind)';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM identity.gugu_devices
        WHERE device_id = p_device_id AND user_id::text = v_owner
    ) THEN
        RAISE EXCEPTION 'device_id % is not owned by current user', p_device_id;
    END IF;
    PERFORM set_config('identity.agent_create_device_id', p_device_id, true);
    v_avatar := CASE
        WHEN identity.is_valid_avatar_url(NULLIF(p_avatar, '')) THEN p_avatar
        ELSE NULL
    END;
    INSERT INTO identity.agent_profiles (id, display_name, owner_id, avatar, agent_type)
    VALUES (COALESCE(p_agent_id, gen_random_uuid()), p_display_name, v_owner::uuid, v_avatar, p_agent_type)
    RETURNING agent_profiles.id INTO v_new_id;
    UPDATE identity.users
    SET
        device_id      = p_device_id,
        local_path     = p_local_path,
        prompt_path    = p_prompt_path,
        inherit_memory = coalesce(p_inherit_memory, true),
        special_focus  = NULLIF(btrim(coalesce(p_special_focus, '')), '')
    WHERE identity.users.id = v_new_id::text;
    RETURN QUERY SELECT v_new_id, p_display_name, v_avatar, now();
END;
$$;


--
-- Name: current_jwt_session_id(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.current_jwt_session_id() RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_raw TEXT := nullif(auth.jwt() ->> 'session_id', '');
BEGIN
    IF v_raw IS NULL OR v_raw !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN NULL;
    END IF;
    RETURN v_raw::uuid;
END;
$_$;


--
-- Name: eject_agent_group_member_after_friendship_delete(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.eject_agent_group_member_after_friendship_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_a_type TEXT;
    v_b_type TEXT;
    v_agent_user_id TEXT;
    v_human_user_id TEXT;
BEGIN
    SELECT type INTO v_a_type FROM identity.users WHERE id = OLD.user_a_id;
    SELECT type INTO v_b_type FROM identity.users WHERE id = OLD.user_b_id;

    IF v_a_type = 'agent' AND COALESCE(v_b_type, 'human') <> 'agent' THEN
        v_agent_user_id := OLD.user_a_id;
        v_human_user_id := OLD.user_b_id;
    ELSIF v_b_type = 'agent' AND COALESCE(v_a_type, 'human') <> 'agent' THEN
        v_agent_user_id := OLD.user_b_id;
        v_human_user_id := OLD.user_a_id;
    ELSE
        RETURN OLD;
    END IF;

    -- @@@1514 解除人类↔agent 好友 → 从该 agent 自有的群(原 channel，creator=agent)踢出该人类。
    DELETE FROM chat.chat_members cm
    USING chat.chats c
    WHERE c.id = cm.chat_id
      AND c.kind = 'group'
      AND c.creator_user_id = v_agent_user_id
      AND cm.user_id = v_human_user_id;

    RETURN OLD;
END;
$$;


--
-- Name: ensure_cloud_device(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.ensure_cloud_device() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    RAISE EXCEPTION 'Gugu Cloud Agent has been retired';
END;
$$;


--
-- Name: erase_human_account(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.erase_human_account(p_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'moments', 'storage', 'public', 'pg_catalog'
    AS $$
DECLARE
    delete_user_ids TEXT[];
    affected_chat_id TEXT;
    affected_chat_kind TEXT;
    affected_chat_status TEXT;
    current_owner_id TEXT;
    new_owner_id TEXT;
    remaining_member_count INTEGER;
    deleted_human_count INTEGER;
BEGIN
    IF NULLIF(p_user_id, '') IS NULL THEN
        RAISE EXCEPTION 'human account id is required';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('identity:erase-human:' || p_user_id, 0));
    IF NOT EXISTS (SELECT 1 FROM identity.users WHERE id = p_user_id AND type = 'human') THEN
        RAISE EXCEPTION 'auth deletion has no matching human identity for %', p_user_id;
    END IF;

    SELECT array_agg(id ORDER BY CASE WHEN id = p_user_id THEN 0 ELSE 1 END, id)
    INTO delete_user_ids
    FROM identity.users
    WHERE id = p_user_id OR (type = 'agent' AND owner_user_id = p_user_id);

    INSERT INTO identity.account_lifecycle_context (
        transaction_id, operation, subject_user_id, delete_user_ids
    ) VALUES (
        pg_current_xact_id(), 'privacy_erasure', p_user_id, delete_user_ids
    );

    FOR affected_chat_id IN
        SELECT DISTINCT cm.chat_id
        FROM chat.chat_members cm
        JOIN chat.chats c ON c.id = cm.chat_id
        WHERE cm.user_id = ANY(delete_user_ids)
        ORDER BY cm.chat_id
    LOOP
        SELECT kind, status INTO affected_chat_kind, affected_chat_status
        FROM chat.chats WHERE id = affected_chat_id FOR UPDATE;
        PERFORM 1 FROM chat.chat_members
        WHERE chat_id = affected_chat_id ORDER BY user_id FOR UPDATE;

        IF affected_chat_kind = 'dm' THEN
            UPDATE chat.chats c
            SET name = '已注销用户', updated_at = now()
            WHERE c.id = affected_chat_id
              AND EXISTS (
                  SELECT 1 FROM chat.chat_members live_peer
                  WHERE live_peer.chat_id = c.id
                    AND NOT (live_peer.user_id = ANY(delete_user_ids))
              );
            CONTINUE;
        END IF;
        IF affected_chat_kind <> 'group' THEN
            CONTINUE;
        END IF;

        SELECT user_id INTO current_owner_id
        FROM chat.chat_members
        WHERE chat_id = affected_chat_id AND role = 'owner'
        ORDER BY user_id LIMIT 1;
        SELECT count(*) INTO remaining_member_count
        FROM chat.chat_members
        WHERE chat_id = affected_chat_id AND NOT (user_id = ANY(delete_user_ids));

        IF affected_chat_status <> 'archived'
           AND current_owner_id = ANY(delete_user_ids) THEN
            SELECT cm.user_id INTO new_owner_id
            FROM chat.chat_members cm
            JOIN identity.users u ON u.id = cm.user_id AND u.type = 'human'
            WHERE cm.chat_id = affected_chat_id
              AND NOT (cm.user_id = ANY(delete_user_ids))
            ORDER BY CASE WHEN cm.role = 'admin' THEN 0 ELSE 1 END, cm.joined_at, cm.user_id
            LIMIT 1;

            IF new_owner_id IS NULL THEN
                UPDATE chat.chat_members SET role = 'member', updated_at = now()
                WHERE chat_id = affected_chat_id AND role = 'owner';
                UPDATE chat.chats
                SET status = 'archived', creator_user_id = NULL, updated_at = now()
                WHERE id = affected_chat_id;
            ELSE
                UPDATE chat.chat_members SET role = 'owner', updated_at = now()
                WHERE chat_id = affected_chat_id AND user_id = new_owner_id;
                UPDATE chat.chat_members SET role = 'member', updated_at = now()
                WHERE chat_id = affected_chat_id AND role = 'owner' AND user_id <> new_owner_id;
                UPDATE chat.chats SET creator_user_id = new_owner_id, updated_at = now()
                WHERE id = affected_chat_id;
            END IF;
        END IF;

        IF remaining_member_count < 2 THEN
            UPDATE chat.chats SET status = 'archived', updated_at = now()
            WHERE id = affected_chat_id AND status = 'active';
        END IF;
    END LOOP;

    -- Global lock order shared with transfer/post paths: chat, command, then identity/device.
    PERFORM 1 FROM identity.gugu_device_commands c
    WHERE c.user_id = p_user_id::uuid
       OR c.payload->>'agent_user_id' = ANY(delete_user_ids)
       OR (c.type IN ('agent.deliver', 'agent.wake')
           AND c.payload->>'sender_user_id' = ANY(delete_user_ids))
       OR c.payload->>'reply_to_sender_user_id' = ANY(delete_user_ids)
       OR (jsonb_typeof(c.payload->'to_user_ids') = 'array' AND EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(c.payload->'to_user_ids') AS recipient(value)
            WHERE recipient.value = ANY(delete_user_ids)
       ))
    ORDER BY c.id FOR UPDATE;
    DELETE FROM identity.gugu_device_commands c
    WHERE c.user_id = p_user_id::uuid
       OR c.payload->>'agent_user_id' = ANY(delete_user_ids)
       OR (c.type IN ('agent.deliver', 'agent.wake')
           AND c.payload->>'sender_user_id' = ANY(delete_user_ids));
    UPDATE identity.gugu_device_commands c
    SET payload = (c.payload - 'reply_to_sender_user_id')
                  || jsonb_build_object('reply_to_sender_name', '已注销用户')
    WHERE c.payload->>'reply_to_sender_user_id' = ANY(delete_user_ids);
    UPDATE identity.gugu_device_commands c
    SET payload = jsonb_set(c.payload, '{to_user_ids}', COALESCE((
            SELECT jsonb_agg(recipient.value ORDER BY recipient.ordinality)
            FROM jsonb_array_elements_text(c.payload->'to_user_ids')
                 WITH ORDINALITY AS recipient(value, ordinality)
            WHERE recipient.value = '*'
               OR NOT (recipient.value = ANY(delete_user_ids))
        ), '[]'::jsonb), true)
    WHERE jsonb_typeof(c.payload->'to_user_ids') = 'array'
      AND EXISTS (
          SELECT 1 FROM jsonb_array_elements_text(c.payload->'to_user_ids') AS recipient(value)
          WHERE recipient.value = ANY(delete_user_ids)
      );

    DELETE FROM chat.message_deliveries d
    WHERE d.device_id IN (
        SELECT 'gugu-agent:' || deleted_agent.id
        FROM unnest(delete_user_ids) AS deleted_agent(id)
        WHERE deleted_agent.id <> p_user_id
    );

    PERFORM 1 FROM identity.users
    WHERE id = ANY(delete_user_ids)
    ORDER BY id FOR UPDATE;
    PERFORM 1 FROM identity.gugu_devices
    WHERE user_id = p_user_id::uuid
    ORDER BY device_id FOR UPDATE;
    DELETE FROM auth.flow_state WHERE user_id = p_user_id::uuid;

    UPDATE chat.messages m
    SET to_user_ids = ARRAY(
            SELECT recipient_id FROM unnest(m.to_user_ids) AS recipient_id
            WHERE NOT (recipient_id = ANY(delete_user_ids))
        )
    WHERE m.to_user_ids && delete_user_ids;
    UPDATE chat.messages m
    SET deleted_for_user_ids = m.deleted_for_user_ids - delete_user_ids
    WHERE m.deleted_for_user_ids ?| delete_user_ids;
    UPDATE chat.gugu_decision_events e
    SET user_task_decisions = e.user_task_decisions - delete_user_ids,
        user_resource_states = e.user_resource_states - delete_user_ids,
        user_rationales = e.user_rationales - delete_user_ids,
        created_by_user_id = CASE
            WHEN e.created_by_user_id = ANY(delete_user_ids) THEN NULL ELSE e.created_by_user_id
        END
    WHERE e.user_task_decisions ?| delete_user_ids
       OR e.user_resource_states ?| delete_user_ids
       OR e.user_rationales ?| delete_user_ids
       OR e.created_by_user_id = ANY(delete_user_ids);
    UPDATE identity.agent_lifecycle_tombstones t
    SET presence_viewer_user_ids = ARRAY(
            SELECT viewer_id FROM unnest(t.presence_viewer_user_ids) AS viewer_id
            WHERE NOT (viewer_id = ANY(delete_user_ids))
        ),
        contact_viewer_user_ids = ARRAY(
            SELECT viewer_id FROM unnest(t.contact_viewer_user_ids) AS viewer_id
            WHERE NOT (viewer_id = ANY(delete_user_ids))
        )
    WHERE NOT (t.owner_user_id = ANY(delete_user_ids))
      AND (t.presence_viewer_user_ids && delete_user_ids
           OR t.contact_viewer_user_ids && delete_user_ids);

    -- Product-visible object erasure is part of this database transaction. Surviving content keeps
    -- its object metadata, but ownership is cleared so a path prefix is never mistaken for authority.
    PERFORM 1 FROM storage.objects o
    WHERE (o.owner::text = ANY(delete_user_ids))
       OR (o.owner_id = ANY(delete_user_ids))
       OR (o.bucket_id = 'avatars' AND split_part(o.name, '.', 1) = ANY(delete_user_ids))
       OR (o.bucket_id = 'chat-media' AND (storage.foldername(o.name))[1] = ANY(delete_user_ids))
       OR (o.bucket_id = 'workspace' AND (storage.foldername(o.name))[2] = ANY(delete_user_ids))
    ORDER BY o.id FOR UPDATE;

    UPDATE storage.objects o
    SET owner = NULL, owner_id = NULL
    WHERE (
            o.owner::text = ANY(delete_user_ids)
            OR o.owner_id = ANY(delete_user_ids)
            OR (o.bucket_id = 'avatars' AND split_part(o.name, '.', 1) = ANY(delete_user_ids))
            OR (o.bucket_id = 'chat-media' AND (storage.foldername(o.name))[1] = ANY(delete_user_ids))
            OR (o.bucket_id = 'workspace' AND (storage.foldername(o.name))[2] = ANY(delete_user_ids))
        )
      AND identity.storage_object_is_referenced(o.bucket_id, o.name);

    INSERT INTO identity.storage_object_deletion_outbox (bucket_id, name)
    SELECT o.bucket_id, o.name
    FROM storage.objects o
    WHERE (
            o.owner::text = ANY(delete_user_ids)
            OR o.owner_id = ANY(delete_user_ids)
            OR (o.bucket_id = 'avatars' AND split_part(o.name, '.', 1) = ANY(delete_user_ids))
            OR (o.bucket_id = 'chat-media' AND (storage.foldername(o.name))[1] = ANY(delete_user_ids))
            OR (o.bucket_id = 'workspace' AND (storage.foldername(o.name))[2] = ANY(delete_user_ids))
        )
      AND NOT identity.storage_object_is_referenced(o.bucket_id, o.name)
    ON CONFLICT (bucket_id, name) DO NOTHING;

    PERFORM 1 FROM storage.s3_multipart_uploads upload
    WHERE upload.owner_id = ANY(delete_user_ids)
    ORDER BY upload.id FOR UPDATE;
    INSERT INTO identity.storage_multipart_abort_outbox (upload_id, bucket_id, object_key)
    SELECT upload.id, upload.bucket_id, upload.key
    FROM storage.s3_multipart_uploads upload
    WHERE upload.owner_id = ANY(delete_user_ids)
    ON CONFLICT (upload_id) DO NOTHING;

    DELETE FROM identity.users WHERE id = p_user_id AND type = 'human';
    GET DIAGNOSTICS deleted_human_count = ROW_COUNT;
    IF deleted_human_count <> 1 THEN
        RAISE EXCEPTION 'human identity erasure affected % rows for %', deleted_human_count, p_user_id;
    END IF;
    DELETE FROM identity.gugu_devices WHERE user_id = p_user_id::uuid;

    IF EXISTS (SELECT 1 FROM identity.users WHERE id = ANY(delete_user_ids)) THEN
        RAISE EXCEPTION 'identity erasure left live rows for %', p_user_id;
    END IF;
    DELETE FROM identity.account_lifecycle_context
    WHERE transaction_id = pg_current_xact_id()
      AND operation = 'privacy_erasure'
      AND subject_user_id = p_user_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'account lifecycle context disappeared before completion';
    END IF;
END;
$$;


--
-- Name: fan_agent_presence_to_viewers(text, jsonb); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.fan_agent_presence_to_viewers(p_agent_user_id text, p_payload jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    viewer_user_id TEXT;
    next_revision BIGINT;
BEGIN
    IF p_payload IS NULL THEN
        RAISE EXCEPTION 'Agent presence payload is required';
    END IF;

    FOR viewer_user_id IN
        SELECT DISTINCT candidate.user_id
          FROM (
            SELECT unnest(t.presence_viewer_user_ids) AS user_id
              FROM identity.agent_lifecycle_tombstones t
             WHERE t.agent_user_id = p_agent_user_id
            UNION
            SELECT u.owner_user_id
              FROM identity.users u
             WHERE u.id = p_agent_user_id
               AND u.type = 'agent'
               AND u.owner_user_id IS NOT NULL
            UNION
            SELECT CASE WHEN f.user_a_id = p_agent_user_id THEN f.user_b_id ELSE f.user_a_id END
              FROM identity.friendships f
             WHERE f.user_a_id = p_agent_user_id OR f.user_b_id = p_agent_user_id
            UNION
            SELECT cm_self.user_id
              FROM chat.chat_members cm_agent
              JOIN chat.chat_members cm_self ON cm_self.chat_id = cm_agent.chat_id
             WHERE cm_agent.user_id = p_agent_user_id
               AND cm_self.user_id <> p_agent_user_id
          ) candidate
         WHERE candidate.user_id IS NOT NULL
         ORDER BY candidate.user_id
    LOOP
        next_revision := chat.append_user_revision(
          viewer_user_id,
          'presence_changed',
          jsonb_build_object('agent_user_id', p_agent_user_id),
          COALESCE(p_payload ->> 'derived_status', '') = 'removed'
        );
        IF chat.claim_presence_wake(viewer_user_id) THEN
            PERFORM realtime.send(
                jsonb_build_object('revision', next_revision),
                'im_revision_advanced',
                'gugu:user:' || viewer_user_id || ':events',
                true
            );
        END IF;
    END LOOP;
END;
$$;


--
-- Name: gugu_device_commands; Type: TABLE; Schema: identity; Owner: -
--

CREATE TABLE identity.gugu_device_commands (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    device_id text NOT NULL,
    type text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    result jsonb,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    completed_at timestamp with time zone,
    claimed_by text,
    claim_token uuid,
    CONSTRAINT gugu_device_commands_status_chk CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'done'::text, 'error'::text]))),
    CONSTRAINT gugu_device_commands_type_chk CHECK ((type = ANY (ARRAY['agent.create'::text, 'agent.deliver'::text, 'agent.wake'::text, 'agent.stop'::text, 'agent.runtime-info'::text, 'agent.set_model'::text, 'agent.retire'::text])))
);


--
-- Name: fetch_fair_pending_device_commands(text, integer); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.fetch_fair_pending_device_commands(p_device_id text, p_per_agent integer DEFAULT 1) RETURNS SETOF identity.gugu_device_commands
    LANGUAGE sql STABLE
    SET search_path TO 'identity', 'public'
    AS $$
    SELECT c.*
    FROM identity.gugu_device_commands c
    WHERE c.id IN (
        SELECT t.id
        FROM (
            SELECT gc.id,
                   row_number() OVER (
                       PARTITION BY COALESCE(gc.payload->>'agent_user_id', gc.id::text)
                       ORDER BY gc.created_at ASC, gc.id ASC
                   ) AS rn
            FROM identity.gugu_device_commands gc
            WHERE gc.device_id = p_device_id
              AND gc.status = 'pending'
        ) t
        WHERE t.rn <= GREATEST(p_per_agent, 1)
    )
    ORDER BY c.created_at ASC, c.id ASC;
$$;


--
-- Name: finalize_agent_team(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.finalize_agent_team(p_operation_id uuid) RETURNS chat.chats
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner         text := (SELECT auth.uid()::text);
    v_op            identity.agent_provision_operations;
    v_group         chat.chats;
    v_pending       int;
    v_group_chat_id text;
    v_name          text;
    v_prompt        text;
    v_member_ids    jsonb;
    r               record;
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    PERFORM identity.assert_provision_owner_live(v_owner);

    SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id;
    IF NOT FOUND OR v_op.owner_user_id <> v_owner THEN RAISE EXCEPTION 'operation % not found for caller', p_operation_id; END IF;
    IF v_op.kind <> 'team' THEN RAISE EXCEPTION 'finalize_agent_team requires a team operation (kind=%)', v_op.kind; END IF;
    IF v_op.phase IN ('cleaning_up','cancelling','cancelled') THEN
        RAISE EXCEPTION 'cannot finalize operation % in cancel phase (%)', p_operation_id, v_op.phase;
    END IF;
    IF v_op.group_chat_id IS NOT NULL THEN
        SELECT * INTO v_group FROM chat.chats WHERE id = v_op.group_chat_id;
        RETURN v_group;
    END IF;

    SELECT count(*) INTO v_pending FROM identity.agent_provisions
    WHERE operation_id = p_operation_id AND phase <> 'completed';
    IF v_pending > 0 THEN
        RAISE EXCEPTION 'cannot finalize operation %: % member(s) not completed', p_operation_id, v_pending;
    END IF;

    v_group_chat_id := v_op.blueprint->>'group_chat_id';
    v_name          := v_op.blueprint->>'team_name';
    v_prompt        := NULLIF(v_op.blueprint->>'group_prompt', '');

    PERFORM 1 FROM identity.users
     WHERE id = v_owner
        OR id IN (SELECT agent_user_id FROM identity.agent_provisions WHERE operation_id = p_operation_id AND agent_user_id IS NOT NULL)
     ORDER BY id FOR KEY SHARE;

    IF EXISTS (
        SELECT 1 FROM identity.agent_provisions p
        WHERE p.operation_id = p_operation_id
          AND (p.agent_user_id IS NULL
               OR NOT EXISTS (SELECT 1 FROM identity.users u
                              WHERE u.id = p.agent_user_id AND u.type = 'agent' AND u.owner_user_id = v_owner)
               OR EXISTS (SELECT 1 FROM identity.agent_lifecycle_tombstones t
                          WHERE t.agent_user_id = p.agent_user_id AND t.owner_user_id = v_owner))
    ) THEN
        RAISE EXCEPTION 'cannot finalize operation %: a member''s exact live agent is gone (removed / tombstoned / not owned) — refusing to build a missing-member group', p_operation_id;
    END IF;

    v_member_ids := (
        SELECT jsonb_agg(jsonb_build_object('user_id', p.agent_user_id, 'role', 'member') ORDER BY p.member_key)
        FROM identity.agent_provisions p
        WHERE p.operation_id = p_operation_id
    );
    v_group := chat.create_gugu_group(v_group_chat_id, v_name, v_owner, v_member_ids, NULL, v_prompt);

    FOR r IN
        SELECT p.agent_user_id AS agent_user_id, p.member_key AS member_key,
               (SELECT array_agg(bm->>'listen_mode') FROM jsonb_array_elements(v_op.blueprint->'members') bm
                WHERE bm->>'member_key' = p.member_key) AS listen_modes
        FROM identity.agent_provisions p WHERE p.operation_id = p_operation_id
    LOOP
        IF r.listen_modes IS NULL OR cardinality(r.listen_modes) <> 1 THEN
            RAISE EXCEPTION 'finalize: member % has % blueprint listen_mode entries (want exactly 1)', r.member_key, COALESCE(cardinality(r.listen_modes), 0);
        END IF;
        IF r.listen_modes[1] IS NULL OR r.listen_modes[1] NOT IN ('passive','active') THEN
            RAISE EXCEPTION 'finalize: member % has invalid listen_mode %', r.member_key, COALESCE(r.listen_modes[1], '<null>');
        END IF;
        UPDATE chat.chat_members SET listen_mode = r.listen_modes[1], updated_at = now()
        WHERE chat_id = v_group_chat_id AND user_id = r.agent_user_id;
    END LOOP;

    -- #5856 上面这个 LOOP 刚把建群时那轮自动调档覆盖回去了。这个群是本事务里现建的,
    -- 没有任何「用户的决定」要尊重 ⇒ 整条线按规矩再落一次,免得系统消息说一套、库里是另一套。
    PERFORM chat.enforce_agent_flood_passive(v_group_chat_id);

    SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id FOR UPDATE;
    IF v_op.group_chat_id IS NOT NULL THEN RETURN v_group; END IF;
    UPDATE identity.agent_provision_operations
    SET group_chat_id = v_group_chat_id, phase = 'completed', updated_at = now()
    WHERE id = p_operation_id;
    RETURN v_group;
END;
$$;


--
-- Name: finish_first_run(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.finish_first_run() RETURNS timestamp with time zone
    LANGUAGE sql
    SET search_path TO 'identity', 'pg_catalog'
    AS $$
  UPDATE identity.users
     SET onboarded_at = COALESCE(onboarded_at, now())
   WHERE id = (SELECT auth.uid()::text)
     AND type = 'human'
  RETURNING onboarded_at;
$$;


--
-- Name: get_agent_join_context(text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.get_agent_join_context(p_agent_user_id text, p_chat_id text) RETURNS TABLE(joined_at timestamp with time zone, skipped_before_join bigint, before_seq bigint, first_pull boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
DECLARE
    v_auth_uid       TEXT := auth.uid()::text;
    v_agent_type     TEXT;
    v_joined_at      TIMESTAMPTZ;
    v_last_read_seq  BIGINT;
    v_hide_history_before TIMESTAMPTZ;
    v_join_context_shown_at TIMESTAMPTZ;
    v_skipped        BIGINT;
    v_last_pre_seq   BIGINT;
    v_before_seq     BIGINT;
    v_next_seq       BIGINT;
BEGIN
    IF v_auth_uid IS NULL THEN
        RAISE EXCEPTION 'not authenticated';
    END IF;
    IF NOT (
        p_agent_user_id = v_auth_uid
        OR EXISTS (
            SELECT 1
            FROM identity.users u
            WHERE u.id = p_agent_user_id
              AND u.type = 'agent'
              AND u.owner_user_id = v_auth_uid
        )
    ) THEN
        RAISE EXCEPTION 'not authorized to read join context for %', p_agent_user_id;
    END IF;

    SELECT u.type INTO v_agent_type
    FROM identity.users u
    WHERE u.id = p_agent_user_id;
    IF v_agent_type IS DISTINCT FROM 'agent' THEN
        RETURN;
    END IF;

    SELECT cm.joined_at, cm.last_read_seq, cm.hide_history_before, cm.join_context_shown_at, c.next_message_seq
      INTO v_joined_at, v_last_read_seq, v_hide_history_before, v_join_context_shown_at, v_next_seq
      FROM chat.chat_members cm
      JOIN chat.chats c ON c.id = cm.chat_id
     WHERE cm.chat_id = p_chat_id
       AND cm.user_id = p_agent_user_id
     FOR UPDATE OF cm;
    IF NOT FOUND OR COALESCE(v_last_read_seq, 0) <> 0 OR v_join_context_shown_at IS NOT NULL THEN
        RETURN;
    END IF;

    -- Match the reader's visibility: hidden history and whispers that do not address this
    -- agent are not claimed as recoverable context.
    SELECT COUNT(*)::BIGINT, MAX(m.seq)
      INTO v_skipped, v_last_pre_seq
      FROM chat.messages m
     WHERE m.chat_id = p_chat_id
       AND m.deleted_at IS NULL
       AND m.sender_user_id <> p_agent_user_id
       AND m.created_at < v_joined_at
       AND (v_hide_history_before IS NULL OR m.created_at >= v_hide_history_before)
       AND chat.whisper_visible_to(m.is_whisper, m.sender_user_id, m.to_user_ids, p_agent_user_id);
    IF COALESCE(v_skipped, 0) = 0 THEN
        UPDATE chat.chat_members
           SET join_context_shown_at = now()
         WHERE chat_id = p_chat_id AND user_id = p_agent_user_id;
        RETURN;
    END IF;

    v_before_seq := COALESCE(v_last_pre_seq + 1, v_next_seq, 1);
    UPDATE chat.chat_members
       SET join_context_shown_at = now()
     WHERE chat_id = p_chat_id AND user_id = p_agent_user_id;
    RETURN QUERY SELECT v_joined_at, v_skipped, v_before_seq, TRUE;
END;
$$;


--
-- Name: get_agent_presence(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.get_agent_presence(p_agent_user_id text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NOT identity.can_view_agent_runtime_state(p_agent_user_id) THEN
        RAISE EXCEPTION 'Agent presence is not viewable by current user';
    END IF;
    RETURN identity.build_agent_presence_payload(p_agent_user_id);
END;
$$;


--
-- Name: get_agent_presence_batch(text[]); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.get_agent_presence_batch(p_agent_user_ids text[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    -- 上限存在的理由不是性能，是让「问得太多」变成一个能被看见的错误而不是一份残缺的答案。
    v_max CONSTANT INT := 200;
    v_ids TEXT[];
    v_count INT;
    v_id TEXT;
    v_results JSONB := '{}'::jsonb;
    v_payload JSONB;
BEGIN
    IF p_agent_user_ids IS NULL THEN
        RAISE EXCEPTION 'get_agent_presence_batch: p_agent_user_ids must not be NULL';
    END IF;

    -- 先去重再判上限：调用方重复传同一个 id 不该把它推过闸，也不该让同一个 id 被查两遍。
    SELECT COALESCE(array_agg(DISTINCT x), ARRAY[]::TEXT[])
      INTO v_ids
      FROM unnest(p_agent_user_ids) AS x
     WHERE x IS NOT NULL AND x <> '';

    v_count := COALESCE(array_length(v_ids, 1), 0);
    IF v_count > v_max THEN
        -- fail loud：❌ 不静默截断。截断会返回一份看起来完整的答案，而调用方无从知道
        -- 哪些 id 从来没被问过 —— 那比报错难查得多。
        RAISE EXCEPTION
            'get_agent_presence_batch: % distinct ids exceeds the cap of %; split the request',
            v_count, v_max;
    END IF;

    FOREACH v_id IN ARRAY v_ids LOOP
        IF NOT identity.can_view_agent_runtime_state(v_id) THEN
            v_results := v_results || jsonb_build_object(v_id, jsonb_build_object('status', 'unauthorized'));
        ELSE
            v_payload := identity.build_agent_presence_payload(v_id);
            IF v_payload IS NULL THEN
                v_results := v_results || jsonb_build_object(v_id, jsonb_build_object('status', 'not_found'));
            ELSE
                v_results := v_results || jsonb_build_object(
                    v_id,
                    jsonb_build_object('status', 'presence', 'presence', v_payload -> 'presence')
                );
            END IF;
        END IF;
    END LOOP;

    -- 包一层 results 而不是裸对象：将来要加批次级元信息（例如服务端时钟）时不必改客户端解析形状。
    RETURN jsonb_build_object('results', v_results);
END;
$$;


--
-- Name: get_public_agent_join(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.get_public_agent_join(p_agent_id text) RETURNS TABLE(id text, display_name text, avatar text, bio text, category text, owner_display_name text, owner_avatar text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT
        u.id,
        COALESCE(ap.display_name, u.display_name) AS display_name,
        COALESCE(ap.avatar, u.avatar)             AS avatar,
        u.bio,
        u.category,
        owner.display_name                        AS owner_display_name,
        owner.avatar                              AS owner_avatar
    FROM identity.users u
    LEFT JOIN identity.agent_profiles ap ON ap.id::text = u.id
    LEFT JOIN identity.users owner       ON owner.id = u.owner_user_id
    WHERE u.id = p_agent_id
      AND u.type = 'agent'
      AND u.agent_public = true;
$$;


--
-- Name: get_thread_messages(text, text, integer); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.get_thread_messages(p_chat_id text, p_thread_root_id text, p_limit integer DEFAULT 40) RETURNS TABLE(sender_user_id text, content text, created_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
    SELECT t.sender_user_id, t.content, t.created_at
    FROM (
        SELECT m.sender_user_id, m.content, m.created_at, m.seq
        FROM chat.messages m
        WHERE m.chat_id = p_chat_id
          AND (m.id = p_thread_root_id OR m.thread_root_id = p_thread_root_id)
          AND m.content_type <> 'system'
          AND m.content IS NOT NULL
          AND m.deleted_at IS NULL
          AND m.retracted_at IS NULL
          AND (
            coalesce((SELECT auth.jwt() ->> 'role'), '') = 'service_role'
            OR EXISTS (
              SELECT 1 FROM chat.chat_members me
              WHERE me.chat_id = p_chat_id AND me.user_id = (SELECT auth.uid()::text)
            )
          )
        ORDER BY m.seq DESC
        LIMIT GREATEST(p_limit, 1)
    ) t
    ORDER BY t.seq ASC;
$$;


--
-- Name: gugu_device_commands_broadcast(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_device_commands_broadcast() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.status = 'pending' THEN
        PERFORM realtime.send(
            jsonb_build_object(
                'id', NEW.id,
                'type', NEW.type,
                'status', NEW.status
            ),
            'command_created',
            'gugu:' || NEW.device_id || ':commands',
            true
        );
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: gugu_device_removal_blocks(text, uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_device_removal_blocks(p_device_id text, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_removed_at TIMESTAMPTZ;
    v_session_created TIMESTAMPTZ;
BEGIN
    SELECT removed_at INTO v_removed_at
      FROM identity.gugu_device_removals
     WHERE device_id = p_device_id
       AND user_id = p_user_id;
    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;
    -- 只替「自己」判:别人的行 RLS 本就写不进来,这里再兜一层,绝不替别人清那一笔。
    IF p_user_id IS DISTINCT FROM auth.uid() THEN
        RETURN TRUE;
    END IF;
    SELECT s.created_at INTO v_session_created
      FROM auth.sessions s
     WHERE s.id = identity.current_jwt_session_id()
       AND s.user_id = p_user_id;
    IF v_session_created IS NOT NULL AND v_session_created > v_removed_at THEN
        DELETE FROM identity.gugu_device_removals
         WHERE device_id = p_device_id
           AND user_id = p_user_id;
        RETURN FALSE;
    END IF;
    RETURN TRUE;
END;
$$;


--
-- Name: gugu_devices_default_label(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_devices_default_label() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_plat text := lower(coalesce(NEW.platform, ''));
    v_base text;
    v_serial int;
BEGIN
    -- rename 走 rename_device（带 label_customized_at），不经自动命名。
    IF NEW.label_customized_at IS NOT NULL THEN
        RETURN NEW;
    END IF;
    -- 心跳 upsert 的 insert-attempt：该 device_id 已存在 → 不重算，label 交给 BEFORE UPDATE preserve。
    IF EXISTS (SELECT 1 FROM identity.gugu_devices WHERE device_id = NEW.device_id) THEN
        RETURN NEW;
    END IF;
    -- #1984：客户端已提供有意义 label → 优先保留，不派生（逆转 #1760 的一律派生）。派生名仅在无 label 时兜底。
    IF NEW.label IS NOT NULL AND btrim(NEW.label) <> '' THEN
        RETURN NEW;
    END IF;

    -- 兜底：客户端未给 label（罕见）→ 按 owner 同平台设备数派生不撞号的友好默认名（原 #1760 逻辑）。
    v_base := CASE
        WHEN v_plat IN ('mac', 'darwin') THEN 'Mac'
        WHEN v_plat = 'linux' THEN 'Linux'
        WHEN v_plat IN ('win', 'win32', 'windows') THEN 'Windows'
        WHEN v_plat = '' THEN 'Device'
        ELSE upper(left(v_plat, 1)) || substr(v_plat, 2)
    END;

    SELECT count(*) INTO v_serial
      FROM identity.gugu_devices
     WHERE user_id = NEW.user_id
       AND (label = v_base OR label LIKE v_base || ' %');
    v_serial := v_serial + 1;
    WHILE EXISTS (
        SELECT 1 FROM identity.gugu_devices
         WHERE user_id = NEW.user_id AND label = v_base || ' ' || v_serial
    ) LOOP
        v_serial := v_serial + 1;
    END LOOP;

    NEW.label := v_base || ' ' || v_serial;
    RETURN NEW;
END;
$$;


--
-- Name: gugu_devices_enforce_machine_limit(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_devices_enforce_machine_limit() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_refusal JSONB;
BEGIN
  IF pg_has_role(current_user, 'service_role', 'MEMBER') THEN
    RETURN NEW;
  END IF;
  IF COALESCE(NEW.capabilities ->> 'host_kind', '') <> 'server' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.capabilities ->> 'host_kind' = 'server' THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND EXISTS (SELECT 1 FROM identity.gugu_devices d WHERE d.device_id = NEW.device_id) THEN
    RETURN NEW;
  END IF;
  -- 同一个账号并发加两台:串行判,❌ 两边都看见「还差一台」一起放进来。
  PERFORM pg_advisory_xact_lock(hashtextextended('gugu-machine-limit:' || NEW.user_id::text, 0));
  v_refusal := identity.gugu_machine_limit_refusal(NEW.user_id, COALESCE(NEW.machine_id, NEW.device_id), NULL);
  IF v_refusal IS NOT NULL THEN
    RAISE EXCEPTION 'DEVICE_LIMIT_REACHED: %', v_refusal::text USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: gugu_devices_preserve_custom_label(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_devices_preserve_custom_label() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- 只有 rename_device 会 bump label_customized_at；其余 update（心跳等）保留旧 label。
    IF NEW.label_customized_at IS NOT DISTINCT FROM OLD.label_customized_at THEN
        NEW.label := OLD.label;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: gugu_devices_refuse_removed(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_devices_refuse_removed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF pg_has_role(current_user, 'service_role', 'MEMBER') THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'INSERT' OR NEW.last_seen_at IS DISTINCT FROM OLD.last_seen_at THEN
        IF identity.gugu_device_removal_blocks(NEW.device_id, NEW.user_id) THEN
            RAISE EXCEPTION 'DEVICE_REMOVED: this machine was removed from the account; sign in again on it to use it'
                USING ERRCODE = 'P0001';
        END IF;
        NEW.auth_session_id := identity.current_jwt_session_id();
    ELSE
        NEW.auth_session_id := OLD.auth_session_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: gugu_devices_stamp_lease(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_devices_stamp_lease() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF pg_has_role(current_user, 'service_role', 'MEMBER') THEN
        RETURN NEW;   -- 受信角色:运维 / 云端 RPC / 夹具,它们不是那台设备
    END IF;
    IF TG_OP = 'INSERT' OR NEW.last_seen_at IS DISTINCT FROM OLD.last_seen_at THEN
        NEW.last_seen_at := now();
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: gugu_machine_limit_refusal(uuid, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.gugu_machine_limit_refusal(p_user_id uuid, p_machine_id text, p_via text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_caller     UUID := auth.uid();
  v_plan_id    TEXT;
  v_max        INTEGER;
  v_max_tunnel INTEGER;
  v_via        TEXT;
  v_listed     BOOLEAN;
  v_listed_via TEXT;
  v_others     INTEGER;
  v_others_tun INTEGER;
BEGIN
  -- 客户端(心跳触发器)只能替自己判;service_role 没有 auth.uid(),可以替任何人判。
  IF v_caller IS NOT NULL AND v_caller IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'gugu_machine_limit_refusal: can only check the caller''s own machines';
  END IF;
  IF p_user_id IS NULL OR NULLIF(p_machine_id, '') IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT max_machines, max_tunnel_machines, plan_id
    INTO v_max, v_max_tunnel, v_plan_id
    FROM identity.machine_limits_for(p_user_id);

  v_via := COALESCE(
    p_via,
    (SELECT e.via FROM identity.gugu_server_enrollments e WHERE e.user_id = p_user_id AND e.machine_id = p_machine_id),
    'tunnel'
  );

  WITH machines AS (
    SELECT DISTINCT ON (COALESCE(d.machine_id, d.device_id))
           COALESCE(d.machine_id, d.device_id) AS machine_key,
           COALESCE(e.via, 'tunnel') AS via
      FROM identity.gugu_devices d
      LEFT JOIN identity.gugu_server_enrollments e
        ON e.user_id = d.user_id AND e.machine_id = d.machine_id
     WHERE d.user_id = p_user_id
       AND d.capabilities ->> 'host_kind' = 'server'
     ORDER BY COALESCE(d.machine_id, d.device_id), (COALESCE(e.via, 'tunnel') = 'tunnel')
  )
  SELECT bool_or(m.machine_key = p_machine_id),
         max(m.via) FILTER (WHERE m.machine_key = p_machine_id),
         count(*) FILTER (WHERE m.machine_key <> p_machine_id),
         count(*) FILTER (WHERE m.machine_key <> p_machine_id AND m.via = 'tunnel')
    INTO v_listed, v_listed_via, v_others, v_others_tun
    FROM machines m;
  v_listed := COALESCE(v_listed, FALSE);

  -- 新机器才会让总数变大。
  IF NOT v_listed AND v_others + 1 > v_max THEN
    RETURN jsonb_build_object('limit', 'total', 'used', v_others, 'max', v_max, 'plan', v_plan_id);
  END IF;
  -- 远程隧道数只在「这台原来不算隧道、这次要算」时变大。
  IF v_via = 'tunnel'
     AND NOT (v_listed AND v_listed_via = 'tunnel')
     AND v_others_tun + 1 > v_max_tunnel THEN
    RETURN jsonb_build_object('limit', 'tunnel', 'used', v_others_tun, 'max', v_max_tunnel, 'plan', v_plan_id);
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: handle_deleted_auth_user(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.handle_deleted_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    PERFORM identity.erase_human_account(OLD.id::text);
    RETURN OLD;
END;
$$;


--
-- Name: handle_new_auth_user(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.handle_new_auth_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_display_name TEXT;
    v_avatar TEXT;
    v_constraint_name TEXT;
BEGIN
    v_display_name := COALESCE(
        NULLIF(NEW.raw_user_meta_data->>'display_name', ''),
        NULLIF(NEW.raw_user_meta_data->>'nickname', ''),
        NULLIF(split_part(NEW.email, '@', 1), ''),
        'User'
    );

    v_avatar := NULLIF(btrim(NEW.raw_user_meta_data->>'avatar_url'), '');
    IF NOT identity.is_valid_avatar_url(v_avatar) THEN
        v_avatar := NULL;
    END IF;

    IF NEW.email IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM identity.users AS existing
           WHERE lower(existing.email) = lower(NEW.email)
             AND existing.id <> NEW.id::text
       ) THEN
        RAISE EXCEPTION USING
            ERRCODE = '23505',
            MESSAGE = 'registration identity email conflicts with an existing identity record';
    END IF;

    BEGIN
        INSERT INTO identity.users (id, type, display_name, avatar, email, created_at, updated_at)
        VALUES (
            NEW.id::text,
            'human',
            v_display_name,
            v_avatar,
            NEW.email,
            now(),
            now()
        )
        ON CONFLICT (id) DO UPDATE SET
            email        = EXCLUDED.email,
            display_name = COALESCE(NULLIF(identity.users.display_name, ''), EXCLUDED.display_name),
            avatar       = CASE
                WHEN identity.is_valid_avatar_url(identity.users.avatar) THEN identity.users.avatar
                ELSE EXCLUDED.avatar
            END,
            updated_at   = now();
    EXCEPTION
        WHEN unique_violation THEN
            GET STACKED DIAGNOSTICS v_constraint_name = CONSTRAINT_NAME;
            IF v_constraint_name IN ('users_email_key', 'users_email_normalized_key') THEN
                RAISE EXCEPTION USING
                    ERRCODE = '23505',
                    MESSAGE = 'registration identity email conflicts with an existing identity record';
            END IF;
            RAISE;
    END;

    RETURN NEW;
END;
$$;


--
-- Name: import_agent_provision_history(uuid, jsonb); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.import_agent_provision_history(p_provision_id uuid, p_payload jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner TEXT := (SELECT auth.uid()::text);
    v_p     identity.agent_provisions;
    v_hash  TEXT;
    v_root  TEXT;
    v_title TEXT;
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN RAISE EXCEPTION 'history payload must be a jsonb object'; END IF;
    IF jsonb_typeof(p_payload->'turns') <> 'array' THEN RAISE EXCEPTION 'history payload.turns must be a jsonb array'; END IF;
    PERFORM identity.assert_provision_owner_live(v_owner);   -- owner auth-row -> advisory (fence) FIRST

    -- Unlocked locate, then lock in global order identity -> chat -> operation/member (last).
    SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id;
    IF NOT FOUND OR v_p.owner_user_id <> v_owner THEN RAISE EXCEPTION 'provision % not found for caller', p_provision_id; END IF;
    IF NOT v_p.history_import_required THEN RAISE EXCEPTION 'provision % did not declare history_import_required', p_provision_id; END IF;
    IF v_p.agent_user_id IS NULL OR v_p.dm_chat_id IS NULL THEN
        RAISE EXCEPTION 'provision % is not prepared (no agent/DM for history import)', p_provision_id;
    END IF;

    PERFORM 1 FROM identity.users WHERE id IN (v_owner, v_p.agent_user_id) ORDER BY id FOR KEY SHARE; -- identity lock (order 1: identity BEFORE chat, F5)
    PERFORM 1 FROM chat.chats WHERE id = v_p.dm_chat_id FOR UPDATE;                                   -- chat lock (order 2)
    SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id FOR UPDATE;            -- operation/member last
    IF v_p.owner_user_id <> v_owner THEN RAISE EXCEPTION 'provision % not owned by caller', p_provision_id; END IF;

    v_hash := md5(p_payload::text);   -- DB-derived; the client never supplies a history hash.

    -- Idempotent replay: an existing marker must match this payload's hash; return the stored root, no re-insert.
    IF v_p.history_thread_root_id IS NOT NULL THEN
        IF v_p.history_payload_hash IS DISTINCT FROM v_hash THEN
            RAISE EXCEPTION 'provision % history replay with a divergent payload (hash mismatch)', p_provision_id;
        END IF;
        RETURN v_p.history_thread_root_id;
    END IF;

    -- First import: run the existing importer in THIS txn, then atomically store hash + root (all-or-zero).
    v_title := COALESCE(NULLIF(p_payload->>'title',''), 'imported session');
    -- Call the 4-arg NO-ARCHIVE overload (20260718143000): root = provenance title, each turn once. The legacy
    -- 7-arg overload rejects a NULL archive; source/session_id are intentionally hash-only metadata (they live in
    -- p_payload → the DB-derived history_payload_hash below) and are NOT part of the imported-thread projection.
    v_root := chat.import_agent_session_history( v_p.agent_user_id, v_p.dm_chat_id, v_title, p_payload->'turns' );
    IF v_root IS NULL OR v_root = '' THEN RAISE EXCEPTION 'history import returned no thread root for provision %', p_provision_id; END IF;
    UPDATE identity.agent_provisions
    SET history_payload_hash = v_hash, history_thread_root_id = v_root, updated_at = now()
    WHERE id = p_provision_id;
    RETURN v_root;
END;
$$;


--
-- Name: gugu_decision_events; Type: TABLE; Schema: chat; Owner: -
--

CREATE TABLE chat.gugu_decision_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    chat_id text NOT NULL,
    event_type text NOT NULL,
    task_ids text[],
    round integer DEFAULT 1 NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    user_task_decisions jsonb DEFAULT '{}'::jsonb NOT NULL,
    user_resource_states jsonb DEFAULT '{}'::jsonb NOT NULL,
    user_rationales jsonb DEFAULT '{}'::jsonb NOT NULL,
    final_decision text,
    final_resource_states jsonb,
    rationale text,
    created_by_user_id text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    settled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT gugu_decision_events_event_type_check CHECK ((event_type = ANY (ARRAY['task_proposed_decision'::text, 'task_submitted_decision'::text, 'group_stop'::text]))),
    CONSTRAINT gugu_decision_events_final_decision_check CHECK ((final_decision = ANY (ARRAY['approved'::text, 'rejected'::text, 'cancelled'::text]))),
    CONSTRAINT gugu_decision_events_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'settled'::text, 'cancelled'::text])))
);


--
-- Name: is_trusted_decision_erasure_update(chat.gugu_decision_events, chat.gugu_decision_events); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.is_trusted_decision_erasure_update(old_row chat.gugu_decision_events, new_row chat.gugu_decision_events) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    allowed_user_ids TEXT[];
BEGIN
    SELECT c.delete_user_ids INTO allowed_user_ids
    FROM identity.account_lifecycle_context c
    WHERE c.transaction_id = pg_current_xact_id()
      AND c.operation = 'privacy_erasure'
      AND c.subject_user_id = c.delete_user_ids[1];

    IF allowed_user_ids IS NULL AND session_user = 'postgres' THEN
        SELECT array_agg(DISTINCT orphan_id ORDER BY orphan_id)
        INTO allowed_user_ids
        FROM (
            SELECT ballot.key AS orphan_id
            FROM (
                SELECT jsonb_object_keys(old_row.user_task_decisions) AS key
                UNION SELECT jsonb_object_keys(old_row.user_resource_states)
                UNION SELECT jsonb_object_keys(old_row.user_rationales)
            ) ballot
            WHERE NOT EXISTS (SELECT 1 FROM identity.users u WHERE u.id = ballot.key)
            UNION
            SELECT old_row.created_by_user_id
            WHERE old_row.created_by_user_id IS NOT NULL
              AND NOT EXISTS (
                  SELECT 1 FROM identity.users u WHERE u.id = old_row.created_by_user_id
              )
        ) orphan_ids;
    END IF;

    IF allowed_user_ids IS NULL OR cardinality(allowed_user_ids) = 0 THEN
        RETURN false;
    END IF;

    RETURN (to_jsonb(new_row) - ARRAY[
                'user_task_decisions', 'user_resource_states', 'user_rationales',
                'created_by_user_id', 'updated_at'
            ]) =
           (to_jsonb(old_row) - ARRAY[
                'user_task_decisions', 'user_resource_states', 'user_rationales',
                'created_by_user_id', 'updated_at'
            ])
       AND new_row.user_task_decisions = old_row.user_task_decisions - allowed_user_ids
       AND new_row.user_resource_states = old_row.user_resource_states - allowed_user_ids
       AND new_row.user_rationales = old_row.user_rationales - allowed_user_ids
       AND new_row.created_by_user_id IS NOT DISTINCT FROM
           CASE
               WHEN old_row.created_by_user_id = ANY(allowed_user_ids) THEN NULL
               ELSE old_row.created_by_user_id
           END;
END;
$$;


--
-- Name: mark_read_on_deliver(text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.mark_read_on_deliver(p_chat_id text, p_message_id text, p_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'chat', 'public'
    AS $$
DECLARE
    v_seq     BIGINT;
    v_current BIGINT;
BEGIN
    -- Same act-as authorization the message-send / mark_read paths use: the caller is the actor or
    -- owns the actor (agents run on the owner's token).
    IF NOT chat.can_act_as(p_user_id, p_chat_id) THEN
        RAISE EXCEPTION 'not authorized to mark read for % in chat %', p_user_id, p_chat_id;
    END IF;

    SELECT seq INTO v_seq
      FROM chat.messages
     WHERE id = p_message_id AND chat_id = p_chat_id AND deleted_at IS NULL;
    IF NOT FOUND THEN
        RETURN;  -- message gone / not in this chat
    END IF;

    -- Receipt broadcasts take account revision locks. Match the member -> revision
    -- order used by mark_read / membership updates before publishing this receipt.
    -- NO KEY UPDATE preserves membership foreign-key readers and the existing
    -- missing-member path; the precise receipt and gap check below are unchanged.
    PERFORM 1 FROM chat.chat_members
     WHERE chat_id = p_chat_id AND user_id = p_user_id
     FOR NO KEY UPDATE;

    -- @@@1529B 逐条精确读（与水位解耦，#598）：无论下方水位能否前进，都记录「本 agent 读了这一条」。
    -- 否则群里第二条起前面有他人未读时水位卡住 → 该消息已读无处记录 → 发送方永远看未读。
    INSERT INTO chat.message_deliveries (
        message_id,
        device_id,
        status,
        delivered_at,
        read_at
    )
    VALUES (
        p_message_id,
        'gugu-agent:' || p_user_id,
        'read',
        now(),
        now()
    )
    ON CONFLICT (message_id, device_id) DO UPDATE SET
        status = 'read',
        delivered_at = COALESCE(chat.message_deliveries.delivered_at, EXCLUDED.delivered_at),
        read_at = COALESCE(chat.message_deliveries.read_at, EXCLUDED.read_at),
        updated_at = now();

    SELECT last_read_seq INTO v_current
      FROM chat.chat_members
     WHERE chat_id = p_chat_id AND user_id = p_user_id;
    IF NOT FOUND THEN
        RETURN;  -- not a member of this chat
    END IF;

    -- Leave the watermark alone if any earlier message from someone else is still unread.
    -- (逐条精确读上面已写，不受此 gate 影响——这里只 gate 水位前进。)
    IF EXISTS (
        SELECT 1
          FROM chat.messages m
         WHERE m.chat_id = p_chat_id
           AND m.sender_user_id <> p_user_id
           AND m.deleted_at IS NULL
           AND m.seq > v_current
           AND m.seq < v_seq
    ) THEN
        RETURN;
    END IF;

    UPDATE chat.chat_members
       SET last_read_seq = GREATEST(last_read_seq, v_seq),
           version       = version + 1,
           updated_at    = now()
     WHERE chat_id = p_chat_id AND user_id = p_user_id;
END;
$$;


--
-- Name: my_recent_machine_limit_refusal(timestamp with time zone); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.my_recent_machine_limit_refusal(p_since timestamp with time zone) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
  SELECT r.refusal || jsonb_build_object('hostname', r.machine ->> 'hostname', 'refused_at', r.refused_at)
    FROM identity.server_login_requests r
   WHERE auth.uid() IS NOT NULL
     AND r.refused_user_id = auth.uid()::text
     AND r.refused_at >= p_since
   ORDER BY r.refused_at DESC
   LIMIT 1;
$$;


--
-- Name: prepare_agent_provision(uuid, uuid, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.prepare_agent_provision(p_provision_id uuid, p_operation_id uuid, p_member_key text, p_device_id text, p_display_name text, p_agent_type text, p_project_path text, p_avatar text, p_special_focus text, p_initial_message_id text, p_initial_message_text text) RETURNS identity.agent_provisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_owner      TEXT := (SELECT auth.uid()::text);
  v_p          identity.agent_provisions;
  v_agent      identity.users;
  v_dm         TEXT;
  v_cmd_id     UUID;
  v_old_status TEXT;
  v_hash       TEXT;
BEGIN
  SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id;
  IF NOT FOUND OR v_p.existing_agent_user_id IS NULL THEN
    RETURN identity.prepare_agent_provision_pre_adopt_7199(
      p_provision_id, p_operation_id, p_member_key, p_device_id, p_display_name,
      p_agent_type, p_project_path, p_avatar, p_special_focus,
      p_initial_message_id, p_initial_message_text
    );
  END IF;

  -- ── 收养:复用原有的身份与私聊,不铸新的 ──
  IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
  PERFORM identity.assert_provision_owner_live(v_owner);
  IF v_p.owner_user_id <> v_owner THEN RAISE EXCEPTION 'provision % not owned by caller', p_provision_id; END IF;
  IF NOT EXISTS (SELECT 1 FROM identity.gugu_devices WHERE device_id = p_device_id AND user_id::text = v_owner) THEN
    RAISE EXCEPTION 'device % is not owned by current user', p_device_id;
  END IF;
  IF NULLIF(btrim(p_member_key), '') IS NULL THEN RAISE EXCEPTION 'prepare: member_key is required'; END IF;
  IF p_initial_message_id IS NOT NULL OR p_initial_message_text IS NOT NULL THEN
    RAISE EXCEPTION 'adopt: an existing agent takes no initial message';
  END IF;

  -- 锁序同 legacy:identity(主人 + 这个 agent,id 有序,FOR KEY SHARE)→ 成员行最后。
  PERFORM 1 FROM identity.users WHERE id IN (v_owner, v_p.existing_agent_user_id) ORDER BY id FOR KEY SHARE;
  SELECT * INTO v_agent FROM identity.users
   WHERE id = v_p.existing_agent_user_id AND type = 'agent' AND owner_user_id = v_owner;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'adopt: agent % is no longer live or not owned by the caller', v_p.existing_agent_user_id;
  END IF;
  SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id FOR UPDATE;
  IF NOT FOUND OR v_p.owner_user_id <> v_owner THEN
    RAISE EXCEPTION 'provision % not found for caller (changed while acquiring locks)', p_provision_id;
  END IF;

  v_hash := identity.provision_member_hash(p_operation_id, p_member_key, p_display_name, p_agent_type,
    p_project_path, p_avatar, p_special_focus, p_device_id,
    v_p.inherit_memory, v_p.history_import_required, v_p.memory_sources, v_p.memory_content_hash);
  IF v_p.payload_hash <> v_hash OR v_p.operation_id <> p_operation_id OR v_p.member_key <> p_member_key THEN
    RAISE EXCEPTION 'provision % divergent member params (server-derived hash mismatch)', p_provision_id;
  END IF;

  -- 幂等重放:已推进的成员原样返回。
  IF v_p.agent_user_id IS NOT NULL AND v_p.phase IN ('awaiting_terminal', 'ready', 'completed') THEN
    RETURN v_p;
  END IF;
  IF v_p.phase <> 'preparing' THEN
    RAISE EXCEPTION 'prepare: provision % is not a slot-granted preparing row (phase=%); claim_provision_slots must grant capacity first', p_provision_id, v_p.phase;
  END IF;
  IF v_agent.device_id IS NOT DISTINCT FROM v_p.device_id THEN
    RAISE EXCEPTION 'adopt: agent % already lives on device %', v_agent.id, v_p.device_id;
  END IF;
  -- 重试:上一条 agent.create 必须是 error 才能再发(与 legacy 同一条)。
  IF v_p.create_command_id IS NOT NULL THEN
    SELECT status INTO v_old_status FROM identity.gugu_device_commands WHERE id = v_p.create_command_id;
    IF v_old_status IS DISTINCT FROM 'error' THEN
      RAISE EXCEPTION 'refusing retry: provision % prior command not in error (status=%)', p_provision_id, COALESCE(v_old_status, '<absent>');
    END IF;
  END IF;

  v_dm := COALESCE(v_p.dm_chat_id, chat.get_or_create_dm(v_agent.id));
  INSERT INTO identity.gugu_device_commands (user_id, device_id, type, payload)
  VALUES (
    v_owner::uuid, v_p.device_id, 'agent.create',
    jsonb_build_object(
      'agent_user_id', v_agent.id,
      'display_name', v_agent.display_name,
      'agent_type', v_p.agent_type,
      'project_path', COALESCE(v_p.project_path, ''),
      'avatar', v_agent.avatar,
      'greeting_chat_id', v_dm,
      'adopt', true,
      'adopt_from_device_id', v_agent.device_id
    ) || jsonb_strip_nulls(jsonb_build_object(
      'model', v_p.model,
      'effort', v_p.effort,
      'permission_mode', v_p.permission_mode,
      'child_harness', v_p.child_harness
    ))
  ) RETURNING id INTO v_cmd_id;

  UPDATE identity.agent_provisions
     SET agent_user_id = v_agent.id,
         dm_chat_id = v_dm,
         create_command_id = v_cmd_id,
         provisioned_agent_user_id = COALESCE(provisioned_agent_user_id, v_agent.id::uuid),
         phase = 'awaiting_terminal', error = NULL, updated_at = now()
   WHERE id = p_provision_id RETURNING * INTO v_p;
  RETURN v_p;
END;
$$;


--
-- Name: prepare_agent_provision_legacy_7199(uuid, uuid, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.prepare_agent_provision_legacy_7199(p_provision_id uuid, p_operation_id uuid, p_member_key text, p_device_id text, p_display_name text, p_agent_type text, p_project_path text, p_avatar text, p_special_focus text, p_initial_message_id text, p_initial_message_text text) RETURNS identity.agent_provisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  -- 原 _legacy_4567(备好成员:身份 + 私聊 + agent.create)
    v_owner   TEXT := (SELECT auth.uid()::text);
    v_p       identity.agent_provisions;
    v_agent   RECORD;
    v_dm_chat TEXT;
    v_cmd_id  UUID;
    v_hash    TEXT;
    v_mkey    TEXT := p_member_key;   -- P2-2: NO COALESCE-to-'single'; an empty member_key is rejected below
    v_old_cmd_status TEXT;
    v_mem     JSONB;
    -- round-4: the UNLOCKED snapshot's authoritative fields — every one of them is re-validated after the member
    -- lock, so a concurrent governed removal / ownership change / phase move during the lock wait fails loud.
    v_snap_agent TEXT;
    v_snap_prov  UUID;
    v_snap_phase TEXT;
    v_snap_hash  TEXT;
    v_snap_op    UUID;
    v_snap_dm    TEXT;
  -- 原 _legacy_6264(首条消息)
  v_chat_kind TEXT;
  v_public_id BIGINT;
  v_inserted_message_id TEXT;
BEGIN
  -- ── 备好成员(原 _legacy_4567)。原来的三处 RETURN 换成 EXIT core:后面两步照样要跑 ──
  <<core>>
  BEGIN
      IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
      PERFORM identity.assert_provision_owner_live(v_owner);
      IF NOT EXISTS (SELECT 1 FROM identity.gugu_devices WHERE device_id = p_device_id AND user_id::text = v_owner) THEN
          RAISE EXCEPTION 'device % is not owned by current user', p_device_id;
      END IF;

      IF NULLIF(btrim(p_member_key), '') IS NULL THEN
          RAISE EXCEPTION 'prepare: member_key is required (P2-2: empty is never defaulted to ''single'')';
      END IF;

      -- P1-a global lock order (identity → chat → command → member LAST): UNLOCKED snapshot to read the bound
      -- agent id / phase / params (pick lock targets + branch), THEN lock the AGENT identity (FOR KEY SHARE) BEFORE
      -- the member row — matching remove_owned_agent's identity-first order, so prepare and an ordinary removal
      -- never acquire {member row, agent identity/runtime} in opposite directions (no AB-BA / 40P01). The row MUST
      -- already exist (start created every member); prepare only VALIDATES + ADVANCES it, never creates a provision.
      SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id;   -- unlocked snapshot (no lock yet)
      IF NOT FOUND THEN
          RAISE EXCEPTION 'provision % not found — every provision must be created by start_agent_provision_operation', p_provision_id;
      END IF;
      IF v_p.owner_user_id <> v_owner THEN RAISE EXCEPTION 'provision % not owned by caller', p_provision_id; END IF;
      -- capture the FULL authoritative snapshot (both binding columns + operation/phase/hash), not just the agent id.
      v_snap_agent := v_p.agent_user_id;
      v_snap_prov  := v_p.provisioned_agent_user_id;
      v_snap_phase := v_p.phase;
      v_snap_hash  := v_p.payload_hash;
      v_snap_op    := v_p.operation_id;
      v_snap_dm    := v_p.dm_chat_id;

      -- identity domain FIRST (global order), then the EXACT-IDENTITY GATE. When the snapshot has a bound agent we
      -- lock {owner, that exact agent} id-ordered FOR KEY SHARE and then re-verify THAT SAME identity is still live
      -- (id = snapshot agent AND type='agent' AND owned by this caller). A concurrent governed remove_owned_agent that
      -- commits while we waited on this lock makes the verification MISS — and we fail loud HERE, before any member
      -- lock, so a reclaimed member can NEVER fall through into first-create and mint a DIFFERENT agent (the round-3
      -- Lane-2 blocker: identity reanimation after governed removal + corrupted cancellation evidence).
      IF v_snap_agent IS NOT NULL THEN
          PERFORM 1 FROM identity.users WHERE id IN (v_owner, v_snap_agent) ORDER BY id FOR KEY SHARE;
          SELECT * INTO v_agent FROM identity.users
           WHERE id = v_snap_agent AND type = 'agent' AND owner_user_id = v_owner;
          IF NOT FOUND THEN
              RAISE EXCEPTION 'prepare: provision % bound agent % is no longer live/owned (governed removal or ownership change) — refusing to re-provision; this member is cancel/settle-only', p_provision_id, v_snap_agent;
          END IF;
      ELSE
          PERFORM 1 FROM identity.users WHERE id = v_owner FOR KEY SHARE;
      END IF;

      -- #6049: the 11-argument wrapper acknowledges its first message in this
      -- transaction. A reused agent must hold its DM membership before either
      -- retry presence fanout or first-message fanout takes account revisions.
      -- Identity remains first, matching governed removal. The provision snapshot
      -- is revalidated below before any branch writes; a first-create has no
      -- existing membership and creates that row in this same transaction.
      IF v_snap_agent IS NOT NULL AND v_snap_dm IS NOT NULL THEN
          PERFORM 1 FROM chat.chat_members
           WHERE chat_id = v_snap_dm AND user_id = v_snap_agent
           FOR NO KEY UPDATE;
      END IF;

      -- member row LAST + re-read + FULL re-validation against the snapshot: BOTH binding columns plus owner /
      -- operation / phase / payload_hash. Any drift while we waited on the identity lock fails loud (never act on a
      -- stale snapshot, never silently re-branch).
      SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id FOR UPDATE;
      IF NOT FOUND OR v_p.owner_user_id <> v_owner THEN
          RAISE EXCEPTION 'provision % not found for caller (changed while acquiring locks)', p_provision_id;
      END IF;
      IF v_p.agent_user_id IS DISTINCT FROM v_snap_agent
         OR v_p.provisioned_agent_user_id IS DISTINCT FROM v_snap_prov
         OR v_p.operation_id IS DISTINCT FROM v_snap_op
         OR v_p.phase IS DISTINCT FROM v_snap_phase
         OR v_p.payload_hash IS DISTINCT FROM v_snap_hash
         OR v_p.dm_chat_id IS DISTINCT FROM v_snap_dm THEN
          RAISE EXCEPTION 'prepare: provision % changed while acquiring locks (agent binding / operation / phase / hash / DM binding) — refusing to act on a stale snapshot', p_provision_id;
      END IF;

      -- BINDING STATE MACHINE — exactly TWO legal states; everything else fails loud (checked BEFORE the idempotent
      -- replay return, so a reclaimed member is rejected even on a ready/completed/retry replay).
      IF v_p.provisioned_agent_user_id IS NOT NULL AND v_p.agent_user_id IS NULL THEN
          RAISE EXCEPTION 'prepare: provision % had its exact agent % governed-removed (evidence retained, link SET NULL) — cancel/settle only; prepare never re-provisions or resurrects an identity (a new agent needs a NEW operation/member)', p_provision_id, v_p.provisioned_agent_user_id;
      END IF;
      IF v_p.agent_user_id IS NOT NULL AND v_p.provisioned_agent_user_id IS NULL THEN
          RAISE EXCEPTION 'prepare: provision % has a live agent link % with no durable binding evidence (invariant violation)', p_provision_id, v_p.agent_user_id;
      END IF;
      IF v_p.agent_user_id IS NOT NULL AND v_p.provisioned_agent_user_id IS NOT NULL
         AND v_p.agent_user_id <> v_p.provisioned_agent_user_id::text THEN
          RAISE EXCEPTION 'prepare: provision % agent link % does not match its durable binding evidence % (invariant violation)', p_provision_id, v_p.agent_user_id, v_p.provisioned_agent_user_id;
      END IF;
      -- Validate the PASSED params against the stored row via the SHARED per-member hash. F2: re-derive from the
      -- STORED immutable memory_content_hash (survives the settle=done scrub) — NEVER the mutable raw memory_content.
      v_hash := identity.provision_member_hash(p_operation_id, v_mkey, p_display_name, p_agent_type,
          p_project_path, p_avatar, p_special_focus, p_device_id,
          v_p.inherit_memory, v_p.history_import_required, v_p.memory_sources, v_p.memory_content_hash);
      IF v_p.payload_hash <> v_hash THEN
          RAISE EXCEPTION 'provision % divergent member params (server-derived hash mismatch)', p_provision_id;
      END IF;
      -- Reusable memory command fragment (identical on first create and same-agent retry, id/timestamps aside).
      v_mem := CASE WHEN v_p.memory_sources IS NOT NULL AND cardinality(v_p.memory_sources) > 0
                    THEN jsonb_build_object('memory_sources', to_jsonb(v_p.memory_sources), 'memory_content', v_p.memory_content)
                    ELSE '{}'::jsonb END;

      -- Idempotent replay: an already-advanced member (agent bound, past 'preparing') returns unchanged.
      IF v_p.agent_user_id IS NOT NULL AND v_p.phase IN ('awaiting_terminal','ready','completed') THEN
          EXIT core;
      END IF;

      -- P1-b: prepare initiates NEW work ONLY from a slot-granted 'preparing' row. claim_provision_slots is the sole
      -- capacity authority (queued first-create + failed retry-selection); prepare NEVER promotes 'queued'/'failed'
      -- itself, so a direct call on either fails loud → bounded concurrency holds against the public authenticated RPC.
      IF v_p.phase <> 'preparing' THEN
          RAISE EXCEPTION 'prepare: provision % is not a slot-granted preparing row (phase=%); claim_provision_slots must grant capacity first', p_provision_id, v_p.phase;
      END IF;

      -- RETRY-REUSE (preparing + a bound agent = claim promoted a 'failed' member back via retry-selection): the
      -- agent + DM already exist and the prior command errored. Reuse the SAME agent/DM, enqueue a NEW agent.create,
      -- replace create_command_id — NEVER a new identity/DM. The agent identity is already FOR KEY SHARE-locked above
      -- (P1-a), so this is serialized against a concurrent remove_owned_agent with NO lock cycle; the op was already
      -- re-opened to 'provisioning_members' by claim's retry-selection (prepare no longer flips the operation phase).
      IF v_p.agent_user_id IS NOT NULL THEN
          IF v_p.dm_chat_id IS NULL THEN
              RAISE EXCEPTION 'preparing provision % has a bound agent but no DM to reuse', p_provision_id;
          END IF;
          SELECT status INTO v_old_cmd_status FROM identity.gugu_device_commands WHERE id = v_p.create_command_id;
          IF v_old_cmd_status IS DISTINCT FROM 'error' THEN
              RAISE EXCEPTION 'refusing retry: provision % prior command not in error (status=%)', p_provision_id, COALESCE(v_old_cmd_status,'<absent>');
          END IF;
          -- Source avatar from the RESOLVED agent identity (the canonical value create_owned_agent wrote at first
          -- create), exactly like the first-create branch below — NOT the nullable provision input. Fail loud if the
          -- exact expected agent row is absent or not ours (e.g. a governed removal raced us — the identity lock makes
          -- that observable, not a deadlock); NEVER fall back to the null input (retry command must not diverge — E blocker).
          SELECT * INTO v_agent FROM identity.users
           WHERE id = v_p.agent_user_id AND type = 'agent' AND owner_user_id = v_owner;
          IF NOT FOUND THEN
              RAISE EXCEPTION 'retry: expected agent % for provision % is absent or not owned by caller', v_p.agent_user_id, p_provision_id;
          END IF;
          INSERT INTO identity.gugu_device_commands (user_id, device_id, type, payload)
          VALUES (
              v_owner::uuid, v_p.device_id, 'agent.create',
              jsonb_build_object('agent_user_id', v_p.agent_user_id, 'display_name', v_p.display_name,
                  'agent_type', v_p.agent_type, 'project_path', COALESCE(v_p.project_path, ''),
                  'avatar', v_agent.avatar, 'greeting_chat_id', v_p.dm_chat_id)
              || CASE WHEN v_p.special_focus IS NOT NULL THEN jsonb_build_object('special_focus', v_p.special_focus) ELSE '{}'::jsonb END
              || v_mem
          ) RETURNING id INTO v_cmd_id;
          PERFORM identity.set_agent_runtime_state(v_p.agent_user_id, 'starting', 'idle', NULL, NULL, NULL, NULL, now());
          UPDATE identity.agent_provisions
          SET create_command_id = v_cmd_id, phase = 'awaiting_terminal', error = NULL, updated_at = now()
          WHERE id = p_provision_id RETURNING * INTO v_p;
          EXIT core;
      END IF;

      -- FIRST-CREATE — legal ONLY when the member has NEVER been bound: agent link AND durable evidence both NULL
      -- (the binding state machine above already rejected every other shape, including governed-removed).
      IF NOT (v_p.agent_user_id IS NULL AND v_p.provisioned_agent_user_id IS NULL) THEN
          RAISE EXCEPTION 'prepare: provision % is not an unbound member — first-create requires both agent link and binding evidence to be NULL', p_provision_id;
      END IF;
      -- Create the agent identity + DM + command in-txn.
      -- Reuse the existing primitives, driven by the ROW's canonical params (authoritative). NOTE: the actual
      -- agent.create EXECUTION (spawn + ACP handshake) and wait-for-terminal happen ASYNC on the device/renderer
      -- — never inside this locked transaction.
      SELECT * INTO v_agent FROM identity.create_owned_agent(
          v_p.display_name, v_p.avatar, v_p.agent_type, v_p.device_id, v_p.project_path, NULL, v_p.inherit_memory, v_p.special_focus
      );
      v_dm_chat := chat.get_or_create_dm(v_agent.id::text);
      INSERT INTO identity.gugu_device_commands (user_id, device_id, type, payload)
      VALUES (
          v_owner::uuid, v_p.device_id, 'agent.create',
          jsonb_build_object('agent_user_id', v_agent.id::text, 'display_name', v_p.display_name,
              'agent_type', v_p.agent_type, 'project_path', COALESCE(v_p.project_path, ''),
              'avatar', v_agent.avatar, 'greeting_chat_id', v_dm_chat)
          || CASE WHEN v_p.special_focus IS NOT NULL THEN jsonb_build_object('special_focus', v_p.special_focus) ELSE '{}'::jsonb END
          || v_mem
      ) RETURNING id INTO v_cmd_id;
      PERFORM identity.set_agent_runtime_state(v_agent.id::text, 'starting', 'idle', NULL, NULL, NULL, NULL, now());
      UPDATE identity.agent_provisions
      SET agent_user_id = v_agent.id::text, dm_chat_id = v_dm_chat, create_command_id = v_cmd_id,
          -- F6: bind the durable provisioned-agent evidence atomically with agent_user_id, set-once (COALESCE),
          -- never cleared — so cancel/settle can prove THIS exact agent's governed removal even if remove_owned_agent
          -- committed BEFORE cancel snapshotted anything (agent_user_id would already be NULL by then).
          provisioned_agent_user_id = COALESCE(provisioned_agent_user_id, v_agent.id::uuid),
          phase = 'awaiting_terminal', updated_at = now()
      WHERE id = p_provision_id RETURNING * INTO v_p;
      EXIT core;
  END core;

  -- ── 首条消息(原 _legacy_6264 的后半;没带首条消息就跳过)──
  IF p_initial_message_id IS NOT NULL AND p_initial_message_text IS NOT NULL THEN
    IF v_p.dm_chat_id IS NULL OR v_p.agent_user_id IS NULL THEN
      RAISE EXCEPTION 'initial message requires a prepared agent DM';
    END IF;

    SELECT kind, public_id INTO v_chat_kind, v_public_id
      FROM chat.chats WHERE id = v_p.dm_chat_id;
    IF v_chat_kind IS NULL THEN
      RAISE EXCEPTION 'initial message chat % not found', v_p.dm_chat_id;
    END IF;

    UPDATE identity.gugu_device_commands
       SET payload = COALESCE(payload, '{}'::jsonb)
         || jsonb_build_object(
              'initial_prompt', p_initial_message_text,
              'initial_message_id', p_initial_message_id,
              'initial_chat_public_id', v_public_id,
              'initial_chat_kind', v_chat_kind
            )
     WHERE id = v_p.create_command_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'initial message command % not found', v_p.create_command_id;
    END IF;

    INSERT INTO chat.messages (
      id, chat_id, sender_user_id, content, content_type, client_message_id, to_user_ids
    ) VALUES (
      p_initial_message_id, v_p.dm_chat_id, v_owner, p_initial_message_text,
      'text', p_initial_message_id, ARRAY[v_p.agent_user_id]
    ) ON CONFLICT (id) DO NOTHING
      RETURNING id INTO v_inserted_message_id;
    IF v_inserted_message_id IS NULL THEN
      -- An idempotent replay may encounter the same message row. Any other row sharing the
      -- client id is a collision and must fail loudly instead of being treated as success;
      -- an edited row is intentionally treated as a collision.
      PERFORM 1
        FROM chat.messages
       WHERE id = p_initial_message_id
         AND chat_id = v_p.dm_chat_id
         AND sender_user_id = v_owner
         AND content = p_initial_message_text
         AND content_type = 'text'
         AND client_message_id = p_initial_message_id
         AND v_p.agent_user_id = ANY(to_user_ids);
      IF NOT FOUND THEN
        RAISE EXCEPTION 'initial message id % already belongs to a different message', p_initial_message_id;
      END IF;
    END IF;

    -- Mark the exact message row read in this transaction; nudge/reader ordering is measured by the E2 criterion.
    PERFORM identity.mark_read_on_deliver(v_p.dm_chat_id, p_initial_message_id, v_p.agent_user_id);

    UPDATE identity.agent_provisions
       SET initial_message_id = p_initial_message_id,
           initial_message_text = p_initial_message_text,
           updated_at = now()
     WHERE id = v_p.id
     RETURNING * INTO v_p;
  END IF;

  -- ── 建模型选项写进命令(原 _legacy_7199 的后半)──
  IF v_p.model IS NOT NULL OR v_p.effort IS NOT NULL OR v_p.permission_mode IS NOT NULL THEN
    -- 同一个事务里写进命令:设备不可能先领到一条没带这些选择的 agent.create。
    UPDATE identity.gugu_device_commands
       SET payload = COALESCE(payload, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
             'model', v_p.model,
             'effort', v_p.effort,
             'permission_mode', v_p.permission_mode
           ))
     WHERE id = v_p.create_command_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'create-choice command % not found', v_p.create_command_id;
    END IF;
  END IF;
  RETURN v_p;
END;
$$;


--
-- Name: prepare_agent_provision_pre_adopt_7199(uuid, uuid, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.prepare_agent_provision_pre_adopt_7199(p_provision_id uuid, p_operation_id uuid, p_member_key text, p_device_id text, p_display_name text, p_agent_type text, p_project_path text, p_avatar text, p_special_focus text, p_initial_message_id text, p_initial_message_text text) RETURNS identity.agent_provisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_p identity.agent_provisions;
BEGIN
  v_p := identity.prepare_agent_provision_legacy_7199(
    p_provision_id, p_operation_id, p_member_key, p_device_id, p_display_name,
    p_agent_type, p_project_path, p_avatar, p_special_focus,
    p_initial_message_id, p_initial_message_text
  );
  IF v_p.child_harness IS NOT NULL OR v_p.first_task IS NOT NULL THEN
    -- 同一个事务里写进命令:设备不可能先领到一条没带这两样的 agent.create。
    UPDATE identity.gugu_device_commands
       SET payload = COALESCE(payload, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
             'child_harness', v_p.child_harness,
             'first_task', v_p.first_task
           ))
     WHERE id = v_p.create_command_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'create-choice command % not found', v_p.create_command_id;
    END IF;
  END IF;
  RETURN v_p;
END;
$$;


--
-- Name: preserve_newer_agent_runtime_state(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.preserve_newer_agent_runtime_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF OLD.last_seen_at IS NOT NULL
       AND (NEW.last_seen_at IS NULL OR NEW.last_seen_at < OLD.last_seen_at) THEN
        RETURN OLD;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: provision_member_hash(uuid, text, text, text, text, text, text, text, boolean, boolean, text[], text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.provision_member_hash(p_operation_id uuid, p_member_key text, p_display_name text, p_agent_type text, p_project_path text, p_avatar text, p_special_focus text, p_device_id text, p_inherit_memory boolean, p_history_import_required boolean, p_memory_sources text[], p_memory_content_hash text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT md5(jsonb_build_object(
        'operation_id', p_operation_id::text, 'member_key', p_member_key,
        'display_name', p_display_name, 'agent_type', p_agent_type,
        'project_path', NULLIF(p_project_path, ''), 'avatar', NULLIF(p_avatar, ''),
        'special_focus', NULLIF(p_special_focus, ''), 'device_id', p_device_id,
        'inherit_memory', to_jsonb(p_inherit_memory),
        'history_import_required', to_jsonb(p_history_import_required),
        'memory_sources', COALESCE(to_jsonb(p_memory_sources), 'null'::jsonb),
        -- F2: the memory dimension enters as a PRECOMPUTED immutable hash (md5 of the raw memory, derived + stored
        -- at start). This helper NEVER re-hashes raw memory, so it reproduces the SAME value after settle=done
        -- scrubs memory_content to NULL — a memory-bearing ready/completed prepare replay no longer falsely diverges.
        'memory_content_hash', COALESCE(to_jsonb(p_memory_content_hash), 'null'::jsonb)
    )::text)
$$;


--
-- Name: provision_taskpage_agent(uuid, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.provision_taskpage_agent(p_agent_id uuid, p_display_name text, p_name_mode text, p_agent_type text, p_device_id text, p_local_path text DEFAULT NULL::text, p_group_chat_id text DEFAULT NULL::text, p_new_group_id text DEFAULT NULL::text, p_group_name text DEFAULT NULL::text) RETURNS TABLE(agent_id uuid, display_name text, group_chat_id text, group_created boolean, prior_group_state text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_owner      TEXT := (SELECT auth.uid()::text);
    v_name       TEXT := btrim(coalesce(p_display_name, ''));
    v_parts      TEXT[];
    v_base       TEXT;
    v_serial     INTEGER;
    v_minted     RECORD;
    v_prior      TEXT := 'none';
    v_group      TEXT := '';
    v_created    BOOLEAN := false;
    v_status     TEXT;
    v_target     TEXT;
    v_kind       TEXT;
    v_denial     TEXT;
BEGIN
    IF v_owner IS NULL THEN
        RAISE EXCEPTION 'provision_taskpage_agent requires authenticated session';
    END IF;
    IF v_name = '' THEN
        RAISE EXCEPTION 'p_display_name is required';
    END IF;
    IF p_name_mode NOT IN ('serial', 'explicit') THEN
        RAISE EXCEPTION 'p_name_mode must be serial or explicit, got %', p_name_mode;
    END IF;

    -- 幂等:这个 id 已经铸过就直接沿用。客户端拿着本机预生成的 id 先把会话起起来,这一发在后台跑 ——
    -- 网络抖一下重发、或两条腿各发了一次,都会带着同一个 id 到这里。❌ 第二发失败:那等于让一次重试
    -- 把已经在用的身份判死。名字与群按已存在的事实回答,不重算,❌ 也不再占一个新号。
    IF EXISTS (
        SELECT 1 FROM identity.users u
        WHERE u.id = p_agent_id::text AND u.type = 'agent' AND u.owner_user_id = v_owner
    ) THEN
        SELECT u.id::uuid AS id, u.display_name INTO v_minted
        FROM identity.users u WHERE u.id = p_agent_id::text;
        v_name := v_minted.display_name;
    ELSE
        -- 名字唯一性(spec agent-provisioning:两个显示名逐字相同的 agent 一旦并存,「查通讯录把名字解析成 ID」
        -- 失去确定答案)。比对面 = 这个账号名下全部云端 agent。
        v_parts := regexp_match(v_name, '^(.*\S)\s+(\d{1,9})$');
        v_base  := COALESCE(v_parts[1], v_name);
        PERFORM pg_advisory_xact_lock(hashtextextended(v_owner || '/' || v_base, 6396));
        IF p_name_mode = 'serial' OR EXISTS (
            SELECT 1 FROM identity.users u
            WHERE u.type = 'agent' AND u.owner_user_id = v_owner AND u.display_name = v_name
        ) THEN
            v_serial := COALESCE(v_parts[2]::INTEGER, CASE WHEN p_name_mode = 'serial' THEN 1 ELSE 2 END);
            -- 原子占号:起号 = GREATEST(这个前缀用过的最大号 + 1, 候选号)。
            INSERT INTO identity.agent_name_serials AS s (owner_user_id, base, high_water)
            VALUES (v_owner, v_base, v_serial)
            ON CONFLICT (owner_user_id, base) DO UPDATE
                SET high_water = GREATEST(s.high_water + 1, EXCLUDED.high_water), updated_at = now()
            RETURNING s.high_water INTO v_serial;
            -- 账本之外还被占着的(老数据、触发器之外写进来的行)照样跳过。
            WHILE EXISTS (
                SELECT 1 FROM identity.users u
                WHERE u.type = 'agent' AND u.owner_user_id = v_owner AND u.display_name = v_base || ' ' || v_serial
            ) LOOP
                v_serial := v_serial + 1;
            END LOOP;
            v_name := v_base || ' ' || v_serial;
        END IF;

        -- 开户:走同一个 create_owned_agent(设备归属校验、agent_create_device_id、users 回填都在它里面)。
        -- 写出来的名字由 users 上的触发器记进 agent_name_serials。
        SELECT * INTO v_minted FROM identity.create_owned_agent(
            v_name, NULL, p_agent_type, p_device_id, p_local_path, NULL, true, NULL, p_agent_id
        );
    END IF;

    -- 项目 = 群。
    IF p_group_name IS NOT NULL THEN
        IF p_group_chat_id IS NULL OR p_group_chat_id = '' THEN
            RAISE EXCEPTION 'p_group_chat_id is required when p_group_name is given';
        END IF;
        SELECT c.status, c.kind INTO v_status, v_kind FROM chat.chats c WHERE c.id = p_group_chat_id;
        IF NOT FOUND THEN
            v_prior := 'missing';
            v_target := p_group_chat_id;
        ELSIF v_kind <> 'group' OR NOT chat.is_chat_member(p_group_chat_id, v_owner) THEN
            -- 安全:映射里递上来的 id 不是调用者自己所在的群(别人的群 / 私聊 / 话题)⇒ ❌ 不往里塞 agent。
            -- 与「映射指着一个归档群」同处置:另建一个项目群,客户端按返回的 group_chat_id 改指映射。
            v_prior := 'foreign';
            IF p_new_group_id IS NULL OR p_new_group_id = '' THEN
                RAISE EXCEPTION 'p_new_group_id is required when the mapped project group is not the caller''s group';
            END IF;
            v_target := p_new_group_id;
        ELSIF v_status = 'archived' THEN
            v_prior := 'archived';
            IF p_new_group_id IS NULL OR p_new_group_id = '' THEN
                RAISE EXCEPTION 'p_new_group_id is required when the mapped project group is archived';
            END IF;
            v_target := p_new_group_id;
        ELSE
            v_prior := 'active';
            v_target := p_group_chat_id;
        END IF;

        IF v_prior = 'active' THEN
            -- 与客户端直插(RLS)同一道「能否加此人」:上限、agent 审批、成员邀请开关。
            -- 串行化同一群的并发加人(与 add_group_agent 同一把群行锁),再判上限。
            PERFORM 1 FROM chat.chats WHERE id = v_target FOR UPDATE;
            v_denial := chat.group_add_denial(v_target, v_minted.id::text, v_owner);
            IF v_denial = 'agent_join_requires_manager' THEN
                -- 群开了「Agent 加入需审批」而调用者不是管理员:进审批队列,这次不入群(会话照常起)。
                PERFORM chat.queue_agent_join_request(v_target, v_minted.id::text, v_owner, NULL);
                v_prior := 'pending_approval';
            ELSIF v_denial IS NOT NULL THEN
                RAISE EXCEPTION 'provision_taskpage_agent: cannot add agent to project group %: %', v_target, v_denial;
            ELSE
                INSERT INTO chat.chat_members (chat_id, user_id, role, listen_mode)
                VALUES (v_target, v_minted.id::text, 'member', 'active')
                ON CONFLICT (chat_id, user_id) DO NOTHING;
            END IF;
        ELSE
            BEGIN
                PERFORM chat.create_gugu_group(
                    v_target, p_group_name, v_owner,
                    jsonb_build_array(jsonb_build_object('user_id', v_minted.id::text, 'role', 'member')),
                    NULL, NULL
                );
                v_created := true;
            EXCEPTION WHEN unique_violation THEN
                -- 背靠背的另一条会话刚用同一个预生成 id 把群建出来了 ⇒ 改加座位。
                -- 串行化同一群的并发加人(与 add_group_agent 同一把群行锁),再判上限。
            PERFORM 1 FROM chat.chats WHERE id = v_target FOR UPDATE;
            v_denial := chat.group_add_denial(v_target, v_minted.id::text, v_owner);
                IF v_denial IS NOT NULL THEN
                    RAISE EXCEPTION 'provision_taskpage_agent: cannot add agent to project group %: %', v_target, v_denial;
                END IF;
                INSERT INTO chat.chat_members (chat_id, user_id, role, listen_mode)
                VALUES (v_target, v_minted.id::text, 'member', 'active')
                ON CONFLICT (chat_id, user_id) DO NOTHING;
                v_prior := 'active';
            END;
            UPDATE chat.chat_members SET listen_mode = 'active'
            WHERE chat_id = v_target AND user_id = v_minted.id::text;
        END IF;
        v_group := CASE WHEN v_prior = 'pending_approval' THEN '' ELSE v_target END;
    END IF;

    RETURN QUERY SELECT v_minted.id, v_name, v_group, v_created, v_prior;
END;
$_$;


--
-- Name: provision_template_message(text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.provision_template_message(p_display_name text, p_agent_type text, p_special_focus text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
    SELECT '我是'
        || CASE WHEN COALESCE(NULLIF(btrim(p_display_name), ''), '你的 Agent') ~ '^[A-Za-z0-9]' THEN ' ' ELSE '' END
        || COALESCE(NULLIF(btrim(p_display_name), ''), '你的 Agent')
        || '，已就位。'
        || CASE WHEN NULLIF(btrim(coalesce(p_special_focus,'')), '') IS NOT NULL
                THEN '我的方向：' || btrim(p_special_focus) || '。' ELSE '' END
        || '有什么可以帮你的，直接说。';
$$;


--
-- Name: publish_device_revision(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.publish_device_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    device_row identity.gugu_devices%ROWTYPE := COALESCE(NEW, OLD);
BEGIN
    PERFORM chat.publish_user_revision(
      device_row.user_id::text,
      'device_changed',
      jsonb_build_object('device_id', device_row.device_id),
      TG_OP = 'DELETE'
    );
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_friend_request_revision(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.publish_friend_request_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    request_row identity.friend_requests%ROWTYPE := COALESCE(NEW, OLD);
    target_user_id TEXT;
BEGIN
    FOR target_user_id IN
      SELECT DISTINCT candidate.user_id
        FROM (
          SELECT request_row.sender_id AS user_id
          UNION ALL
          SELECT request_row.receiver_id
          UNION ALL
          SELECT receiver.owner_user_id
            FROM identity.users receiver
           WHERE receiver.id = request_row.receiver_id
             AND receiver.type = 'agent'
             AND receiver.owner_user_id IS NOT NULL
        ) candidate
       WHERE candidate.user_id IS NOT NULL
       ORDER BY candidate.user_id
    LOOP
      PERFORM chat.publish_user_revision(
        target_user_id,
        'friend_requests_changed',
        jsonb_build_object('request_id', request_row.id),
        TG_OP = 'DELETE'
      );
    END LOOP;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_friendship_revision(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.publish_friendship_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    friendship_row identity.friendships%ROWTYPE := COALESCE(NEW, OLD);
    target_user_id TEXT;
BEGIN
    FOR target_user_id IN
      SELECT DISTINCT recipient.user_id
        FROM (VALUES (friendship_row.user_a_id), (friendship_row.user_b_id)) recipient(user_id)
       WHERE recipient.user_id IS NOT NULL
       ORDER BY recipient.user_id
    LOOP
      PERFORM chat.publish_user_revision(
        target_user_id,
        'friendship_changed',
        jsonb_build_object('user_a_id', friendship_row.user_a_id, 'user_b_id', friendship_row.user_b_id),
        TG_OP = 'DELETE'
      );
    END LOOP;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: publish_identity_display_revision(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.publish_identity_display_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    viewer TEXT;
BEGIN
    FOR viewer IN
        SELECT candidate.id
          FROM (
                SELECT NEW.id AS id
                UNION
                SELECT CASE WHEN f.user_a_id = NEW.id THEN f.user_b_id ELSE f.user_a_id END
                  FROM identity.friendships f
                 WHERE f.user_a_id = NEW.id OR f.user_b_id = NEW.id
                UNION
                SELECT peer.user_id
                  FROM chat.chat_members mine
                  JOIN chat.chat_members peer
                    ON peer.chat_id = mine.chat_id AND peer.user_id <> mine.user_id
                 WHERE mine.user_id = NEW.id
               ) candidate
          JOIN identity.users u ON u.id = candidate.id AND u.type <> 'agent'
         WHERE NOT (NEW.type = 'agent' AND candidate.id IS NOT DISTINCT FROM NEW.owner_user_id)
    LOOP
        PERFORM chat.publish_user_revision(
          viewer,
          'agent_changed',
          jsonb_build_object('agent_user_id', NEW.id),
          false
        );
    END LOOP;
    RETURN NEW;
END;
$$;


--
-- Name: publish_owned_agent_revision(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.publish_owned_agent_revision() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    agent_row identity.users%ROWTYPE := COALESCE(NEW, OLD);
BEGIN
    IF agent_row.type = 'agent' AND agent_row.owner_user_id IS NOT NULL THEN
      PERFORM chat.publish_user_revision(
        agent_row.owner_user_id,
        'agent_changed',
        jsonb_build_object('agent_user_id', agent_row.id),
        TG_OP = 'DELETE'
      );
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: pull_agent_inbox_v2(text, text, bigint, integer, jsonb, bigint); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.pull_agent_inbox_v2(p_agent_user_id text, p_chat_id text DEFAULT NULL::text, p_after_seq bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 80, p_scan_after jsonb DEFAULT NULL::jsonb, p_scan_max_ingest_seq bigint DEFAULT NULL::bigint) RETURNS TABLE(chat_id text, chat_kind text, chat_public_id integer, chat_name text, chat_creator_user_id text, listen_mode text, notification_level text, last_read_seq bigint, id text, seq bigint, sender_user_id text, sender_type text, sender_display_name text, sender_gugu_number integer, content text, content_type text, to_user_ids text[], is_whisper boolean, reply_to_message_id text, reply_to_sender_user_id text, reply_to_content text, thread_root_id text, is_thread_root boolean, created_at timestamp with time zone, scan_max_ingest_seq bigint, via_app text, file_item_id uuid, file_version integer, file_blob_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'chat', 'identity', 'public'
    AS $$
 DECLARE
     -- 这一次扫描的上界:首页取序列此刻的位置并随行返回,后续页原样传回。❌ 墙钟(#6327)。
     v_fence BIGINT;
 BEGIN
     -- 授权镜像 chat.can_act_as 的身份半边(fail-closed):调用者是该 agent 本人,或拥有该 agent。
     IF (SELECT auth.uid()) IS NULL THEN
         RAISE EXCEPTION 'not authenticated';
     END IF;
     IF NOT (
         p_agent_user_id = (SELECT auth.uid()::text)
         OR EXISTS (
             SELECT 1 FROM identity.users u
             WHERE u.id = p_agent_user_id
               AND u.type = 'agent'
               AND u.owner_user_id = (SELECT auth.uid()::text)
         )
     ) THEN
         RAISE EXCEPTION 'not authorized to pull unread for %', p_agent_user_id;
     END IF;

     v_fence := COALESCE(
         p_scan_max_ingest_seq,
         pg_sequence_last_value(pg_get_serial_sequence('chat.messages', 'ingest_seq')::regclass),
         0
     );

     RETURN QUERY
     SELECT
         m.chat_id,
         c.kind,
         c.public_id,
         c.name,
         c.creator_user_id,
         cm.listen_mode,
         cm.notification_level,
         cm.last_read_seq,
         m.id,
         m.seq,
         m.sender_user_id,
         su.type,
         su.display_name,
         su.gugu_number,
         m.content,
         m.content_type,
         m.to_user_ids,
         m.is_whisper,
         m.reply_to_message_id,
         rm.sender_user_id,
         rm.content,
         m.thread_root_id,
         m.is_thread_root,
         m.created_at,
         v_fence,
         m.via_app,
         -- ◇ 附件指针(agent 拿它去 attachments/urls 取字节)。
         m.file_item_id,
         m.file_version,
         m.file_blob_id
     FROM chat.chat_members cm
     JOIN chat.chats c    ON c.id = cm.chat_id
     JOIN chat.messages m ON m.chat_id = cm.chat_id
     -- 回复**预览**(给这个收件人看的上下文),按它的可读性裁剪;路由目标另算,见谓词的最后一个参数。
     LEFT JOIN chat.messages rm
            ON rm.id = m.reply_to_message_id
           AND rm.deleted_at IS NULL
           AND NOT rm.is_whisper
           -- @@@5856 **这个 agent** 读不读得到被回复的那一条:一条它入群前的消息被别人回复 + @ 它,
           -- 正文不许原样落到它主人的机器上。⚠️ 传 p_agent_user_id:auth.uid() 是调用方(主人),不是收件人。
           AND chat.can_read_message(rm.id, p_agent_user_id)
     LEFT JOIN identity.users su ON su.id = m.sender_user_id
     WHERE cm.user_id = p_agent_user_id
       AND (p_chat_id IS NULL OR cm.chat_id = p_chat_id)
       AND c.status = 'active'
       AND m.deleted_at IS NULL
       -- A deregistered human/agent is not retroactively a system sender.
       AND (m.sender_user_id IS NOT NULL OR m.content_type = 'system')
       AND m.seq > GREATEST(cm.last_read_seq, COALESCE(p_after_seq, 0))
       -- #5258 入群门:只投递 agent 在场之后到达的消息。入群前的历史归它自己按需回看,
       -- ❌ 不当积压推。与 hide_history_before 那道门同形(`>=`,同一 now() 时钟)。
       AND m.ingest_seq > cm.joined_ingest_seq
       AND m.ingest_seq <= v_fence
       AND (p_scan_after IS NULL OR
            (m.chat_id, m.seq) > (p_scan_after->>'chat_id', (p_scan_after->>'seq')::BIGINT))
       -- 已消费排除:水位可停滞(gap gate),精确读行才是逐条消费事实
       AND NOT EXISTS (
           SELECT 1 FROM chat.message_deliveries d
           WHERE d.message_id = m.id
             AND d.device_id = 'gugu-agent:' || p_agent_user_id
             AND d.status = 'read'
       )
       -- @@@6400 「叫醒谁」在消息写入那一刻定下(chat.message_agent_wakes),这里只读结果。
       -- ❌ 再拿此刻的 to_user_ids / 回复目标 / 档位重判:它们事后会变(删 agent、注销、切档)。
       AND EXISTS (
           SELECT 1 FROM chat.message_agent_wakes w
           WHERE w.message_id = m.id
             AND w.agent_user_id = p_agent_user_id
       )
     ORDER BY m.chat_id, m.seq
     LIMIT GREATEST(COALESCE(p_limit, 80), 1);
 END;
 $$;


--
-- Name: recheck_device_command_execution(uuid, uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.recheck_device_command_execution(p_id uuid, p_claim_token uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    command_row identity.gugu_device_commands%ROWTYPE;
BEGIN
    SELECT * INTO command_row
    FROM identity.gugu_device_commands c
    WHERE c.id = p_id AND c.claim_token = p_claim_token
      AND c.status = 'running'
    LIMIT 1;
    IF NOT FOUND THEN RETURN false; END IF;
    IF command_row.type <> 'agent.deliver' THEN RETURN true; END IF;
    PERFORM identity.assert_device_command_post_context(
        p_id,
        p_claim_token,
        command_row.payload->>'agent_user_id',
        command_row.payload->>'chat_id',
        NULL,
        NULL
    );
    RETURN true;
END;
$$;


--
-- Name: record_agent_deliver_outcome(text, boolean); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.record_agent_deliver_outcome(p_agent_user_id text, p_ok boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_count INTEGER;
BEGIN
    IF NOT identity.can_write_agent_runtime_state(p_agent_user_id) THEN
        RAISE EXCEPTION 'agent runtime state for % is not writable by current user', p_agent_user_id;
    END IF;
    -- fail loud:NULL 不是合法结局(plpgsql 的 IF NULL 会静默落到失败分支 = 幽灵 +1)。
    IF p_ok IS NULL THEN
        RAISE EXCEPTION 'record_agent_deliver_outcome: p_ok is required';
    END IF;
    IF p_ok THEN
        UPDATE identity.agent_runtime_states
           SET consecutive_deliver_failures = 0,
               updated_at = now()
         WHERE agent_user_id = p_agent_user_id
           AND consecutive_deliver_failures <> 0;
        RETURN 0;
    END IF;
    UPDATE identity.agent_runtime_states
       SET consecutive_deliver_failures = consecutive_deliver_failures + 1,
           updated_at = now()
     WHERE agent_user_id = p_agent_user_id
    RETURNING consecutive_deliver_failures INTO v_count;
    RETURN COALESCE(v_count, 0);
END; $$;


--
-- Name: record_agent_name_serial(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.record_agent_name_serial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_parts TEXT[];
BEGIN
    IF NEW.type IS DISTINCT FROM 'agent' OR NEW.owner_user_id IS NULL THEN
        RETURN NEW;
    END IF;
    v_parts := regexp_match(btrim(coalesce(NEW.display_name, '')), '^(.*\S)\s+(\d{1,9})$');
    IF v_parts IS NULL THEN
        RETURN NEW;
    END IF;
    INSERT INTO identity.agent_name_serials AS s (owner_user_id, base, high_water)
    VALUES (NEW.owner_user_id, v_parts[1], v_parts[2]::INTEGER)
    ON CONFLICT (owner_user_id, base) DO UPDATE
        SET high_water = EXCLUDED.high_water, updated_at = now()
        WHERE s.high_water < EXCLUDED.high_water;
    RETURN NEW;
END;
$_$;


--
-- Name: recover_orphaned_device_commands(text, integer); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.recover_orphaned_device_commands(p_device_id text, p_stale_seconds integer DEFAULT 90) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    recovered_count INTEGER;
BEGIN
    IF (SELECT auth.uid()) IS NULL THEN
        RAISE EXCEPTION 'recover_orphaned_device_commands requires an authenticated user';
    END IF;
    UPDATE identity.gugu_device_commands c
    SET status = 'pending', claim_token = NULL, claimed_at = NULL, claimed_by = NULL
    WHERE c.device_id = p_device_id
      AND c.user_id = (SELECT auth.uid())
      AND c.status = 'running'
      AND (
          c.claimed_by IS NULL
          OR NOT EXISTS (
              SELECT 1 FROM identity.runtime_instances ri
              WHERE ri.instance_id = c.claimed_by
                AND ri.last_heartbeat_at > now() - make_interval(secs => p_stale_seconds)
          )
      );
    GET DIAGNOSTICS recovered_count = ROW_COUNT;
    RETURN recovered_count;
END;
$$;


--
-- Name: reject_friend_request_by_id(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.reject_friend_request_by_id(p_request_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
BEGIN
    UPDATE identity.friend_requests fr
       SET status = 'rejected', updated_at = now()
     WHERE fr.id = p_request_id
       AND fr.status = 'pending'
       AND (
           fr.receiver_id = v_me
           OR EXISTS (
               SELECT 1
                 FROM identity.users u
                WHERE u.id = fr.receiver_id
                  AND u.type = 'agent'
                  AND u.owner_user_id = v_me
           )
       );

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Friend request not found';
    END IF;
END;
$$;


--
-- Name: reject_retired_cloud_agent(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.reject_retired_cloud_agent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
BEGIN
    IF NEW.agent_type = 'gugu-cloud'
       AND (TG_OP = 'INSERT' OR OLD.agent_type IS DISTINCT FROM NEW.agent_type) THEN
        RAISE EXCEPTION 'Gugu Cloud Agent has been retired';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_retired_thread_handoff_command(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.reject_retired_thread_handoff_command() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.type = 'agent.deliver'
       AND NULLIF(NEW.payload->>'thread_root_id', '') IS NOT NULL
       AND NEW.payload->>'agent_user_id' = NEW.payload->>'sender_user_id'
       AND NEW.payload->'to_user_ids' @> jsonb_build_array(NEW.payload->>'agent_user_id')
    THEN
        RAISE EXCEPTION 'agent thread handoff is retired; use emdash conversation delivery';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: remove_contact(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.remove_contact(p_contact_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_contact identity.users%ROWTYPE;
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF p_contact_user_id IS NULL OR p_contact_user_id = '' OR p_contact_user_id = v_me THEN
        RAISE EXCEPTION 'Invalid contact';
    END IF;

    SELECT *
    INTO v_contact
    FROM identity.users
    WHERE id = p_contact_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Contact not found';
    END IF;

    IF v_contact.type = 'agent' AND v_contact.owner_user_id = v_me THEN
        RAISE EXCEPTION 'Owned agent deletion is managed separately';
    END IF;

    DELETE FROM identity.friendships
    WHERE user_a_id = LEAST(v_me, p_contact_user_id)
      AND user_b_id = GREATEST(v_me, p_contact_user_id);

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Friendship not found';
    END IF;

    DELETE FROM identity.contact_overrides
    WHERE owner_user_id = v_me
      AND contact_user_id = p_contact_user_id;

    DELETE FROM identity.contact_group_members cgm
    USING identity.contact_groups cg
    WHERE cgm.group_id = cg.id
      AND cg.owner_user_id = v_me
      AND cgm.contact_user_id = p_contact_user_id;
END;
$$;


--
-- Name: remove_device(text, boolean); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.remove_device(p_device_id text, p_cascade boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me UUID := auth.uid();
    v_device identity.gugu_devices%ROWTYPE;
    v_agent_ids TEXT[];
    v_agent_id TEXT;
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF NULLIF(p_device_id, '') IS NULL THEN
        RAISE EXCEPTION 'Device is required';
    END IF;

    SELECT * INTO v_device
      FROM identity.gugu_devices
     WHERE device_id = p_device_id
       AND user_id = v_me
       FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Device is not owned by current user';
    END IF;

    SELECT coalesce(array_agg(id ORDER BY id), ARRAY[]::TEXT[])
      INTO v_agent_ids
      FROM identity.users
     WHERE device_id = p_device_id
       AND type = 'agent'
       AND owner_user_id = v_me::text;

    IF coalesce(array_length(v_agent_ids, 1), 0) > 0 AND NOT p_cascade THEN
        -- 客户端按 DEVICE_HAS_AGENTS 前缀识别「拦」态（列出 agent 走 UI 查询，不在错误里塞明细）。
        RAISE EXCEPTION 'DEVICE_HAS_AGENTS: % agent(s) bound to this device', array_length(v_agent_ids, 1);
    END IF;

    FOREACH v_agent_id IN ARRAY v_agent_ids LOOP
        PERFORM identity.remove_owned_agent(v_agent_id);
    END LOOP;

    DELETE FROM identity.gugu_devices
     WHERE device_id = p_device_id
       AND user_id = v_me;

    IF v_device.capabilities ->> 'host_kind' = 'server' THEN
        INSERT INTO identity.gugu_device_removals (device_id, user_id, removed_at)
        VALUES (p_device_id, v_me, now())
        ON CONFLICT (device_id, user_id) DO UPDATE SET removed_at = EXCLUDED.removed_at;

        -- 吊销它的登录。绝不吊销发起移除的这一端自己的会话。
        IF v_device.auth_session_id IS NOT NULL
           AND v_device.auth_session_id IS DISTINCT FROM identity.current_jwt_session_id() THEN
            BEGIN
                DELETE FROM auth.sessions
                 WHERE id = v_device.auth_session_id
                   AND user_id = v_me;
            EXCEPTION WHEN insufficient_privilege THEN
                -- 吊销不了也不让移除失败:①③ 仍然生效,server 看到 DEVICE_REMOVED 就自己退出登录。
                RAISE WARNING 'remove_device: cannot revoke auth session % (insufficient privilege)', v_device.auth_session_id;
            END;
        END IF;
    END IF;
END;
$$;


--
-- Name: remove_owned_agent(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.remove_owned_agent(p_agent_user_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_me TEXT := auth.uid()::text;
    v_agent identity.users%ROWTYPE;
    v_owned_agent_group_ids TEXT[];
    v_archive_chat_ids TEXT[];
    v_touched_chat_ids TEXT[];
    v_presence_viewer_ids TEXT[];
    v_contact_viewer_ids TEXT[];
    v_removed_payload JSONB;
    v_chat_id TEXT;
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    IF NULLIF(p_agent_user_id, '') IS NULL THEN
        RAISE EXCEPTION 'Agent is required';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM identity.agent_lifecycle_tombstones t
        WHERE t.agent_user_id = p_agent_user_id
          AND t.owner_user_id = v_me
    ) THEN
        RETURN;
    END IF;

    SELECT *
      INTO v_agent
      FROM identity.users
     WHERE id = p_agent_user_id
       AND type = 'agent'
       AND owner_user_id = v_me
     FOR UPDATE;

    IF NOT FOUND THEN
        IF EXISTS (
            SELECT 1
            FROM identity.agent_lifecycle_tombstones t
            WHERE t.agent_user_id = p_agent_user_id
              AND t.owner_user_id = v_me
        ) THEN
            RETURN;
        END IF;
        RAISE EXCEPTION 'Agent is not owned by current user';
    END IF;

    SELECT coalesce(array_agg(DISTINCT viewer_id), ARRAY[]::TEXT[])
      INTO v_contact_viewer_ids
      FROM (
          SELECT v_me AS viewer_id
          UNION
          SELECT CASE WHEN f.user_a_id = v_agent.id THEN f.user_b_id ELSE f.user_a_id END
          FROM identity.friendships f
          WHERE f.user_a_id = v_agent.id OR f.user_b_id = v_agent.id
      ) viewers;

    SELECT coalesce(array_agg(DISTINCT viewer_id), ARRAY[]::TEXT[])
      INTO v_presence_viewer_ids
      FROM (
          SELECT unnest(v_contact_viewer_ids) AS viewer_id
          UNION
          SELECT cm_self.user_id
          FROM chat.chat_members cm_agent
          JOIN chat.chat_members cm_self ON cm_self.chat_id = cm_agent.chat_id
          WHERE cm_agent.user_id = v_agent.id
            AND cm_self.user_id <> v_agent.id
      ) viewers;

    INSERT INTO identity.agent_lifecycle_tombstones (
        agent_user_id,
        owner_user_id,
        display_name,
        avatar,
        bio,
        gugu_number,
        agent_public,
        desired_status,
        device_id,
        local_path,
        agent_created_at,
        removed_at,
        presence_viewer_user_ids,
        contact_viewer_user_ids
    ) VALUES (
        v_agent.id,
        v_me,
        v_agent.display_name,
        v_agent.avatar,
        v_agent.bio,
        v_agent.gugu_number,
        false,
        'offline',
        v_agent.device_id,
        v_agent.local_path,
        v_agent.created_at,
        now(),
        v_presence_viewer_ids,
        v_contact_viewer_ids
    );

    SELECT coalesce(array_agg(DISTINCT c.id), ARRAY[]::TEXT[])
      INTO v_owned_agent_group_ids
      FROM chat.chats c
     WHERE c.kind = 'group'
       AND c.creator_user_id = v_agent.id;

    SELECT coalesce(array_agg(DISTINCT c.id), ARRAY[]::TEXT[])
      INTO v_archive_chat_ids
      FROM chat.chats c
     WHERE c.kind IN ('dm', 'ai')
       AND EXISTS (
           SELECT 1
             FROM chat.chat_members cm
            WHERE cm.chat_id = c.id
              AND cm.user_id = v_agent.id
       );

    v_archive_chat_ids := (
        SELECT coalesce(array_agg(DISTINCT id), ARRAY[]::TEXT[])
          FROM unnest(v_archive_chat_ids || v_owned_agent_group_ids) AS ids(id)
    );

    SELECT coalesce(array_agg(DISTINCT c.id), ARRAY[]::TEXT[])
      INTO v_touched_chat_ids
      FROM chat.chats c
     WHERE c.id = ANY(v_archive_chat_ids)
        OR EXISTS (
            SELECT 1
              FROM chat.chat_members cm
             WHERE cm.chat_id = c.id
               AND cm.user_id = v_agent.id
        );

    UPDATE chat.chats c
       SET status = 'archived', updated_at = now()
     WHERE c.status <> 'archived'
       AND c.id = ANY(v_archive_chat_ids);

    -- @@@5919 消息只随它的专属会话(上面刚归档的单聊 / ai 会话 / 它自己建的群)一起删;
    -- 投递行与表态随消息级联。共享会话里的消息一条不删 —— @ 它、发给它的是别人写的字,
    -- 它自己说过的话是别人对话的上下文(删了还会把别人回复它的 reply_to 一并置空)。
    -- 与 identity.erase_human_account 同一套:消息留着,只擦对这个身份的引用。
    DELETE FROM chat.messages m
    WHERE m.chat_id = ANY(v_archive_chat_ids);

    -- 它自己那一份投递行(agent 的投递键是 'gugu-agent:<id>')与它自己按的表态。
    DELETE FROM chat.message_deliveries d
    WHERE d.device_id = 'gugu-agent:' || v_agent.id;
    DELETE FROM chat.message_reactions r
    WHERE r.user_id = v_agent.id;

    -- @@@6400 名单擦空 = 定向消息变「没点名」,会被 active agent 的下一次拉取捡走;只剩它时保留它的 id。
    UPDATE chat.messages m
    SET to_user_ids = ARRAY(
            SELECT recipient_id FROM unnest(m.to_user_ids) AS recipient_id
            WHERE recipient_id <> v_agent.id
        )
    WHERE v_agent.id = ANY(m.to_user_ids)
      AND EXISTS (
          SELECT 1 FROM unnest(m.to_user_ids) AS other(recipient_id)
          WHERE other.recipient_id <> v_agent.id
      );
    UPDATE chat.messages m
    SET deleted_for_user_ids = m.deleted_for_user_ids - v_agent.id
    WHERE m.deleted_for_user_ids ? v_agent.id;

    DELETE FROM chat.gugu_decision_events
    WHERE chat_id = ANY(v_owned_agent_group_ids)
       OR created_by_user_id = v_agent.id;
    DELETE FROM chat.group_scheduler_states WHERE chat_id = ANY(v_owned_agent_group_ids);
    DELETE FROM chat.group_tasks WHERE chat_id = ANY(v_owned_agent_group_ids);
    DELETE FROM chat.group_outputs WHERE chat_id = ANY(v_owned_agent_group_ids);
    DELETE FROM chat.group_agent_states WHERE chat_id = ANY(v_owned_agent_group_ids);
    DELETE FROM chat.group_agent_states WHERE agent_user_id = v_agent.id;

    UPDATE chat.group_tasks
       SET owner_agent_user_id = NULL,
           reviewer_agent_user_id = NULL,
           updated_at = now()
     WHERE owner_agent_user_id = v_agent.id
        OR reviewer_agent_user_id = v_agent.id;
    UPDATE chat.group_outputs
       SET produced_by_user_id = NULL
     WHERE produced_by_user_id = v_agent.id;
    DELETE FROM chat.chat_members WHERE chat_id = ANY(v_owned_agent_group_ids);

    UPDATE chat.chats c
       SET status = 'archived', updated_at = now()
     WHERE c.kind = 'group'
       AND c.status = 'active'
       AND c.creator_user_id <> v_agent.id
       AND EXISTS (
           SELECT 1 FROM chat.chat_members cm
           WHERE cm.chat_id = c.id AND cm.user_id = v_agent.id
       )
       AND (
           SELECT count(*) FROM chat.chat_members cm2 WHERE cm2.chat_id = c.id
       ) <= 2;

    DELETE FROM chat.chat_members WHERE user_id = v_agent.id;

    FOREACH v_chat_id IN ARRAY v_touched_chat_ids LOOP
        PERFORM chat.recompute_chat_last_message(v_chat_id);
    END LOOP;

    DELETE FROM identity.friendships
    WHERE user_a_id = v_agent.id OR user_b_id = v_agent.id;
    DELETE FROM identity.friend_requests
    WHERE sender_id = v_agent.id OR receiver_id = v_agent.id;
    DELETE FROM identity.contact_overrides
    WHERE owner_user_id = v_agent.id OR contact_user_id = v_agent.id;
    DELETE FROM identity.contact_group_members cgm
    USING identity.contact_groups cg
    WHERE cgm.group_id = cg.id
      AND (cgm.contact_user_id = v_agent.id OR cg.owner_user_id = v_agent.id);
    DELETE FROM identity.agent_runtime_states WHERE agent_user_id = v_agent.id;
    DELETE FROM identity.gugu_device_commands WHERE payload->>'agent_user_id' = v_agent.id;
    DELETE FROM identity.agent_profiles
    WHERE id::text = v_agent.id AND owner_id::text = v_me;
    DELETE FROM identity.users
    WHERE id = v_agent.id AND type = 'agent' AND owner_user_id = v_me;

    v_removed_payload := identity.build_agent_presence_payload(v_agent.id);
    IF v_removed_payload IS NULL THEN
        RAISE EXCEPTION 'Removed agent lifecycle payload is missing';
    END IF;

    PERFORM identity.fan_agent_presence_to_viewers(v_agent.id, v_removed_payload);
END;
$$;


--
-- Name: rename_device(text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.rename_device(p_device_id text, p_label text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'pg_catalog'
    AS $$
DECLARE
    v_me UUID := auth.uid();
    v_label TEXT := btrim(p_label);
BEGIN
    IF v_me IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    IF NULLIF(p_device_id, '') IS NULL THEN
        RAISE EXCEPTION 'Device is required';
    END IF;
    IF v_label = '' THEN
        RAISE EXCEPTION 'Device label must not be empty';
    END IF;

    -- clock_timestamp()(真实墙钟，事务内单调递增)而非 now()(事务开始时刻，同事务内冻结)：
    -- 保证每次 rename 都 bump 出与旧值不同的标记 → 触发器可靠区分「rename」与「心跳」。
    UPDATE identity.gugu_devices
       SET label = v_label,
           label_customized_at = clock_timestamp(),
           updated_at = now()
     WHERE device_id = p_device_id
       AND user_id = v_me;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Device is not owned by current user';
    END IF;
END;
$$;


--
-- Name: agent_model_selections; Type: TABLE; Schema: identity; Owner: -
--

CREATE TABLE identity.agent_model_selections (
    agent_user_id text NOT NULL,
    owner_user_id text NOT NULL,
    desired jsonb NOT NULL,
    applied jsonb,
    applied_at timestamp with time zone,
    apply_error text,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: report_agent_model_selection(text, jsonb, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.report_agent_model_selection(p_agent_user_id text, p_applied jsonb, p_error text DEFAULT NULL::text) RETURNS identity.agent_model_selections
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_row     identity.agent_model_selections;
    v_applied JSONB;
    v_owner   TEXT;
BEGIN
    IF NOT identity.can_write_agent_runtime_state(p_agent_user_id) THEN
        RAISE EXCEPTION 'Agent model selection is not writable by current user';
    END IF;
    IF p_applied IS NOT NULL THEN
        v_applied := identity.validate_agent_model_selection(p_applied);
    END IF;

    SELECT owner_user_id INTO v_owner FROM identity.users WHERE id = p_agent_user_id;

    INSERT INTO identity.agent_model_selections (
        agent_user_id, owner_user_id, desired, applied, applied_at, apply_error, updated_at
    )
    VALUES (
        p_agent_user_id,
        v_owner,
        COALESCE(v_applied, jsonb_build_object('source', 'default')),
        v_applied,
        CASE WHEN v_applied IS NULL THEN NULL ELSE now() END,
        p_error,
        now()
    )
    ON CONFLICT (agent_user_id) DO UPDATE
        SET applied     = COALESCE(v_applied, identity.agent_model_selections.applied),
            applied_at  = CASE WHEN v_applied IS NULL THEN identity.agent_model_selections.applied_at ELSE now() END,
            apply_error = p_error,
            updated_at  = now()
    RETURNING * INTO v_row;

    RETURN v_row;
END;
$$;


--
-- Name: runtime_instance_heartbeat(text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.runtime_instance_heartbeat(p_instance_id text, p_device_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_sweep_age_seconds INTEGER;
BEGIN
    IF (SELECT auth.uid()) IS NULL THEN
        RAISE EXCEPTION 'runtime_instance_heartbeat requires an authenticated user';
    END IF;
    INSERT INTO identity.runtime_instances (instance_id, device_id, owner_user_id, last_heartbeat_at)
    VALUES (p_instance_id, p_device_id, (SELECT auth.uid()), now())
    ON CONFLICT (instance_id) DO UPDATE
        SET last_heartbeat_at = now(),
            device_id = EXCLUDED.device_id
        WHERE identity.runtime_instances.owner_user_id = (SELECT auth.uid());

    SELECT floor(EXTRACT(EPOCH FROM now() - s.last_run_at))::INTEGER
      INTO v_sweep_age_seconds
      FROM identity.device_lease_sweeps s
     WHERE s.id;

    -- NULL 只可能来自那一行不见了。原样传出去,让宿主把它当故障报,❌ 不要在这里补一个好看的默认值。
    RETURN jsonb_build_object('device_lease_sweep_age_seconds', v_sweep_age_seconds);
END;
$$;


--
-- Name: scrub_terminal_agent_create_memory(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.scrub_terminal_agent_create_memory() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
    IF NEW.type = 'agent.create'
       AND NEW.status IN ('done','error')
       AND NEW.payload ? 'memory_content' THEN
        NEW.payload = NEW.payload - 'memory_content';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: search_users(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.search_users(p_query text) RETURNS TABLE(id text, gugu_number integer, display_name text, avatar text, bio text, type text, owner_user_id text, agent_public boolean, desired_status text, device_id text, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $_$
DECLARE
    v_q     TEXT := btrim(p_query);
    v_me    TEXT := auth.uid()::text;
    -- LIKE 元字符转义:让查询串里的 % / _ 当字面量,不被用户注入成通配(子串搜索的 % 是我们自己加的）。
    v_like  TEXT := replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_');
BEGIN
    IF v_q = '' THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT u.id, u.gugu_number, u.display_name, u.avatar, u.bio, u.type,
           u.owner_user_id, u.agent_public, u.desired_status, u.device_id,
           u.created_at, u.updated_at
    FROM identity.users u
    WHERE u.id <> COALESCE(v_me, '')
      AND (
            -- 昵称子串(大小写不敏感)
            u.display_name ILIKE '%' || v_like || '%' ESCAPE '\'
            -- 咕咕号精确(纯数字查询时)。限 1-9 位:int4 上限 2147483647(10 位),9 位必然安全;
            -- 10 位以上的数字串不匹配此支(落空返回「未找到」),避免 v_q::integer 溢出使整个 RPC 报错。
            OR (v_q ~ '^\d{1,9}$' AND u.gugu_number = v_q::integer)
            -- 完整邮箱精确(regex 白名单 + 等值,无通配 → 不可枚举;email 仅在此 definer 内被读，绝不返回)
            OR (v_q ~ '^[A-Za-z0-9._+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$' AND lower(u.email) = lower(v_q))
          )
      -- agent 可见性(沿用客户端 searchUsers 语义):人 / 自己的 agent / 公开 agent
      AND (u.type <> 'agent' OR u.owner_user_id = v_me OR u.agent_public = true)
    ORDER BY (u.gugu_number IS NOT NULL) DESC, u.display_name
    LIMIT 20;
END;
$_$;


--
-- Name: server_login_mark_refused(uuid, text, jsonb); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.server_login_mark_refused(p_id uuid, p_user_id text, p_refusal jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
  update identity.server_login_requests
     set status = 'refused', refusal = p_refusal, refused_user_id = p_user_id, refused_at = now(),
         decided_at = coalesce(decided_at, now())
   where id = p_id;
$$;


--
-- Name: set_agent_desired_status(text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.set_agent_desired_status(p_agent_user_id text, p_desired_status text) RETURNS identity.users
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_agent identity.users;
    v_runtime identity.agent_runtime_states;
BEGIN
    IF p_desired_status NOT IN ('online', 'offline') THEN
        RAISE EXCEPTION 'Invalid agent desired status: %', p_desired_status;
    END IF;

    UPDATE identity.users
    SET desired_status = p_desired_status,
        updated_at = now()
    WHERE id = p_agent_user_id
      AND type = 'agent'
      AND owner_user_id = (SELECT auth.uid()::text)
    RETURNING *
    INTO v_agent;

    IF v_agent.id IS NULL THEN
        RAISE EXCEPTION 'Agent desired status is not writable by current user';
    END IF;

    IF p_desired_status = 'offline' AND v_agent.device_id IS NOT NULL THEN
        INSERT INTO identity.gugu_device_commands (
            user_id,
            device_id,
            type,
            payload
        )
        VALUES (
            v_agent.owner_user_id::uuid,
            v_agent.device_id,
            'agent.stop',
            jsonb_build_object('agent_user_id', v_agent.id)
        );
    END IF;

    SELECT *
    INTO v_runtime
    FROM identity.agent_runtime_states
    WHERE agent_user_id = p_agent_user_id;

    PERFORM realtime.send(
        jsonb_build_object(
            'runtime', jsonb_build_object(
                'agent_user_id', v_agent.id,
                'desired_status', v_agent.desired_status,
                'runtime_status', COALESCE(v_runtime.runtime_status, 'offline'),
                'activity_status', COALESCE(v_runtime.activity_status, 'idle'),
                'runtime_kind', v_runtime.runtime_kind,
                'runtime_label', v_runtime.runtime_label,
                'window_title', v_runtime.window_title,
                'pid', v_runtime.pid,
                'last_seen_at', v_runtime.last_seen_at,
                'updated_at', COALESCE(v_runtime.updated_at, v_agent.updated_at)
            )
        ),
        'runtime_changed',
        'agent:' || v_agent.id || ':runtime',
        true
    );

    RETURN v_agent;
END;
$$;


--
-- Name: set_agent_model_selection(text, jsonb); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.set_agent_model_selection(p_agent_user_id text, p_selection jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_agent     identity.users;
    v_selection JSONB;
    v_command   UUID;
BEGIN
    v_selection := identity.validate_agent_model_selection(p_selection);

    SELECT * INTO v_agent
    FROM identity.users
    WHERE id = p_agent_user_id
      AND type = 'agent'
      AND owner_user_id = (SELECT auth.uid()::text);

    IF v_agent.id IS NULL THEN
        RAISE EXCEPTION 'Agent model selection is not writable by current user';
    END IF;
    IF v_agent.device_id IS NULL THEN
        RAISE EXCEPTION 'Agent % is not bound to a device; nothing can apply a model selection', p_agent_user_id;
    END IF;

    INSERT INTO identity.agent_model_selections (agent_user_id, owner_user_id, desired, updated_at)
    VALUES (v_agent.id, v_agent.owner_user_id, v_selection, now())
    ON CONFLICT (agent_user_id) DO UPDATE
        SET desired = EXCLUDED.desired,
            owner_user_id = EXCLUDED.owner_user_id,
            apply_error = NULL,
            updated_at = now();

    INSERT INTO identity.gugu_device_commands (user_id, device_id, type, payload)
    VALUES (
        v_agent.owner_user_id::uuid,
        v_agent.device_id,
        'agent.set_model',
        jsonb_build_object('agent_user_id', v_agent.id, 'selection', v_selection)
    )
    RETURNING id INTO v_command;

    RETURN v_command;
END;
$$;


--
-- Name: set_agent_public(text, boolean); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.set_agent_public(p_agent_user_id text, p_agent_public boolean) RETURNS identity.users
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner_user_id TEXT := auth.uid()::text;
    v_agent identity.users%ROWTYPE;
BEGIN
    IF v_owner_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    UPDATE identity.users
       SET agent_public = COALESCE(p_agent_public, false),
           mycel_id = CASE
               WHEN COALESCE(p_agent_public, false) AND mycel_id IS NULL
                   THEN nextval('identity.mycel_id_seq')
               ELSE mycel_id
           END,
           updated_at = now()
     WHERE id = NULLIF(p_agent_user_id, '')
       AND type = 'agent'
       AND owner_user_id = v_owner_user_id
     RETURNING * INTO v_agent;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Agent is not owned by current user';
    END IF;

    RETURN v_agent;
END;
$$;


--
-- Name: agent_runtime_states; Type: TABLE; Schema: identity; Owner: -
--

CREATE TABLE identity.agent_runtime_states (
    agent_user_id text NOT NULL,
    owner_user_id text NOT NULL,
    runtime_status text DEFAULT 'unknown'::text NOT NULL,
    activity_status text DEFAULT 'idle'::text NOT NULL,
    runtime_kind text,
    runtime_label text,
    window_title text,
    pid integer,
    last_seen_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    recent_tool_type text,
    recent_actions text[],
    last_action_at timestamp with time zone,
    active_chat_id text,
    consecutive_deliver_failures integer DEFAULT 0 NOT NULL,
    agent_status text,
    agent_status_detail text,
    CONSTRAINT agent_runtime_states_activity_status_chk CHECK ((activity_status = ANY (ARRAY['idle'::text, 'running'::text]))),
    CONSTRAINT agent_runtime_states_agent_status_chk CHECK (
CASE
    WHEN (agent_status IS NULL) THEN (agent_status_detail IS NULL)
    WHEN (agent_status = 'working'::text) THEN ((agent_status_detail IS NULL) OR (agent_status_detail = ANY (ARRAY['running'::text, 'parked'::text])))
    WHEN (agent_status = 'needs_user'::text) THEN ((agent_status_detail IS NULL) OR (agent_status_detail = ANY (ARRAY['approval'::text, 'question'::text, 'plan'::text, 'dialog'::text])))
    WHEN (agent_status = 'idle'::text) THEN ((agent_status_detail IS NULL) OR (agent_status_detail = ANY (ARRAY['done'::text, 'plain'::text])))
    WHEN (agent_status = 'error'::text) THEN (agent_status_detail IS NULL)
    ELSE false
END),
    CONSTRAINT agent_runtime_states_deliver_failures_chk CHECK ((consecutive_deliver_failures >= 0)),
    CONSTRAINT agent_runtime_states_runtime_status_chk CHECK ((runtime_status = ANY (ARRAY['starting'::text, 'online'::text, 'offline'::text])))
);


--
-- Name: COLUMN agent_runtime_states.consecutive_deliver_failures; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.agent_runtime_states.consecutive_deliver_failures IS '#2175 连续异常 deliver 回合计数(终态失败+已读不回);成功回合清零;renderer 按阈值派生异常态。';


--
-- Name: COLUMN agent_runtime_states.agent_status; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.agent_runtime_states.agent_status IS '#6448 宿主状态写入者写下的基础态(idle / working / needs_user / error);NULL = 这一次写说不出读数,读方退回 activity_status。';


--
-- Name: COLUMN agent_runtime_states.agent_status_detail; Type: COMMENT; Schema: identity; Owner: -
--

COMMENT ON COLUMN identity.agent_runtime_states.agent_status_detail IS '#6448 附属态(只给显示):working → running / parked;needs_user → approval / question / plan / dialog;idle → done / plain。';


--
-- Name: set_agent_runtime_state(text, text, text, text, text, text, integer, timestamp with time zone, text, text[], timestamp with time zone, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.set_agent_runtime_state(p_agent_user_id text, p_runtime_status text DEFAULT NULL::text, p_activity_status text DEFAULT 'idle'::text, p_runtime_kind text DEFAULT NULL::text, p_runtime_label text DEFAULT NULL::text, p_window_title text DEFAULT NULL::text, p_pid integer DEFAULT NULL::integer, p_last_seen_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recent_tool_type text DEFAULT NULL::text, p_recent_actions text[] DEFAULT NULL::text[], p_last_action_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_active_chat_id text DEFAULT NULL::text, p_agent_status text DEFAULT NULL::text, p_agent_status_detail text DEFAULT NULL::text) RETURNS identity.agent_runtime_states
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_row identity.agent_runtime_states;
BEGIN
    IF NOT identity.can_write_agent_runtime_state(p_agent_user_id) THEN
        RAISE EXCEPTION 'Agent runtime state is not writable by current user';
    END IF;

    INSERT INTO identity.agent_runtime_states (
        agent_user_id, owner_user_id, runtime_status, activity_status, runtime_kind,
        runtime_label, window_title, pid, last_seen_at, recent_tool_type, recent_actions,
        last_action_at, active_chat_id, agent_status, agent_status_detail
    )
    VALUES (
        p_agent_user_id,
        (SELECT auth.uid()::text),
        COALESCE(p_runtime_status, 'offline'),
        COALESCE(p_activity_status, 'idle'),
        p_runtime_kind, p_runtime_label, p_window_title, p_pid,
        COALESCE(p_last_seen_at, now()),
        p_recent_tool_type, p_recent_actions, p_last_action_at,
        CASE WHEN COALESCE(p_activity_status, 'idle') = 'running' THEN p_active_chat_id ELSE NULL END,
        p_agent_status, p_agent_status_detail
    )
    ON CONFLICT (agent_user_id) DO UPDATE
    SET runtime_status = COALESCE(EXCLUDED.runtime_status, agent_runtime_states.runtime_status),
        activity_status = EXCLUDED.activity_status,
        runtime_kind = EXCLUDED.runtime_kind,
        runtime_label = EXCLUDED.runtime_label,
        window_title = EXCLUDED.window_title,
        pid = EXCLUDED.pid,
        last_seen_at = EXCLUDED.last_seen_at,
        recent_tool_type = COALESCE(EXCLUDED.recent_tool_type, agent_runtime_states.recent_tool_type),
        recent_actions = COALESCE(EXCLUDED.recent_actions, agent_runtime_states.recent_actions),
        last_action_at = COALESCE(EXCLUDED.last_action_at, agent_runtime_states.last_action_at),
        active_chat_id = CASE WHEN EXCLUDED.activity_status = 'running' THEN EXCLUDED.active_chat_id ELSE NULL END,
        -- 读数每次都覆盖:说不出读数的写(NULL)就是「这一行此刻没有读数」,❌ 留着上一句。
        agent_status = EXCLUDED.agent_status,
        agent_status_detail = EXCLUDED.agent_status_detail
    RETURNING *
    INTO v_row;

    RETURN v_row;
END;
$$;


--
-- Name: set_agent_runtime_state_owner(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.set_agent_runtime_state_owner() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner_user_id TEXT;
BEGIN
    SELECT u.owner_user_id
    INTO v_owner_user_id
    FROM identity.users u
    WHERE u.id = NEW.agent_user_id
      AND u.type = 'agent';

    IF v_owner_user_id IS NULL THEN
        RAISE EXCEPTION 'Agent runtime state requires an owned agent';
    END IF;

    NEW.owner_user_id := v_owner_user_id;
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;


--
-- Name: set_agent_runtime_state_with_api_key(text, text, text, text, text, text, text, integer, timestamp with time zone, text, text[], timestamp with time zone, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.set_agent_runtime_state_with_api_key(p_api_token text, p_agent_user_id text, p_runtime_status text DEFAULT NULL::text, p_activity_status text DEFAULT 'idle'::text, p_runtime_kind text DEFAULT NULL::text, p_runtime_label text DEFAULT NULL::text, p_window_title text DEFAULT NULL::text, p_pid integer DEFAULT NULL::integer, p_last_seen_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recent_tool_type text DEFAULT NULL::text, p_recent_actions text[] DEFAULT NULL::text[], p_last_action_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_active_chat_id text DEFAULT NULL::text) RETURNS identity.agent_runtime_states
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_key RECORD;
    v_row identity.agent_runtime_states;
BEGIN
    SELECT * INTO v_key FROM identity.verify_api_key(p_api_token) LIMIT 1;
    IF v_key.user_id IS NULL THEN
        RAISE EXCEPTION 'API key is invalid, revoked, or expired';
    END IF;
    IF NOT (
        'daemon:heartbeat' = ANY(v_key.scopes)
        OR 'agent:manage' = ANY(v_key.scopes)
    ) THEN
        RAISE EXCEPTION 'API key is missing daemon heartbeat scope';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM identity.users u
        WHERE u.id = p_agent_user_id AND u.type = 'agent' AND u.owner_user_id = v_key.user_id
    ) THEN
        RAISE EXCEPTION 'Agent runtime state is not writable by this API key';
    END IF;

    INSERT INTO identity.agent_runtime_states (
        agent_user_id, owner_user_id, runtime_status, activity_status, runtime_kind,
        runtime_label, window_title, pid, last_seen_at, recent_tool_type, recent_actions,
        last_action_at, active_chat_id, agent_status, agent_status_detail
    )
    VALUES (
        p_agent_user_id,
        v_key.user_id,
        COALESCE(p_runtime_status, 'offline'),
        COALESCE(p_activity_status, 'idle'),
        p_runtime_kind, p_runtime_label, p_window_title, p_pid,
        COALESCE(p_last_seen_at, now()),
        p_recent_tool_type, p_recent_actions, p_last_action_at,
        CASE WHEN COALESCE(p_activity_status, 'idle') = 'running' THEN p_active_chat_id ELSE NULL END,
        NULL, NULL
    )
    ON CONFLICT (agent_user_id) DO UPDATE
    SET runtime_status = COALESCE(EXCLUDED.runtime_status, agent_runtime_states.runtime_status),
        activity_status = EXCLUDED.activity_status,
        runtime_kind = EXCLUDED.runtime_kind,
        runtime_label = EXCLUDED.runtime_label,
        window_title = EXCLUDED.window_title,
        pid = EXCLUDED.pid,
        last_seen_at = EXCLUDED.last_seen_at,
        recent_tool_type = COALESCE(EXCLUDED.recent_tool_type, agent_runtime_states.recent_tool_type),
        recent_actions = COALESCE(EXCLUDED.recent_actions, agent_runtime_states.recent_actions),
        last_action_at = COALESCE(EXCLUDED.last_action_at, agent_runtime_states.last_action_at),
        active_chat_id = CASE WHEN EXCLUDED.activity_status = 'running' THEN EXCLUDED.active_chat_id ELSE NULL END,
        agent_status = NULL,
        agent_status_detail = NULL
    RETURNING *
    INTO v_row;

    RETURN v_row;
END;
$$;


--
-- Name: set_api_keys_updated_at(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.set_api_keys_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;


--
-- Name: settle_agent_provision_terminal(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.settle_agent_provision_terminal(p_provision_id uuid) RETURNS identity.agent_provisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_owner      TEXT := (SELECT auth.uid()::text);
  v_before     identity.agent_provisions;
  v_p          identity.agent_provisions;
  v_agent      identity.users;
  v_old_device TEXT;
BEGIN
  SELECT * INTO v_before FROM identity.agent_provisions WHERE id = p_provision_id;
  IF NOT FOUND OR v_before.existing_agent_user_id IS NULL OR v_owner IS NULL OR v_before.owner_user_id <> v_owner THEN
    RETURN identity.settle_agent_provision_terminal_pre_adopt_7199(p_provision_id);
  END IF;

  -- identity 优先(与 legacy 的锁序一致):先拿这个 agent 行的 NO KEY UPDATE —— 稍后要改它的 device_id。
  PERFORM 1 FROM identity.users WHERE id = v_before.existing_agent_user_id FOR NO KEY UPDATE;
  v_p := identity.settle_agent_provision_terminal_pre_adopt_7199(p_provision_id);

  -- 只在这一次从「没落定」变成 ready 时切家;重放(已 ready / completed)与 failed 原样返回。
  IF v_p.phase <> 'ready' OR v_before.phase IN ('ready', 'completed') THEN
    RETURN v_p;
  END IF;

  SELECT * INTO v_agent FROM identity.users
   WHERE id = v_p.existing_agent_user_id AND type = 'agent' AND owner_user_id = v_owner;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'adopt: agent % is no longer live or not owned by the caller', v_p.existing_agent_user_id;
  END IF;
  v_old_device := v_agent.device_id;

  IF v_old_device IS DISTINCT FROM v_p.device_id THEN
    PERFORM set_config('identity.agent_adopt_move_agent_id', v_agent.id, true);
    UPDATE identity.users
       SET device_id = v_p.device_id,
           local_path = NULLIF(COALESCE(v_p.project_path, ''), ''),
           updated_at = now()
     WHERE id = v_agent.id;
    PERFORM set_config('identity.agent_adopt_move_agent_id', '', true);

    -- 指向旧家的会话绑定作废;新家自己报上来的(device_id 已是新家)不动。
    DELETE FROM identity.agent_sessions
     WHERE agent_user_id = v_agent.id AND device_id IS NOT DISTINCT FROM v_old_device;
    -- 还没被旧家领走的投递改投新家;旧家已领走(running)的归它自己跑完。
    UPDATE identity.gugu_device_commands
       SET device_id = v_p.device_id
     WHERE type = 'agent.deliver' AND status = 'pending'
       AND device_id = v_old_device AND payload->>'agent_user_id' = v_agent.id;
    -- 旧家:拆运行时、撤已安排与投递登记(不删文件)。同事务只发这一次。
    IF v_old_device IS NOT NULL THEN
      INSERT INTO identity.gugu_device_commands (user_id, device_id, type, payload)
      VALUES (
        v_owner::uuid, v_old_device, 'agent.retire',
        jsonb_build_object('agent_user_id', v_agent.id, 'moved_to_device_id', v_p.device_id, 'reason', 'moved')
      );
    END IF;
  END IF;
  RETURN v_p;
END;
$$;


--
-- Name: settle_agent_provision_terminal_pre_adopt_7199(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.settle_agent_provision_terminal_pre_adopt_7199(p_provision_id uuid) RETURNS identity.agent_provisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner      TEXT := (SELECT auth.uid()::text);
    v_p          identity.agent_provisions;
    v_cmd_status TEXT;
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    PERFORM identity.assert_provision_owner_live(v_owner);

    -- Unlocked locate (which command to lock).
    SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id;
    IF NOT FOUND OR v_p.owner_user_id <> v_owner THEN RAISE EXCEPTION 'provision % not found for caller', p_provision_id; END IF;
    IF v_p.create_command_id IS NULL THEN RAISE EXCEPTION 'provision % has no command to settle', p_provision_id; END IF;

    -- F5 identity lock FIRST (order: identity → command → operation/member): matches remove_owned_agent's
    -- identity→command order, so settle and a concurrent governed removal never form an AB-BA cycle. The erase
    -- advisory does NOT cover ordinary removal, so correctness comes from THIS shared resource order, not the fence.
    PERFORM 1 FROM identity.users WHERE id IN (v_owner, v_p.agent_user_id) ORDER BY id FOR KEY SHARE;
    -- command lock + read true terminal — reject if not yet terminal.
    SELECT status INTO v_cmd_status FROM identity.gugu_device_commands WHERE id = v_p.create_command_id FOR UPDATE;
    IF v_cmd_status IS NULL THEN RAISE EXCEPTION 'provision % command missing', p_provision_id; END IF;
    IF v_cmd_status NOT IN ('done','error') THEN
        RAISE EXCEPTION 'provision % command not terminal yet (status=%)', p_provision_id, v_cmd_status;
    END IF;
    -- operation/member (last) + re-read.
    SELECT * INTO v_p FROM identity.agent_provisions WHERE id = p_provision_id FOR UPDATE;
    IF v_p.phase NOT IN ('awaiting_terminal','ready','failed','completed') THEN
        RAISE EXCEPTION 'provision % in phase % cannot be settled', p_provision_id, v_p.phase;
    END IF;

    IF v_cmd_status = 'done' THEN
        IF v_p.phase IN ('ready','completed') THEN RETURN v_p; END IF;   -- idempotent
        -- Scrub the raw inherited-memory bytes from BOTH the terminal command payload AND the provision row in
        -- this same fenced txn: the runtime has consumed it and neither history import nor complete needs it, so
        -- a ready/completed member and its terminal command never retain raw memory. memory_sources (non-secret) stays.
        UPDATE identity.gugu_device_commands SET payload = payload - 'memory_content' WHERE id = v_p.create_command_id;
        UPDATE identity.agent_provisions SET phase = 'ready', error = NULL, memory_content = NULL, updated_at = now()
        WHERE id = p_provision_id RETURNING * INTO v_p;
        RETURN v_p;
    ELSE
        IF v_p.phase = 'failed' THEN RETURN v_p; END IF;   -- idempotent
        -- Scrub raw memory from the terminal ERROR command payload, but RETAIN the provision-row copy so a
        -- same-agent retry can rebuild an identical command (row retains only while failed/retryable).
        UPDATE identity.gugu_device_commands SET payload = payload - 'memory_content' WHERE id = v_p.create_command_id;
        UPDATE identity.agent_provisions SET phase = 'failed', error = 'agent_create_command_error', updated_at = now()
        WHERE id = p_provision_id RETURNING * INTO v_p;
        UPDATE identity.agent_provision_operations SET phase = 'failed', error = 'member_provision_failed', updated_at = now()
        WHERE id = v_p.operation_id AND phase NOT IN ('completed','cancelled');
        RETURN v_p;
    END IF;
END;
$$;


--
-- Name: agent_provision_operations; Type: TABLE; Schema: identity; Owner: -
--

CREATE TABLE identity.agent_provision_operations (
    id uuid NOT NULL,
    owner_user_id text NOT NULL,
    device_id text NOT NULL,
    kind text NOT NULL,
    payload_hash text NOT NULL,
    blueprint jsonb NOT NULL,
    phase text DEFAULT 'provisioning_members'::text NOT NULL,
    group_chat_id text,
    concurrency_limit smallint DEFAULT 2 NOT NULL,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_provision_operations_concurrency_limit_check CHECK ((concurrency_limit >= 1)),
    CONSTRAINT agent_provision_operations_kind_check CHECK ((kind = ANY (ARRAY['single'::text, 'team'::text]))),
    CONSTRAINT agent_provision_operations_phase_check CHECK ((phase = ANY (ARRAY['provisioning_members'::text, 'completed'::text, 'failed'::text, 'cleaning_up'::text, 'cancelled'::text])))
);


--
-- Name: settle_provision_cancellation(uuid); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.settle_provision_cancellation(p_operation_id uuid) RETURNS identity.agent_provision_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_owner     TEXT := (SELECT auth.uid()::text);
    v_op        identity.agent_provision_operations;
    r           RECORD;
    v_removed   BOOLEAN;
    v_remaining INT;
BEGIN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    PERFORM identity.assert_provision_owner_live(v_owner);

    SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id;
    IF NOT FOUND OR v_op.owner_user_id <> v_owner THEN RAISE EXCEPTION 'operation % not found for caller', p_operation_id; END IF;
    IF v_op.phase = 'cancelled' THEN RETURN v_op; END IF;   -- idempotent terminal
    -- settle only ADVANCES a cancel that cancel_agent_provision_operation already opened (operation → 'cleaning_up');
    -- it never starts one. ('cancelling' is a MEMBER phase; the operation itself only ever reaches 'cleaning_up'.)
    IF v_op.phase <> 'cleaning_up' THEN
        RAISE EXCEPTION 'settle_provision_cancellation: operation % is not in a cancel phase (%)', p_operation_id, v_op.phase;
    END IF;

    -- Per cancelling member: advance to 'cancelled' ONLY from postconditions the renderer cannot fabricate.
    FOR r IN SELECT * FROM identity.agent_provisions
             WHERE operation_id = p_operation_id AND phase = 'cancelling' FOR UPDATE LOOP
        v_removed := FALSE;
        IF r.provisioned_agent_user_id IS NULL AND r.agent_user_id IS NULL THEN
            -- F6: provably never bound an agent (queued / never-prepared — the binding sets provisioned_agent_user_id
            -- AND agent_user_id atomically and never clears the evidence) → nothing was created → cancelled directly.
            -- NOT keyed on the no-FK create_command_id column: removal deletes the command yet leaves that column
            -- dangling non-NULL, so a column-NULL test would wrongly refuse to converge (missing evidence ≠ success).
            v_removed := TRUE;
        ELSIF r.provisioned_agent_user_id IS NOT NULL THEN
            -- bound an agent (evidence set at prepare, survives the ON DELETE SET NULL null-out AND a removal that
            -- committed BEFORE cancel): terminal ONLY when every durable postcondition of remove_owned_agent holds
            -- for the SNAPSHOTTED agent, judged by EXISTENCE. AND, not OR.
            v_removed := (
                NOT EXISTS (SELECT 1 FROM identity.users u WHERE u.id = r.provisioned_agent_user_id::text)
                AND EXISTS (SELECT 1 FROM identity.agent_lifecycle_tombstones t
                             WHERE t.agent_user_id = r.provisioned_agent_user_id::text AND t.owner_user_id = v_owner)
                AND NOT EXISTS (SELECT 1 FROM identity.agent_runtime_states s
                                 WHERE s.agent_user_id = r.provisioned_agent_user_id::text)
                AND NOT EXISTS (SELECT 1 FROM identity.gugu_device_commands c
                                 WHERE c.payload->>'agent_user_id' = r.provisioned_agent_user_id::text)
            );
        END IF;

        IF v_removed THEN
            -- defensive raw-memory scrub on terminal (row + any residual create-command payload).
            IF r.create_command_id IS NOT NULL THEN
                UPDATE identity.gugu_device_commands SET payload = payload - 'memory_content' WHERE id = r.create_command_id;
            END IF;
            UPDATE identity.agent_provisions
            SET phase = 'cancelled', memory_content = NULL, updated_at = now()
            WHERE id = r.id;
        END IF;
    END LOOP;

    -- operation LAST: lock + re-validate, then terminal only when EVERY member is cancelled (else stay cleaning_up).
    SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id FOR UPDATE;
    IF v_op.phase = 'cancelled' THEN RETURN v_op; END IF;
    SELECT count(*) INTO v_remaining FROM identity.agent_provisions
    WHERE operation_id = p_operation_id AND phase <> 'cancelled';
    IF v_remaining = 0 THEN
        UPDATE identity.agent_provision_operations SET phase = 'cancelled', updated_at = now()
        WHERE id = p_operation_id RETURNING * INTO v_op;
    ELSE
        UPDATE identity.agent_provision_operations SET phase = 'cleaning_up', updated_at = now()
        WHERE id = p_operation_id RETURNING * INTO v_op;
    END IF;
    RETURN v_op;
END;
$$;


--
-- Name: stamp_agent_provision_command_id(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.stamp_agent_provision_command_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
    v_updated INTEGER;
BEGIN
    IF NEW.create_command_id IS NULL
       OR NEW.create_command_id IS NOT DISTINCT FROM OLD.create_command_id THEN
        RETURN NEW;
    END IF;

    UPDATE identity.gugu_device_commands
    SET payload = payload || jsonb_build_object('provision_id', NEW.id::text)
    WHERE id = NEW.create_command_id
      AND type = 'agent.create'
      AND user_id = NEW.owner_user_id::uuid
      AND device_id = NEW.device_id;
    GET DIAGNOSTICS v_updated = ROW_COUNT;
    IF v_updated <> 1 THEN
        RAISE EXCEPTION 'provision % command % is missing or not agent.create', NEW.id, NEW.create_command_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: start_agent_provision_operation(uuid, text, jsonb, jsonb, jsonb, text, text, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.start_agent_provision_operation(p_operation_id uuid, p_device_id text, p_blueprint jsonb, p_memory_content jsonb DEFAULT NULL::jsonb, p_initial_message jsonb DEFAULT NULL::jsonb, p_model text DEFAULT NULL::text, p_effort text DEFAULT NULL::text, p_permission_mode text DEFAULT NULL::text, p_child_harness text DEFAULT NULL::text, p_first_task text DEFAULT NULL::text) RETURNS identity.agent_provision_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_owner        TEXT := (SELECT auth.uid()::text);
  v_op           identity.agent_provision_operations;
  v_blueprint    JSONB := p_blueprint;
  v_member       JSONB;
  v_existing_id  TEXT;
  v_agent        identity.users;
  v_profile_type TEXT;
  v_known        BOOLEAN;
  v_row          identity.agent_provisions;
BEGIN
  IF p_blueprint IS NOT NULL AND jsonb_typeof(p_blueprint) = 'object'
     AND jsonb_typeof(p_blueprint->'members') = 'array'
     AND EXISTS (
       SELECT 1 FROM jsonb_array_elements(p_blueprint->'members') e
        WHERE jsonb_typeof(e) = 'object' AND e ? 'existing_agent_user_id'
     ) THEN
    IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
    IF p_blueprint->>'kind' <> 'single' OR jsonb_array_length(p_blueprint->'members') <> 1 THEN
      RAISE EXCEPTION 'adopt: existing_agent_user_id is only valid for a single blueprint with exactly one member';
    END IF;
    v_member := p_blueprint->'members'->0;
    v_existing_id := v_member->>'existing_agent_user_id';
    IF jsonb_typeof(v_member->'existing_agent_user_id') <> 'string'
       OR v_existing_id !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
      RAISE EXCEPTION 'adopt: existing_agent_user_id must be an agent id (uuid)';
    END IF;
    -- 不继承记忆、不导入历史、不带首条消息 / 第一件事:文件由客户端拷过去,这条身份已经有自己的历史。
    IF (v_member->'inherit_memory') IS DISTINCT FROM 'false'::jsonb
       OR (v_member->'history_import_required') IS DISTINCT FROM 'false'::jsonb
       OR (v_member ? 'memory_sources' AND jsonb_typeof(v_member->'memory_sources') <> 'null')
       OR (p_memory_content IS NOT NULL AND jsonb_typeof(p_memory_content) <> 'null')
       OR (p_initial_message IS NOT NULL AND jsonb_typeof(p_initial_message) <> 'null')
       OR NULLIF(btrim(COALESCE(p_first_task, '')), '') IS NOT NULL THEN
      RAISE EXCEPTION 'adopt: an existing agent moves with its own files; inherit_memory, history import, memory sources, initial message and first_task are not allowed';
    END IF;
    v_blueprint := jsonb_set(p_blueprint, '{members,0}', v_member - 'existing_agent_user_id');

    -- 新单才核对「现在的」事实;重放(同一单已存在)只核对它记着的是同一个 agent。
    SELECT EXISTS (SELECT 1 FROM identity.agent_provision_operations WHERE id = p_operation_id) INTO v_known;
    IF NOT v_known THEN
      SELECT * INTO v_agent FROM identity.users
       WHERE id = v_existing_id AND type = 'agent' AND owner_user_id = v_owner;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'adopt: agent % is not found or not owned by the caller', v_existing_id;
      END IF;
      SELECT ap.agent_type INTO v_profile_type FROM identity.agent_profiles ap WHERE ap.id = v_existing_id::uuid;
      IF v_profile_type IS NULL THEN
        RAISE EXCEPTION 'adopt: agent % has no profile', v_existing_id;
      END IF;
      IF v_profile_type <> COALESCE(v_member->>'agent_type', '') THEN
        RAISE EXCEPTION 'adopt: agent % is a % agent, the member says %', v_existing_id, v_profile_type, v_member->>'agent_type';
      END IF;
      IF v_agent.device_id IS NOT DISTINCT FROM p_device_id THEN
        RAISE EXCEPTION 'adopt: agent % already lives on device %', v_existing_id, p_device_id;
      END IF;
      IF EXISTS (
        SELECT 1 FROM identity.agent_provisions ap
         WHERE ap.existing_agent_user_id = v_existing_id AND ap.phase NOT IN ('completed', 'cancelled')
           AND ap.operation_id <> p_operation_id
      ) THEN
        RAISE EXCEPTION 'adopt: agent % already has a move in flight', v_existing_id;
      END IF;
    END IF;
  END IF;

  v_op := identity.start_agent_provision_operation_pre_adopt_7199(
    p_operation_id, p_device_id, v_blueprint, p_memory_content, p_initial_message,
    p_model, p_effort, p_permission_mode, p_child_harness, p_first_task
  );

  IF v_existing_id IS NOT NULL THEN
    SELECT * INTO v_row FROM identity.agent_provisions
     WHERE operation_id = p_operation_id AND member_key = (v_blueprint->'members'->0->>'member_key')
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'adopt: member % not found', (v_blueprint->'members'->0->>'member_key');
    END IF;
    IF v_row.existing_agent_user_id IS NOT NULL AND v_row.existing_agent_user_id <> v_existing_id THEN
      RAISE EXCEPTION 'adopt: replay names a different agent than the recorded one';
    END IF;
    -- 之前这一单是新生(没带 existing)再带它重放 = 改了意图,拒;只有刚建的行(还没记过)才记上。
    IF v_row.existing_agent_user_id IS NULL THEN
      IF v_row.phase NOT IN ('queued', 'preparing') OR v_row.agent_user_id IS NOT NULL THEN
        RAISE EXCEPTION 'adopt: an existing agent cannot be attached to an already-prepared member';
      END IF;
      UPDATE identity.agent_provisions SET existing_agent_user_id = v_existing_id, updated_at = now() WHERE id = v_row.id;
    END IF;
  END IF;
  RETURN v_op;
END;
$_$;


--
-- Name: start_agent_provision_operation_legacy_7199(uuid, text, jsonb, jsonb, jsonb, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.start_agent_provision_operation_legacy_7199(p_operation_id uuid, p_device_id text, p_blueprint jsonb, p_memory_content jsonb DEFAULT NULL::jsonb, p_initial_message jsonb DEFAULT NULL::jsonb, p_model text DEFAULT NULL::text, p_effort text DEFAULT NULL::text, p_permission_mode text DEFAULT NULL::text) RETURNS identity.agent_provision_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_op identity.agent_provision_operations;
  v_model TEXT := NULLIF(btrim(p_model), '');
  v_effort TEXT := NULLIF(btrim(p_effort), '');
  v_permission_mode TEXT := NULLIF(btrim(p_permission_mode), '');
  v_existing identity.agent_provisions;
  -- 原 _legacy_6264(首条消息)
  v_text TEXT;
  v_message_id TEXT;
  -- 原 _legacy_4567(开单本体)
    v_owner        TEXT := (SELECT auth.uid()::text);
    v_kind         TEXT;
    v_hash         TEXT;
    v_limit        SMALLINT;
    v_members      JSONB;
    v_norm_members JSONB := '[]'::jsonb;
    v_norm_bp      JSONB;
    m              JSONB;
    v_norm_m       JSONB;
    v_mkey         TEXT;
    v_srcs         JSONB;
    v_mc           JSONB;
    v_mc_hash      TEXT;
    v_srcs_arr     TEXT[];
    v_keys         TEXT[] := '{}';
    v_pids         TEXT[] := '{}';
BEGIN
  -- ── 校验:建模型选项(原 _legacy_7199)→ 首条消息(原 _legacy_6264),顺序与原来逐层调用时一致 ──
  IF v_model IS NOT NULL
     AND (length(v_model) > 200 OR v_model !~ '^[A-Za-z0-9._:/@+-]+$') THEN
    RAISE EXCEPTION 'model must be a model id from the create list';
  END IF;
  IF v_effort IS NOT NULL
     AND (length(v_effort) > 200 OR v_effort !~ '^[A-Za-z0-9._:/@+-]+$') THEN
    RAISE EXCEPTION 'effort must be an effort id from the create list';
  END IF;
  IF v_permission_mode IS NOT NULL AND v_permission_mode !~ '^[a-z][a-z-]{0,40}$' THEN
    RAISE EXCEPTION 'permission_mode must be a gugu permission mode';
  END IF;
  IF (v_model IS NOT NULL OR v_effort IS NOT NULL OR v_permission_mode IS NOT NULL)
     AND p_blueprint->>'kind' <> 'single' THEN
    RAISE EXCEPTION 'model / effort / permission_mode are only valid for a single agent';
  END IF;

  IF p_initial_message IS NOT NULL THEN
    IF jsonb_typeof(p_initial_message) <> 'object'
       OR EXISTS (SELECT 1 FROM jsonb_object_keys(p_initial_message) AS k(key)
                  WHERE key NOT IN ('text', 'client_message_id'))
       OR NULLIF(btrim(p_initial_message->>'text'), '') IS NULL
       OR NULLIF(btrim(p_initial_message->>'client_message_id'), '') IS NULL THEN
      RAISE EXCEPTION 'initial message must contain non-empty text and client_message_id';
    END IF;
    v_text := p_initial_message->>'text';
    v_message_id := p_initial_message->>'client_message_id';
    IF p_blueprint->>'kind' <> 'single' THEN
      RAISE EXCEPTION 'initial message is only valid for a single chat-page agent';
    END IF;
  END IF;

  -- ── 开单本体(原 _legacy_4567)。原来的提前 RETURN 换成 EXIT core:后面两步照样要跑 ──
  <<core>>
  BEGIN
      IF v_owner IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;
      PERFORM identity.assert_provision_owner_live(v_owner);
      IF NOT EXISTS (SELECT 1 FROM identity.gugu_devices WHERE device_id = p_device_id AND user_id::text = v_owner) THEN
          RAISE EXCEPTION 'device % is not owned by current user', p_device_id;
      END IF;

      -- ── kind-branched STRICT allowlist + shape validation ────────────────────────────────────────
      IF p_blueprint IS NULL OR jsonb_typeof(p_blueprint) <> 'object' THEN RAISE EXCEPTION 'blueprint must be a jsonb object'; END IF;
      IF p_memory_content IS NOT NULL AND jsonb_typeof(p_memory_content) <> 'object' THEN RAISE EXCEPTION 'p_memory_content must be a jsonb object'; END IF;
      v_kind := p_blueprint->>'kind';
      IF v_kind NOT IN ('single','team') THEN RAISE EXCEPTION 'blueprint.kind must be single|team'; END IF;

      IF v_kind = 'single' THEN
          -- single carries NO group intent at all; exactly one member; concurrency fixed at 1.
          IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_blueprint) AS ok(k)
                     WHERE k NOT IN ('kind','concurrency_limit','members')) THEN
              RAISE EXCEPTION 'single blueprint forbids team-only keys (group_chat_id/team_name/group_prompt)';
          END IF;
          v_limit := COALESCE((p_blueprint->>'concurrency_limit')::smallint, 1);
          IF v_limit <> 1 THEN RAISE EXCEPTION 'single blueprint.concurrency_limit must be 1'; END IF;
          v_members := p_blueprint->'members';
          IF v_members IS NULL OR jsonb_typeof(v_members) <> 'array' OR jsonb_array_length(v_members) <> 1 THEN
              RAISE EXCEPTION 'single blueprint.members must have exactly 1 member';
          END IF;
      ELSE
          IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_blueprint) AS ok(k)
                     WHERE k NOT IN ('kind','group_chat_id','team_name','group_prompt','concurrency_limit','members')) THEN
              RAISE EXCEPTION 'team blueprint has unexpected top-level keys';
          END IF;
          IF COALESCE(p_blueprint->>'group_chat_id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
              RAISE EXCEPTION 'team blueprint.group_chat_id must be a uuid';
          END IF;
          IF NULLIF(btrim(p_blueprint->>'team_name'), '') IS NULL OR length(p_blueprint->>'team_name') > 200 THEN
              RAISE EXCEPTION 'team blueprint.team_name is required and must be <= 200 chars';
          END IF;
          -- group_prompt is a REQUIRED team group field: present + a JSON string (empty '' allowed for "no
          -- charter"). Missing key, JSON null, or a non-string type all fail loud (never mapped silently to NULL).
          IF NOT (p_blueprint ? 'group_prompt') OR jsonb_typeof(p_blueprint->'group_prompt') <> 'string' THEN
              RAISE EXCEPTION 'team blueprint.group_prompt is required and must be a string';
          END IF;
          IF length(p_blueprint->>'group_prompt') > 8000 THEN RAISE EXCEPTION 'team blueprint.group_prompt too long'; END IF;
          v_limit := COALESCE((p_blueprint->>'concurrency_limit')::smallint, 2);
          IF v_limit < 1 THEN RAISE EXCEPTION 'team blueprint.concurrency_limit must be >= 1'; END IF;
          v_members := p_blueprint->'members';
          IF v_members IS NULL OR jsonb_typeof(v_members) <> 'array' OR jsonb_array_length(v_members) < 1 THEN
              RAISE EXCEPTION 'team blueprint.members must be a non-empty array';
          END IF;
      END IF;

      FOR m IN SELECT * FROM jsonb_array_elements(v_members) LOOP
          IF v_kind = 'single' THEN
              IF EXISTS (SELECT 1 FROM jsonb_object_keys(m) AS ok(k)
                         WHERE k NOT IN ('provision_id','member_key','display_name','agent_type','project_path','avatar','special_focus','inherit_memory','history_import_required','memory_sources')) THEN
                  RAISE EXCEPTION 'single member has unexpected keys (listen_mode forbidden)';
              END IF;
          ELSE
              IF EXISTS (SELECT 1 FROM jsonb_object_keys(m) AS ok(k)
                         WHERE k NOT IN ('provision_id','member_key','display_name','agent_type','project_path','avatar','special_focus','inherit_memory','history_import_required','memory_sources','listen_mode')) THEN
                  RAISE EXCEPTION 'team member has unexpected keys';
              END IF;
              -- listen_mode is REQUIRED for a team member: present, a non-null STRING, in the enum. Missing,
              -- JSON null, empty string, unknown value, or a non-string type all fail loud (never default silently).
              IF NOT (m ? 'listen_mode')
                 OR jsonb_typeof(m->'listen_mode') <> 'string'
                 OR (m->>'listen_mode') NOT IN ('passive','active') THEN
                  RAISE EXCEPTION 'team member.listen_mode is required and must be passive|active';
              END IF;
          END IF;
          IF COALESCE(m->>'provision_id','') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
              RAISE EXCEPTION 'member.provision_id must be a uuid';
          END IF;
          IF NULLIF(btrim(m->>'member_key'),'') IS NULL THEN RAISE EXCEPTION 'member.member_key is required'; END IF;
          IF NULLIF(btrim(m->>'display_name'),'') IS NULL THEN RAISE EXCEPTION 'member.display_name is required'; END IF;
          IF NULLIF(btrim(m->>'agent_type'),'') IS NULL THEN RAISE EXCEPTION 'member.agent_type is required'; END IF;
          -- inherit_memory + history_import_required: REQUIRED explicit strict booleans (never inferred/defaulted).
          IF NOT (m ? 'inherit_memory') OR jsonb_typeof(m->'inherit_memory') <> 'boolean' THEN
              RAISE EXCEPTION 'member.inherit_memory is required and must be a boolean';
          END IF;
          IF NOT (m ? 'history_import_required') OR jsonb_typeof(m->'history_import_required') <> 'boolean' THEN
              RAISE EXCEPTION 'member.history_import_required is required and must be a boolean';
          END IF;

          v_mkey := m->>'member_key';
          v_srcs := m->'memory_sources';
          v_mc   := CASE WHEN p_memory_content IS NOT NULL THEN p_memory_content->v_mkey ELSE NULL END;
          IF v_srcs IS NOT NULL AND jsonb_typeof(v_srcs) <> 'null' THEN
              -- memory_sources present: non-empty array of unique known sources, with content for EXACTLY them.
              IF jsonb_typeof(v_srcs) <> 'array' OR jsonb_array_length(v_srcs) = 0 THEN
                  RAISE EXCEPTION 'member.memory_sources must be a non-empty array when present';
              END IF;
              IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_srcs) s
                         WHERE jsonb_typeof(s) <> 'string' OR (s #>> '{}') NOT IN ('claude-code','codex')) THEN
                  RAISE EXCEPTION 'member.memory_sources must be strings in claude-code|codex';
              END IF;
              IF (SELECT count(DISTINCT s) FROM jsonb_array_elements_text(v_srcs) s) <> jsonb_array_length(v_srcs) THEN
                  RAISE EXCEPTION 'member.memory_sources must be unique';
              END IF;
              IF v_mc IS NULL OR jsonb_typeof(v_mc) <> 'object' THEN
                  RAISE EXCEPTION 'p_memory_content missing content for member % with selected memory_sources', v_mkey;
              END IF;
              IF (SELECT count(*) FROM jsonb_object_keys(v_mc)) <> jsonb_array_length(v_srcs)
                 OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(v_srcs) s WHERE NOT (v_mc ? s))
                 OR EXISTS (SELECT 1 FROM jsonb_each(v_mc) e WHERE jsonb_typeof(e.value) <> 'string') THEN
                  RAISE EXCEPTION 'p_memory_content for member % must map EXACTLY its memory_sources to string content', v_mkey;
              END IF;
              v_srcs_arr := ARRAY(SELECT jsonb_array_elements_text(v_srcs));
              v_mc_hash  := md5(v_mc::text);
          ELSE
              -- no sources selected → there must be NO content supplied for this member.
              IF v_mc IS NOT NULL AND jsonb_typeof(v_mc) <> 'null' THEN
                  RAISE EXCEPTION 'p_memory_content has content for member % which selected no memory_sources', v_mkey;
              END IF;
              v_srcs_arr := NULL;
              v_mc       := NULL;
              v_mc_hash  := NULL;
          END IF;

          -- normalized member = INPUT member + server-derived memory_content_hash (only when sources present).
          v_norm_m := m || (CASE WHEN v_mc_hash IS NOT NULL THEN jsonb_build_object('memory_content_hash', v_mc_hash) ELSE '{}'::jsonb END);
          v_norm_members := v_norm_members || jsonb_build_array(v_norm_m);

          v_keys := v_keys || v_mkey;
          v_pids := v_pids || (m->>'provision_id');
      END LOOP;
      IF (SELECT count(DISTINCT x) FROM unnest(v_keys) x) <> cardinality(v_keys) THEN RAISE EXCEPTION 'member_key values must be unique'; END IF;
      IF (SELECT count(DISTINCT x) FROM unnest(v_pids) x) <> cardinality(v_pids) THEN RAISE EXCEPTION 'provision_id values must be unique'; END IF;
      -- reject any p_memory_content key not matching a member (content without sources / unknown member).
      IF p_memory_content IS NOT NULL AND EXISTS (
          SELECT 1 FROM jsonb_object_keys(p_memory_content) AS k(key) WHERE key <> ALL(v_keys)
      ) THEN
          RAISE EXCEPTION 'p_memory_content has keys not matching any member';
      END IF;

      -- NORMALIZED stored blueprint = INPUT with members replaced by the normalized members. jsonb text is
      -- canonical (sorted keys) → operation hash is stable across equal-value inputs regardless of key order.
      v_norm_bp := jsonb_set(p_blueprint, '{members}', v_norm_members);
      v_hash := md5(v_norm_bp::text);

      -- Idempotent replay: re-normalized new INPUT must match the stored NORMALIZED blueprint + hash + kind.
      SELECT * INTO v_op FROM identity.agent_provision_operations WHERE id = p_operation_id FOR UPDATE;
      IF FOUND THEN
          IF v_op.owner_user_id <> v_owner THEN RAISE EXCEPTION 'operation % not owned by caller', p_operation_id; END IF;
          -- device is part of the operation's durable intent: same id + same blueprint but a DIFFERENT device is a
          -- divergent intent, not an idempotent success — never silently return the original (old-device) operation.
          IF v_op.blueprint <> v_norm_bp OR v_op.payload_hash <> v_hash OR v_op.kind <> v_kind
             OR v_op.device_id IS DISTINCT FROM p_device_id THEN
              RAISE EXCEPTION 'operation % already exists with a different blueprint/device (same-id divergent intent)', p_operation_id;
          END IF;
          EXIT core;
      END IF;

      INSERT INTO identity.agent_provision_operations (id, owner_user_id, device_id, kind, payload_hash, blueprint, concurrency_limit)
      VALUES (p_operation_id, v_owner, p_device_id, v_kind, v_hash, v_norm_bp, v_limit)
      RETURNING * INTO v_op;

      -- Member rows from the NORMALIZED members. Raw memory bytes are stored in memory_content (cleared later);
      -- the per-member payload_hash is the shared provision_member_hash (prepare re-derives the same from the row).
      FOR v_norm_m IN SELECT * FROM jsonb_array_elements(v_norm_members) LOOP
          v_mkey := v_norm_m->>'member_key';
          v_srcs := v_norm_m->'memory_sources';
          v_srcs_arr := CASE WHEN v_srcs IS NOT NULL AND jsonb_typeof(v_srcs) = 'array'
                             THEN ARRAY(SELECT jsonb_array_elements_text(v_srcs)) ELSE NULL END;
          v_mc := CASE WHEN p_memory_content IS NOT NULL THEN p_memory_content->v_mkey ELSE NULL END;
          INSERT INTO identity.agent_provisions (
              id, owner_user_id, operation_id, member_key, device_id,
              display_name, agent_type, project_path, avatar, special_focus,
              inherit_memory, memory_sources, memory_content, memory_content_hash, history_import_required,
              payload_hash, phase
          ) VALUES (
              (v_norm_m->>'provision_id')::uuid, v_owner, p_operation_id, v_mkey, p_device_id,
              v_norm_m->>'display_name', v_norm_m->>'agent_type', NULLIF(v_norm_m->>'project_path',''), NULLIF(v_norm_m->>'avatar',''),
              NULLIF(v_norm_m->>'special_focus',''),
              -- F2: persist the server-derived memory hash immutably; the shared per-member hash consumes THAT
              -- (not raw memory_content), so prepare re-derives the same payload_hash after the raw bytes are scrubbed.
              (v_norm_m->>'inherit_memory')::boolean, v_srcs_arr, v_mc, v_norm_m->>'memory_content_hash', (v_norm_m->>'history_import_required')::boolean,
              identity.provision_member_hash(
                  p_operation_id, v_mkey, v_norm_m->>'display_name', v_norm_m->>'agent_type',
                  NULLIF(v_norm_m->>'project_path',''), NULLIF(v_norm_m->>'avatar',''), NULLIF(v_norm_m->>'special_focus',''),
                  p_device_id, (v_norm_m->>'inherit_memory')::boolean, (v_norm_m->>'history_import_required')::boolean,
                  v_srcs_arr, v_norm_m->>'memory_content_hash'),
              'queued'
          );
      END LOOP;
      EXIT core;
  END core;

  -- ── 记下首条消息(原 _legacy_6264 的后半)──
  IF v_text IS NOT NULL THEN
    DECLARE
      v_existing identity.agent_provisions;
    BEGIN
      SELECT * INTO v_existing
        FROM identity.agent_provisions
       WHERE operation_id = p_operation_id
         AND member_key = (p_blueprint->'members'->0->>'member_key')
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'initial message member % not found', (p_blueprint->'members'->0->>'member_key');
      END IF;
      IF v_existing.initial_message_text IS NOT NULL OR v_existing.initial_message_id IS NOT NULL THEN
        IF v_existing.initial_message_text IS DISTINCT FROM v_text
           OR v_existing.initial_message_id IS DISTINCT FROM v_message_id THEN
          RAISE EXCEPTION 'initial message replay has divergent text or client_message_id';
        END IF;
      ELSIF v_existing.phase NOT IN ('queued','preparing') THEN
        RAISE EXCEPTION 'initial message cannot be attached after member preparation';
      ELSE
        UPDATE identity.agent_provisions
           SET initial_message_text = v_text,
               initial_message_id = v_message_id,
               updated_at = now()
         WHERE id = v_existing.id;
      END IF;
    END;
  END IF;

  -- ── 记下模型选项(原 _legacy_7199 的后半)──
  IF v_model IS NOT NULL OR v_effort IS NOT NULL OR v_permission_mode IS NOT NULL THEN
    SELECT * INTO v_existing
      FROM identity.agent_provisions
     WHERE operation_id = p_operation_id
       AND member_key = (p_blueprint->'members'->0->>'member_key')
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'create-choice member % not found', (p_blueprint->'members'->0->>'member_key');
    END IF;
    -- 重放:已记下的值必须一致;逐项判,一项分歧就拒。
    IF v_model IS NOT NULL AND v_existing.model IS NOT NULL
       AND v_existing.model IS DISTINCT FROM v_model THEN
      RAISE EXCEPTION 'model replay diverges from the recorded model';
    END IF;
    IF v_effort IS NOT NULL AND v_existing.effort IS NOT NULL
       AND v_existing.effort IS DISTINCT FROM v_effort THEN
      RAISE EXCEPTION 'effort replay diverges from the recorded effort';
    END IF;
    IF v_permission_mode IS NOT NULL AND v_existing.permission_mode IS NOT NULL
       AND v_existing.permission_mode IS DISTINCT FROM v_permission_mode THEN
      RAISE EXCEPTION 'permission_mode replay diverges from the recorded permission_mode';
    END IF;
    IF (v_model IS NOT NULL AND v_existing.model IS NULL)
       OR (v_effort IS NOT NULL AND v_existing.effort IS NULL)
       OR (v_permission_mode IS NOT NULL AND v_existing.permission_mode IS NULL) THEN
      IF v_existing.phase NOT IN ('queued','preparing') THEN
        RAISE EXCEPTION 'create choices cannot be attached after member preparation';
      END IF;
      UPDATE identity.agent_provisions
         SET model = COALESCE(model, v_model),
             effort = COALESCE(effort, v_effort),
             permission_mode = COALESCE(permission_mode, v_permission_mode),
             updated_at = now()
       WHERE id = v_existing.id;
    END IF;
  END IF;
  RETURN v_op;
END;
$_$;


--
-- Name: start_agent_provision_operation_pre_adopt_7199(uuid, text, jsonb, jsonb, jsonb, text, text, text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.start_agent_provision_operation_pre_adopt_7199(p_operation_id uuid, p_device_id text, p_blueprint jsonb, p_memory_content jsonb DEFAULT NULL::jsonb, p_initial_message jsonb DEFAULT NULL::jsonb, p_model text DEFAULT NULL::text, p_effort text DEFAULT NULL::text, p_permission_mode text DEFAULT NULL::text, p_child_harness text DEFAULT NULL::text, p_first_task text DEFAULT NULL::text) RETURNS identity.agent_provision_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $_$
DECLARE
  v_op identity.agent_provision_operations;
  v_child_harness TEXT := NULLIF(btrim(p_child_harness), '');
  v_first_task TEXT := NULLIF(btrim(p_first_task), '');
  v_existing identity.agent_provisions;
BEGIN
  IF v_child_harness IS NOT NULL AND v_child_harness !~ '^[a-z][a-z0-9-]{0,40}$' THEN
    RAISE EXCEPTION 'child_harness must be a harness id';
  END IF;
  IF v_first_task IS NOT NULL AND length(v_first_task) > 8000 THEN
    RAISE EXCEPTION 'first_task is longer than 8000 characters';
  END IF;
  IF v_first_task IS NOT NULL AND p_initial_message IS NOT NULL AND jsonb_typeof(p_initial_message) <> 'null' THEN
    RAISE EXCEPTION 'first_task and initial_message are mutually exclusive: a new agent has one first turn';
  END IF;
  IF (v_child_harness IS NOT NULL OR v_first_task IS NOT NULL)
     AND p_blueprint->>'kind' <> 'single' THEN
    RAISE EXCEPTION 'child_harness / first_task are only valid for a single agent';
  END IF;

  v_op := identity.start_agent_provision_operation_legacy_7199(
    p_operation_id, p_device_id, p_blueprint, p_memory_content, p_initial_message,
    p_model, p_effort, p_permission_mode
  );

  IF v_child_harness IS NOT NULL OR v_first_task IS NOT NULL THEN
    SELECT * INTO v_existing
      FROM identity.agent_provisions
     WHERE operation_id = p_operation_id
       AND member_key = (p_blueprint->'members'->0->>'member_key')
     FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'create-choice member % not found', (p_blueprint->'members'->0->>'member_key');
    END IF;
    -- 重放:已记下的值必须一致;逐项判,一项分歧就拒。
    IF v_child_harness IS NOT NULL AND v_existing.child_harness IS NOT NULL
       AND v_existing.child_harness IS DISTINCT FROM v_child_harness THEN
      RAISE EXCEPTION 'child_harness replay diverges from the recorded child_harness';
    END IF;
    IF v_first_task IS NOT NULL AND v_existing.first_task IS NOT NULL
       AND v_existing.first_task IS DISTINCT FROM v_first_task THEN
      RAISE EXCEPTION 'first_task replay diverges from the recorded first_task';
    END IF;
    IF (v_child_harness IS NOT NULL AND v_existing.child_harness IS NULL)
       OR (v_first_task IS NOT NULL AND v_existing.first_task IS NULL) THEN
      IF v_existing.phase NOT IN ('queued','preparing') THEN
        RAISE EXCEPTION 'create choices cannot be attached after member preparation';
      END IF;
      UPDATE identity.agent_provisions
         SET child_harness = COALESCE(child_harness, v_child_harness),
             first_task = COALESCE(first_task, v_first_task),
             updated_at = now()
       WHERE id = v_existing.id;
    END IF;
  END IF;
  RETURN v_op;
END;
$_$;


--
-- Name: storage_actor_is_live(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.storage_actor_is_live() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    actor_id TEXT := (SELECT auth.uid()::text);
BEGIN
    IF actor_id IS NULL THEN RETURN false; END IF;
    PERFORM 1 FROM identity.users
    WHERE id = actor_id AND type = 'human'
    FOR KEY SHARE;
    RETURN FOUND;
END;
$$;


--
-- Name: storage_object_is_referenced(text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.storage_object_is_referenced(p_bucket_id text, p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
    SELECT EXISTS (SELECT 1 FROM chat.file_blobs b WHERE b.bucket_id = p_bucket_id AND b.object_name = p_name AND chat.file_blob_in_use(b.id))
        -- 从没登记成 blob 的对象(群头像、动态、老消息……):只剩老式引用。
        OR EXISTS (SELECT 1 FROM chat.messages m WHERE m.storage_bucket_id = p_bucket_id AND m.storage_object_name = p_name)
        OR EXISTS (SELECT 1 FROM chat.chats c WHERE c.avatar_storage_bucket_id = p_bucket_id AND c.avatar_storage_object_name = p_name)
        OR EXISTS (SELECT 1 FROM chat.group_outputs o WHERE o.storage_bucket_id = p_bucket_id AND o.storage_object_name = p_name);
$$;


--
-- Name: sweep_device_leases(integer); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.sweep_device_leases(p_limit integer DEFAULT 1000) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'chat', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_flipped INTEGER := 0;
BEGIN
    IF p_limit IS NULL OR p_limit <= 0 THEN
        RAISE EXCEPTION 'sweep_device_leases requires a positive p_limit (got %)', p_limit;
    END IF;

    -- 一轮有界:一次机房级的租约集体过期(库重启、网络分区恢复)会让成千上万行同时到期,
    -- 而每一行都要触发一次 publish。宁可分几轮追上,也不要一条语句放出一场广播风暴。
    WITH expired AS (
        SELECT d.device_id
          FROM identity.gugu_devices d
         WHERE d.status = 'online'
           AND d.last_seen_at < now() - interval '2 minutes'   -- = DEVICE_ONLINE_STALE_MS
         ORDER BY d.last_seen_at
         LIMIT p_limit
         FOR UPDATE SKIP LOCKED
    )
    UPDATE identity.gugu_devices d
       SET status     = 'offline',
           updated_at = now()
      FROM expired e
     WHERE d.device_id = e.device_id;

    GET DIAGNOSTICS v_flipped = ROW_COUNT;

    UPDATE identity.device_lease_sweeps
       SET last_run_at  = now(),
           last_flipped = v_flipped
     WHERE id;

    IF v_flipped >= p_limit THEN
        -- 撞到上限 = 还有没扫完的,下一轮继续。说出来,不要让「追不上」看起来像「扫干净了」。
        RAISE WARNING 'sweep_device_leases hit its per-run bound (% rows); the remainder waits for the next run', p_limit;
    END IF;

    RETURN v_flipped;
END;
$$;


--
-- Name: sync_agent_profile_user(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.sync_agent_profile_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    requested_device_id TEXT := NULLIF(current_setting('identity.agent_create_device_id', true), '');
    fallback_device_id TEXT; v_avatar TEXT; v_rows INTEGER;
BEGIN
    IF requested_device_id IS NULL THEN
        SELECT kd.device_id INTO fallback_device_id
        FROM identity.gugu_devices kd
        WHERE kd.user_id::text = NEW.owner_id::text
        ORDER BY kd.last_seen_at DESC
        LIMIT 1;
    END IF;

    v_avatar := CASE
        WHEN identity.is_valid_avatar_url(NULLIF(NEW.avatar, '')) THEN NEW.avatar
        ELSE NULL
    END;
    INSERT INTO identity.users (id, type, display_name, avatar, owner_user_id, device_id, mycel_id, created_at, updated_at)
    VALUES (
        NEW.id::text, 'agent', NEW.display_name, v_avatar, NEW.owner_id::text,
        COALESCE(requested_device_id, fallback_device_id), NULL, NEW.created_at, now()
    )
    -- 冲突只可能是「同一个主人的 agent 重新同步」才更新;type 与 owner_user_id 因此不用也不许再写。
    ON CONFLICT (id) DO UPDATE SET
        display_name = EXCLUDED.display_name,
        avatar = EXCLUDED.avatar,
        device_id = COALESCE(identity.users.device_id, EXCLUDED.device_id),
        updated_at = now()
    WHERE identity.users.type = 'agent'
      AND identity.users.owner_user_id = EXCLUDED.owner_user_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
        RAISE EXCEPTION 'agent id % is already taken by another identity', NEW.id
            USING ERRCODE = 'unique_violation';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: upsert_agent_session(text, text, text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.upsert_agent_session(p_agent_user_id text, p_provider_session_id text, p_runtime_kind text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
  v_device_id TEXT;
BEGIN
  IF p_agent_user_id IS NULL OR p_provider_session_id IS NULL THEN
    RAISE EXCEPTION 'upsert_agent_session requires agent_user_id and provider_session_id';
  END IF;
  -- owner-only: the caller must own the agent (auth.uid() = agent's owner_user_id).
  IF NOT identity.can_write_agent_runtime_state(p_agent_user_id) THEN
    RAISE EXCEPTION 'not allowed to write agent session for %', p_agent_user_id;
  END IF;
  SELECT u.device_id INTO v_device_id
  FROM identity.users u
  WHERE u.id = p_agent_user_id AND u.type = 'agent';

  INSERT INTO identity.agent_sessions (agent_user_id, provider_session_id, device_id, runtime_kind, last_bound_at)
  VALUES (p_agent_user_id, p_provider_session_id, v_device_id, p_runtime_kind, now())
  ON CONFLICT (agent_user_id) DO UPDATE SET
    provider_session_id = EXCLUDED.provider_session_id,
    device_id           = EXCLUDED.device_id,
    runtime_kind        = EXCLUDED.runtime_kind,
    last_bound_at       = now();
END;
$$;


--
-- Name: users_block_device_id_change(); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.users_block_device_id_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.device_id IS DISTINCT FROM NEW.device_id
       AND OLD.device_id IS NOT NULL THEN
        -- 搬家的 settle 路径在同一事务里把开关设成这个 agent 的 id;别的 agent / 别的路径一概照旧拒绝。
        IF NEW.type = 'agent'
           AND NULLIF(current_setting('identity.agent_adopt_move_agent_id', true), '') IS NOT DISTINCT FROM NEW.id THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION
            'identity.users.device_id is immutable once set (was %, attempted %)',
            OLD.device_id, NEW.device_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_agent_model_selection(jsonb); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.validate_agent_model_selection(p_selection jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'identity', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_source   TEXT;
    v_model    TEXT;
    v_protocol TEXT;
BEGIN
    IF p_selection IS NULL OR jsonb_typeof(p_selection) <> 'object' THEN
        RAISE EXCEPTION 'agent model selection must be a JSON object';
    END IF;
    v_source := p_selection->>'source';
    IF v_source = 'default' THEN
        RETURN jsonb_build_object('source', 'default');
    END IF;
    v_model := btrim(COALESCE(p_selection->>'modelId', ''));
    IF v_model = '' OR length(v_model) > 128 THEN
        RAISE EXCEPTION 'agent model selection requires a modelId (1..128 chars)';
    END IF;
    IF v_source = 'byok' THEN
        RETURN jsonb_build_object('source', 'byok', 'modelId', v_model);
    END IF;
    IF v_source = 'platform' THEN
        v_protocol := p_selection->>'protocol';
        IF v_protocol NOT IN ('anthropic-messages', 'openai-responses', 'gemini-generate-content') THEN
            RAISE EXCEPTION 'agent model selection has an invalid protocol: %', COALESCE(v_protocol, '<null>');
        END IF;
        RETURN jsonb_build_object('source', 'platform', 'modelId', v_model, 'protocol', v_protocol);
    END IF;
    RAISE EXCEPTION 'agent model selection has an invalid source: %', COALESCE(v_source, '<null>');
END;
$$;


--
-- Name: verify_api_key(text); Type: FUNCTION; Schema: identity; Owner: -
--

CREATE FUNCTION identity.verify_api_key(p_token text) RETURNS TABLE(user_id text, key_id text, scopes text[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public', 'extensions', 'pg_catalog'
    AS $$
DECLARE
    v_hash TEXT;
BEGIN
    IF p_token IS NULL OR length(p_token) < 16 THEN
        RETURN;
    END IF;

    v_hash := encode(digest(p_token, 'sha256'), 'hex');

    RETURN QUERY
    UPDATE identity.api_keys k
    SET last_used_at = now(),
        updated_at = now()
    WHERE k.key_hash = v_hash
      AND k.key_prefix = left(p_token, 12)
      AND k.revoked_at IS NULL
      AND (k.expires_at IS NULL OR k.expires_at > now())
    RETURNING k.user_id::text, k.id::text, k.scopes;
END;
$$;


--
-- Name: broadcast_feed_changed(); Type: FUNCTION; Schema: moments; Owner: -
--

CREATE FUNCTION moments.broadcast_feed_changed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'moments', 'chat', 'identity', 'realtime', 'public', 'pg_catalog'
    AS $$
DECLARE
    v_post_id TEXT;
    v_author_id TEXT;
    v_area TEXT;
    v_is_official BOOLEAN := false;
    v_viewer_id TEXT;
BEGIN
    IF TG_TABLE_NAME = 'posts' THEN
        v_post_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.id ELSE NEW.id END;
        v_author_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.user_id ELSE NEW.user_id END;
        v_area := 'posts';
        SELECT COALESCE(u.is_official, false)
        INTO v_is_official
        FROM identity.users u
        WHERE u.id = v_author_id;
    ELSIF TG_TABLE_NAME = 'post_media' THEN
        v_post_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.post_id ELSE NEW.post_id END;
        v_area := 'posts';
    ELSIF TG_TABLE_NAME = 'post_likes' THEN
        v_post_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.post_id ELSE NEW.post_id END;
        v_area := 'likes';
    ELSIF TG_TABLE_NAME = 'post_comments' THEN
        v_post_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.post_id ELSE NEW.post_id END;
        v_area := 'comments';
    ELSIF TG_TABLE_NAME = 'comment_media' THEN
        SELECT c.post_id
        INTO v_post_id
        FROM moments.post_comments c
        WHERE c.id = CASE WHEN TG_OP = 'DELETE' THEN OLD.comment_id ELSE NEW.comment_id END;
        v_area := 'comments';
    END IF;

    IF v_author_id IS NULL AND v_post_id IS NOT NULL THEN
        SELECT p.user_id, COALESCE(u.is_official, false)
        INTO v_author_id, v_is_official
        FROM moments.posts p
        LEFT JOIN identity.users u ON u.id = p.user_id
        WHERE p.id = v_post_id;
    END IF;

    IF v_post_id IS NOT NULL AND v_author_id IS NOT NULL THEN
        FOR v_viewer_id IN
            SELECT v_author_id
            UNION
            SELECT CASE
                WHEN f.user_a_id = v_author_id THEN f.user_b_id
                ELSE f.user_a_id
            END
            FROM identity.friendships f
            WHERE f.user_a_id = v_author_id OR f.user_b_id = v_author_id
            UNION
            SELECT u.id
            FROM identity.users u
            WHERE v_is_official
              AND u.type = 'human'
        LOOP
            PERFORM realtime.send(
                jsonb_build_object(
                    'area', v_area,
                    'op', lower(TG_OP),
                    'post_id', v_post_id
                ),
                'moments_changed',
                'gugu:user:' || v_viewer_id || ':events',
                true
            );
        END LOOP;
    END IF;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: can_view_post_author(text); Type: FUNCTION; Schema: moments; Owner: -
--

CREATE FUNCTION moments.can_view_post_author(p_author_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'moments', 'identity', 'public'
    AS $$
    SELECT p_author_id = (SELECT auth.uid()::text)
        OR moments.is_friend(p_author_id)
        OR EXISTS (
            SELECT 1 FROM identity.users u
            WHERE u.id = p_author_id AND u.is_official
        );
$$;


--
-- Name: is_friend(text); Type: FUNCTION; Schema: moments; Owner: -
--

CREATE FUNCTION moments.is_friend(p_user_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM identity.friendships
        WHERE (user_a_id = (SELECT auth.uid()::text) AND user_b_id = p_user_id)
           OR (user_b_id = (SELECT auth.uid()::text) AND user_a_id = p_user_id)
    );
$$;


--
-- Name: hook_before_user_created(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hook_before_user_created(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'identity', 'pg_catalog'
    AS $$
DECLARE
    v_email  TEXT := lower(btrim(COALESCE(event->'user'->>'email', '')));
    v_domain TEXT;
    v_labels TEXT[];
    v_rule   TEXT;
BEGIN
    IF v_email = '' OR position('@' IN v_email) = 0 THEN
        RETURN '{}'::JSONB;                        -- 无邮箱的建号路径(手机号/匿名,当前都关着)不归这里管
    END IF;
    v_domain := rtrim(substr(v_email, length(v_email) - position('@' IN reverse(v_email)) + 2), '.');
    v_labels := string_to_array(v_domain, '.');

    SELECT r.rule INTO v_rule
      FROM identity.signup_email_domain_rules r
     WHERE r.domain = ANY (ARRAY(
             SELECT array_to_string(v_labels[i:], '.')
               FROM generate_subscripts(v_labels, 1) AS i))
     ORDER BY length(r.domain) DESC
     LIMIT 1;

    IF v_rule = 'deny' THEN
        RETURN jsonb_build_object('error', jsonb_build_object(
            'http_code', 403,
            'message', '不支持使用临时邮箱注册，请换用常用邮箱。Disposable email addresses are not supported.'));
    END IF;
    RETURN '{}'::JSONB;
END;
$$;


--
-- Name: my_usage_daily(date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_usage_daily(p_from date, p_to date, p_device_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
    v_uid    UUID := auth.uid();
    v_result JSONB;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'my_usage_daily requires an authenticated caller' USING ERRCODE = '42501';
    END IF;
    IF p_from IS NULL OR p_to IS NULL THEN
        RAISE EXCEPTION 'my_usage_daily: p_from and p_to are required' USING ERRCODE = '22023';
    END IF;
    IF p_from > p_to THEN
        RAISE EXCEPTION 'my_usage_daily: p_from (%) is after p_to (%)', p_from, p_to USING ERRCODE = '22023';
    END IF;
    IF p_to - p_from + 1 > 400 THEN
        RAISE EXCEPTION 'my_usage_daily: range of % days exceeds the 400-day limit', p_to - p_from + 1
            USING ERRCODE = '22023';
    END IF;

    WITH scoped AS (
        SELECT u.*
        FROM public.usage_daily u
        WHERE u.user_id = v_uid
          AND u.day BETWEEN p_from AND p_to
          AND (p_device_id IS NULL OR u.device_id = p_device_id)
    ),
    totals AS (
        SELECT s.day, s.engine,
               SUM(s.sessions)::BIGINT           AS sessions,
               SUM(s.run_seconds)::BIGINT        AS run_seconds,
               SUM(s.input_tokens)::BIGINT       AS input_tokens,
               SUM(s.output_tokens)::BIGINT      AS output_tokens,
               SUM(s.cache_read_tokens)::BIGINT  AS cache_read_tokens,
               SUM(s.cache_write_tokens)::BIGINT AS cache_write_tokens,
               SUM(s.parallel_seconds)::BIGINT   AS parallel_seconds,
               MAX(s.peak_concurrency)           AS peak_concurrency
        FROM scoped s
        GROUP BY s.day, s.engine
    ),
    -- 三张「模型 → token」表同一个合并法:摊平成 (kind, 模型, 数) 再按键相加。
    model_entries AS (
        SELECT s.day, s.engine, m.kind, kv.key AS model, kv.value::NUMERIC AS tokens
        FROM scoped s
        CROSS JOIN LATERAL (VALUES ('all', s.models), ('gugu', s.gugu_models), ('byok', s.byok_models)) AS m(kind, doc)
        CROSS JOIN LATERAL jsonb_each(m.doc) AS kv(key, value)
    ),
    model_totals AS (
        SELECT x.day, x.engine,
               COALESCE(jsonb_object_agg(x.model, x.tokens) FILTER (WHERE x.kind = 'all'),  '{}'::jsonb) AS models,
               COALESCE(jsonb_object_agg(x.model, x.tokens) FILTER (WHERE x.kind = 'gugu'), '{}'::jsonb) AS gugu_models,
               COALESCE(jsonb_object_agg(x.model, x.tokens) FILTER (WHERE x.kind = 'byok'), '{}'::jsonb) AS byok_models
        FROM (
            SELECT e.day, e.engine, e.kind, e.model, SUM(e.tokens) AS tokens
            FROM model_entries e
            GROUP BY e.day, e.engine, e.kind, e.model
        ) x
        GROUP BY x.day, x.engine
    ),
    hour_totals AS (
        SELECT h.day, h.engine, array_agg(h.total ORDER BY h.slot) AS hours
        FROM (
            SELECT s.day, s.engine, x.slot, SUM(x.value)::BIGINT AS total
            FROM scoped s
            CROSS JOIN LATERAL unnest(s.hours) WITH ORDINALITY AS x(value, slot)
            GROUP BY s.day, s.engine, x.slot
        ) h
        GROUP BY h.day, h.engine
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'day',              to_char(t.day, 'YYYY-MM-DD'),
               'engine',           t.engine,
               'sessions',         t.sessions,
               'runSeconds',       t.run_seconds,
               'inputTokens',      t.input_tokens,
               'outputTokens',     t.output_tokens,
               'cacheReadTokens',  t.cache_read_tokens,
               'cacheWriteTokens', t.cache_write_tokens,
               'models',           COALESCE(mt.models, '{}'::jsonb),
               'guguModels',       COALESCE(mt.gugu_models, '{}'::jsonb),
               'byokModels',       COALESCE(mt.byok_models, '{}'::jsonb),
               'hours',            to_jsonb(COALESCE(ht.hours, array_fill(0::BIGINT, ARRAY[24]))),
               'parallelSeconds',  t.parallel_seconds,
               'peakConcurrency',  t.peak_concurrency
           ) ORDER BY t.day, t.engine), '[]'::jsonb)
      INTO v_result
    FROM totals t
    LEFT JOIN model_totals mt ON mt.day = t.day AND mt.engine = t.engine
    LEFT JOIN hour_totals  ht ON ht.day = t.day AND ht.engine = t.engine;

    RETURN v_result;
END;
$$;


--
-- Name: my_usage_devices(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_usage_devices() RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
    v_uid    UUID := auth.uid();
    v_result JSONB;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'my_usage_devices requires an authenticated caller' USING ERRCODE = '42501';
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
               'deviceId', d.device_id,
               'firstDay', to_char(d.first_day, 'YYYY-MM-DD'),
               'lastDay',  to_char(d.last_day, 'YYYY-MM-DD')
           ) ORDER BY d.last_day DESC, d.device_id), '[]'::jsonb)
      INTO v_result
    FROM (
        SELECT u.device_id, MIN(u.day) AS first_day, MAX(u.day) AS last_day
        FROM public.usage_daily u
        WHERE u.user_id = v_uid
        GROUP BY u.device_id
    ) d;

    RETURN v_result;
END;
$$;


--
-- Name: server_login_approve(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_login_approve(p_user_code text, p_user_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
declare
  r identity.server_login_requests%rowtype;
  v_refusal jsonb;
begin
  select * into r from identity.server_login_requests
   where user_code = upper(p_user_code)
     and status = 'pending'
     and expires_at > now()
   for update;
  if not found or nullif(p_user_id, '') is null then
    return null;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('gugu-machine-limit:' || p_user_id, 0));
  v_refusal := identity.gugu_machine_limit_refusal(p_user_id::uuid, r.machine_id, r.via);
  if v_refusal is not null then
    perform identity.server_login_mark_refused(r.id, p_user_id, v_refusal);
    return jsonb_build_object('status', 'refused', 'refusal', v_refusal);
  end if;
  update identity.server_login_requests
     set status = 'approved', approved_user_id = p_user_id, decided_at = now()
   where id = r.id;
  return jsonb_build_object('status', 'approved');
end;
$$;


--
-- Name: server_login_decide(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_login_decide(p_user_code text, p_user_id text, p_approve boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
declare
  v_status text;
begin
  update identity.server_login_requests r
     set status = case when p_approve then 'approved' else 'denied' end,
         approved_user_id = case when p_approve then p_user_id else null end,
         decided_at = now()
   where r.user_code = upper(p_user_code)
     and r.status = 'pending'
     and r.expires_at > now()
  returning r.status into v_status;
  return v_status;
end;
$$;


--
-- Name: server_login_grant(text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_login_grant(p_device_code_hash text, p_user_code text, p_machine jsonb, p_requester_ip text, p_user_id text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
declare
  v_expires timestamptz;
begin
  if nullif(p_user_id, '') is null then
    raise exception 'server_login_grant: user is required';
  end if;
  delete from identity.server_login_requests where expires_at < now() - interval '1 day';
  insert into identity.server_login_requests
    (device_code_hash, user_code, machine, requester_ip, via, status, approved_user_id, decided_at)
  values (p_device_code_hash, p_user_code, coalesce(p_machine, '{}'::jsonb), p_requester_ip, 'ssh',
          'approved', p_user_id, now())
  returning expires_at into v_expires;
  return v_expires;
end;
$$;


--
-- Name: server_login_poll(text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_login_poll(p_device_code_hash text, p_min_interval_seconds integer, p_machine_id text DEFAULT NULL::text) RETURNS TABLE(result text, user_id text, detail jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
#variable_conflict use_column
declare
  r identity.server_login_requests%rowtype;
  v_machine text;
  v_refusal jsonb;
begin
  select * into r from identity.server_login_requests
   where device_code_hash = p_device_code_hash
   for update;
  if not found or r.status = 'consumed' then
    return query select 'expired'::text, null::text, null::jsonb;
    return;
  end if;
  if r.status = 'denied' then
    return query select 'denied'::text, null::text, null::jsonb;
    return;
  end if;
  if r.status = 'refused' then
    return query select 'machine_limit'::text, null::text, r.refusal;
    return;
  end if;
  if r.status = 'approved' then
    v_machine := coalesce(nullif(left(coalesce(p_machine_id, ''), 200), ''), r.machine_id);
    if v_machine is not null then
      perform pg_advisory_xact_lock(hashtextextended('gugu-machine-limit:' || r.approved_user_id, 0));
      v_refusal := identity.gugu_machine_limit_refusal(r.approved_user_id::uuid, v_machine, r.via);
      if v_refusal is not null then
        perform identity.server_login_mark_refused(r.id, r.approved_user_id, v_refusal);
        return query select 'machine_limit'::text, null::text, v_refusal;
        return;
      end if;
      insert into identity.gugu_server_enrollments (user_id, machine_id, via, enrolled_at)
      values (r.approved_user_id::uuid, v_machine, r.via, now())
      on conflict (user_id, machine_id) do update set via = excluded.via, enrolled_at = excluded.enrolled_at;
    end if;
    update identity.server_login_requests
       set status = 'consumed', consumed_at = now(), machine_id = coalesce(machine_id, v_machine)
     where id = r.id;
    return query select 'approved'::text, r.approved_user_id, null::jsonb;
    return;
  end if;
  if r.expires_at <= now() then
    return query select 'expired'::text, null::text, null::jsonb;
    return;
  end if;
  if r.last_polled_at is not null
     and r.last_polled_at > now() - make_interval(secs => greatest(p_min_interval_seconds, 1) - 1) then
    update identity.server_login_requests set last_polled_at = now() where id = r.id;
    return query select 'slow_down'::text, null::text, null::jsonb;
    return;
  end if;
  update identity.server_login_requests set last_polled_at = now() where id = r.id;
  return query select 'pending'::text, null::text, null::jsonb;
end;
$$;


--
-- Name: server_login_start(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_login_start(p_device_code_hash text, p_user_code text, p_machine jsonb, p_requester_ip text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
declare
  v_expires timestamptz;
begin
  delete from identity.server_login_requests where expires_at < now() - interval '1 day';
  insert into identity.server_login_requests (device_code_hash, user_code, machine, requester_ip, via, machine_id)
  values (p_device_code_hash, p_user_code, coalesce(p_machine, '{}'::jsonb), p_requester_ip, 'tunnel',
          nullif(left(coalesce(p_machine ->> 'machine_id', ''), 200), ''))
  returning expires_at into v_expires;
  return v_expires;
end;
$$;


--
-- Name: server_login_view(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.server_login_view(p_user_code text) RETURNS TABLE(machine jsonb, requester_ip text, status text, created_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'identity', 'public'
    AS $$
  select r.machine, r.requester_ip, r.status, r.created_at, r.expires_at
  from identity.server_login_requests r
  where r.user_code = upper(p_user_code);
$$;


