    join_context_shown_at timestamp with time zone,
    joined_ingest_seq bigint NOT NULL,
    CONSTRAINT chat_members_listen_mode_chk CHECK ((listen_mode = ANY (ARRAY['passive'::text, 'active'::text]))),
    CONSTRAINT chat_members_notification_level_check CHECK ((notification_level = ANY (ARRAY['all'::text, 'important'::text, 'none'::text]))),
    CONSTRAINT chat_members_role_check CHECK ((role = ANY (ARRAY['owner'::text, 'admin'::text, 'member'::text])))
);

ALTER TABLE ONLY chat.chat_members REPLICA IDENTITY FULL;


--
-- Name: COLUMN chat_members.listen_mode; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON COLUMN chat.chat_members.listen_mode IS '两档(#5856):passive = 点名才回;active = 会被不点名的发言叫醒,回不回它自己判断。❌ 不要再加第三档 —— 三档里有两档行为一样,那是 2026-09-19 收掉的东西。';


