    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT contacts_self_chk CHECK ((owner_user_id <> contact_user_id)),
    CONSTRAINT contacts_state_chk CHECK ((state = ANY (ARRAY['normal'::text, 'blocked'::text, 'muted'::text])))
);


--
-- Name: file_blob_gc; Type: TABLE; Schema: chat; Owner: -
--

CREATE TABLE chat.file_blob_gc (
    blob_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    claim_token uuid,
    next_attempt_at timestamp with time zone NOT NULL,
    claimed_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT file_blob_gc_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT file_blob_gc_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'failed'::text])))
);


--
-- Name: TABLE file_blob_gc; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON TABLE chat.file_blob_gc IS '可能没人引用了的 blob:失去一个引用(条目、历史、上传登记)时进来,next_attempt_at 起才领;领的时候再核一次引用。写法同 identity.storage_object_deletion_outbox。';


--
-- Name: file_blobs; Type: TABLE; Schema: chat; Owner: -
--

CREATE TABLE chat.file_blobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    bucket_id text NOT NULL,
    object_name text NOT NULL,
    sha256 text,
    size_bytes bigint,
    content_type text NOT NULL,
    width integer,
    height integer,
    state text DEFAULT 'live'::text NOT NULL,
    created_by text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT file_blobs_bucket_id_check CHECK ((bucket_id = ANY (ARRAY['oss'::text, 'workspace'::text]))),
    CONSTRAINT file_blobs_height_check CHECK ((height > 0)),
    CONSTRAINT file_blobs_oss_shape CHECK (((bucket_id <> 'oss'::text) OR ((sha256 IS NOT NULL) AND (size_bytes IS NOT NULL) AND (size_bytes <= 26214400) AND (object_name = ((substr(sha256, 1, 2) || '/'::text) || sha256))))),
    CONSTRAINT file_blobs_sha256_check CHECK ((sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT file_blobs_size_bytes_check CHECK ((size_bytes >= 0)),
    CONSTRAINT file_blobs_state_check CHECK ((state = ANY (ARRAY['live'::text, 'deleting'::text]))),
    CONSTRAINT file_blobs_width_check CHECK ((width > 0))
);


--
-- Name: TABLE file_blobs; Type: COMMENT; Schema: chat; Owner: -
--

COMMENT ON TABLE chat.file_blobs IS '一份字节一行:在哪(oss = OSS 私有桶 <sha256 前两位>/<sha256>;workspace = Supabase 存储桶里的老对象,按 pointer 原地指)、多大、类型、图片宽高。条目和历史经 blob_id 指它;没人引用了由 chat.file_blob_gc 回收。只经 SECURITY DEFINER 的函数读写。';


