--
-- Name: usage_daily; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.usage_daily (
    user_id uuid DEFAULT auth.uid() NOT NULL,
    device_id text NOT NULL,
    day date NOT NULL,
    engine text NOT NULL,
    sessions integer DEFAULT 0 NOT NULL,
    run_seconds bigint DEFAULT 0 NOT NULL,
    input_tokens bigint DEFAULT 0 NOT NULL,
    output_tokens bigint DEFAULT 0 NOT NULL,
    cache_read_tokens bigint DEFAULT 0 NOT NULL,
    cache_write_tokens bigint DEFAULT 0 NOT NULL,
    models jsonb DEFAULT '{}'::jsonb NOT NULL,
    hours integer[] DEFAULT array_fill(0, ARRAY[24]) NOT NULL,
    parallel_seconds bigint DEFAULT 0 NOT NULL,
    peak_concurrency integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    gugu_models jsonb DEFAULT '{}'::jsonb NOT NULL,
    byok_models jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT usage_daily_byok_models_chk CHECK (((jsonb_typeof(byok_models) = 'object'::text) AND (NOT jsonb_path_exists(byok_models, '$.*?(@.type() != "number" || @ < 0)'::jsonpath)) AND (octet_length((byok_models)::text) <= 16384))),
    CONSTRAINT usage_daily_counts_chk CHECK (((sessions >= 0) AND (run_seconds >= 0) AND (input_tokens >= 0) AND (output_tokens >= 0) AND (cache_read_tokens >= 0) AND (cache_write_tokens >= 0) AND (parallel_seconds >= 0) AND (peak_concurrency >= 0))),
    CONSTRAINT usage_daily_day_chk CHECK (((day >= '2020-01-01'::date) AND (day <= (CURRENT_DATE + 2)))),
    CONSTRAINT usage_daily_device_id_chk CHECK (((char_length(device_id) >= 1) AND (char_length(device_id) <= 128))),
    CONSTRAINT usage_daily_engine_chk CHECK (((char_length(engine) >= 1) AND (char_length(engine) <= 64))),
    CONSTRAINT usage_daily_gugu_models_chk CHECK (((jsonb_typeof(gugu_models) = 'object'::text) AND (NOT jsonb_path_exists(gugu_models, '$.*?(@.type() != "number" || @ < 0)'::jsonpath)) AND (octet_length((gugu_models)::text) <= 16384))),
    CONSTRAINT usage_daily_hours_chk CHECK (((array_ndims(hours) = 1) AND (cardinality(hours) = 24) AND (array_position(hours, NULL::integer) IS NULL) AND (0 <= ALL (hours)))),
    CONSTRAINT usage_daily_models_chk CHECK (((jsonb_typeof(models) = 'object'::text) AND (NOT jsonb_path_exists(models, '$.*?(@.type() != "number" || @ < 0)'::jsonpath)) AND (octet_length((models)::text) <= 16384)))
);


