--
-- Name: chats chats_insert_own; Type: POLICY; Schema: chat; Owner: -
--

CREATE POLICY chats_insert_own ON chat.chats FOR INSERT TO authenticated WITH CHECK (((creator_user_id = ( SELECT (auth.uid())::text AS uid)) AND (agent_flood_tuned_at IS NULL) AND ((kind <> 'topic'::text) OR ((source_chat_id IS NOT NULL) AND chat.is_member(source_chat_id) AND (( SELECT src.kind
   FROM chat.chats src
  WHERE (src.id = chats.source_chat_id)) <> 'topic'::text) AND (EXISTS ( SELECT 1
   FROM chat.messages m
  WHERE ((m.id = chats.source_message_id) AND (m.chat_id = chats.source_chat_id) AND (m.deleted_at IS NULL) AND (m.retracted_at IS NULL) AND (NOT m.is_whisper)))) AND chat.can_read_message(source_message_id, ( SELECT (auth.uid())::text AS uid))))));


