--

CREATE POLICY chats_update_owner ON chat.chats FOR UPDATE TO authenticated USING ((chat.is_member(id) AND (EXISTS ( SELECT 1
   FROM chat.chat_members
  WHERE ((chat_members.chat_id = chats.id) AND (chat_members.user_id = ( SELECT (auth.uid())::text AS uid)) AND (chat_members.role = ANY (ARRAY['owner'::text, 'admin'::text]))))))) WITH CHECK ((chat.is_member(id) AND (EXISTS ( SELECT 1
   FROM chat.chat_members
  WHERE ((chat_members.chat_id = chats.id) AND (chat_members.user_id = ( SELECT (auth.uid())::text AS uid)) AND (chat_members.role = ANY (ARRAY['owner'::text, 'admin'::text])))))));


