--
-- Name: messages messages_insert_member; Type: POLICY; Schema: chat; Owner: -
--

CREATE POLICY messages_insert_member ON chat.messages FOR INSERT TO authenticated WITH CHECK (((chat.can_act_as(sender_user_id, chat_id) OR chat.can_speak_in_topic(chat_id, sender_user_id)) AND ((to_user_ids IS NULL) OR (array_length(to_user_ids, 1) IS NULL) OR (('*'::text = ANY (to_user_ids)) AND (EXISTS ( SELECT 1
   FROM chat.chats c
  WHERE ((c.id = messages.chat_id) AND (c.kind = ANY (ARRAY['group'::text, 'topic'::text])))))) OR (NOT (EXISTS ( SELECT 1
   FROM unnest(messages.to_user_ids) target(target_user_id)
  WHERE ((target.target_user_id <> '*'::text) AND (NOT chat.is_addressable_in(messages.chat_id, target.target_user_id)))))))));


--
-- Name: messages messages_select_member; Type: POLICY; Schema: chat; Owner: -
--

CREATE POLICY messages_select_member ON chat.messages FOR SELECT TO authenticated USING (((deleted_at IS NULL) AND ((EXISTS ( SELECT 1
   FROM chat.chat_members cm
  WHERE ((cm.chat_id = messages.chat_id) AND (cm.user_id = ( SELECT (auth.uid())::text AS uid)) AND ((cm.hide_history_before IS NULL) OR (messages.created_at >= cm.hide_history_before))))) OR chat.can_see_topic_message(chat_id, created_at, ( SELECT (auth.uid())::text AS uid))) AND chat.whisper_visible_to(is_whisper, sender_user_id, to_user_ids, ( SELECT (auth.uid())::text AS uid))));


