  WHERE ((d.device_id = gugu_device_commands.device_id) AND (d.user_id = ( SELECT auth.uid() AS uid))))) AND ((type <> ALL (ARRAY['agent.deliver'::text, 'agent.wake'::text])) OR (EXISTS ( SELECT 1
   FROM identity.users u
  WHERE ((u.id = (gugu_device_commands.payload ->> 'agent_user_id'::text)) AND (u.type = 'agent'::text) AND (u.owner_user_id = ( SELECT (auth.uid())::text AS uid)) AND (u.desired_status = 'online'::text)))))));


