-- Installation policy. NULL limits mean the operator has not configured a maximum.
CREATE TABLE identity.installation_machine_limits (
 id boolean PRIMARY KEY DEFAULT true CHECK(id),
 max_machines integer CHECK(max_machines>=0),
 max_tunnel_machines integer CHECK(max_tunnel_machines>=0)
);
ALTER TABLE identity.installation_machine_limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON identity.installation_machine_limits FROM PUBLIC, anon, authenticated;
INSERT INTO identity.installation_machine_limits(id) VALUES(true);
CREATE FUNCTION identity.machine_limits_for(p_user_id uuid)
RETURNS TABLE(max_machines integer,max_tunnel_machines integer,plan_id text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=identity,pg_catalog
AS $limits$ SELECT max_machines,max_tunnel_machines,'installation'::text FROM identity.installation_machine_limits WHERE id $limits$;
REVOKE ALL ON FUNCTION identity.machine_limits_for(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION identity.machine_limits_for(uuid) TO service_role;

