-- Foundation background maintenance. Attachment GC credentials are configured by setup, never in source.
SELECT cron.schedule('device-lease-sweep','15 seconds',$job$SELECT identity.sweep_device_leases()$job$);
SELECT cron.schedule('file-blob-upload-sweep','*/10 * * * *',$job$SELECT chat.file_blob_sweep()$job$);
SELECT cron.schedule('file-blob-gc-kick','*/10 * * * *',$job$SELECT chat.file_blob_gc_kick()$job$);

-- Uncommitted signed uploads have no blob row. Return only expired staging keys to the server GC.
CREATE FUNCTION chat.attachment_expired_staging(p_bucket text)
RETURNS TABLE(name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog
AS $staging$
 SELECT name FROM storage.objects
 WHERE bucket_id=p_bucket AND name LIKE 'staging/%' AND created_at < now()-interval '1 day'
 ORDER BY created_at LIMIT 50
$staging$;
REVOKE ALL ON FUNCTION chat.attachment_expired_staging(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION chat.attachment_expired_staging(text) TO service_role;

-- Realtime authorization is attached to the platform schema and must travel with the foundation.
CREATE POLICY "gugu_agent_presence_events_select" ON realtime."messages" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((split_part(topic, ':'::text, 1) = 'agent'::text) AND (split_part(topic, ':'::text, 3) = 'presence'::text) AND identity.can_view_agent_runtime_state(split_part(topic, ':'::text, 2))));
CREATE POLICY "gugu_command_events_select" ON realtime."messages" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((split_part(topic, ':'::text, 1) = 'gugu'::text) AND (split_part(topic, ':'::text, 3) = 'commands'::text) AND (EXISTS ( SELECT 1
   FROM identity.gugu_devices d
  WHERE ((d.device_id = split_part(messages.topic, ':'::text, 2)) AND (d.user_id = ( SELECT auth.uid() AS uid)))))));
CREATE POLICY "gugu_user_events_select" ON realtime."messages" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((split_part(topic, ':'::text, 1) = 'gugu'::text) AND (split_part(topic, ':'::text, 2) = 'user'::text) AND (split_part(topic, ':'::text, 3) = ( SELECT (auth.uid())::text AS uid)) AND (split_part(topic, ':'::text, 4) = 'events'::text)));
CREATE POLICY "gugu_rpc_events_select" ON realtime."messages" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((split_part(topic, ':'::text, 1) = 'gugu'::text) AND (split_part(topic, ':'::text, 3) = 'rpc'::text) AND (EXISTS ( SELECT 1
   FROM identity.gugu_devices d
  WHERE ((d.device_id = split_part(messages.topic, ':'::text, 2)) AND (d.user_id = ( SELECT auth.uid() AS uid)))))));
CREATE POLICY "gugu_rpc_events_insert" ON realtime."messages" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (((split_part(topic, ':'::text, 1) = 'gugu'::text) AND (split_part(topic, ':'::text, 3) = 'rpc'::text) AND (EXISTS ( SELECT 1
   FROM identity.gugu_devices d
  WHERE ((d.device_id = split_part(messages.topic, ':'::text, 2)) AND (d.user_id = ( SELECT auth.uid() AS uid)))))));
CREATE POLICY "gugu_message_preview_select" ON realtime."messages" AS PERMISSIVE FOR SELECT TO "authenticated" USING (((split_part(topic, ':'::text, 1) = 'gugu'::text) AND (split_part(topic, ':'::text, 2) = 'preview'::text) AND (chat.is_member(split_part(topic, ':'::text, 3)) OR identity.can_write_agent_runtime_state(split_part(topic, ':'::text, 4))) AND chat.is_chat_member(split_part(topic, ':'::text, 3), split_part(topic, ':'::text, 4))));
CREATE POLICY "gugu_message_preview_insert" ON realtime."messages" AS PERMISSIVE FOR INSERT TO "authenticated" WITH CHECK (((split_part(topic, ':'::text, 1) = 'gugu'::text) AND (split_part(topic, ':'::text, 2) = 'preview'::text) AND identity.can_write_agent_runtime_state(split_part(topic, ':'::text, 4)) AND chat.is_chat_member(split_part(topic, ':'::text, 3), split_part(topic, ':'::text, 4))));

-- Preserve fail-closed authorization for subsequent migrations, as well as current object ACLs.
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA chat GRANT SELECT,USAGE ON SEQUENCES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA chat GRANT SELECT,INSERT,DELETE,UPDATE ON TABLES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA identity GRANT SELECT,USAGE ON SEQUENCES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA identity GRANT SELECT,INSERT,DELETE,UPDATE ON TABLES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA moments GRANT SELECT,USAGE ON SEQUENCES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA moments GRANT SELECT,INSERT,DELETE,UPDATE ON TABLES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON SEQUENCES TO postgres;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT UPDATE ON SEQUENCES TO anon;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT UPDATE ON SEQUENCES TO authenticated;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT UPDATE ON SEQUENCES TO service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON FUNCTIONS TO postgres;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT ALL ON TABLES TO postgres;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLES TO anon;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLES TO authenticated;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public GRANT REFERENCES,TRIGGER,TRUNCATE,MAINTAIN ON TABLES TO service_role;
CREATE FUNCTION public.gg_revoke_public_execute_on_new_function() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT c.object_identity
        FROM pg_event_trigger_ddl_commands() c
        JOIN pg_proc p ON p.oid = c.objid
        WHERE c.command_tag = 'CREATE FUNCTION'
          AND c.schema_name IN ('public', 'identity', 'chat', 'billing', 'moments')
          AND p.prorettype NOT IN (
              'pg_catalog.trigger'::regtype,
              'pg_catalog.event_trigger'::regtype
          )
    LOOP
        EXECUTE format(
            'REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon, authenticated',
            r.object_identity
        );
    END LOOP;
END;
$$;
REVOKE ALL ON FUNCTION public.gg_revoke_public_execute_on_new_function() FROM PUBLIC,anon,authenticated;
CREATE EVENT TRIGGER gg_revoke_public_execute_on_functions
  ON ddl_command_end WHEN TAG IN ('CREATE FUNCTION')
  EXECUTE FUNCTION public.gg_revoke_public_execute_on_new_function();

NOTIFY pgrst, 'reload schema';
